{"afk/afkAi.ts":"import { generateWithGroq } from "../utils/groq.js";

// AFK sistemi için Groq entegrasyonu. Biri AFK olan birini etiketlediğinde,
// eski sabit "X şu an AFK: sebep" şablonu yerine kısa, bağlama uygun bir
// cevap ürettiriyoruz. customevent/otomod sistemleriyle hiçbir ilgisi yok —
// yalnızca messageCreate.ts'teki mevcut AFK akışına takılan bağımsız bir
// yardımcı. Groq başarısız/timeout olursa çağıran taraf eski statik mesaja
// düşer (bkz. events/messageCreate.ts), yani kullanıcı hiçbir zaman cevapsız
// kalmaz.

export interface AfkMentionInfo {
  displayName: string;
  reason: string;
  minutesAgo: number;
}

const SYSTEM_PROMPT = `Sen bir Discord botusun. Görevin, birisi şu an AFK (uzakta) olan bir veya \
birkaç kullanıcıyı etiketlediğinde, bunu haber veren KISA ve doğal bir Türkçe mesaj yazmak.

KURALLAR:
- 1-2 cümlelik tek bir mesaj yaz; aşırı kısa (tek kelime veya yalnızca birkaç kelime) cevap verme. Yaklaşık 12-35 kelime kullan.
- Her AFK kullanıcıyı ve sebebini mesajına doğal şekilde dahil et.
- Sana verilen {{mention}} placeholder'larını AYNEN, değiştirmeden koru (bunlar Discord etiketleridir).
- Abartılı emoji veya resmi bir dil kullanma, samimi ama kısa ol.
- Uydurma bilgi ekleme, sadece verilen sebep/süre bilgisine dayan.
- Açıklama, giriş cümlesi ekleme — direkt mesajın kendisini yaz.`;

function formatMinutes(minutes: number): string {
  if (minutes < 1) return "az önce";
  if (minutes < 60) return `${minutes} dakika önce`;
  const hours = Math.floor(minutes / 60);
  return `${hours} saat önce`;
}

/**
 * Etiketlenen AFK kullanıcı(lar) için Groq ile kısa bir bilgilendirme mesajı
 * üretir. `mentions` içindeki her kayıt bir {{mention_N}} placeholder'ıyla
 * eşleşir; dönen metinde bu placeholder'lar gerçek Discord mention'larıyla
 * (<@id>) değiştirilerek geri döner. Başarısız olursa null döner — çağıran
 * taraf statik şablona düşmeli.
 */
export async function generateAfkMentionReply(
  mentions: { userId: string; info: AfkMentionInfo }[],
  triggeringMessageContent: string,
): Promise<string | null> {
  if (mentions.length === 0) return null;

  const placeholderMap = new Map<string, string>();
  const listForPrompt = mentions
    .map(({ userId, info }, i) => {
      const placeholder = `{{mention_${i}}}`;
      placeholderMap.set(placeholder, `<@${userId}>`);
      return `${placeholder} (${info.displayName}) — sebep: "${info.reason}", ${formatMinutes(info.minutesAgo)} AFK oldu.`;
    })
    .join("\n");

  const userPrompt = `Etiketlenen AFK kullanıcılar:\n${listForPrompt}\n\nEtiketleyen kişinin mesajı: "${triggeringMessageContent.slice(0, 300)}"`;

  try {
    const raw = await generateWithGroq(SYSTEM_PROMPT, userPrompt, {
      maxTokens: 1_024,
      temperature: 0.75,
    });
    let text = raw.trim().slice(0, 500);
    if (!text) return null;

    for (const [placeholder, mention] of placeholderMap) {
      text = text.split(placeholder).join(mention);
    }

    return text;
  } catch (err) {
    console.warn("⚠️ AFK Groq mesajı üretilemedi, statik şablona düşülüyor:", err);
    return null;
  }
}
","afk/store.ts":"import { eq } from "drizzle-orm";
import { db, afkTable } from "../db/index.js";

// ---------------------------------------------------------------------------
// AFK sistemi — diğer kalıcı runtime state'lerle aynı
// desen: açılışta DB'den belleğe yükleniyor, her değişiklikte hem bellek hem
// DB güncelleniyor. Böylece bot yeniden başlasa da AFK durumları kaybolmuyor.
// ---------------------------------------------------------------------------

interface AfkEntry {
  reason: string;
  since: number;
}

const afkMap = new Map<string, AfkEntry>(); // key: userId

let loaded = false;
let loadingPromise: Promise<void> | null = null;

async function loadAfk(): Promise<void> {
  const rows = await db.select().from(afkTable);
  afkMap.clear();
  for (const row of rows) afkMap.set(row.userId, { reason: row.reason, since: row.since.getTime() });
  loaded = true;
  console.log(`[AFK] ${rows.length} kayıtlı AFK durumu yüklendi.`);
}

export async function ensureAfkLoaded(): Promise<void> {
  if (loaded) return;
  if (!loadingPromise) {
    loadingPromise = loadAfk().finally(() => {
      loadingPromise = null;
    });
  }
  await loadingPromise;
}

export async function setAfk(userId: string, reason: string): Promise<void> {
  const since = Date.now();
  try {
    await db
      .insert(afkTable)
      .values({ userId, reason, since: new Date(since) })
      .onConflictDoUpdate({
        target: afkTable.userId,
        set: { reason, since: new Date(since) },
      });
    afkMap.set(userId, { reason, since });
  } catch (err) {
    console.error(`[AFK] Kaydedilirken hata (${userId}):`, err);
    throw err;
  }
}

export function getAfk(userId: string): AfkEntry | null {
  return afkMap.get(userId) ?? null;
}

/** AFK durumunu kaldırır (bellek + DB) ve varsa önceki kaydı döner. */
export async function clearAfk(userId: string): Promise<AfkEntry | null> {
  const entry = afkMap.get(userId) ?? null;
  if (!entry) return null;
  try {
    const deleted = await db
      .delete(afkTable)
      .where(eq(afkTable.userId, userId))
      .returning({ userId: afkTable.userId });
    if (deleted.length === 0) return null;
    afkMap.delete(userId);
    return entry;
  } catch (err) {
    // DB silinmediyse bellekte de silme; ancak bu mesajı AFK dönüşü olarak
    // işaretlemeyerek her mesajda sahte "hoşgeldin" yanıtı üretme.
    console.error(`[AFK] Silinirken hata (${userId}):`, err);
    return null;
  }
}
","automod/automod.ts":"import {
  Message,
  EmbedBuilder,
  PermissionFlagsBits,
  TextChannel,
  GuildMember,
} from "discord.js";
import { getGuildConfig, getEffectiveWordList, addStrike } from "./store.js";
import { OWNER_ID } from "../config.js";

const INVITE_REGEX =
  /(discord\.gg\/|discord(?:app)?\.com\/invite\/)[a-z0-9-]+/i;

// Mesaj içeriğinde GERÇEKTEN yazılmış <@id> etiketlerini yakalar.
// message.mentions.users kullanmıyoruz çünkü Discord, bir mesaja "yanıtla"
// (reply) ile cevap verildiğinde ve reply bildirimi açıksa, yanıtlanan kişiyi
// kullanıcı hiç @ yazmamış olsa bile otomatik olarak mentions.users'a ekliyor.
// Bu yüzden salt reply mention'lar etiket-spam sayacını yanlışlıkla artırıyordu.
// Regex yalnızca mesaj METNİNDE fiilen yazılmış <@123...> / <@!123...>
// biçimindeki etiketleri sayar, reply bildirimini saymaz.
const EXPLICIT_MENTION_REGEX = /<@!?(\d+)>/g;

function countExplicitMentions(content: string): number {
  const matches = content.match(EXPLICIT_MENTION_REGEX);
  return matches ? matches.length : 0;
}

// --- Flood/spam takibi: geçici, bellek-içi (yeniden başlatmada sıfırlanır,
// bu bilinçli bir tercih — flood durumu zaten kısa ömürlü olduğu için
// disk'e yazmaya gerek yok). ---
interface RecentMsg {
  ts: number;
  content: string;
}
const recentMessages = new Map<string, RecentMsg[]>(); // key: guildId:userId

const FLOOD_WINDOW_MS = 7_000;
// Eskiden 8+ mesaj gerekiyordu — bu, gerçek bir flood/spam saldırısını yakalamadan
// önce çok fazla mesajın kanala düşmesine izin veriyordu (algılama "yavaş" hissettiriyordu).
// 6'ya düşürüldü: normal, hızlı yazan bir üyenin 7 saniyede 6 farklı mesaj atması hâlâ
// pek olası değil, bu yüzden üyeleri rahatsız etme riski düşük kalıyor, ama gerçek
// flood/spam artık 2 mesaj daha erken (daha hızlı) yakalanıyor.
const FLOOD_MESSAGE_LIMIT = 6; // 7 sn içinde 6+ mesaj
const DUPLICATE_WINDOW_MS = 10_000;
// Eskiden 5+ aynı mesaj gerekiyordu. 4'e düşürüldü: 15 saniyede aynı mesajı 4 kez
// art arda atmak normal bir üye için zaten olağan değil (rahatsız etme riski düşük),
// ama tekrar eden spam artık 1 mesaj daha erken yakalanıyor.
const DUPLICATE_LIMIT = 4; // 15 sn içinde aynı mesajdan 4+

function trackAndCheckFlood(
  guildId: string,
  userId: string,
  content: string,
): "flood" | "duplicate" | null {
  const key = `${guildId}:${userId}`;
  const now = Date.now();
  const list = recentMessages.get(key) ?? [];
  list.push({ ts: now, content });

  // eski kayıtları temizle
  const trimmed = list.filter((m) => now - m.ts <= DUPLICATE_WINDOW_MS);
  recentMessages.set(key, trimmed);

  const withinFlood = trimmed.filter((m) => now - m.ts <= FLOOD_WINDOW_MS);
  if (withinFlood.length >= FLOOD_MESSAGE_LIMIT) return "flood";

  if (content.trim().length > 0) {
    const dupCount = trimmed.filter(
      (m) => m.content === content && now - m.ts <= DUPLICATE_WINDOW_MS,
    ).length;
    if (dupCount >= DUPLICATE_LIMIT) return "duplicate";
  }

  return null;
}

// --- Etiket (mention) spam takibi ---
// Duplicate kontrolü mesaj METNİNİN aynı olmasını arar — biri her seferinde
// farklı bir şey yazıp hep aynı kişiyi etiketlerse ("@x naber", "@x abi" gibi)
// duplicate bunu YAKALAMAZ. Bu yüzden ayrı bir sayaç: kısa sürede kaç kez
// etiket (mention) atılmış, mesaj içeriği ne olursa olsun sayar.
interface RecentMention {
  ts: number;
}
const recentMentions = new Map<string, RecentMention[]>(); // key: guildId:userId

const MENTION_WINDOW_MS = 10_000;
const MENTION_LIMIT = 4; // 10 sn içinde toplam 5+ etiket -> etiket spam

// Bellek sızıntısı önlemi: bir kullanıcı bir kez mesaj attıktan sonra, bir daha
// hiç yazmasa bile recentMessages/recentMentions Map'lerindeki kaydı sonsuza
// dek tutuluyordu (yalnızca kayıtların İÇİNDEKİ zaman damgaları temizleniyordu,
// Map anahtarının kendisi hiç silinmiyordu). Uzun süre çalışan, çok kullanıcılı
// bir botta bu Map'ler zamanla gereksiz yere büyür. Periyodik olarak, süresi
// tamamen dolmuş (artık hiçbir aktif kaydı kalmamış) anahtarları temizliyoruz.
const STALE_CLEANUP_INTERVAL_MS = 10 * 60_000; // 10 dakikada bir
const cleanupInterval = setInterval(() => {
  const now = Date.now();
  for (const [key, list] of recentMessages) {
    if (!list.some((m) => now - m.ts <= DUPLICATE_WINDOW_MS)) recentMessages.delete(key);
  }
  for (const [key, list] of recentMentions) {
    if (!list.some((m) => now - m.ts <= MENTION_WINDOW_MS)) recentMentions.delete(key);
  }
}, STALE_CLEANUP_INTERVAL_MS);
cleanupInterval.unref?.();

function trackAndCheckMentionSpam(
  guildId: string,
  authorId: string,
  mentionCount: number,
): boolean {
  if (mentionCount <= 0) return false;
  const key = `${guildId}:${authorId}`;
  const now = Date.now();
  const list = recentMentions.get(key) ?? [];

  // Bu mesajdaki her etiket için ayrı bir zaman damgası ekle (bir mesajda
  // birden fazla kişi etiketlenmiş olsa da toplamda sayılır).
  for (let i = 0; i < mentionCount; i++) list.push({ ts: now });

  const trimmed = list.filter((m) => now - m.ts <= MENTION_WINDOW_MS);
  recentMentions.set(key, trimmed);

  return trimmed.length >= MENTION_LIMIT;
}

// --- Yasaklı kelime tespiti ---

// LEETSPEAK / SEMBOL İKAMESİ:
// "s1kt1r", "4mk", "5ktr", "amın@" gibi rakam/sembol ikameli yazımlar eskiden
// hiç yakalanmıyordu çünkü normalize() rakamları olduğu gibi bırakıyordu.
// Bunu SADECE harf içeren token'larda uyguluyoruz (saf sayısal token'lara
// -tarih, id, vs.- dokunmuyoruz) ki normal mesajlar bozulmasın. Yine de bu,
// "3d model" gibi nadir durumlarda ufak bir false-positive riski taşıyor —
// bilinçli bir ödünleşim, çünkü amaç kaçırmaları en aza indirmek.
const LEET_MAP: Record<string, string> = {
  "4": "a", "@": "a",
  "3": "e",
  "1": "i", "!": "i",
  "0": "o",
  "5": "s", "$": "s",
  "7": "t",
};
const LEET_CHARS_RE = /[43107!@$]/;
const HAS_LETTER_RE = /[a-zçğıöşüA-ZÇĞİÖŞÜ]/;

function deleet(text: string): string {
  return text.replace(/\S+/g, (token) => {
    if (!HAS_LETTER_RE.test(token) || !LEET_CHARS_RE.test(token)) return token;
    return token.replace(/[43107!@$]/g, (ch) => LEET_MAP[ch]);
  });
}

function normalize(text: string): string {
  return deleet(text)
    .toLocaleLowerCase("tr-TR")
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "") // aksan işaretlerini kaldır
    .replace(/[^a-zçğıöşü0-9\s]/gi, " ") // noktalama/emoji vs -> boşluk
    .replace(/(.)\1{2,}/g, "$1$1") // "sikkkk" -> "sikk" gibi tekrarları kırp
    .replace(/\s+/g, " ")
    .trim();
}

function escapeRegex(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

// ÜNSÜZ İSKELETİ (consonant skeleton) — SESLİ HARF ATLAMA:
// Türkçe'de mesajlaşırken sesli harfleri atarak kısaltma çok yaygındır
// ("selam" -> "slm", "naber" -> "nbr"). Küfürler de aynı şekilde kısaltılıp
// filtreyi atlatmak için kullanılabilir: "yarrak" -> "yrrk", "sikim" -> "skm".
// Bunu SADECE tamamen sesli harf İÇERMEYEN (yani bariz şekilde kısaltılmış)
// ve en az 3 harfli token'larda, TAM EŞLEŞME ile uyguluyoruz — alt string
// olarak değil. Böylece "gt", "cd" gibi rastgele 2 harfli zararsız kısaltmalar
// (iskelet çok kısa olduğu için) dahil edilmiyor, ve normal sesli-harfli
// kelimeler bu kontrole hiç girmiyor (yalnızca kullanıcı bilerek sesli
// harfleri atladığında devreye giriyor).
const TR_VOWELS_RE = /[aeıioöuü]/g;
// NOT: TR_VOWELS_RE global (/g) bayraklı — .test() ile kullanılırsa lastIndex
// durumu ardışık çağrılar arasında bozulur (her ikinci çağrıda yanlış sonuç
// döner). Bu yüzden "içeriyor mu?" kontrolleri için AYRI, global olmayan bir
// regex kullanıyoruz; .replace() global bayrakla sorunsuz çalışır.
const TR_HAS_VOWEL_RE = /[aeıioöuü]/;
function consonantSkeleton(s: string): string {
  return s.replace(TR_VOWELS_RE, "");
}

interface CompiledBannedWord {
  original: string;
  flat: string;
  boundary: RegExp;
  skeleton: string | null;
  // Sadece `!otomod kelime-ekle` ile eklenmiş, sunucuya özel kelimeler için
  // true. Varsayılan listenin aksine bu kelimelerin çekim biçimleri elle
  // girilmediği için (admin tek bir kök yazar), TAM kelime eşleşmesi
  // Türkçe'nin sondan eklemeli yapısı yüzünden neredeyse hiç tetiklenmezdi:
  // "aptal" eklenince "aptalsın", "salaksın" gibi gerçek kullanımlar asla
  // yakalanmıyordu (kelime sınırı "aptal" ile "sın" arasında YOK). Bu
  // kelimeler için ayrıca "kelime bir token'ın BAŞINDA geçiyor mu" (önek)
  // kontrolü de yapılır — bkz. containsBannedWord.
  isCustom: boolean;
}

// The default word list is fairly large. Re-normalizing every word and
// compiling a RegExp for every message was needlessly expensive and caused
// visible lag during busy chats. The store returns the same array until a
// guild's settings change, so a WeakMap gives us a safe, automatic cache.
const compiledWordCache = new WeakMap<string[], CompiledBannedWord[]>();

function compileWordList(wordList: string[], customWords: Set<string>): CompiledBannedWord[] {
  const cached = compiledWordCache.get(wordList);
  if (cached) return cached;

  const compiled: CompiledBannedWord[] = [];
  for (const original of wordList) {
    const normalized = normalize(original);
    if (!normalized) continue;
    const flat = normalized.replace(/\s+/g, "");
    // İskelet en az 4 ünsüz harf içermiyorsa (ör. "göt" -> "gt", "porn" ->
    // "prn") atla. 3 harfli iskeletler pratikte çok az sayıda kombinasyona
    // sıkıştığı için masum kısaltmalarla çakışma riski çok yüksek — ör.
    // "porn" kelimesinin iskeleti "prn" olduğu için tıpta yaygın kullanılan
    // "PRN" (gerektiğinde) kısaltması yanlışlıkla küfür sayılıp siliniyordu.
    // Aynı şekilde "sks"(seks), "sht", "cnt", "mck", "gtn" gibi birçok 3
    // harfli iskelet de gerçek kelime/kısaltmalarla örtüşüyordu. Eşiği 4'e
    // çıkarmak, hâlâ "blyat", "fckr", "pssy" gibi daha uzun (ve çok daha az
    // rastgele çakışma riski taşıyan) obfuscation'ları yakalarken bu false
    // positive'leri ortadan kaldırıyor.
    const skeletonCandidate = consonantSkeleton(flat);
    const skeleton = skeletonCandidate.length >= 4 ? skeletonCandidate : null;
    compiled.push({
      original,
      flat,
      boundary: new RegExp(
        `(^|[^a-zçğıöşü0-9])${escapeRegex(normalized)}([^a-zçğıöşü0-9]|$)`,
        "i",
      ),
      skeleton,
      isCustom: customWords.has(original),
    });
  }
  compiledWordCache.set(wordList, compiled);
  return compiled;
}

/**
 * Yasaklı kelime kontrolü. Şu stratejileri kullanır:
 *
 * 1. BOUNDARY (kelime sınırı): Tüm kelimeler için. "oç", "siktir" gibi
 *    kısaltmalar ve tam sözcükler SADECE kelime sınırı (boşluk/noktalama)
 *    ile ayrılmışsa match olur.
 *    ✓ "bi oç gördüm" → match
 *    ✓ "siktir git" → match
 *    ✗ "koç" ("oç" alt string, ama boundary'de FAIL) → NO match
 *
 * 2. FLAT (harf dizisi): 4+ karakterli kelimelere SADECE boundary FAIL'inde uygulanır.
 *    Amaç: "sikeyim" → "s.i.k.e.y.i.m" gibi ayrılmış yazımı yakalamak.
 *    ✓ Kullanıcı "s.i.k.i.m" yazarsa, flat harf dizisi "sikim" bulur.
 *    ✓ "sikimi" (doğal inflection) yazarsa, flat "sikim" alt string'i bulur.
 *    ✗ "koç" → "oç" (3 char) olduğu için flat'a tabi değil, boundary'de FAIL.
 *
 * 3 harf ve altı kısaltmalar (amk, aq, oç, sg, mk, ...) SADECE boundary'ye tabi.
 * Böylece "faq", "koç", "mq" gibi innocent kelimeler yanlışlıkla yakalanmaz.
 */
function containsBannedWord(content: string, wordList: string[], customWords: Set<string>): string | null {
  const norm = normalize(content);
  if (!norm) return null;

  // OBFUSCATED TOKEN OLUŞTURMA:
  // Sadece ARDIŞIK TEK HARFLİ token'ları birleştiriyoruz — bu "s.i.k.i.m"
  // gibi harf harf ayrılmış yazımları yakalamak için (noktalar/boşluklar
  // normalize() içinde zaten boşluğa çevrilip tek harflik token'lara
  // bölünmüş oluyor). Birden fazla harfli, NORMAL YAZILMIŞ kelimeler bu
  // listeye ASLA girmiyor — aşağıda neden önemli olduğu açıklanıyor.
  // Eskiden sadece TEK harfli ardışık token'lar birleştiriliyordu (yalnızca
  // "s.i.k.i.m" gibi harf-harf ayrılmış yazımı yakalar). "sik im" / "si kim"
  // gibi kısa parçalara bölünmüş kaçırmalar hiç yakalanmıyordu. Sınırı 3
  // karaktere çıkarıyoruz; riski sınırlamak için EN AZ İKİ ardışık kısa
  // token gerektiriyoruz (tek başına kısa bir kelime, ör. "ok", "ya", "mi",
  // "her", "bir", birleştirmeye girmez — masum kısa kelime dizileri bu
  // yüzden etkilenmez; test edildi).
  const rawTokens = norm.split(" ").filter(Boolean);

  // SESLİ HARFSİZ TOKEN'LAR: "yrrk", "skm" gibi bariz şekilde sesli harfleri
  // atlanarak yazılmış token'ları ayrıca topluyoruz (bkz. consonantSkeleton
  // yorumu). TAM EŞLEŞME ile kullanılacak, alt string olarak değil.
  const vowellessTokens = rawTokens.filter(
    (tok) => tok.length >= 4 && !TR_HAS_VOWEL_RE.test(tok),
  );

  const obfuscatedTokens: string[] = [];
  let buffer = "";
  let bufferPieceCount = 0;
  const flushBuffer = () => {
    if (bufferPieceCount >= 2 && buffer.length > 1) obfuscatedTokens.push(buffer);
    buffer = "";
    bufferPieceCount = 0;
  };
  for (const tok of rawTokens) {
    if (tok.length <= 3) {
      buffer += tok;
      bufferPieceCount += 1;
    } else {
      flushBuffer();
    }
  }
  flushBuffer();

  for (const word of compileWordList(wordList, customWords)) {
    // BOUNDARY KONTROLÜ: ` norm ` içine word'ü kelime sınırıyla ara.
    // Wordlist zaten çoğu yaygın çekim biçimini (sikimi, götü, götün,
    // amcığı, yarrağımı...) tek tek içeriyor, dolayısıyla NORMAL yazılmış
    // kelimeler için bu tam-eşleşme kontrolü yeterli ve güvenli.
    if (word.boundary.test(` ${norm} `)) {
      return word.original;
    }

    // OBFUSCATION KONTROLÜ: SADECE harf-harf ayrılmış yazımlarda (yukarıda
    // birleştirilen obfuscatedTokens) ve sadece 4+ karakterli kelimelerde
    // kelimenin BAŞINDA ara.
    //
    // ÖNEMLİ — bu kontrolü normal (bitişik yazılmış) kelimelere UYGULAMIYORUZ
    // artık. Önceden her token'da (obfuscated olsun olmasın) substring/prefix
    // aranıyordu; bu da tamamen farklı köklerin sırf ilk birkaç harfi
    // örtüştüğü için yanlışlıkla eşleşmesine yol açıyordu. Örnek: "götü"
    // (küfür, göt+ü) yasaklı kelimesi, "götürecekleri" (götürmek fiilinden,
    // "getirecekleri" anlamında tamamen masum) kelimesinin başında aynen
    // geçiyor — iki kelimenin hiçbir anlamsal ilgisi yok, sadece tesadüfen
    // aynı 4 harfle başlıyorlar. "arayarak" (aramak fiilinden) da aynı
    // şekilde "yarak" ile bitiyor ama alakasız. Bu tür rastgele harf
    // çakışmaları normal kelimelerde çok sık olduğundan (ve wordlist zaten
    // gerçek çekim biçimlerini elle listelediğinden), obfuscation kontrolünü
    // yalnızca GERÇEKTEN harf-harf ayrılmış yazıma (bariz kaçırma girişimi)
    // özgüledik. Bu, kullanıcıların bahsettiği "masum cümleleri engelleme"
    // bug'ının kök nedeniydi.
    if (word.flat.length >= 4) {
      for (const tok of obfuscatedTokens) {
        if (tok.length >= word.flat.length && tok.startsWith(word.flat)) {
          return word.original;
        }
      }
    }

    // SESLİ HARFSİZ KISALTMA KONTROLÜ: "sus lan yrrk" -> "yrrk" token'ı
    // "yarrak" kelimesinin ünsüz iskeletiyle (yrrk) TAM eşleşiyorsa yakala.
    // Alt string DEĞİL, tam eşleşme — bu yüzden iskeleti "yrrk" olan başka
    // bir kelimenin parçası olarak rastgele geçmesi söz konusu değil.
    if (word.skeleton) {
      for (const tok of vowellessTokens) {
        if (tok === word.skeleton) {
          return word.original;
        }
      }
    }

    // ÖZEL KELİME ÖNEK KONTROLÜ: `!otomod kelime-ekle` ile eklenen kelimeler
    // için, admin sadece TEK bir kök yazar (varsayılan listedeki gibi tüm
    // Türkçe çekim biçimleri elle girilmemiştir). Türkçe sondan eklemeli
    // (agglutinative) bir dil olduğu için gerçek kullanımların neredeyse
    // tamamı bir ek taşır ("aptal" -> "aptalsın", "aptalmışsın", "aptalca"
    // gibi) ve bu ekler boşluksuz bitişik yazılır — yani yukarıdaki BOUNDARY
    // kontrolü (kelimenin TEK BAŞINA olmasını ister) bu durumların hiçbirini
    // yakalayamaz. Bu yüzden özel kelimeler için ayrıca "bir token bu
    // kelimeyle BAŞLIYOR mu" kontrolü yapılır. Sadece 4+ karakterli özel
    // kelimelerde uygulanır (kısa köklerde rastgele önek çakışması riski
    // çok yüksek olurdu — ör. 3 harfli bir kelime yüzlerce alakasız
    // kelimenin başında çıkabilir).
    if (word.isCustom && word.flat.length >= 4) {
      for (const tok of rawTokens) {
        if (tok.length > word.flat.length && tok.startsWith(word.flat)) {
          return word.original;
        }
      }
    }
  }
  return null;
}

// --- Muafiyet kontrolü ---
// Kural: sunucu Administrator (yönetici) yetkisine sahip kişiler, bot sahibi
// (owner) ve sunucu tarafından `!otomod rol-izin @rol` ile açıkça muaf
// tutulan rollere sahip üyeler otomodun dışında tutulur.

// Bot sahibi: yetkisi ne olursa olsun otomodun asla etkilemeyeceği kişi.

function isExempt(member: GuildMember, exemptRoleIds: string[], guildOwnerId: string): boolean {
  if (member.id === OWNER_ID) return true;
  if (member.id === guildOwnerId) return true; // Sunucu sahibi muaf
  // Admin muafiyeti kaldırıldı - yöneticiler de küfür engeline tabi
  if (exemptRoleIds.some((id) => member.roles.cache.has(id))) return true;
  return false;
}

// --- Ana giriş noktası: messageCreate event'inden çağrılır ---
// Döndürdüğü `true`, mesajın silindiği ve bir ihlal işlendiği anlamına gelir;
// bunu çağıran taraf komut işlemeyi atlamak için kullanabilir.
export async function handleAutoModMessage(message: Message): Promise<boolean> {
  if (!message.guild || !message.member || message.author.bot) return false;
  if (!message.content) return false;

  const cfg = await getGuildConfig(message.guild.id);
  if (!cfg.enabled) return false;

  if (isExempt(message.member, cfg.exemptRoleIds, message.guild.ownerId)) {
    return false;
  }

  let reason: string | null = null;
  let detail = "";

  if (cfg.bannedWords) {
    const { words: wordList, customWords } = await getEffectiveWordList(message.guild.id);
    const hit = containsBannedWord(message.content, wordList, customWords);
    if (hit) {
      reason = "Yasaklı kelime";
      detail = `Tespit edilen ifade sansürlendi.`;
      // DEBUG: Ne trigger'ladığını görmek için
      console.log(
        `[AUTOMOD TRIGGER] Guild: ${message.guild.id}, User: ${message.author.username} (${message.author.id}), ` +
        `Banned word: "${hit}", Message: "${message.content.slice(0, 200)}"`,
      );
    }
  }

  if (
    !reason &&
    cfg.inviteLinks &&
    !cfg.inviteAllowedChannelIds.includes(message.channel.id) &&
    INVITE_REGEX.test(message.content)
  ) {
    reason = "Discord davet linki";
    detail = "Sunucuda davet linki paylaşımı yasak.";
  }

  const explicitMentionCount = countExplicitMentions(message.content);
  if (!reason && cfg.spamFlood && explicitMentionCount > 0) {
    const mentionSpam = trackAndCheckMentionSpam(
      message.guild.id,
      message.author.id,
      explicitMentionCount,
    );
    if (mentionSpam) {
      reason = "Etiket spam (mention flood)";
      detail = `Kısa sürede çok fazla kullanıcı etiketlendi.`;
    }
  }

  if (!reason && cfg.spamFlood) {
    const flood = trackAndCheckFlood(
      message.guild.id,
      message.author.id,
      message.content,
    );
    if (flood === "flood") {
      reason = "Flood (hızlı ardışık mesaj)";
      detail = "Kısa sürede çok fazla mesaj gönderildi.";
    } else if (flood === "duplicate") {
      reason = "Spam (aynı mesajın tekrarı)";
      detail = "Aynı mesaj kısa sürede birden çok kez gönderildi.";
    }
  }

  if (!reason) return false;

  // Mesajı sil
  try {
    await message.delete();
  } catch {
    // mesaj zaten silinmiş olabilir, sorun değil
  }

  const strike = await addStrike(message.guild.id, message.author.id);
  const willTimeout = strike.count >= cfg.strikesBeforeTimeout;

  let timeoutLabel: string | null = null;
  let timeoutFailed = false;
  if (willTimeout && message.member.moderatable) {
    const escalation = strike.count - cfg.strikesBeforeTimeout; // 0,1,2,...
    // Süre, sunucunun `!otomod sure` ile ayarladığı başlangıç süresinden
    // (cfg.baseTimeoutMinutes) başlayıp her yeni ihlalde katlanarak artar,
    // `!otomod ust-sinir` ile ayarlanan üst sınırı (cfg.maxTimeoutMinutes) geçmez.
    // ÖNEMLİ — önceden burada sabit kodlanmış [1,2,4,6,8,16] dizisi kullanılıyordu;
    // bu da `!otomod sure`/`!otomod ust-sinir` ile yapılan sunucuya özel ayarların
    // panelde görünüp fiilen hiçbir etkisi olmamasına yol açan bir bug'dı.
    const minutes = Math.min(
      cfg.baseTimeoutMinutes * Math.pow(2, escalation),
      cfg.maxTimeoutMinutes,
    );
    try {
      await message.member.timeout(
        minutes * 60_000,
        `Otomod: ${strike.count}. ihlal (${reason})`,
      );
      timeoutLabel = `${minutes} dakika susturma`;
    } catch (err) {
      console.error("⚠️ Otomod timeout uygulanamadı:", err);
      timeoutFailed = true;
    }
  } else if (willTimeout) {
    // moderatable=false: hedef botun rolünden eşit/üstte ya da sunucu
    // sahibi. Eskiden bu durumda kullanıcıya sanki eşik hiç aşılmamış gibi
    // "x/y uyarı" gösteriliyordu — oysa timeout GEREKLİYDİ ama uygulanamadı.
    // Moderatörlerin bunu fark edip manuel müdahale edebilmesi için ayrı
    // ve açık bir durum olarak işaretliyoruz.
    console.error(
      `⚠️ Otomod timeout uygulayamadı (yetki/rol hiyerarşisi): ${message.author.id} @ ${message.guild.id}`,
    );
    timeoutFailed = true;
  }

  // Kanalda basit bir uyarı göster
  try {
    const message_text = timeoutLabel
      ? `<a:suiti:1540384843551088760> **${message.author}** • ${reason} | ${timeoutLabel}`
      : timeoutFailed
        ? `<a:uyari:1540384826782130257> **${message.author}** • ${reason} | ${strike.count}. ihlal — susturma uygulanamadı (yetki/rol), moderatör müdahalesi gerekebilir`
        : `<a:uyari:1540384826782130257> **${message.author}** • ${reason} | ${strike.count}/${cfg.strikesBeforeTimeout} uyarı`;

    if (message.channel.isSendable()) {
      const sent = await message.channel.send(message_text);
      setTimeout(() => sent.delete().catch(() => {}), 6_000);
    }
  } catch (err) {
    console.error("⚠️ Otomod kanal uyarısı gönderilemedi:", err);
  }

  // Log kanalına detaylı kayıt — kanalda uyarı mesajı atılamasa bile
  // (yukarıdaki isSendable() false ise) bu kayıt YİNE DE düşmeli; eskiden
  // erken `return true` yüzünden böyle durumlarda ihlal hiç loglanmıyordu.
  if (cfg.logChannelId) {
    try {
      const logChannel = await message.guild.channels.fetch(cfg.logChannelId);
      if (logChannel?.isTextBased()) {
        const logEmbed = new EmbedBuilder()
          .setColor(timeoutLabel ? 0xed4245 : timeoutFailed ? 0x992d22 : 0xf4a017)
          .setTitle("🛡️ Otomod İşlemi")
          .addFields(
            { name: "Kullanıcı", value: `${message.author} (${message.author.id})`, inline: true },
            { name: "Kanal", value: `${message.channel}`, inline: true },
            { name: "Sebep", value: reason, inline: true },
            { name: "Detay", value: detail || "-", inline: false },
            { name: "İhlal sayısı", value: `${strike.count}`, inline: true },
            {
              name: "İşlem",
              value: timeoutLabel ?? (timeoutFailed ? "⚠️ Susturma GEREKLİYDİ ama uygulanamadı (yetki/rol)" : "Sadece silme + uyarı"),
              inline: true,
            },
            { name: "Mesaj içeriği", value: message.content.slice(0, 1000) || "-", inline: false },
          )
          .setTimestamp();
        await (logChannel as TextChannel).send({ embeds: [logEmbed] });
      }
    } catch (err) {
      console.error("⚠️ Otomod log kanalına yazılamadı:", err);
    }
  }

  return true;
}
","automod/store.ts":"import { eq } from "drizzle-orm";
import { db, pool, automodConfigTable, automodStrikesTable } from "../db/index.js";
import { ALL_DEFAULT_BANNED_WORDS } from "./wordlist.js";

export interface GuildAutomodConfig {
  enabled: boolean;
  bannedWords: boolean;
  inviteLinks: boolean;
  spamFlood: boolean;
  wordList: string[]; // varsayılan listeye ek olarak sunucuya özel kelimeler
  removedDefaults: string[]; // varsayılan listeden çıkarılmış kelimeler
  inviteAllowedChannelIds: string[]; // bu kanallarda davet linki kontrolü uygulanmaz (ör. #partner)
  exemptRoleIds: string[]; // bu rollerden birine sahip üyeler otomodun tamamından muaf (admin/owner gibi)
  logChannelId: string | null;
  strikesBeforeTimeout: number;
  baseTimeoutMinutes: number;
  maxTimeoutMinutes: number;
  strikeResetMinutes: number;
}

const MAX_CUSTOM_WORDS = 500;
const MAX_WORD_LENGTH = 64;

const DEFAULTS: GuildAutomodConfig = {
  enabled: true,
  bannedWords: true,
  inviteLinks: false,
  spamFlood: true,
  wordList: [],
  removedDefaults: [],
  inviteAllowedChannelIds: [],
  exemptRoleIds: [],
  logChannelId: null,
  strikesBeforeTimeout: 3,
  baseTimeoutMinutes: 1,
  maxTimeoutMinutes: 60,
  strikeResetMinutes: 30,
};

function safeParseArray(raw: string | null | undefined): string[] {
  if (!raw) return [];
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed)
      ? [...new Set(parsed
          .filter((x): x is string => typeof x === "string")
          .map((x) => x.trim().slice(0, MAX_WORD_LENGTH))
          .filter(Boolean))].slice(0, MAX_CUSTOM_WORDS)
      : [];
  } catch {
    return [];
  }
}

function boundedInteger(value: number, fallback: number, min: number, max: number): number {
  return Number.isInteger(value) ? Math.min(max, Math.max(min, value)) : fallback;
}

function rowToConfig(row: typeof automodConfigTable.$inferSelect): GuildAutomodConfig {
  const baseTimeoutMinutes = boundedInteger(row.baseTimeoutMinutes, DEFAULTS.baseTimeoutMinutes, 1, 40_320);
  const maxTimeoutMinutes = boundedInteger(row.maxTimeoutMinutes, DEFAULTS.maxTimeoutMinutes, baseTimeoutMinutes, 40_320);
  return {
    enabled: row.enabled,
    bannedWords: row.bannedWords,
    inviteLinks: row.inviteLinks,
    spamFlood: row.spamFlood,
    wordList: safeParseArray(row.wordList),
    removedDefaults: safeParseArray(row.removedDefaults),
    inviteAllowedChannelIds: safeParseArray(row.inviteAllowedChannelIds),
    exemptRoleIds: safeParseArray(row.exemptRoleIds),
    logChannelId: row.logChannelId,
    strikesBeforeTimeout: boundedInteger(row.strikesBeforeTimeout, DEFAULTS.strikesBeforeTimeout, 1, 100),
    baseTimeoutMinutes,
    maxTimeoutMinutes,
    strikeResetMinutes: boundedInteger(row.strikeResetMinutes, DEFAULTS.strikeResetMinutes, 1, 10_080),
  };
}

// Küçük bir bellek-içi cache: her mesajda DB'ye gitmemek için. updateGuildConfig
// çağrıldığında cache güncellenir; başka bir process'ten değişirse en geç
// CACHE_TTL_MS sonra fark edilir.
const cache = new Map<string, { cfg: GuildAutomodConfig; ts: number }>();
const CACHE_TTL_MS = 30_000;
const effectiveWordCache = new Map<string, { cfg: GuildAutomodConfig; words: string[]; customWords: Set<string> }>();
const configLoads = new Map<string, Promise<GuildAutomodConfig>>();
const configUpdateQueues = new Map<string, Promise<GuildAutomodConfig>>();

/** Bot açılışında çağrılır; ilk mesaj/komut DB sorgusunu beklemez. */
export async function warmAutomodConfigCache(): Promise<void> {
  const rows = await db.select().from(automodConfigTable);
  const timestamp = Date.now();
  for (const row of rows) cache.set(row.guildId, { cfg: rowToConfig(row), ts: timestamp });
}

async function loadGuildConfig(guildId: string): Promise<GuildAutomodConfig> {
  const rows = await db
    .select()
    .from(automodConfigTable)
    .where(eq(automodConfigTable.guildId, guildId));

  let cfg: GuildAutomodConfig;
  if (rows[0]) {
    cfg = rowToConfig(rows[0]);
  } else {
    await db.insert(automodConfigTable).values({ guildId }).onConflictDoNothing();
    cfg = { ...DEFAULTS };
  }
  cache.set(guildId, { cfg, ts: Date.now() });
  effectiveWordCache.delete(guildId);
  return cfg;
}

export async function getGuildConfig(guildId: string): Promise<GuildAutomodConfig> {
  const cached = cache.get(guildId);
  if (cached) {
    // Mesaj/komut yolunu DB gecikmesine bağlama. Süresi dolmuş ayar güvenle
    // kullanılmaya devam eder; yenileme arka planda yapılır.
    if (Date.now() - cached.ts >= CACHE_TTL_MS && !configLoads.has(guildId)) {
      const refresh = loadGuildConfig(guildId).catch((error: unknown) => {
        console.error(`[AUTOMOD] Ayar yenileme başarısız (${guildId}):`, error);
        return cached.cfg;
      }).finally(() => {
        if (configLoads.get(guildId) === refresh) configLoads.delete(guildId);
      });
      configLoads.set(guildId, refresh);
    }
    return cached.cfg;
  }

  const inFlight = configLoads.get(guildId);
  if (inFlight) return inFlight;
  const load = loadGuildConfig(guildId).finally(() => {
    if (configLoads.get(guildId) === load) configLoads.delete(guildId);
  });
  configLoads.set(guildId, load);
  return load;
}

export function updateGuildConfig(
  guildId: string,
  patch: Partial<GuildAutomodConfig>,
): Promise<GuildAutomodConfig> {
  const previous = configUpdateQueues.get(guildId);
  const base = previous ? previous.catch(() => getGuildConfig(guildId)) : getGuildConfig(guildId);
  let update!: Promise<GuildAutomodConfig>;
  update = base.then(async (current) => {
    const merged: GuildAutomodConfig = { ...current, ...patch };
    merged.maxTimeoutMinutes = Math.max(merged.baseTimeoutMinutes, merged.maxTimeoutMinutes);
    const values = {
      guildId,
      enabled: merged.enabled,
      bannedWords: merged.bannedWords,
      inviteLinks: merged.inviteLinks,
      spamFlood: merged.spamFlood,
      wordList: JSON.stringify(merged.wordList),
      removedDefaults: JSON.stringify(merged.removedDefaults),
      inviteAllowedChannelIds: JSON.stringify(merged.inviteAllowedChannelIds),
      exemptRoleIds: JSON.stringify(merged.exemptRoleIds),
      logChannelId: merged.logChannelId,
      strikesBeforeTimeout: merged.strikesBeforeTimeout,
      baseTimeoutMinutes: merged.baseTimeoutMinutes,
      maxTimeoutMinutes: merged.maxTimeoutMinutes,
      strikeResetMinutes: merged.strikeResetMinutes,
      updatedAt: new Date(),
    };

    await db
      .insert(automodConfigTable)
      .values(values)
      .onConflictDoUpdate({ target: automodConfigTable.guildId, set: values });

    cache.set(guildId, { cfg: merged, ts: Date.now() });
    effectiveWordCache.delete(guildId);
    return merged;
  });
  configUpdateQueues.set(guildId, update);
  void update.then(
    () => { if (configUpdateQueues.get(guildId) === update) configUpdateQueues.delete(guildId); },
    () => { if (configUpdateQueues.get(guildId) === update) configUpdateQueues.delete(guildId); },
  );
  return update;
}

export interface EffectiveWordList {
  words: string[];
  // Sunucuya özel `!otomod kelime-ekle` ile eklenmiş kelimeler. Varsayılan
  // listeden farklı olarak bunlar için TÜM Türkçe çekim biçimleri elle
  // girilmemiştir (admin sadece tek bir kök/kelime yazar) — bu yüzden
  // automod.ts bu kelimeler için ekstra bir "önek eşleşmesi" uygular
  // (bkz. containsBannedWord). Bkz. addStrike/handleAutoModMessage.
  customWords: Set<string>;
}

export async function getEffectiveWordList(guildId: string): Promise<EffectiveWordList> {
  const cfg = await getGuildConfig(guildId);
  const cached = effectiveWordCache.get(guildId);
  if (cached?.cfg === cfg) return { words: cached.words, customWords: cached.customWords };

  // Türkçe + İngilizce + Rusça (latin translit) varsayılan listeler wordlist.ts'de
  // birleştirilip export ediliyor. removedDefaults, bu birleşik listenin
  // herhangi bir kelimesini o sunucu için etkisiz kılmak için kullanılabilir.
  const base = ALL_DEFAULT_BANNED_WORDS.filter((w) => !cfg.removedDefaults.includes(w));
  const words = [...new Set([...base, ...cfg.wordList])];
  const customWords = new Set(cfg.wordList);
  effectiveWordCache.set(guildId, { cfg, words, customWords });
  return { words, customWords };
}

// --- Strike (ihlal sayacı) yönetimi ---

export interface StrikeData {
  count: number;
  lastViolation: number; // epoch ms
}

export async function getStrike(guildId: string, userId: string): Promise<StrikeData> {
  const key = `${guildId}:${userId}`;
  const cfg = await getGuildConfig(guildId);
  const rows = await db
    .select()
    .from(automodStrikesTable)
    .where(eq(automodStrikesTable.key, key));

  const row = rows[0];
  if (!row) return { count: 0, lastViolation: 0 };

  const lastViolationMs = row.lastViolation.getTime();
  const expired = Date.now() - lastViolationMs > cfg.strikeResetMinutes * 60_000;
  if (expired) {
    await db.delete(automodStrikesTable).where(eq(automodStrikesTable.key, key));
    return { count: 0, lastViolation: 0 };
  }
  return { count: row.count, lastViolation: lastViolationMs };
}

export async function addStrike(guildId: string, userId: string): Promise<StrikeData> {
  const key = `${guildId}:${userId}`;
  const cfg = await getGuildConfig(guildId);

  // The old read-then-write sequence lost strikes when two messages arrived
  // in the same event-loop tick. Do the increment atomically in PostgreSQL
  // and reset an expired counter in the same statement.
  const result = await pool.query<{ count: number; last_violation: Date | string }>(
    `
      INSERT INTO discord_automod_strikes
        (key, guild_id, user_id, count, last_violation)
      VALUES ($1, $2, $3, 1, NOW())
      ON CONFLICT (key) DO UPDATE SET
        count = CASE
          WHEN discord_automod_strikes.last_violation <
            NOW() - ($4 * INTERVAL '1 minute')
          THEN 1
          ELSE discord_automod_strikes.count + 1
        END,
        last_violation = NOW()
      RETURNING count, last_violation
    `,
    [key, guildId, userId, Math.max(1, cfg.strikeResetMinutes)],
  );

  const row = result.rows[0];
  if (!row) {
    // This should be impossible with RETURNING, but keeping the failure
    // explicit is safer than returning a made-up strike count.
    throw new Error("Otomod ihlali kaydı oluşturulamadı.");
  }
  return {
    count: Number(row.count),
    lastViolation: new Date(row.last_violation).getTime(),
  };
}

export async function resetStrikes(guildId: string, userId: string): Promise<void> {
  await db.delete(automodStrikesTable).where(eq(automodStrikesTable.key, `${guildId}:${userId}`));
}
","automod/wordlist.ts":"// Otomod — varsayılan (default) yasaklı kelime listeleri.
//
// Bu dosya SADECE varsayılanları tutar ve tüm sunucular için ortaktır.
// Sunucuya özel ekleme/çıkarma burada DEĞİL, veritabanında tutulur:
//   - "!otomod kelime-ekle" -> guild config'in wordList alanına eklenir
//   - "!otomod kelime-sil"  -> guild config'in wordList alanından silinir,
//                              varsayılan listedeyse removedDefaults'a eklenir
