","commands/afk.ts":"import type { Message } from "discord.js";
import type { Command } from "../types.js";
import { EMOJIS } from "../utils/emojis.js";
import { setAfk } from "../afk/store.js";

// Aynı mesajın tekrar tekrar görünmemesi için birkaç yumuşak varyasyon.
const AFK_SET_TEMPLATES: ((user: string, reason: string) => string)[] = [
  (user, reason) => `${EMOJIS.afkSet} Tamamdır ${user}, seni AFK olarak işaretledim, sebep; **${reason}**`,
  (user, reason) => `${EMOJIS.afkSet} Oldu ${user}, artık AFK görünüyorsun, sebep; **${reason}**`,
  (user, reason) => `${EMOJIS.afkSet} Anlaşıldı ${user}, AFK moduna aldım seni, sebep; **${reason}**`,
  (user, reason) => `${EMOJIS.afkSet} Notu aldım ${user}, AFK olarak işaretlendin, sebep; **${reason}**`,
];

const command: Command = {
  name: "afk",
  aliases: ["uzakta"],
  description: "AFK (uzakta) durumuna geçer — seni etiketleyenlere otomatik bilgi verilir",
  usage: "!afk [sebep]",
  category: "genel",

  async execute(message: Message, args: string[]) {
    const reason = args.join(" ").trim() || "belirtilmedi";
    await setAfk(message.author.id, reason);
    const template = AFK_SET_TEMPLATES[Math.floor(Math.random() * AFK_SET_TEMPLATES.length)];
    return message.reply({ content: template(`${message.author}`, reason), allowedMentions: { repliedUser: false } });
  },
};

export default command;
","commands/bilgi.ts":"import { EmbedBuilder, type GuildMember, type Message } from "discord.js";
import type { Command } from "../types.js";
import { COLORS } from "../utils/embeds.js";
import { errorEmbed } from "../utils/embeds.js";

function formatDate(date: Date): string {
  return date.toLocaleDateString("tr-TR", { day: "2-digit", month: "long", year: "numeric" });
}

const command: Command = {
  name: "bilgi",
  aliases: ["userinfo", "kullanici", "ui"],
  description: "Kendin ya da bir kullanıcı hakkında bilgi gösterir",
  usage: "!bilgi [@kullanıcı]",
  category: "genel",

  async execute(message: Message) {
    if (!message.guild) {
      return message.reply({ embeds: [errorEmbed("Hata", "Bu komut sadece sunucu içinde kullanılabilir.")] });
    }

    const mentioned = message.mentions.members?.first();
    const member: GuildMember = mentioned ?? (message.member as GuildMember);

    const roles = member.roles.cache
      .filter((r) => r.id !== message.guild!.id)
      .sort((a, b) => b.position - a.position)
      .map((r) => `<@&${r.id}>`);

    const embed = new EmbedBuilder()
      .setColor(member.displayHexColor && member.displayHexColor !== "#000000" ? member.displayHexColor : COLORS.info)
      .setTitle(`👤 ${member.user.tag}`)
      .setThumbnail(member.user.displayAvatarURL({ size: 512 }))
      .addFields(
        { name: "Takma ad", value: member.displayName, inline: true },
        { name: "Kullanıcı ID", value: member.id, inline: true },
        { name: "Bot mu?", value: member.user.bot ? "Evet" : "Hayır", inline: true },
        { name: "Hesap oluşturulma", value: formatDate(member.user.createdAt), inline: true },
        { name: "Sunucuya katılma", value: member.joinedAt ? formatDate(member.joinedAt) : "bilinmiyor", inline: true },
        { name: `Roller (${roles.length})`, value: roles.length > 0 ? roles.slice(0, 20).join(", ") : "yok" },
      )
      .setFooter({ text: `İsteyen: ${message.author.tag}` })
      .setTimestamp();

    return message.reply({ embeds: [embed] });
  },
};

export default command;
","commands/custom-sil.ts":"import { EmbedBuilder, type Message } from "discord.js";
import type { Command } from "../types.js";
import { COLORS } from "../utils/embeds.js";
import { EMOJIS } from "../utils/emojis.js";
import { getGuildPrefix, requireOwnerOrGuildOwner } from "../events/messageCreate.js";
import { deleteCustomEvent } from "../customEvents/store.js";

const command: Command = {
  name: "custom-sil",
  aliases: ["customsil", "customevent-sil", "ce-sil"],
  description: "Bu sunucudaki bir custom event'i siler (sadece sunucu sahibi/taç sahibi)",
  usage: "!custom-sil <isim>",
  category: "genel",

  async execute(message: Message, args: string[]) {
    if (!message.guild) {
      return message.reply(`${EMOJIS.error} Bu komut sadece bir sunucu içinde kullanılabilir.`);
    }
    if (!(await requireOwnerOrGuildOwner(message))) return;

    const prefix = getGuildPrefix(message.guild.id);
    const name = (args[0] ?? "").toLowerCase().trim();

    if (!name) {
      return message.reply(`${EMOJIS.usage} Kullanım: \`${prefix}custom-sil <isim>\` (ör. \`${prefix}custom-sil selamla\`)`);
    }

    const deleted = await deleteCustomEvent(message.guild.id, name);

    if (!deleted) {
      return message.reply({
        embeds: [
          new EmbedBuilder()
            .setColor(COLORS.error)
            .setTitle(`${EMOJIS.error} Bulunamadı`)
            .setDescription(`\`${name}\` adında bir custom event yok. \`${prefix}customevent-liste\` ile mevcut olanları görebilirsin.`),
        ],
      });
    }

    return message.reply({
      embeds: [
        new EmbedBuilder()
          .setColor(COLORS.success)
          .setTitle("🗑️ Custom event silindi")
          .setDescription(`\`${name}\` başarıyla silindi.`),
      ],
    });
  },
};

export default command;
","commands/customevent-ayar.ts":"import { EmbedBuilder, type Message } from "discord.js";
import type { Command } from "../types.js";
import { COLORS } from "../utils/embeds.js";
import { EMOJIS } from "../utils/emojis.js";
import { getGuildPrefix, requireOwnerOrGuildOwner } from "../events/messageCreate.js";
import {
  getCustomEvent,
  updateCustomEventSettings,
  type CustomEventRestrictions,
} from "../customEvents/store.js";
import { parseChannelMention, parseMention } from "../utils/parse.js";

const PERMISSIONS = new Set(["ManageMessages", "ManageRoles", "ModerateMembers", "Administrator"]);

function targetId(raw: string | undefined, parser: (value: string) => string | null): string | null {
  return raw ? parser(raw) : null;
}

const command: Command = {
  name: "customevent-ayar",
  aliases: ["customevent-ayarla", "ce-ayar", "custom-ayar"],
  description: "Custom event'i açar/kapatır ve güvenli rol/kanal kısıtlarını düzenler",
  usage: "!customevent-ayar <isim> <işlem> [rol/kanal/izin]",
  category: "genel",

  async execute(message: Message, args: string[]) {
    if (!message.guild) {
      return message.reply(`${EMOJIS.error} Bu komut sadece bir sunucu içinde kullanılabilir.`);
    }
    if (!(await requireOwnerOrGuildOwner(message))) return;

    const prefix = getGuildPrefix(message.guild.id);
    const name = args[0]?.toLowerCase().trim();
    const operation = args[1]?.toLocaleLowerCase("tr-TR");
    const event = name ? await getCustomEvent(message.guild.id, name) : null;

    if (!name || !operation || !event) {
      return message.reply({
        embeds: [
          new EmbedBuilder()
            .setColor(COLORS.warning)
            .setTitle(`${EMOJIS.usage} Custom event ayarı`)
            .setDescription(
              [
                `\`${prefix}customevent-ayar <isim> <işlem> [hedef]\``,
                "",
                "**İşlemler:**",
                "`aç` / `kapat` — event'i etkinleştirir veya durdurur",
                "`rol-ekle` / `rol-sil` — sadece bu rollerde çalıştırır",
                "`rol-yasakla` / `rol-yasak-kaldir` — bu rolleri engeller (deny önceliklidir)",
                "`kanal-ekle` / `kanal-sil` — sadece bu kanallarda çalıştırır",
                "`kanal-yasakla` / `kanal-yasak-kaldir` — kanalları engeller",
                "`izin <ManageMessages|ManageRoles|ModerateMembers|Administrator>` — kullanıcı izni ister",
                "`izin kaldır` — izin şartını kaldırır",
                "`durum` — mevcut kısıtları gösterir",
              ].join("\n"),
            ),
        ],
      });
    }

    const current = event.restrictions;
    const patch: Partial<CustomEventRestrictions> & { enabled?: boolean } = {};
    const id = args[2];

    switch (operation) {
      case "aç":
      case "ac":
        patch.enabled = true;
        break;
      case "kapat":
        patch.enabled = false;
        break;
      case "rol-ekle":
      case "rol-sil":
      case "rol-yasakla":
      case "rol-yasak-kaldir": {
        const roleId = targetId(id, parseMention);
        if (!roleId || !message.guild.roles.cache.has(roleId)) {
          return message.reply(`${EMOJIS.error} Geçerli bir rol mention'ı veya rol ID'si vermelisin.`);
        }
        const isAllow = operation === "rol-ekle" || operation === "rol-sil";
        const field = isAllow ? "allowedRoleIds" : "deniedRoleIds";
        const values = new Set(current[field]);
        if (operation.endsWith("sil") || operation.endsWith("kaldir")) values.delete(roleId);
        else values.add(roleId);
        patch[field] = [...values];
        break;
      }
      case "kanal-ekle":
      case "kanal-sil":
      case "kanal-yasakla":
      case "kanal-yasak-kaldir": {
        const channelId = targetId(id, parseChannelMention);
        if (!channelId || !message.guild.channels.cache.has(channelId)) {
          return message.reply(`${EMOJIS.error} Geçerli bir kanal mention'ı veya kanal ID'si vermelisin.`);
        }
        const isAllow = operation === "kanal-ekle" || operation === "kanal-sil";
        const field = isAllow ? "allowedChannelIds" : "deniedChannelIds";
        const values = new Set(current[field]);
        if (operation.endsWith("sil") || operation.endsWith("kaldir")) values.delete(channelId);
        else values.add(channelId);
        patch[field] = [...values];
        break;
      }
      case "izin": {
        const permission = id === "kaldır" || id === "kaldir" ? null : id;
        if (permission !== null && (!permission || !PERMISSIONS.has(permission))) {
          return message.reply(`${EMOJIS.error} İzin şunlardan biri olmalı: ${[...PERMISSIONS].join(", ")}.`);
        }
        patch.requiredPermission = permission;
        break;
      }
      case "durum":
        return message.reply({
          embeds: [
            new EmbedBuilder()
              .setColor(COLORS.info)
              .setTitle(`Custom event: ${event.name}`)
              .setDescription(
                [
                  `Durum: ${event.enabled ? "açık" : "kapalı"}`,
                  `Gerekli izin: ${current.requiredPermission ?? "yok"}`,
                  `İzin verilen roller: ${current.allowedRoleIds.length ? current.allowedRoleIds.map((value) => `<@&${value}>`).join(", ") : "hepsi"}`,
                  `Yasaklı roller: ${current.deniedRoleIds.length ? current.deniedRoleIds.map((value) => `<@&${value}>`).join(", ") : "yok"}`,
                  `İzin verilen kanallar: ${current.allowedChannelIds.length ? current.allowedChannelIds.map((value) => `<#${value}>`).join(", ") : "hepsi"}`,
                  `Yasaklı kanallar: ${current.deniedChannelIds.length ? current.deniedChannelIds.map((value) => `<#${value}>`).join(", ") : "yok"}`,
                ].join("\n"),
              ),
          ],
        });
      default:
        return message.reply(`${EMOJIS.error} Bilinmeyen işlem. Yardım için \`${prefix}customevent-ayar\` yaz.`);
    }

    const updated = await updateCustomEventSettings(message.guild.id, event.name, patch);
    if (!updated) return message.reply(`${EMOJIS.error} Custom event artık bulunamadı.`);
    return message.reply({
      embeds: [
        new EmbedBuilder()
          .setColor(COLORS.success)
          .setTitle(`${EMOJIS.success} Ayar güncellendi`)
          .setDescription(`\`${event.name}\` custom event ayarı başarıyla güncellendi.`),
      ],
    });
  },
};

export default command;","commands/customevent-liste.ts":"import { EmbedBuilder, type Message } from "discord.js";
