","commands/fun/bilgiyarismasi.ts":"import {
  ActionRowBuilder,
  ButtonBuilder,
  ButtonStyle,
  ComponentType,
  EmbedBuilder,
  type Message,
} from "discord.js";
import type { Command } from "../../types.js";
import { DEFAULT_PREFIX } from "../../config.js";
import { COLORS } from "../../utils/embeds.js";
import { generateWithGemini } from "../../utils/gemini.js";
import { requirePremiumOrTrial } from "../../premium/gate.js";
import { addQuizWin } from "../../utils/quizStore.js";

// !bilgiyarismasi [kategori] — Gemini'ye çoktan seçmeli bir bilgi yarışması
// sorusu ürettirip 4 butonla (A/B/C/D) sunucuda "kim önce doğru bilecek"
// yarışması başlatır. İlk doğru cevaplayan sunucu skoruna 1 galibiyet
// yazdırır (bkz. utils/quizStore.ts).

const QUESTION_TIME_MS = 30_000;
const LETTERS = ["A", "B", "C", "D"] as const;

// Aynı kanalda aynı anda birden fazla yarışma başlamasını önler — hem
// karışıklığı hem de gereksiz Gemini isteklerini engeller.
const activeChannels = new Set<string>();

const SYSTEM_PROMPT = `Sen bir Discord bilgi yarışması sorusu üreten bir asistansın.
Kullanıcının verdiği konu/kategoriye uygun, TEK bir çoktan seçmeli soru üret.

KURALLAR:
- Soru Türkçe olmalı, orta zorlukta, doğrulanabilir/genel kültür niteliğinde bir bilgi içermeli.
- Tam olarak 4 şık üret. Şıklar birbirinden açıkça farklı ve makul uzunlukta olmalı.
- Şıklardan SADECE BİRİ doğru olmalı, diğerleri gerçekten yanlış olmalı (belirsiz/tartışmalı sorulardan kaçın).
- Cevabını SADECE aşağıdaki JSON formatında ver, başka HİÇBİR metin ekleme (açıklama, markdown kod bloğu, giriş cümlesi YOK):
{"soru": "...", "secenekler": ["...", "...", "...", "..."], "dogruIndex": 0}
- "dogruIndex" 0-3 arası bir tam sayı olmalı ve "secenekler" dizisindeki doğru şıkkın index'ini göstermeli.`;

function isQuizRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

interface QuizQuestion {
  soru: string;
  secenekler: [string, string, string, string];
  dogruIndex: 0 | 1 | 2 | 3;
}

function parseQuizJson(raw: string): QuizQuestion | null {
  // Gemini bazen ```json ... ``` kod bloğuna sarabiliyor — buna karşı toleranslı ol.
  const stripped = raw.trim().replace(/^```(?:json)?/i, "").replace(/```$/, "").trim();
  let parsed: unknown;
  try {
    parsed = JSON.parse(stripped);
  } catch {
    return null;
  }
  if (
    !isQuizRecord(parsed) ||
    typeof parsed.soru !== "string" ||
    !Array.isArray(parsed.secenekler) ||
    parsed.secenekler.length !== 4 ||
    !parsed.secenekler.every((s: unknown) => typeof s === "string" && s.trim().length > 0) ||
    typeof parsed.dogruIndex !== "number" ||
    !Number.isInteger(parsed.dogruIndex) ||
    parsed.dogruIndex < 0 ||
    parsed.dogruIndex > 3
  ) {
    return null;
  }
  return {
    soru: parsed.soru.trim(),
    secenekler: parsed.secenekler.map((s: string) => s.trim()) as [string, string, string, string],
    dogruIndex: parsed.dogruIndex as 0 | 1 | 2 | 3,
  };
}

function questionEmbed(q: QuizQuestion, secondsLeft: number, revealed: false | number, winner?: string) {
  const embed = new EmbedBuilder()
    .setColor(revealed === false ? COLORS.info : COLORS.success)
    .setTitle("🧠 Bilgi Yarışması")
    .setDescription(q.soru)
    .addFields(
      q.secenekler.map((opt, i) => ({
        name: `${LETTERS[i]}${revealed !== false && i === q.dogruIndex ? " ✅" : ""}`,
        value: opt,
        inline: false,
      })),
    )
    .setFooter({ text: revealed === false ? `${secondsLeft} saniyen var — doğru cevabı ilk tıklayan kazanır!` : "Bilgi Yarışması" })
    .setTimestamp();
  if (winner) {
    embed.addFields({ name: "🏆 Kazanan", value: winner, inline: false });
  } else if (revealed !== false) {
    embed.addFields({ name: "😶 Sonuç", value: "Süre doldu, kimse doğru bilemedi.", inline: false });
  }
  return embed;
}

function buildButtons(disabled: boolean): ActionRowBuilder<ButtonBuilder>[] {
  const row = new ActionRowBuilder<ButtonBuilder>().addComponents(
    LETTERS.map((letter, i) =>
      new ButtonBuilder()
        .setCustomId(`quiz_answer_${i}`)
        .setLabel(letter)
        .setStyle(ButtonStyle.Primary)
        .setDisabled(disabled),
    ),
  );
  return [row];
}

const command: Command = {
  name: "bilgiyarismasi",
  aliases: ["quiz", "yarisma", "bilgiyarışması"],
  description: "Gemini destekli çoktan seçmeli bilgi yarışması başlatır",
  usage: `${DEFAULT_PREFIX}bilgiyarismasi [konu]`,
  category: "fun",

  async execute(message: Message, args: string[]) {
    if (!message.guild || !message.channel.isSendable()) return;

    if (activeChannels.has(message.channel.id)) {
      return message.reply("<a:1000021813:1540389526873317518> Bu kanalda zaten devam eden bir yarışma var, önce onun bitmesini bekle.");
    }

    if (!(await requirePremiumOrTrial(message, "bilgiyarismasi"))) return;

    const topic = args.join(" ").trim() || "genel kültür";

    activeChannels.add(message.channel.id);
    const loadingMsg = await message
      .reply(`<a:1000021907:1540738818297303111> \`${topic}\` konusunda bir soru hazırlanıyor...`)
      .catch(() => null);

    try {
      let question: QuizQuestion | null = null;
      // Gemini bazen JSON dışı bir şey döndürebilir — bir kez daha deniyoruz,
      // yine olmazsa kullanıcıya açıkça hata gösteriyoruz (sessizce yutmuyoruz).
      for (let attempt = 0; attempt < 2 && !question; attempt++) {
        const raw = await generateWithGemini(SYSTEM_PROMPT, `Konu: ${topic}`);
        question = parseQuizJson(raw);
      }

      if (!question) {
        await loadingMsg
          ?.edit("<a:1000021813:1540389526873317518> Soru üretilemedi (Gemini geçersiz bir cevap verdi), tekrar dene.")
          .catch(() => null);
        return;
      }

      const q = question;
      const secondsLeft = Math.floor(QUESTION_TIME_MS / 1000);
      const quizMsg = await (loadingMsg
        ? loadingMsg.edit({ content: "", embeds: [questionEmbed(q, secondsLeft, false)], components: buildButtons(false) })
        : message.channel.send({ embeds: [questionEmbed(q, secondsLeft, false)], components: buildButtons(false) }));

      const answeredUsers = new Set<string>();

      const collector = quizMsg.createMessageComponentCollector({
        componentType: ComponentType.Button,
        time: QUESTION_TIME_MS,
      });

      collector.on("collect", (interaction) => {
        void (async () => {
        if (!interaction.customId.startsWith("quiz_answer_")) return;

        // Aynı kullanıcı bir kere yanlış tıklayıp tekrar deneyemesin —
        // her kullanıcının bu soruda tek hakkı var (gerçek yarışma hissi için).
        if (answeredUsers.has(interaction.user.id)) {
          await interaction.reply({ content: "Bu soruda zaten bir hakkını kullandın.", ephemeral: true }).catch(() => null);
          return;
        }
        answeredUsers.add(interaction.user.id);

        const chosenIndex = Number(interaction.customId.replace("quiz_answer_", ""));
        const correct = chosenIndex === q.dogruIndex;

        if (!correct) {
          await interaction.reply({ content: "❌ Yanlış cevap, başkası dener.", ephemeral: true }).catch(() => null);
          return;
        }

        collector.stop("answered");
        await interaction.reply({ content: "✅ Doğru bildin!", ephemeral: true }).catch(() => null);
        await addQuizWin(message.guild!.id, interaction.user.id).catch((err) =>
          console.error("Bilgi yarışması skoru kaydedilemedi:", err),
        );
        await quizMsg
          .edit({ embeds: [questionEmbed(q, 0, q.dogruIndex, `${interaction.user}`)], components: buildButtons(true) })
          .catch(() => null);
        })().catch((error: unknown) => console.error("Bilgi yarışması etkileşim hatası:", error));
      });

      collector.on("end", (_collected, reason) => {
        activeChannels.delete(message.channel.id);
        if (reason === "answered") return; // zaten yukarıda güncellendi
        void quizMsg
          .edit({ embeds: [questionEmbed(q, 0, q.dogruIndex)], components: buildButtons(true) })
          .catch(() => null);
      });
    } catch (err) {
      activeChannels.delete(message.channel.id);
      console.error("bilgiyarismasi hatası:", err);
      await loadingMsg?.edit(`<a:1000021813:1540389526873317518> Hata oluştu: ${err instanceof Error ? err.message : String(err)}`).catch(() => null);
      return;
    }

    return;
  },
};

export default command;
","commands/fun/ceviri.ts":"import { EmbedBuilder, type Message } from "discord.js";
import type { Command } from "../../types.js";
import { DEFAULT_PREFIX } from "../../config.js";
import { getGuildPrefix } from "../../events/messageCreate.js";
import { COLORS } from "../../utils/embeds.js";
import { generateWithGemini } from "../../utils/gemini.js";
import { requirePremiumOrTrial } from "../../premium/gate.js";

// !ceviri <hedef dil> <metin>
// (bir mesaja yanıt vererek) !ceviri <hedef dil>  -> yanıtlanan mesajı çevirir

const MAX_INPUT_CHARS = 8_000;

function buildSystemPrompt(targetLang: string): string {
  return `Sen profesyonel bir çevirmensin. Sana verilen metni "${targetLang}" diline çevireceksin.

KURALLAR:
- SADECE çeviriyi yaz. Açıklama, giriş cümlesi, tırnak işareti ekleme.
- Anlamı ve tonu koru; birebir kelime kelime değil, doğal bir çeviri yap.
- Metnin dilini otomatik algıla, kullanıcı belirtmese de kaynak dili sen anla.
- Metindeki biçimlendirmeyi (satır sonları, madde işaretleri vb.) mümkün olduğunca koru.`;
}

const command: Command = {
  name: "ceviri",
  aliases: ["çeviri", "translate", "cevir"],
  description: "Gemini ile metni istenen dile çevirir",
  usage: `${DEFAULT_PREFIX}ceviri <hedef dil> <metin> (veya bir mesaja yanıt vererek)`,
  category: "fun",

  async execute(message: Message, args: string[]) {
    if (!(await requirePremiumOrTrial(message, "ceviri"))) return;

    const prefix = getGuildPrefix(message.guild?.id);
    const targetLang = args[0]?.trim();
    let text = args.slice(1).join(" ").trim();

    if (!text && message.reference?.messageId) {
      try {
        const replied = await message.fetchReference();
        text = replied.content?.trim() ?? "";
      } catch {
        // yanıtlanan mesaj alınamadı, aşağıdaki kontrol yakalayacak
      }
    }

    if (!targetLang || !text) {
      return message.reply(
        `<a:1000021907:1540738818297303111> Kullanım: \`${prefix}ceviri <hedef dil> <metin>\`\n` +
        `Örnek: \`${prefix}ceviri ingilizce merhaba nasılsın\`\n` +
        `Ya da bir mesaja yanıt vererek: \`${prefix}ceviri ingilizce\``,
      );
    }

    if (text.length > MAX_INPUT_CHARS) {
      return message.reply(`<a:1000021813:1540389526873317518> Metin çok uzun (maks ${MAX_INPUT_CHARS} karakter).`);
    }

    const loadingMsg = await message.reply(`<a:1000021907:1540738818297303111> ${targetLang} diline çevriliyor...`);

    try {
      const translated = await generateWithGemini(buildSystemPrompt(targetLang), text);
      const trimmed = translated.trim().slice(0, 4000);

      if (!trimmed) {
        return loadingMsg.edit("<a:1000021813:1540389526873317518> Gemini bir çeviri üretemedi, tekrar dene.");
      }

      const embed = new EmbedBuilder()
        .setColor(COLORS.success)
        .setTitle(`<a:1000021814:1540389540513194066> Çeviri (${targetLang})`)
        .setDescription(trimmed)
        .setFooter({ text: `İsteyen: ${message.author.tag}` })
        .setTimestamp();

      return loadingMsg.edit({ content: "", embeds: [embed] });
    } catch (err: unknown) {
      console.error("ceviri hatası:", err);
      return loadingMsg.edit(`<a:1000021813:1540389526873317518> Hata oluştu: ${err instanceof Error ? err.message : String(err)}`);
    }
  },
};

export default command;
