","commands/fun/hesapla.ts":"import type { Message } from "discord.js";
import type { Command } from "../../types.js";
import { infoEmbed, errorEmbed } from "../../utils/embeds.js";
import { generateWithGroq } from "../../utils/groq.js";
import { requirePremiumOrTrial } from "../../premium/gate.js";

// Güvenli bir dört işlem hesap makinesi. `eval`/`Function` KULLANILMIYOR —
// kullanıcı girdisi doğrudan JS olarak çalıştırılmaz (uzaktan kod çalıştırma
// riski). Bunun yerine basit bir shunting-yard ile kendi ifade ayrıştırıcımızı
// yazdık: sadece sayılar, + - * / ve parantez destekleniyor.

class ExpressionError extends Error {}

function tokenize(expr: string): string[] {
  const tokens: string[] = [];
  let i = 0;
  while (i < expr.length) {
    const ch = expr[i];
    if (/\s/.test(ch)) {
      i++;
      continue;
    }
    if (/[0-9.]/.test(ch)) {
      let num = "";
      while (i < expr.length && /[0-9.]/.test(expr[i])) num += expr[i++];
      if ((num.match(/\./g) ?? []).length > 1) throw new ExpressionError("Geçersiz sayı formatı.");
      tokens.push(num);
      continue;
    }
    if ("+-*/()".includes(ch)) {
      tokens.push(ch);
      i++;
      continue;
    }
    throw new ExpressionError(`Beklenmeyen karakter: "${ch}"`);
  }
  return tokens;
}

const PRECEDENCE: Record<string, number> = { "+": 1, "-": 1, "*": 2, "/": 2 };

// Shunting-yard: infix -> RPN, sonra RPN'i hesapla. Sadece +,-,*,/ ve
// parantez olduğu için tam bir AST'ye gerek yok.
function toRpn(tokens: string[]): string[] {
  const output: string[] = [];
  const ops: string[] = [];
  let prevToken: string | null = null;

  for (const token of tokens) {
    if (/^[0-9.]+$/.test(token)) {
      output.push(token);
    } else if (token === "(") {
      ops.push(token);
    } else if (token === ")") {
      while (ops.length && ops[ops.length - 1] !== "(") output.push(ops.pop()!);
      if (ops.pop() !== "(") throw new ExpressionError("Parantezler eşleşmiyor.");
    } else {
      // Unary minus/plus desteği: "-5" veya "(-5+2)" gibi durumlar için,
      // bir operatörden hemen sonra veya ifadenin başında gelen +/- işaretini
      // 0'dan çıkarma/ekleme olarak ele alıyoruz.
      const isUnary = token === "-" || token === "+";
      const prevWasOperandOrClose = prevToken !== null && (/^[0-9.]+$/.test(prevToken) || prevToken === ")");
      if (isUnary && !prevWasOperandOrClose) {
        output.push("0");
      }
      while (
        ops.length &&
        ops[ops.length - 1] !== "(" &&
        PRECEDENCE[ops[ops.length - 1]] >= PRECEDENCE[token]
      ) {
        output.push(ops.pop()!);
      }
      ops.push(token);
    }
    prevToken = token;
  }
  while (ops.length) {
    const op = ops.pop()!;
    if (op === "(") throw new ExpressionError("Parantezler eşleşmiyor.");
    output.push(op);
  }
  return output;
}

function evalRpn(rpn: string[]): number {
  const stack: number[] = [];
  for (const token of rpn) {
    if (/^[0-9.]+$/.test(token)) {
      stack.push(Number.parseFloat(token));
      continue;
    }
    const b = stack.pop();
    const a = stack.pop();
    if (a === undefined || b === undefined) throw new ExpressionError("Geçersiz ifade.");
    switch (token) {
      case "+": stack.push(a + b); break;
      case "-": stack.push(a - b); break;
      case "*": stack.push(a * b); break;
      case "/":
        if (b === 0) throw new ExpressionError("Sıfıra bölme yapılamaz.");
        stack.push(a / b);
        break;
      default: throw new ExpressionError(`Bilinmeyen işlem: ${token}`);
    }
  }
  if (stack.length !== 1) throw new ExpressionError("Geçersiz ifade.");
  return stack[0];
}

function safeEvaluate(expr: string): number {
  const tokens = tokenize(expr);
  if (tokens.length === 0) throw new ExpressionError("Boş ifade.");
  const rpn = toRpn(tokens);
  const result = evalRpn(rpn);
  if (!Number.isFinite(result)) throw new ExpressionError("Sonuç hesaplanamadı.");
  return result;
}

const MAX_EXPR_LENGTH = 200;

const AI_SYSTEM_PROMPT = `Sen bir hesap makinesisin. Kullanıcı sana bir matematik ifadesi, kelime problemi \
veya yüzde/oran hesabı verecek. Görevin SADECE sonucu hesaplamak.

KURALLAR:
- Yanıtın SADECE sayısal sonuç olsun (gerekiyorsa kısa birimle, ör. "%25" veya "42.5").
- Açıklama, adım adım çözüm, giriş cümlesi YAZMA — sadece nihai sonucu yaz.
- Sonucu bulamıyorsan veya ifade matematiksel değilse tek kelimeyle "HATA" yaz.
- Ondalık sonuçları makul bir hassasiyette (en fazla 6 basamak) yuvarla.`;

async function evaluateWithAi(expr: string): Promise<string | null> {
  try {
    const answer = await generateWithGroq(AI_SYSTEM_PROMPT, expr, { maxTokens: 200, temperature: 0 });
    const trimmed = answer.trim();
    if (!trimmed || /^hata$/i.test(trimmed)) return null;
    return trimmed;
  } catch (err) {
    console.error("hesapla AI fallback hatası:", err);
    return null;
  }
}

const command: Command = {
  name: "hesapla",
  aliases: ["hesap", "calc"],
  description: "Matematik ifadesini hesaplar; basit işlemler anında, karmaşık/kelime problemleri AI ile çözülür",
  usage: "!hesapla <ifade>  örn: !hesapla (12 + 8) * 3 / 2  |  !hesapla 150'nin %20 fazlası",
  category: "fun",

  async execute(message: Message, args: string[]) {
    const expr = args.join(" ").trim();
    if (!expr) {
      return message.reply({ embeds: [errorEmbed("Eksik Kullanım", `Kullanım: \`${command.usage}\``)] });
    }
    if (expr.length > MAX_EXPR_LENGTH) {
      return message.reply({ embeds: [errorEmbed("Çok Uzun", `İfade en fazla ${MAX_EXPR_LENGTH} karakter olabilir.`)] });
    }

    // Hızlı yol: basit +,-,*,/ ve parantez içeren saf sayısal ifadeler yerel
    // olarak, API'ye hiç gitmeden anında hesaplanır (ücretsiz, sınırsız,
    // gecikmesiz).
    try {
      const result = safeEvaluate(expr);
      const rounded = Math.round(result * 1e9) / 1e9;
      return message.reply({ embeds: [infoEmbed("🧮 Sonuç", `\`${expr}\` = **${rounded}**`)] });
    } catch {
      // Yerel parser bunu anlayamadı (kelime problemi, yüzde, üs, karekök,
      // vb.) — AI'a düşülüyor. Bu yol diğer AI komutları gibi premium/deneme
      // kontrolünden geçer, çünkü API kotası tüketiyor.
      if (!(await requirePremiumOrTrial(message, "hesapla"))) return;

      const loadingMsg = await message.reply("<a:1000021907:1540738818297303111> Hesaplanıyor...");
      const aiResult = await evaluateWithAi(expr);
      if (!aiResult) {
        return loadingMsg.edit({
          content: "",
          embeds: [errorEmbed("Hesaplanamadı", "Bu ifadeyi ne yerel hesap makinesi ne de AI çözebildi. Daha net yazmayı dene.")],
        });
      }
      return loadingMsg.edit({
        content: "",
        embeds: [infoEmbed("🧮 Sonuç (AI)", `\`${expr}\` = **${aiResult}**`, { footer: "Karmaşık ifade — AI ile hesaplandı" })],
      });
    }
  },
};

export default command;
","commands/fun/kelime.ts":"import { ChannelType, EmbedBuilder, PermissionFlagsBits, type Message } from "discord.js";
import type { Command } from "../../types.js";
import { DEFAULT_PREFIX, OWNER_ID } from "../../config.js";
import { getGuildPrefix } from "../../events/messageCreate.js";
import { COLORS } from "../../utils/embeds.js";
import { EMOJIS } from "../../utils/emojis.js";
import {
  getConfiguredChannelId,
  getGuildWordScores,
  getStatus,
  getTopStreaks,
  isOwnerBypassEnabled,
  removeWordChainChannel,
  setOwnerBypass,
  setWordChainChannel,
} from "../../utils/wordchain.js";

function isAdmin(message: Message): boolean {
  return message.author.id === OWNER_ID || (message.member?.permissions.has("Administrator") ?? false);
}

function rulesEmbed(prefix: string, channelId: string): EmbedBuilder {
  return new EmbedBuilder()
    .setColor(COLORS.success)
    .setTitle("🔤 Kelime Zinciri")
    .setDescription(
      `Bu kanal artık <#${channelId}> için **kalıcı** Kelime Zinciri kanalı. Sunucu kapansa, bot yeniden başlasa bile zincir kaldığı yerden devam eder.\n\n` +
        "**Kurallar**\n" +
        "• Bir önceki kelimenin **son harfiyle** başla.\n" +
        "• Aynı kelime, kullanıldıktan 2 saat sonra yeniden kullanılabilir.\n" +
        "• Aynı kişi art arda iki kez oynayamaz.\n" +
        "• Bu kanala sadece kelime yazılabilir, kurala uymayan mesajlar otomatik silinir.\n\n" +
        `📊 Durumu görmek için: \`${prefix}kelime durum\` • Rekoru görmek için: \`${prefix}kelime skor\``,
    )
    .setFooter({ text: "Kelime Zinciri • Kalıcı Sistem" })
    .setTimestamp();
}

const command: Command = {
  name: "kelime",
  aliases: ["kelimeoyunu", "wordchain"],
  description: "Sunucuya kalıcı bir Kelime Zinciri kanalı bağlar: bir önceki kelimenin son harfiyle devam edilir",
  usage: `${DEFAULT_PREFIX}kelime <kanal [#kanal]|kaldir|durum|skor>`,
  category: "fun",

  async execute(message: Message, args: string[]) {
    if (!message.guild) return;
    const prefix = getGuildPrefix(message.guild.id);
    const sub = args[0]?.toLowerCase();

    if (sub === "izin") {
      if (message.author.id !== OWNER_ID) {
        return message.reply(`${EMOJIS.error} Bu komutu sadece bot sahibi kullanabilir.`);
      }
      const toggle = args[1]?.toLowerCase();
      if (toggle === "ac" || toggle === "aç" || toggle === "on") {
        setOwnerBypass(true);
        return message.reply(`${EMOJIS.success} Muafiyet açıldı — artık Kelime Zinciri kanalına normal mesaj atabilirsin, oyuna dahil olmazsın.`);
      }
      if (toggle === "kapat" || toggle === "off") {
        setOwnerBypass(false);
        return message.reply(`${EMOJIS.success} Muafiyet kapatıldı — artık sen de herkes gibi oyuna dahilsin.`);
      }
      return message.reply(
        `<a:1000021907:1540738818297303111> Kullanım: \`${prefix}kelime izin aç\` veya \`${prefix}kelime izin kapat\`\n` +
          `Şu an: **${isOwnerBypassEnabled() ? "açık" : "kapalı"}**`,
      );
    }

    if (sub === "kanal" || sub === "kanal-ayarla" || sub === "setup" || sub === "baslat" || sub === "başlat") {
      if (!isAdmin(message)) {
        return message.reply(`${EMOJIS.error} Bu komutu sadece **Yönetici** kullanabilir.`);
      }

      const targetChannel = message.mentions.channels.first() ?? message.channel;
      if (targetChannel.type !== ChannelType.GuildText) {
        return message.reply(`${EMOJIS.error} Sadece bir metin kanalını Kelime Zinciri kanalı yapabilirsin.`);
      }

      const me = message.guild.members.me;
      const perms = me ? targetChannel.permissionsFor(me) : null;
      if (!perms?.has(PermissionFlagsBits.SendMessages) || !perms.has(PermissionFlagsBits.ManageMessages)) {
        return message.reply(
          `${EMOJIS.error} <#${targetChannel.id}> kanalında **Mesaj Gönder** ve **Mesajları Yönet** iznine ihtiyacım var.`,
        );
      }

      const existingChannelId = getConfiguredChannelId(message.guild.id);
      const result = await setWordChainChannel(message.guild.id, targetChannel.id, message.author.id);
      if (!result.ok) {
        return message.reply(`<a:1000021907:1540738818297303111> <#${targetChannel.id}> zaten bu sunucunun Kelime Zinciri kanalı.`);
      }

      const embed = rulesEmbed(prefix, targetChannel.id);
      const sent = await targetChannel.send({ embeds: [embed] }).catch(() => null);
      if (sent) await sent.pin().catch(() => null);

      const note = existingChannelId && existingChannelId !== targetChannel.id
        ? ` Eski kanal (<#${existingChannelId}>) artık devre dışı; sunucu rekoru korundu.`
        : "";
      return message.reply(`${EMOJIS.success} <#${targetChannel.id}> artık kalıcı Kelime Zinciri kanalı.${note}`);
    }

    if (sub === "kaldir" || sub === "durdur" || sub === "kapat" || sub === "stop") {
      if (!isAdmin(message)) {
        return message.reply(`${EMOJIS.error} Bu komutu sadece **Yönetici** kullanabilir.`);
      }
      const removedChannelId = await removeWordChainChannel(message.guild.id);
      if (!removedChannelId) {
        return message.reply("<a:1000021813:1540389526873317518> Bu sunucuda kurulu bir Kelime Zinciri kanalı yok.");
      }
      return message.reply(`🏁 Kelime Zinciri kaldırıldı. <#${removedChannelId}> artık normal bir kanal.`);
    }

    if (sub === "durum" || sub === "status") {
      const status = getStatus(message.guild.id);
      if (!status) {
        return message.reply(
          `<a:1000021907:1540738818297303111> Bu sunucuda henüz bir Kelime Zinciri kanalı yok — \`${prefix}kelime kanal #kanal\` ile kur.`,
        );
      }
      const embed = new EmbedBuilder()
        .setColor(COLORS.success)
        .setTitle("🔤 Kelime Zinciri — Durum")
        .addFields(
          { name: "Kanal", value: `<#${status.channelId}>`, inline: true },
          { name: "Mevcut seri", value: `${status.streak}`, inline: true },
          { name: "Sunucu rekoru", value: status.bestHolderId ? `${status.bestStreak} (<@${status.bestHolderId}>)` : "-", inline: true },
          { name: "Son kelime", value: status.lastWord ? `**${status.lastWord}**` : "-", inline: true },
          { name: "Gereken harf", value: status.requiredLetter ? `**${status.requiredLetter}**` : "herhangi biri", inline: true },
          { name: "Kullanılan kelime sayısı", value: `${status.usedWordsCount}`, inline: true },
        );
      return message.reply({ embeds: [embed] });
    }

    if (sub === "skor" || sub === "en-iyi" || sub === "best") {
      const scores = await getGuildWordScores(message.guild.id, 10);
      if (scores.length === 0) {
        return message.reply(`<a:1000021907:1540738818297303111> Henüz kabul edilmiş bir kelime yok; ilk kelimeni oynayarak skorunu oluşturabilirsin.`);
      }
      const medals = ["🥇", "🥈", "🥉"];
      const lines = scores.map((entry, i) => {
        const rank = medals[i] ?? `**${i + 1}.**`;
        return `${rank} <@${entry.userId}> — **${entry.words}** kelime`;
      });
      const status = getStatus(message.guild.id);
      const footer = status?.bestHolderId
        ? `Zincir rekoru: ${status.bestStreak} • Rekor sahibi: ${status.bestHolderId}`
        : "Oyuncu başına kabul edilen kelime sayısı";
      const embed = new EmbedBuilder()
        .setColor(COLORS.success)
        .setTitle("🏆 Kelime Zinciri — Oyuncu Skorları")
        .setDescription(lines.join("\n"))
        .setFooter({ text: footer })
        .setTimestamp();
      return message.reply({ embeds: [embed] });
    }

    if (sub === "top" || sub === "toplist" || sub === "leaderboard") {
      const top = getTopStreaks(10);
      if (top.length === 0) {
        return message.reply(`<a:1000021907:1540738818297303111> Henüz hiçbir sunucuda bir Kelime Zinciri rekoru yok.`);
      }

      const medals = ["🥇", "🥈", "🥉"];
      const lines = top.map((entry, i) => {
        const rank = medals[i] ?? `**${i + 1}.**`;
        const guildName = message.client.guilds.cache.get(entry.guildId)?.name ?? "Bilinmeyen sunucu";
        const holder = entry.bestHolderId ? `<@${entry.bestHolderId}>` : "bilinmeyen";
        return `${rank} **${entry.bestStreak}** kelime — ${holder} • *${guildName}*`;
      });

      const embed = new EmbedBuilder()
        .setColor(COLORS.success)
        .setTitle("🏆 Kelime Zinciri — Sunucular Arası İlk 10")
        .setDescription(lines.join("\n"))
        .setFooter({ text: "Kelime Zinciri • Tüm Sunucular" })
        .setTimestamp();

      return message.reply({ embeds: [embed] });
    }

    return message.reply(
      `<a:1000021907:1540738818297303111> Kullanım:\n` +
        `\`${prefix}kelime kanal [#kanal]\` — bu kanalı (veya belirtilen kanalı) kalıcı Kelime Zinciri kanalı yap\n` +
        `\`${prefix}kelime kaldir\` — Kelime Zinciri kanalını kaldır\n` +
        `\`${prefix}kelime durum\` — mevcut zincirin durumunu göster\n` +
        `\`${prefix}kelime skor\` — sunucu rekorunu göster\n` +
        `\`${prefix}kelime top\` — tüm sunucular arasında en iyi ilk 10 rekoru göster\n` +
        `\`${prefix}kelime izin aç/kapat\` — (sadece bot sahibi) kelime kanalına normal mesaj atma muafiyeti`,
    );
  },
};

export default command;
","commands/fun/kod-analiz.ts":"import { EmbedBuilder, type Message } from "discord.js";
import type { Command } from "../../types.js";
import { DEFAULT_PREFIX } from "../../config.js";
import { getGuildPrefix } from "../../events/messageCreate.js";
import { COLORS } from "../../utils/embeds.js";
import { generateForCode } from "../../utils/codeModel.js";
import { fetchAttachmentText } from "../../utils/codeFiles.js";
import { requirePremiumOrTrial } from "../../premium/gate.js";

// !kod-analiz <kod veya ekli dosya>
//
// src/utils/gemini.ts üzerinden (Gemini) verilen kodu inceler; ne işe
// yaradığını, olası hataları/güvenlik sorunlarını ve iyileştirme
// önerilerini Türkçe olarak özetler.

const MAX_INPUT_CHARS = 12_000;
const MAX_ATTACHMENT_BYTES = 200_000; // ~200KB, metin dosyası için yeterli

const SYSTEM_PROMPT = `Sen deneyimli bir kod inceleme (code review) uzmanısın. Sana verilen kodu analiz edeceksin.

KURALLAR:
- Cevabını Türkçe yaz.
- Aşağıdaki başlıkları kullan (varsa emojiyle): "Ne işe yarıyor", "Olası hatalar / riskler", "İyileştirme önerileri".
- Kısa ve öz ol; madde işaretleri kullan, gereksiz uzatma.
- Kod bloklarını sadece kısa alıntı yaparken kullan, tüm kodu tekrar yazma.
- Kodun zararlı/kötü amaçlı (virüs, exploit, hesap çalma vb.) olduğunu düşünüyorsan bunu açıkça belirt ve öneri verme.
- Toplam cevap 1500 karakteri geçmesin.`;

function extractCodeFromMessage(args: string[]): string {
  const raw = args.join(" ");
  const fenced = raw.match(/```[a-z0-9]*\n?([\s\S]*?)```/i);
  if (fenced) return fenced[1].trim();
  return raw.trim();
}

const command: Command = {
  name: "kod-analiz",
  aliases: ["kodanaliz", "code-review", "kod-incele"],
  description: "MiniMax M3 ile verilen veya ekli kodu analiz eder, hata ve iyileştirme önerisi sunar",
  usage: `${DEFAULT_PREFIX}kod-analiz <kod bloğu> (veya bir kod dosyası ekle)`,
  category: "fun",

  async execute(message: Message, args: string[]) {
    if (!(await requirePremiumOrTrial(message, "kod-analiz"))) return;

    const prefix = getGuildPrefix(message.guild?.id);

    let code = extractCodeFromMessage(args);
    let sourceLabel = "mesajdaki kod";

    const attachment = message.attachments.first();
    if (attachment) {
      if (attachment.size > MAX_ATTACHMENT_BYTES) {
        return message.reply(
          `<a:1000021813:1540389526873317518> Dosya çok büyük (maks ~${Math.floor(MAX_ATTACHMENT_BYTES / 1000)}KB).`,
        );
      }
      try {
        const text = await fetchAttachmentText(attachment.url);
        code = text;
        sourceLabel = attachment.name ?? "ekli dosya";
      } catch (err) {
        return message.reply(`<a:1000021813:1540389526873317518> Ekli dosya okunamadı: ${err instanceof Error ? err.message : "tekrar dene."}`);
      }
    }

    if (!code || code.length < 5) {
      return message.reply(
        `<a:1000021907:1540738818297303111> Kullanım: \`${prefix}kod-analiz <kod>\` (mesaja kod bloğu yaz ya da bir dosya ekle)\n` +
        "Örnek: bir kod bloğu içine kodunu yapıştır ya da komuta bir dosya ekleyerek gönder.",
      );
    }

    const truncated = code.length > MAX_INPUT_CHARS;
    if (truncated) code = code.slice(0, MAX_INPUT_CHARS);

    const loadingMsg = await message.reply("<a:1000021907:1540738818297303111> Kod analiz ediliyor...");

    try {
      const { text: analysis } = await generateForCode(
        SYSTEM_PROMPT,
        `Dosya/kaynak: ${sourceLabel}\n\nKod:\n\`\`\`\n${code}\n\`\`\``,
      );

      const trimmedAnalysis = analysis.trim().slice(0, 4000);

      if (!trimmedAnalysis) {
        return loadingMsg.edit("<a:1000021813:1540389526873317518> Bir analiz üretilemedi, tekrar dene.");
      }

      const embed = new EmbedBuilder()
        .setColor(COLORS.info)
        .setTitle("<a:1000021814:1540389540513194066> Kod Analizi")
        .setDescription(trimmedAnalysis)
        .setFooter({
          text: `Kaynak: ${sourceLabel}${truncated ? " (kısaltıldı)" : ""} • İsteyen: ${message.author.tag}`,
        })
        .setTimestamp();

      return loadingMsg.edit({ content: "", embeds: [embed] });
    } catch (err: unknown) {
      console.error("kod-analiz hatası:", err);
      return loadingMsg.edit(`<a:1000021813:1540389526873317518> Hata oluştu: ${err instanceof Error ? err.message : String(err)}`);
    }
  },
};

export default command;
","commands/fun/kod-duzelt.ts":"import { AttachmentBuilder, EmbedBuilder, type Message } from "discord.js";
import type { Command } from "../../types.js";
import { DEFAULT_PREFIX } from "../../config.js";
import { getGuildPrefix } from "../../events/messageCreate.js";
import { COLORS } from "../../utils/embeds.js";
import { generateCodeText } from "../../utils/codeModel.js";
import { extractCodeBlockWithRest, fetchAttachmentText } from "../../utils/codeFiles.js";
import { keyFromExtension, labelForKey } from "../../utils/langs.js";
import { requirePremiumOrTrial } from "../../premium/gate.js";

// !kod-duzelt <kod veya ekli dosya> [sorun açıklaması]
//
// src/utils/gemini.ts üzerinden (Gemini) verilen koddaki hataları bulup
// düzeltir, düzeltilmiş dosyayı geri gönderir ve neyin değiştiğini
// kısaca özetler.

const MAX_INPUT_CHARS = 12_000;
const MAX_ATTACHMENT_BYTES = 200_000;

const SYSTEM_PROMPT = `Sen deneyimli bir yazılım geliştiricisisin. Sana verilen koddaki hataları bulup düzelteceksin.

ÇIKTI FORMATI (SIRAYLA):
1) Önce tek bir \`\`\` kod bloğu içinde DÜZELTİLMİŞ TAM kodu ver (orijinal dille aynı dilde, eksiksiz, çalışır durumda).
2) Kod bloğundan SONRA "DEĞİŞİKLİKLER:" başlığıyla madde madde neyi neden değiştirdiğini kısaca (Türkçe) özetle.

KURALLAR:
- Kod bloğunun içine açıklama yazma, sadece kod.
- Kullanıcı bir sorun belirttiyse öncelikle onu çöz; belirtmediyse gördüğün gerçek hataları/bugları düzelt.
- Kodun mantığını ve amacını gereksiz yere değiştirme, sadece hatayı düzelt / iyileştir.
- Eğer kodda gerçek bir hata bulamazsan, kodu olduğu gibi geri ver ve "DEĞİŞİKLİKLER:" kısmında hata bulunamadığını belirt.
- "// devamı buraya" gibi yer tutucular kullanma, kod eksiksiz olmalı.
- ÇOK ÖNEMLİ: Düzeltilmiş kodu KESİNLİKLE orijinal kodla AYNI dilde ver. Orijinal dili başka bir dile ASLA çevirme (ör. orijinal TypeScript ise düz JavaScript döndürme, gerçek TypeScript söz dizimini koru).`;

function extractCodeAndNote(args: string[]): { code: string; note: string } {
  const raw = args.join(" ");
  const fenced = raw.match(/```[a-z0-9]*\n?([\s\S]*?)```/i);
  if (fenced) {
    const note = raw.replace(fenced[0], "").trim();
    return { code: fenced[1].trim(), note };
  }
  return { code: raw.trim(), note: "" };
}

function extractFixedCode(raw: string): { code: string; explanation: string; truncated: boolean } {
  const { code, rest, truncated } = extractCodeBlockWithRest(raw);
  return { code, explanation: rest || "Belirtilmedi.", truncated };
}

const command: Command = {
  name: "kod-duzelt",
  aliases: ["koddüzelt", "kod-düzelt", "fix-code", "kodfix"],
  description: "MiniMax M3 ile verilen veya ekli koddaki hataları bulup düzeltir",
  usage: `${DEFAULT_PREFIX}kod-duzelt <kod bloğu> [sorun açıklaması] (veya bir kod dosyası ekle)`,
  category: "fun",

  async execute(message: Message, args: string[]) {
    if (!(await requirePremiumOrTrial(message, "kod-duzelt"))) return;

    const prefix = getGuildPrefix(message.guild?.id);

    let { code, note } = extractCodeAndNote(args);
    let sourceLabel = "mesajdaki kod";
    let attachExt = "txt";

    const attachment = message.attachments.first();
    if (attachment) {
      if (attachment.size > MAX_ATTACHMENT_BYTES) {
        return message.reply(
          `<a:1000021813:1540389526873317518> Dosya çok büyük (maks ~${Math.floor(MAX_ATTACHMENT_BYTES / 1000)}KB).`,
        );
      }
      try {
        code = await fetchAttachmentText(attachment.url);
        sourceLabel = attachment.name ?? "ekli dosya";
        note = args.join(" ").trim();
        const extMatch = /\.([a-z0-9]+)$/i.exec(attachment.name ?? "");
        if (extMatch) attachExt = extMatch[1].toLowerCase();
      } catch (err) {
        return message.reply(`<a:1000021813:1540389526873317518> Ekli dosya okunamadı: ${err instanceof Error ? err.message : "tekrar dene."}`);
      }
    }

    if (!code || code.length < 5) {
      return message.reply(
        `<a:1000021907:1540738818297303111> Kullanım: \`${prefix}kod-duzelt <kod> [sorun açıklaması]\` (mesaja kod bloğu yaz ya da bir dosya ekle)\n` +
        "Örnek: bir kod bloğu içine kodunu yapıştır, isteğe bağlı olarak sorunu yaz (örn: \"çöktü, düzelt\").",
      );
    }

    const truncated = code.length > MAX_INPUT_CHARS;
    if (truncated) code = code.slice(0, MAX_INPUT_CHARS);

    const loadingMsg = await message.reply("<a:1000021907:1540738818297303111> Kod düzeltiliyor...");

    try {
      const userPrompt =
        `Dosya/kaynak: ${sourceLabel}\n` +
        (note ? `Kullanıcının belirttiği sorun: ${note}\n` : "") +
        `\nKod:\n\`\`\`\n${code}\n\`\`\``;

      const expectedLangKey = keyFromExtension(attachExt);
      const { text: rawText, retried } = await generateCodeText(SYSTEM_PROMPT, userPrompt, {
        expectedLangKey,
        expectedLabel: expectedLangKey ? labelForKey(expectedLangKey) : undefined,
      });
      const { code: fixedCode, explanation, truncated: outputTruncated } = extractFixedCode(rawText);

      if (!fixedCode || fixedCode.length < 5) {
        return loadingMsg.edit("<a:1000021813:1540389526873317518> Geçerli bir düzeltme üretilemedi, tekrar dene.");
      }

      const filename = `duzeltilmis.${attachExt === "ts" ? "txt" : attachExt}`;
      const fileAttachment = new AttachmentBuilder(Buffer.from(fixedCode, "utf-8"), {
        name: filename,
      });

      const embed = new EmbedBuilder()
        .setColor(outputTruncated ? COLORS.error : COLORS.success)
        .setTitle(
          outputTruncated
            ? "<a:1000021813:1540389526873317518> Kod Düzeltildi (EKSİK KALDI)"
            : "<a:1000021814:1540389540513194066> Kod Düzeltildi",
        )
        .setDescription(
          [
            `**Kaynak:** ${sourceLabel}${truncated ? " (kısaltıldı)" : ""}`,
            `**Değişiklikler:**\n${explanation.slice(0, 1500)}`,
            retried ? "_Not: İlk üretim beklenen dille tam eşleşmedi, otomatik olarak yeniden üretildi._" : "",
            outputTruncated
              ? "\n⚠️ **Uyarı:** Kod çok uzun olduğu için tam bitirilemeden kesildi, ekteki dosya eksik/bozuk olabilir. Kodu daha küçük parçalar hâlinde göndermen önerilir."
              : "",
          ].filter(Boolean).join("\n"),
        )
        .setFooter({ text: `İsteyen: ${message.author.tag}` })
        .setTimestamp();

      return loadingMsg.edit({ content: "", embeds: [embed], files: [fileAttachment] });
    } catch (err: unknown) {
      console.error("kod-duzelt hatası:", err);
      return loadingMsg.edit(`<a:1000021813:1540389526873317518> Hata oluştu: ${err instanceof Error ? err.message : String(err)}`);
    }
  },
};

