","commands/fun/kod-yaz.ts":"import { AttachmentBuilder, EmbedBuilder, type Message } from "discord.js";
import type { Command } from "../../types.js";
import { DEFAULT_PREFIX } from "../../config.js";
import { getGuildPrefix } from "../../events/messageCreate.js";
import { COLORS } from "../../utils/embeds.js";
import { generateCodeText } from "../../utils/codeModel.js";
import { extractCodeFiles, fetchAttachmentText } from "../../utils/codeFiles.js";
import { LANG_MAP, type LangInfo } from "../../utils/langs.js";
import { requirePremiumOrTrial } from "../../premium/gate.js";

// !kod-yaz py/js/ts <istenilen özellikler>
//
// src/utils/codeModel.ts üzerinden (ana model: OpenRouter/MiniMax M3,
// yanıt alınamazsa Gemini) istenen dilde hazır kod dosyası/dosyaları
// ürettirir ve doğrudan Discord'a dosya olarak ekler. Gerektiğinde (ör.
// bir HTML+CSS+JS projesi) birden fazla dosya döndürebilir — bkz.
// utils/codeFiles.ts.
//
// NOT: Discord, ".ts" uzantısını içerik türünden bağımsız olarak video/akış
// dosyası gibi algılayıp önizleme/oynatıcı göstermeye çalışıyor; bu yüzden
// TypeScript çıktısı ".txt" uzantısıyla gönderiliyor (içerik yine TypeScript
// kodu, sadece dosya uzantısı Discord uyumluluğu için değiştirildi). Bu kural
// modelin ürettiği çoklu dosyalarda da (dosya adı .ts ile bitiyorsa) uygulanır.

const MAX_FILES = 8;
// Discord'da normal kullanıcı mesajları 2000 karakterle sınırlı — uzun/detaylı
// istekler (ör. "90 komutlu bir Discord botu" gibi çok maddeli spesifikasyonlar)
// bu sınıra takılıp Discord tarafında baştan kesiliyor, bot hiçbir zaman
// isteğin tamamını görmüyor. Bunu aşmak için kullanıcı isteğini bir .txt/.md
// dosyası olarak EKLEYEBİLİR; ekliyse featureText args yerine bu dosyadan
// okunur (bkz. utils/codeFiles.ts fetchAttachmentText — kod-analiz/kod-duzelt/
// kod-test'te zaten kullanılan aynı yardımcı).
const MAX_ATTACHMENT_BYTES = 400_000; // ~200KB, uzun bir spesifikasyon metni için fazlasıyla yeterli
const MAX_FEATURE_CHARS = 35_000;

function slugify(raw: string): string {
  const slug = raw
    .toLowerCase()
    .replace(/ı/g, "i")
    .replace(/ğ/g, "g")
    .replace(/ü/g, "u")
    .replace(/ş/g, "s")
    .replace(/ö/g, "o")
    .replace(/ç/g, "c")
    .replace(/[^a-z0-9\s_-]/g, "")
    .trim()
    .replace(/\s+/g, "-")
    .slice(0, 40)
    .replace(/^-+|-+$/g, "");
  return slug || "kod";
}

// Discord'un .ts dosyalarını video sanma sorunu — dosya adı .ts ile bitiyorsa
// (tek dosyalık cevapta olduğu gibi çoklu dosyalarda da) .txt'ye çeviriyoruz.
function discordSafeFilename(filename: string): string {
  return /\.ts$/i.test(filename) ? filename.replace(/\.ts$/i, ".txt") : filename;
}

// BUG NOTU: buildSystemPrompt() modele KURULUM/AI NOTLARI bloğunu eklemesini
// söylüyordu ama bu SADECE bir istemdi — modelin gerçekten uyacağının hiçbir
// garantisi yoktu. Pratikte model (özellikle kısa/basit isteklerde ya da
// yanıtı normalden erken bitirdiğinde) bu bölümü sıkça atlıyor, kullanıcı da
// üretilen dosyada "kurulum rehberi ve AI notları yok" diye şikayet ediyordu.
// Artık bunu prompt'a güvenmek yerine kod tarafında GARANTİ ALTINA ALIYORUZ:
// ana dosyanın kodunda bu iki başlık bulunamazsa, dile özel, önceden
// hazırlanmış bir yedek KURULUM/AI NOTLARI bloğu otomatik olarak en başa
// ekleniyor (bkz. ensureInstallGuide aşağıda).
const KURULUM_RE = /KURULUM\s*:/i;
const AI_NOTLARI_RE = /AI\s*NOTLAR(I|LARI)?\s*:/i;
// Model bazen "Kurulum Rehberi", "Setup", "Installation", "AI Notes" yazabiliyor
const KURULUM_LOOSE_RE = /(?:KURULUM|KURULUM\s*REHBER[İI]|SETUP|INSTALL(?:ATION)?)\s*:/i;
const AI_NOTLARI_LOOSE_RE = /(?:AI\s*NOTLAR(?:I|LARI)?|AI\s*NOTES?|NOTLAR(?:I|LARI)?|NOTES?)\s*:/i;

// Her dil için somut, genel-geçer bir kurulum/çalıştırma talimatı. Modelin
// ürettiği koda özel bağımlılıkları elbette bilemeyiz (bu yüzden yedek metin
// bunu açıkça belirtiyor), ama en azından "hangi araç kurulu olmalı ve nasıl
// çalıştırılır" sorusuna her zaman somut bir cevap veriyor.
const FALLBACK_INSTALL_HINTS: Record<string, string> = {
  py: "Python 3.x kurulu olmalı. Kodun kullandığı ek kütüphaneler varsa: pip install <paket-adi>. Çalıştırmak için: python dosya-adi.py",
  js: "Node.js (18+) kurulu olmalı. Ek paket gerekiyorsa: npm init -y && npm install <paket-adi>. Çalıştırmak için: node dosya-adi.js",
  ts: "Node.js ve TypeScript kurulu olmalı: npm install -g typescript ts-node. Derlemek için: tsc dosya-adi.ts, ardından: node dosya-adi.js (ya da doğrudan: npx ts-node dosya-adi.ts)",
  cpp: "Bir C++ derleyicisi (g++ veya clang++) gerekli. Derlemek için: g++ -std=c++17 dosya-adi.cpp -o program, çalıştırmak için: ./program",
  c: "Bir C derleyicisi (gcc veya clang) gerekli. Derlemek için: gcc dosya-adi.c -o program, çalıştırmak için: ./program",
  cs: ".NET SDK kurulu olmalı. Bir proje içindeysen: dotnet run, değilse: csc ile derleyip oluşan .exe/.dll'i çalıştır.",
  java: "JDK kurulu olmalı. Derlemek için: javac Dosya.java, çalıştırmak için: java Dosya",
  go: "Go kurulu olmalı. Çalıştırmak için: go run dosya-adi.go",
  rs: "Rust ve Cargo kurulu olmalı. Derlemek için: rustc dosya-adi.rs -o program, çalıştırmak için: ./program",
  php: "PHP (8.x) kurulu olmalı. Çalıştırmak için: php dosya-adi.php",
  rb: "Ruby kurulu olmalı. Çalıştırmak için: ruby dosya-adi.rb",
  kt: "Kotlin derleyicisi kurulu olmalı. Derlemek için: kotlinc dosya-adi.kt -include-runtime -d program.jar, çalıştırmak için: java -jar program.jar",
  swift: "Swift kurulu olmalı (macOS/Linux). Çalıştırmak için: swift dosya-adi.swift",
  lua: "Lua kurulu olmalı. Çalıştırmak için: lua dosya-adi.lua",
  sql: "Bir veritabanı istemcisiyle (ör. psql, mysql, sqlite3) bu dosyayı çalıştırabilirsin; hangi veritabanı motoru olduğuna göre küçük sözdizimi farkları olabilir.",
  sh: "Bash kurulu olmalı (Linux/macOS/WSL). Çalıştırma izni ver: chmod +x dosya-adi.sh, sonra: ./dosya-adi.sh",
  html: "Ekstra bir kurulum gerekmez, dosyayı bir tarayıcıda açman yeterli.",
  css: "Ekstra bir kurulum gerekmez; bu dosyayı ilgili HTML dosyana <link rel=\"stylesheet\"> ile bağla.",
  bds: "BDFD (Bot Designer For Discord) tarzı bir platformda bu kodu ilgili komut kutusuna doğrudan yapıştırman yeterli, ekstra kurulum gerekmez.",
};

// Yorum söz diziminin çok satırlı bir blok olarak yazılması gereken diller
// (HTML/CSS gibi açılış+kapanış gerektirenler, BDScript gibi tek fonksiyonlu
// olanlar) için satırları saran yardımcı. wrapComment tek satır içindir; bu,
// birden fazla satırı TEK bir yorum bloğu olarak sarar.
function wrapCommentBlock(info: LangInfo, lines: string[]): string {
  switch (info.commentPrefix) {
    case "<!--":
      return `<!--\n${lines.join("\n")}\n-->`;
    case "/*":
      return `/*\n${lines.join("\n")}\n*/`;
    case "$comment":
      return `$comment[${lines.join(" ")}]`;
    default:
      return lines.map((l) => `${info.commentPrefix} ${l}`).join("\n");
  }
}

/**
 * Ana dosyanın kodunda KURULUM/AI NOTLARI bölümleri yoksa (model atladıysa),
 * dile özel bir yedek blok üretip kodun EN BAŞINA ekler. Zaten varsa kodu
 * olduğu gibi döner — model doğru şekilde eklediyse burada tekrar eklenmez.
 * Hem dar hem gevşek regex kullanır (model "Setup:" / "AI Notes:" yazsa bile
 * tekrar eklenmez).
 */
function ensureInstallGuide(code: string, info: LangInfo): string {
  const hasKurulum = KURULUM_RE.test(code) || KURULUM_LOOSE_RE.test(code);
  const hasAiNotes = AI_NOTLARI_RE.test(code) || AI_NOTLARI_LOOSE_RE.test(code);
  if (hasKurulum && hasAiNotes) {
    return code;
  }
  const installHint = FALLBACK_INSTALL_HINTS[info.key] ?? `Gerekli araçları kur ve dosyayı ${info.label} için standart yöntemle çalıştır.`;
  const lines: string[] = [];
  if (!hasKurulum) {
    lines.push(`KURULUM: ${installHint}`);
  }
  if (!hasAiNotes) {
    lines.push(
      "AI NOTLARI: Model bu bölümü kendi cevabına eklemediği için bot tarafından otomatik olarak eklendi. Kodu kullanmadan önce mutlaka gözden geçir; bağımlılıklar kodun geri kalanına göre değişebilir.",
    );
  }
  if (lines.length === 0) return code;
  const guide = wrapCommentBlock(info, lines);
  return `${guide}\n\n${code}`;
}

/**
 * Kodun başındaki KURULUM ve AI NOTLARI bölümlerini çıkarır.
 * Hem normal hem gevşek başlıkları destekler. Yorum satırı prefix'lerini temizler.
 * Bulunamazsa fallback metin döner.
 */
function extractGuideSections(
  code: string,
  info: LangInfo,
): { kurulum: string; aiNotlari: string } {
  const installHint =
    FALLBACK_INSTALL_HINTS[info.key] ??
    `Gerekli araçları kur ve dosyayı ${info.label} için standart yöntemle çalıştır.`;

  // Yorum prefix'lerini temizleyerek satırları normalize et
  const lines = code.split("\n").map((line) => {
    let cleaned = line.trim();
    // Ortak yorum prefix'lerini temizle
    cleaned = cleaned
      .replace(/^\/\/\s*/, "")
      .replace(/^#\s*/, "")
      .replace(/^--\s*/, "")
      .replace(/^<!--\s*/, "")
      .replace(/^\/\*\s*/, "")
      .replace(/^\*\s*/, "")
      .replace(/^\$comment\[/, "")
      .replace(/\]$/, "")
      .trim();
    return cleaned;
  });

  let kurulum = "";
  let aiNotlari = "";
  let currentSection: "kurulum" | "ai" | null = null;
  const kurulumLines: string[] = [];
  const aiLines: string[] = [];

  for (const line of lines) {
    if (!line) {
      if (currentSection === "kurulum" && kurulumLines.length > 0) continue;
      if (currentSection === "ai" && aiLines.length > 0) continue;
      continue;
    }

    if (KURULUM_RE.test(line) || KURULUM_LOOSE_RE.test(line)) {
      currentSection = "kurulum";
      // Başlık satırının kendisinden sonraki kısmı al
      const afterColon = line.split(/:\s*/).slice(1).join(": ").trim();
      if (afterColon) kurulumLines.push(afterColon);
      continue;
    }

    if (AI_NOTLARI_RE.test(line) || AI_NOTLARI_LOOSE_RE.test(line)) {
      currentSection = "ai";
      const afterColon = line.split(/:\s*/).slice(1).join(": ").trim();
      if (afterColon) aiLines.push(afterColon);
      continue;
    }

    // Kod başlangıcına geldikse dur (yorum dışı satır)
    if (
      currentSection &&
      !line.startsWith("//") &&
      !line.startsWith("#") &&
      !line.startsWith("*") &&
      !line.startsWith("<!--") &&
      !line.startsWith("/*") &&
      !line.startsWith("$comment") &&
      (line.includes("import ") ||
        line.includes("from ") ||
        line.includes("def ") ||
        line.includes("function ") ||
        line.includes("class ") ||
        line.includes("const ") ||
        line.includes("let ") ||
        line.includes("var ") ||
        line.includes("package ") ||
        line.includes("using ") ||
        line.startsWith("<?") ||
        /^[a-zA-Z_$]/.test(line))
    ) {
      break;
    }

    if (currentSection === "kurulum") {
      kurulumLines.push(line);
    } else if (currentSection === "ai") {
      aiLines.push(line);
    }
  }

  kurulum = kurulumLines.join(" ").trim() || installHint;
  aiNotlari =
    aiLines.join(" ").trim() ||
    "Model bu bölümü kendi cevabına eklemediği için bot tarafından otomatik olarak eklendi. Kodu kullanmadan önce mutlaka gözden geçir.";

  // Discord embed field limiti ~1024 karakter
  if (kurulum.length > 1000) kurulum = kurulum.slice(0, 997) + "...";
  if (aiNotlari.length > 1000) aiNotlari = aiNotlari.slice(0, 997) + "...";

  return { kurulum, aiNotlari };
}

const BDSCRIPT_GUIDE = `
BDSCRIPT ÖZEL KURALLARI (ÇOK ÖNEMLİ):
- BDScript, BDFD (Bot Designer For Discord) tarzı bot oluşturucu platformlarda kullanılan, fonksiyon tabanlı bir kod/etiket dilidir. JavaScript veya normal bir programlama dili DEĞİLDİR.
