","commands/fun/sifre.ts":"import crypto from "node:crypto";
import type { Message } from "discord.js";
import type { Command } from "../../types.js";
import { infoEmbed, errorEmbed } from "../../utils/embeds.js";

const CHARSET = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789!@#$%^&*()-_=+";
const MIN_LENGTH = 6;
const MAX_LENGTH = 64;
const DEFAULT_LENGTH = 16;

// crypto.randomInt kullanıyoruz (Math.random DEĞİL) çünkü bu bir şifre
// üretici — tahmin edilebilir bir PRNG ile üretilen "şifre" güvenlik
// açısından anlamsız olur.
function generatePassword(length: number): string {
  let result = "";
  for (let i = 0; i < length; i++) {
    result += CHARSET[crypto.randomInt(0, CHARSET.length)];
  }
  return result;
}

const command: Command = {
  name: "sifre",
  aliases: ["şifre", "password", "pw"],
  description: "Rastgele, güvenli bir şifre üretir (DM üzerinden gönderir)",
  usage: "!sifre [uzunluk (6-64), varsayılan 16]",
  category: "fun",

  async execute(message: Message, args: string[]) {
    let length = DEFAULT_LENGTH;
    if (args[0]) {
      const parsed = Number.parseInt(args[0], 10);
      if (!Number.isFinite(parsed) || parsed < MIN_LENGTH || parsed > MAX_LENGTH) {
        return message.reply({
          embeds: [errorEmbed("Hatalı Uzunluk", `Uzunluk ${MIN_LENGTH} ile ${MAX_LENGTH} arasında olmalı.`)],
        });
      }
      length = parsed;
    }

    const password = generatePassword(length);

    // Kanala açık şifre yazmamak için DM'den göndermeyi deniyoruz; DM kapalıysa
    // (privacy ayarı) kanalda gönderip 15 saniye sonra siliyoruz ki ortalıkta
    // kalmasın.
    try {
      await message.author.send({ embeds: [infoEmbed("🔑 Üretilen Şifre", `\`\`\`${password}\`\`\``, {
        footer: "Bu mesajı gördükten sonra silebilirsin.",
      })] });
      await message.reply({ embeds: [infoEmbed("🔑 Şifre Üretildi", "Şifreni DM olarak gönderdim, kontrol et.")] }).catch(() => null);
    } catch {
      const sent = await message.reply({
        embeds: [infoEmbed("🔑 Üretilen Şifre", `\`\`\`${password}\`\`\`\n⚠️ DM'in kapalı olduğu için buraya yazdım, gördükten sonra mesajı silmeni öneririm.`)],
      });
      setTimeout(() => sent.delete().catch(() => null), 15_000);
    }
  },
};

export default command;
","commands/fun/sor.ts":"import { EmbedBuilder, type Message } from "discord.js";
import type { Command } from "../../types.js";
import { DEFAULT_PREFIX } from "../../config.js";
import { getGuildPrefix } from "../../events/messageCreate.js";
import { COLORS } from "../../utils/embeds.js";
import { generateWithGroq } from "../../utils/groq.js";
import { requirePremiumOrTrial } from "../../premium/gate.js";

// !sor <soru>
//
// Groq'a serbest, genel amaçlı bir soru sorar (kod dışı konular dahil).

const MAX_INPUT_CHARS = 4_000;
const MAX_FILE_CHARS = 6_000;
const MAX_FILE_BYTES = 512 * 1024; // 512 KB

// İçeriği metin olarak okunabilecek uzantılar/MIME tipleri
const TEXT_EXT_RE = /\.(txt|md|markdown|json|csv|log|ts|js|tsx|jsx|py|java|c|cpp|h|hpp|cs|go|rb|php|html|css|xml|yaml|yml|sql|sh|env)$/i;

function isReadableTextFile(name: string, contentType: string | null): boolean {
  if (contentType?.startsWith("text/")) return true;
  if (contentType === "application/json") return true;
  return TEXT_EXT_RE.test(name);
}

async function readAttachmentText(attachment: {
  name: string;
  url: string;
  size: number;
  contentType: string | null;
}): Promise<string | null> {
  if (!isReadableTextFile(attachment.name, attachment.contentType)) return null;
  if (attachment.size > MAX_FILE_BYTES) return null;

  const res = await fetch(attachment.url);
  if (!res.ok) return null;

  const text = await res.text();
  return text.length > MAX_FILE_CHARS ? text.slice(0, MAX_FILE_CHARS) : text;
}

const SYSTEM_PROMPT = `Sen bir Discord sunucusunda yardımcı bir asistansın. Kullanıcının sorusuna Türkçe, net ve doğru şekilde cevap ver.

KURALLAR:
- Cevabını Türkçe yaz (kullanıcı başka dilde sorarsa o dilde cevap verebilirsin).
- Kısa ve öz ol; gereksiz uzun girizgah yapma, direkt cevaba gir.
- Emin olmadığın konularda bunu belirt, uydurma bilgi verme.
- Zararlı, tehlikeli veya kötüye kullanılabilecek bir istek gelirse kibarca reddet.
- Toplam cevap 1800 karakteri geçmesin.`;

const command: Command = {
  name: "sor",
  aliases: ["ai", "soru", "ask"],
  description: "ai'ye genel bir soru sorar",
  usage: `${DEFAULT_PREFIX}sor <soru>`,
  category: "fun",

  async execute(message: Message, args: string[]) {
    if (!(await requirePremiumOrTrial(message, "sor"))) return;

    const prefix = getGuildPrefix(message.guild?.id);
    const question = args.join(" ").trim();

    const attachment = message.attachments.first();

    if (!question && !attachment) {
      return message.reply(
        `<a:1000021907:1540738818297303111> Kullanım: \`${prefix}sor <soru>\`\n` +
        `Örnek: \`${prefix}sor Türkiye'nin başkenti neresidir?\`\n` +
        `Ayrıca bir metin dosyası ekleyip onun içeriği hakkında da soru sorabilirsin.`,
      );
    }

    if (question.length > MAX_INPUT_CHARS) {
      return message.reply(`<a:1000021813:1540389526873317518> Soru çok uzun (maks ${MAX_INPUT_CHARS} karakter).`);
    }

    const loadingMsg = await message.reply("<a:1000021907:1540738818297303111> AI düşünüyor...");

    try {
      let fileContent: string | null = null;

      if (attachment) {
        try {
          fileContent = await readAttachmentText({
            name: attachment.name,
            url: attachment.url,
            size: attachment.size,
            contentType: attachment.contentType,
          });
        } catch (fileErr) {
          console.error("sor dosya okuma hatası:", fileErr);
        }

        if (!fileContent) {
          return loadingMsg.edit(
            `<a:1000021813:1540389526873317518> Dosya okunamadı. Desteklenen metin tabanlı bir dosya (maks ${Math.round(
              MAX_FILE_BYTES / 1024,
            )} KB) eklediğinden emin ol.`,
          );
        }
      }

      const effectiveQuestion = fileContent
        ? `${question || "Bu dosyayı özetle ve içeriği hakkında bilgi ver."}\n\n[Eklenen dosya: ${attachment!.name}]\n---\n${fileContent}\n---`
        : question;

      const answer = await generateWithGroq(SYSTEM_PROMPT, effectiveQuestion, {
        maxTokens: 8_024,
        temperature: 0.45,
      });
      const trimmed = answer.trim().slice(0, 4000);

      if (!trimmed) {
        return loadingMsg.edit("<a:1000021813:1540389526873317518> AI bir cevap üretemedi, tekrar dene.");
      }

      const embed = new EmbedBuilder()
        .setColor(COLORS.info)
        .setTitle("<a:1000021814:1540389540513194066> Cevap")
        .setDescription(trimmed)
        .setFooter({ text: `Soran: ${message.author.tag}` })
        .setTimestamp();

      return loadingMsg.edit({ content: "", embeds: [embed] });
    } catch (err: unknown) {
      console.error("sor hatası:", err);
      return loadingMsg.edit(`<a:1000021813:1540389526873317518> Hata oluştu: ${err instanceof Error ? err.message : String(err)}`);
    }
  },
};

export default command;
