","commands/fun/zar.ts":"import type { Message } from "discord.js";
import type { Command } from "../../types.js";
import { infoEmbed, errorEmbed } from "../../utils/embeds.js";

const command: Command = {
  name: "zar",
  aliases: ["roll", "dice"],
  description: "Zar atar",
  usage: "!zar [yüzler] [adet]  <:1000021812:1540388040646590564>  örn: !zar 20 2",
  category: "fun",

  async execute(message: Message, args: string[]) {
    const sides = parseInt(args[0] ?? "6", 10);
    const count = parseInt(args[1] ?? "1", 10);

    if (isNaN(sides) || sides < 2 || sides > 1000 || isNaN(count) || count < 1 || count > 10) {
      return message.reply({ embeds: [errorEmbed("Hatalı Kullanım", `Kullanım: \`${command.usage}\`\nYüzler: 2–1000, Adet: 1–10`)] });
    }

    const rolls = Array.from({ length: count }, () => Math.floor(Math.random() * sides) + 1);
    const total = rolls.reduce((a, b) => a + b, 0);
    const rollsText = count > 1
      ? `\n🎲 Sonuçlar: ${rolls.join(", ")}\n📊 Toplam: **${total}**`
      : `\n🎲 Sonuç: **${rolls[0]}**`;

    return message.reply({ embeds: [infoEmbed(`🎲 ${count}d${sides} Zar Atışı`, `${message.author} zar attı!${rollsText}`)] });
  },
};

