","commands/hatirlat.ts":"import type { Message } from "discord.js";
import type { Command } from "../types.js";
import { infoEmbed, errorEmbed } from "../utils/embeds.js";

// NOT: Hatırlatıcılar bilinçli olarak sadece BELLEK-İÇİ tutuluyor (DB'ye
// yazılmıyor). Bot yeniden başlarsa bekleyen hatırlatıcılar kaybolur — bu
// basit bir "birazdan hatırlat" komutu için kabul edilebilir bir ödünleşim;
// kalıcılık gerekiyorsa ayrı bir DB tablosu + açılışta yeniden zamanlama
// eklenmesi gerekir.
const MIN_MS = 10_000; // 10 saniyeden kısa hatırlatıcıya izin verme (spam riski)
const MAX_MS = 7 * 24 * 60 * 60_000; // 7 gün
const MAX_ACTIVE_PER_USER = 10;

const activeCountByUser = new Map<string, number>();

const UNIT_MS: Record<string, number> = {
  sn: 1_000,
  s: 1_000,
  dk: 60_000,
  d: 60_000,
  saat: 3_600_000,
  sa: 3_600_000,
  g: 86_400_000,
  gun: 86_400_000,
  gün: 86_400_000,
};

// "1g2saat30dk" gibi birleşik süreleri de destekler.
function parseDuration(input: string): number | null {
  const re = /(\d+)\s*(sn|dk|d|saat|sa|gün|gun|g|s)\b/giu;
  let match: RegExpExecArray | null;
  let total = 0;
  let matchedAny = false;
  while ((match = re.exec(input))) {
    matchedAny = true;
    const amount = Number.parseInt(match[1], 10);
    const unit = UNIT_MS[match[2].toLowerCase()];
    if (!unit) return null;
    total += amount * unit;
  }
  return matchedAny ? total : null;
}

const command: Command = {
  name: "hatirlat",
  aliases: ["remind", "hatırlat"],
  description: "Belirtilen süre sonra sana (veya kanala) hatırlatma gönderir",
  usage: "!hatirlat <süre> <mesaj>  örn: !hatirlat 10dk su iç | !hatirlat 1g2saat toplantı",
  category: "genel",

  async execute(message: Message, args: string[]) {
    if (args.length < 2) {
      return message.reply({ embeds: [errorEmbed("Eksik Kullanım", `Kullanım: \`${command.usage}\`\nBirimler: sn, dk, saat, g (gün)`)] });
    }

    const durationMs = parseDuration(args[0]);
    const note = args.slice(1).join(" ").trim();

    if (durationMs === null || durationMs <= 0) {
      return message.reply({ embeds: [errorEmbed("Geçersiz Süre", "Süre formatı hatalı. Örnek: `10dk`, `2saat`, `1g`, `1g2saat30dk`")] });
    }
    if (durationMs < MIN_MS) {
      return message.reply({ embeds: [errorEmbed("Çok Kısa", "En az 10 saniyelik bir süre gir.")] });
    }
    if (durationMs > MAX_MS) {
      return message.reply({ embeds: [errorEmbed("Çok Uzun", "En fazla 7 gün sonrasına hatırlatıcı kurabilirsin.")] });
    }
    if (!note) {
      return message.reply({ embeds: [errorEmbed("Eksik Mesaj", "Ne hatırlatmamı istediğini de yazmalısın.")] });
    }

    const activeCount = activeCountByUser.get(message.author.id) ?? 0;
    if (activeCount >= MAX_ACTIVE_PER_USER) {
      return message.reply({ embeds: [errorEmbed("Limit Doldu", `Aynı anda en fazla ${MAX_ACTIVE_PER_USER} bekleyen hatırlatıcın olabilir.`)] });
    }

    const dueAt = Date.now() + durationMs;
    activeCountByUser.set(message.author.id, activeCount + 1);

    const timer = setTimeout(() => {
      activeCountByUser.set(message.author.id, Math.max(0, (activeCountByUser.get(message.author.id) ?? 1) - 1));
      void message
        .reply({ embeds: [infoEmbed("⏰ Hatırlatma", note, { footer: `Kurulma zamanı: ${new Date(dueAt - durationMs).toLocaleString("tr-TR")}` })] })
        .catch(() => null);
    }, durationMs);
    timer.unref?.();

    return message.reply({
      embeds: [infoEmbed("✅ Hatırlatıcı Kuruldu", `<t:${Math.floor(dueAt / 1000)}:R> hatırlatacağım:\n> ${note}`)],
    });
  },
};

export default command;
