const HOME_ID = "home";

function visibleCategories(isOwner: boolean): Category[] {
  return CATEGORIES.filter((c) => !c.ownerOnly || isOwner);
}

function buildHomeEmbed(prefix: string, isOwner: boolean) {
  const cats = visibleCategories(isOwner);
  return brandBanner(
    new EmbedBuilder()
      .setColor(COLORS.brand)
      .setAuthor({ name: BOT_NAME, iconURL: undefined })
      .setTitle(`${EMOJIS.info} Komut Merkezi`)
      .setDescription(
        "Aşağıdaki menüden bir kategori seç ve o kategorinin komutlarını keşfet. 💗",
      )
      .addFields(
        cats.map((c) => ({
          name: `${c.emoji} ${c.label}`,
          value: c.description,
          inline: true,
        })),
      )
      .setFooter({ text: `Prefix: ${prefix} • ${BOT_NAME}` })
      .setTimestamp(),
  );
}

function buildCategoryEmbed(cat: Category, prefix: string) {
  return new EmbedBuilder()
    .setColor(COLORS.brand)
    .setAuthor({ name: BOT_NAME })
    .setTitle(`${cat.emoji} ${cat.label}`)
    .setDescription(cat.lines(prefix).join("\n"))
    .setFooter({
      text: `Prefix: ${prefix} • "Ana Sayfa"ya dönmek için menüyü kullan`,
    })
    .setTimestamp();
}

