    .addOptions(
      {
        label: "Ana Sayfa",
        value: HOME_ID,
        emoji: EMOJIS.info,
        default: selected === HOME_ID,
      },
      ...visibleCategories(isOwner).map((c) => ({
        label: c.label,
        value: c.id,
        emoji: c.emoji,
        description: c.description.slice(0, 100),
        default: selected === c.id,
      })),
    );

  return new ActionRowBuilder<StringSelectMenuBuilder>().addComponents(menu);
}

function buildEmbed(id: string, prefix: string, isOwner: boolean) {
  if (id === HOME_ID) return buildHomeEmbed(prefix, isOwner);
  const cat = visibleCategories(isOwner).find((c) => c.id === id);
  if (!cat) return buildHomeEmbed(prefix, isOwner);
  return buildCategoryEmbed(cat, prefix);
}

const command: Command = {
  name: "help",
  aliases: ["yardim", "komutlar"],
  description: "Tüm komutları listeler",
  usage: "!help",
  category: "genel",

  async execute(message: Message) {
    const prefix = getGuildPrefix(message.guild?.id);
    await ensureHalfOwnersLoaded();
    // "owner" kategorisi half-owner'lara da gösteriliyor çünkü
    // premium / özelüye vb. komutları onlar da kullanabiliyor.
    const isOwner =
      message.author.id === OWNER_ID || isHalfOwner(message.author.id);
    let current = HOME_ID;

    const reply = await message.reply({
      embeds: [buildEmbed(current, prefix, isOwner)],
      components: [buildSelectRow(isOwner, current)],
    });

    const collector = reply.createMessageComponentCollector({
      componentType: ComponentType.StringSelect,
      time: 10 * 60 * 1000,
      filter: (interaction) => interaction.user.id === message.author.id,
    });

    collector.on("collect", (interaction: StringSelectMenuInteraction) => {
      void (async () => {
        if (interaction.user.id !== message.author.id) {
          await interaction.reply({
            content: `${EMOJIS.error} Bu menü sana ait değil, kendi \`${prefix}help\` komutunu çalıştır.`,
            ephemeral: true,
          });
          return;
        }

        current = interaction.values[0] ?? HOME_ID;

        await interaction.update({
          embeds: [buildEmbed(current, prefix, isOwner)],
          components: [buildSelectRow(isOwner, current)],
        });
      })().catch((error: unknown) =>
        console.error("Yardım menüsü etkileşim hatası:", error),
      );
    });

    collector.on("end", () => {
      void reply
        .edit({ components: [buildSelectRow(isOwner, current, true)] })
        .catch(() => null);
    });
  },
};

export default command;
","commands/mod/ban.ts":"import { PermissionFlagsBits, type Message, TextChannel } from "discord.js";
import type { Command } from "../../types.js";
import { generateCaseId, notifCard } from "../../utils/modUtils.js";
import { parseMention } from "../../utils/parse.js";
import { hasPermission } from "../../utils/permissions.js";
import { canModerate, getBotModerationBlockReason, botModerationBlockMessage } from "../../utils/hierarchy.js";
import { getChannelSetting } from "../../utils/channelSettings.js";
import { EMOJIS } from "../../utils/emojis.js";
import { COLORS, moderationEmbed, errorEmbed, permissionErrorEmbed } from "../../utils/embeds.js";
import { OWNER_ID } from "../../config.js";

// Discord'un kendi "Yasakla" ekranındaki mesaj geçmişi silme seçenekleriyle
// birebir aynı süreler (saniye cinsinden). deleteMessageSeconds native ban
// API parametresidir — Discord bunu kendi tarafında, tüm kanallarda anında
// halleder. Botun kendi başına sunucuyu tek tek tarayıp silmesine (eski
// purgeUserMessages yaklaşımı) hiç gerek yok; hem yavaş hem rate-limit'e
// takılıyordu, hem de zaten Discord'un hazır bir sistemi var.
const DELETE_RANGES: Record<string, { seconds: number; label: string }> = {
  "hicbiri": { seconds: 0, label: "Hiçbiri" },
  "1s": { seconds: 3_600, label: "Önceki 1 saat" },
  "6s": { seconds: 21_600, label: "Önceki 6 saat" },
  "12s": { seconds: 43_200, label: "Önceki 12 saat" },
  "24s": { seconds: 86_400, label: "Önceki 24 saat" },
  "3g": { seconds: 259_200, label: "Önceki 3 gün" },
  "7g": { seconds: 604_800, label: "Önceki 7 gün" },
};
const DEFAULT_DELETE_RANGE = DELETE_RANGES["7g"];

const command: Command = {
  name: "ban",
  description: "Kullanıcıyı sunucudan yasaklar",
  usage: "!ban <@kullanıcı> [1s|6s|12s|24s|3g|7g|hicbiri] [sebep]",
  category: "mod",

  async execute(message: Message, args: string[]) {
    if (!message.guild || !message.member) return;

    const hasPerm = await hasPermission(message, "ban");
    if (!hasPerm) {
      if (!message.member.permissions.has(PermissionFlagsBits.BanMembers)) {
        return message.reply({ embeds: [errorEmbed("Yetkin Yok", "Ban yetkin yok. Admin'den: `!izin ban @senin-adın`")] });
      }
    }

    const targetId = parseMention(args[0] ?? "");
    if (!targetId) {
      return message.reply({ embeds: [errorEmbed("Eksik Kullanım", "Kullanım: `!ban <@kullanıcı> [1s|6s|12s|24s|3g|7g|hicbiri] [sebep]`")] });
    }
    if (targetId === message.author.id) {
      return message.reply({ embeds: [errorEmbed("Olmaz", "Kendini yasaklayamazsın.")] });
    }
    if (targetId === message.client.user.id) {
      return message.reply({ embeds: [errorEmbed("Olmaz", "Beni yasaklayamazsın.")] });
    }
    if (targetId === OWNER_ID) {
      return message.reply({ embeds: [errorEmbed("Olmaz", "Sahibimi yasaklayamam lol 💗")] });
    }

    // İkinci argüman bir silme süresi anahtar kelimesiyse onu ayır, geri
    // kalanı sebep olarak kullan. Belirtilmezse varsayılan (7 gün) uygulanır.
    const maybeRange = (args[1] ?? "").toLowerCase();
    const deleteRange = DELETE_RANGES[maybeRange] ?? DEFAULT_DELETE_RANGE;
    const reasonArgs = DELETE_RANGES[maybeRange] ? args.slice(2) : args.slice(1);
    const reason = reasonArgs.join(" ") || "Sebep belirtilmedi";

    const member = await message.guild.members.fetch(targetId).catch(() => null);

    if (!member) {
      return message.reply({ embeds: [errorEmbed("Bulunamadı", "Kullanıcı sunucuda değil.")] });
    }

    // 🛠️ KRİTİK DÜZELTME: message.guild.members.me CACHE'TEN okur. Botun rolü
    // az önce değiştirildiyse (taşındıysa/yeni rol verildiyse) bu cache bayat
    // kalabilir ve hiyerarşi kontrolü yanlış "izin var" sonucu üretip asıl
    // Discord API çağrısında "Missing Permissions" (50013) ile patlayabilirdi
    // — kontrol geçse bile gerçek API isteği güncel rol pozisyonuna bakıyordu.
    // fetchMe() ile her zaman taze veriyi alıyoruz.
    const me = await message.guild.members.fetchMe().catch(() => message.guild!.members.me);
    const blockReason = getBotModerationBlockReason(me, member, PermissionFlagsBits.BanMembers, message.author.id);
    if (blockReason) {
      return message.reply({
        embeds: [permissionErrorEmbed(
          botModerationBlockMessage(blockReason, "yasaklayamam", "Üyeleri Yasakla"),
          message.client.user.displayAvatarURL(),
        )],
      });
    }
    if (!member.user.bot && !canModerate(message.member, member)) {
      return message.reply({ embeds: [errorEmbed("Hiyerarşi Engeli", "Bu kullanıcının rolü seninkiyle aynı ya da daha yüksek.")] });
    }

    const caseId = generateCaseId();
    const card = notifCard("Kullanıcı yasaklandı", member.user, reason, message.author.tag, "Kalıcı");

    let dmGonderildi = true;
    try {
      await member.send({ embeds: [card] });
    } catch {
      dmGonderildi = false;
    }

    try {
      await member.ban({ reason: `[${caseId}] ${message.author.tag}: ${reason}`, deleteMessageSeconds: deleteRange.seconds });
    } catch (err) {
      // Discord'un ham "Missing Permissions" hatasını burada yakalayıp
      // gerçek nedeni gösteriyoruz: yukarıdaki ön-kontroller geçse bile API
      // isteği anlık rol hiyerarşisine bakar, o yüzden bu senaryo hâlâ
      // (nadiren) oluşabilir — kullanıcıya en azından net bir mesaj döner.
      const code = (err as { code?: number })?.code;
      if (code === 50013) {
        return message.reply({
          embeds: [permissionErrorEmbed(
            "Maalesef bunu gerçekleştirmek için sunucuda yeterli yetkim yok :(\nDiscord isteği reddetti (Missing Permissions). Rolümün hedef kullanıcının TÜM rollerinden yüksekte olduğundan ve **Üyeleri Yasakla** (veya Yönetici) iznine sahip olduğundan emin olabilir misin? Rolü az önce taşıdıysan bir kere yeniden başlatmak cache'i tazeler.",
            message.client.user.displayAvatarURL(),
          )],
        });
      }
      throw err;
    }

    const mainEmbed = moderationEmbed({
      action: "Kullanıcı Yasaklandı",
      emoji: EMOJIS.ban,
      color: COLORS.error,
      targetTag: `${member.user}`,
      targetId: member.id,
      targetAvatar: member.user.displayAvatarURL({ size: 256 }),
      moderatorTag: `${message.author}`,
      reason,
      caseId,
      duration: "Kalıcı",
      extraFields: [
        ...(!dmGonderildi ? [{ name: `${EMOJIS.error} Not`, value: "DM gönderilemedi", inline: true }] : []),
        { name: "🗑️ Mesajlar", value: `Silindi: ${deleteRange.label}`, inline: false },
      ],
    });

    await message.reply({ embeds: [mainEmbed] });

    // Log işlemi — sunucuya özel kanal ayarlanmışsa
    const logEmbed = moderationEmbed({
      action: "Ban İşlemi",
      emoji: EMOJIS.ban,
      color: COLORS.error,
      targetTag: `${member.user}`,
      targetId: member.id,
      targetAvatar: member.user.displayAvatarURL({ size: 256 }),
      moderatorTag: `${message.author}`,
      reason,
      caseId,
      duration: "Kalıcı",
      extraFields: [{ name: "🗑️ Mesajlar", value: `Silindi: ${deleteRange.label}`, inline: false }],
    });
    try {
      const logChannelId = await getChannelSetting(message.guild.id, "ceza");
      const logChannel = logChannelId ? await message.guild.channels.fetch(logChannelId).catch(() => null) : null;
      if (logChannel && logChannel.isTextBased()) {
        await (logChannel as TextChannel).send({ embeds: [logEmbed] });
      }
    } catch (err) {
      console.error("Ban log kanalına gönderilemedi:", err);
    }
  },
};

export default command;","commands/mod/clear.ts":"import { PermissionFlagsBits, TextChannel, type Message } from "discord.js";
import type { Command } from "../../types.js";
import { EMOJIS } from "../../utils/emojis.js";
import { OWNER_ID } from "../../config.js";

const BULK_DELETE_CHUNK = 100;
const MAX_CLEAR_AMOUNT = 1000;
const MAX_USER_SCAN = 10_000;
const RESULT_DELETE_DELAY = 5000;

type DeleteResult = {
  deleted: number;
  skippedOld: number;
  failed: boolean;
};

function isValidAmount(value: string | undefined): boolean {
  return value !== undefined && /^\d+$/.test(value);
}

/** ID listesini Discord'un 100 mesajlık sınırına göre sıralı şekilde siler. */
async function deleteIds(channel: TextChannel, ids: string[]): Promise<DeleteResult> {
  let deleted = 0;
  let skippedOld = 0;
  let failed = false;

  for (let index = 0; index < ids.length; index += BULK_DELETE_CHUNK) {
    const chunk = ids.slice(index, index + BULK_DELETE_CHUNK);

    try {
      // filterOld=true: Discord'un 14 günden eski mesajları otomatik atlamasına izin verir.
      const result = await channel.bulkDelete(chunk, true);
      deleted += result.size;
      skippedOld += chunk.length - result.size;
    } catch {
      // Bir parça başarısız olsa bile sonraki parçaları denemeye devam et.
      failed = true;
    }
  }

  return { deleted, skippedOld, failed };
}

/** Son mesajları tarar ve bulunan ID'leri döndürür. */
async function fetchMessageIds(
  channel: TextChannel,
  amount: number,
  predicate?: (message: Message) => boolean,
): Promise<{ ids: string[]; scanned: number; reachedEnd: boolean }> {
  const ids: string[] = [];
  let scanned = 0;
  let before: string | undefined;

  while (scanned < amount) {
    const limit = Math.min(BULK_DELETE_CHUNK, amount - scanned);
    const batch = await channel.messages.fetch({ limit, ...(before ? { before } : {}) });

    if (batch.size === 0) {
      return { ids, scanned, reachedEnd: true };
    }

    for (const message of batch.values()) {
      if (!predicate || predicate(message)) ids.push(message.id);
    }

    scanned += batch.size;
    const oldest = batch.last();
    if (!oldest || batch.size < limit) {
      return { ids, scanned, reachedEnd: true };
    }
    before = oldest.id;
  }

  return { ids, scanned, reachedEnd: false };
}

function formatResult(
  result: DeleteResult,
  requested: number,
  scanned: number,
  targetMention?: string,
  reachedEnd = false,
): string {
  const targetText = targetMention ? ` (${targetMention})` : "";
  let text = `${EMOJIS.success} **${result.deleted}** mesaj silindi${targetText}.`;

  if (targetMention) {
    text += ` Son **${scanned}** mesaj tarandı.`;
    if (result.deleted < requested && reachedEnd) {
      text += " Kanala ait daha fazla mesaj bulunamadı.";
    }
  } else if (result.skippedOld > 0) {
    text += ` ${result.skippedOld} mesaj 14 günden eski olduğu için atlandı.`;
  }

  if (result.failed) {
    text += " Bazı mesajlar silinemedi; yetkileri ve kanal kayıtlarını kontrol et.";
  }

  return text;
}

const command: Command = {
  name: "clear",
  aliases: ["sil"],
  description: "Mesajları toplu siler; istersen belirli bir kullanıcının mesajlarını temizler.",
  usage: "!clear <1-1000> [@kullanıcı]",
  category: "mod",

  async execute(message: Message, args: string[]) {
    if (!message.guild || !message.member) return;

    const isOwner = message.author.id === OWNER_ID;
    const canManageMessages = message.member.permissions.has(PermissionFlagsBits.ManageMessages);
    if (!isOwner && !canManageMessages) {
      await message.reply(`${EMOJIS.error} Bu komut için **Mesajları Yönet** yetkisine ihtiyacın var.`);
      return;
    }

    if (!message.channel.isTextBased() || !("bulkDelete" in message.channel)) {
      await message.reply(`${EMOJIS.error} Bu komut yalnızca yazı kanallarında kullanılabilir.`);
      return;
    }

    const rawAmount = args[0];
    if (!isValidAmount(rawAmount)) {
      await message.reply(`${EMOJIS.usage} Kullanım: \`!clear <1-${MAX_CLEAR_AMOUNT}> [@kullanıcı]\``);
      return;
    }

    const amount = Number(rawAmount);
    if (!Number.isSafeInteger(amount) || amount < 1 || amount > MAX_CLEAR_AMOUNT) {
      await message.reply(`${EMOJIS.usage} Miktar **1** ile **${MAX_CLEAR_AMOUNT}** arasında olmalı.`);
      return;
    }

    const channel = message.channel as TextChannel;
    const targetUser = message.mentions.users.first();

    const botMember = message.guild.members.me;
    if (!botMember || !botMember.permissionsIn(channel).has(PermissionFlagsBits.ManageMessages)) {
      await message.reply(`${EMOJIS.error} Botun bu kanalda **Mesajları Yönet** yetkisi yok.`);
      return;
    }

    // Komut mesajını arama başlamadan sil; aksi halde miktar hesabı kayar.
    await message.delete().catch(() => undefined);

    try {
      if (targetUser) {
        // Kullanıcı filtresinde "amount" silinecek mesaj sayısıdır. Bu nedenle
        // amount kadar mesaj değil, amount kullanıcı mesajı bulana kadar taranır.
        const scanLimit = Math.min(MAX_USER_SCAN, Math.max(amount, amount * 10));
        const fetched = await fetchMessageIds(
          channel,
          scanLimit,
          (candidate) => candidate.author.id === targetUser.id,
        );
        const deleteResult = await deleteIds(channel, fetched.ids.slice(0, amount));
        const resultText = formatResult(
          deleteResult,
          amount,
          fetched.scanned,
          targetUser.toString(),
          fetched.reachedEnd,
        );
        const reply = await channel.send(resultText);
        setTimeout(() => reply.delete().catch(() => undefined), RESULT_DELETE_DELAY);
        return;
      }

      const fetched = await fetchMessageIds(channel, amount);
      const deleteResult = await deleteIds(channel, fetched.ids);
      const resultText = formatResult(deleteResult, amount, fetched.scanned, undefined, fetched.reachedEnd);
      const reply = await channel.send(resultText);
      setTimeout(() => reply.delete().catch(() => undefined), RESULT_DELETE_DELAY);
    } catch {
      const reply = await channel.send(
        `${EMOJIS.error} Mesajlar silinirken bir hata oluştu. Botun **Mesajları Yönet** yetkisini ve kanal izinlerini kontrol et.`,
      );
      setTimeout(() => reply.delete().catch(() => undefined), RESULT_DELETE_DELAY);
    }
  },
};

export default command;
","commands/mod/guard.ts":"import type { Message } from "discord.js";
import type { Command } from "../../types.js";
import { OWNER_ID } from "../../config.js";
import { buildGuardPanel, getGuardConfig, updateGuardConfig } from "../../utils/guard.js";
import { errorEmbed, successEmbed, infoEmbed } from "../../utils/embeds.js";
import { EMOJIS } from "../../utils/emojis.js";

function canManageGuard(message: Message): boolean {
  // Sunucu sahibi veya bot sahibi — bot'un kendi mesajı zaten messageCreate'de filtrelenir.
  return message.author.id === OWNER_ID || message.author.id === message.guild?.ownerId;
}

const command: Command = {
  name: "guard",
  aliases: ["koruma"],
  description: "Event-tabanlı sunucu guard ayarlarını Discord içinden yönetir",
  usage: "!guard panel|aç|kapat|durum",
  category: "mod",
  async execute(message: Message, args: string[]) {
    if (!message.guild) return;
    if (!canManageGuard(message)) {
      return message.reply({ embeds: [errorEmbed("Yetkin Yok", "Bu guard panelini yalnızca sunucu sahibi veya bot sahibi kullanabilir.")] });
    }
    const sub = args[0]?.toLocaleLowerCase("tr-TR");
    if (sub === "panel" || !sub) {
      return message.reply(await buildGuardPanel(message.guild.id));
    }
    if (sub === "aç" || sub === "ac" || sub === "on") {
      await updateGuardConfig(message.guild.id, { enabled: true });
      return message.reply({ embeds: [successEmbed("Guard Açıldı", `Ayrıntılı modülleri \`!guard panel\` üzerinden seçebilirsin.`)] });
    }
    if (sub === "kapat" || sub === "off") {
      await updateGuardConfig(message.guild.id, { enabled: false });
      return message.reply({ embeds: [successEmbed("Guard Kapatıldı", "Sunucu artık guard tarafından izlenmiyor.")] });
    }
    if (sub === "durum" || sub === "status") {
      const config = await getGuardConfig(message.guild.id);
      const flag = (v: boolean) => (v ? `${EMOJIS.success} Açık` : `${EMOJIS.error} Kapalı`);
      return message.reply({
        embeds: [
          infoEmbed("Guard Durumu", undefined, {
            fields: [
              { name: "🛡️ Genel", value: flag(config.enabled), inline: true },
              { name: "🎭 Rol Koruması", value: flag(config.antiRoleDelete), inline: true },
              { name: "📺 Kanal Koruması", value: flag(config.antiChannelDelete), inline: true },
              { name: "🤖 Bot Koruması", value: flag(config.antiBotAdd), inline: true },
              { name: "🚨 Raid Koruması", value: flag(config.antiRaid), inline: true },
              { name: "🔨 Toplu Ban Koruması", value: flag(config.antiMassBan), inline: true },
              { name: "👢 Toplu Kick Koruması", value: flag(config.antiMassKick), inline: true },
              { name: "🔑 Yetki Koruması", value: flag(config.antiPermissionEscalation), inline: true },
            ],
          }),
        ],
      });
    }
    return message.reply({ embeds: [errorEmbed("Kullanım", "`!guard panel`, `!guard aç`, `!guard kapat` veya `!guard durum`")] });
  },
};

export default command;
","commands/mod/hosgeldin.ts":"import { EmbedBuilder, PermissionFlagsBits, ChannelType, type Message } from "discord.js";
import type { Command } from "../../types.js";
import { EMOJIS } from "../../utils/emojis.js";
import { getGuildPrefix } from "../../events/messageCreate.js";
import { OWNER_ID } from "../../config.js";
import {
  getGuildWelcomeConfig,
  updateGuildWelcomeConfig,
} from "../../welcome/store.js";
import { buildWelcomePanelView } from "../../welcome/panel.js";
import { renderWelcomeMessage, isTemplateTooLong, MAX_TEMPLATE_LENGTH } from "../../welcome/render.js";
import { extractRawRest } from "../../utils/parse.js";

const PLACEHOLDER_HELP =
  "`{n}` üye sayısı • `{kullanici}` etiket • `{isim}` kullanıcı adı • `{sunucu}` sunucu adı";

// `!hosgeldin ayarla #kanal `<hoşgeldin mesajı>` `<görüşürüz mesajı>`` biçimini
// destekler: art arda gelen, backtick (`) ya da kod bloğu (```) ile sarılmış
// iki ayrı segment arar. Segmentler arasında/dışında sadece boşluk varsa iki
// ayrı mesaj olarak kabul edilir; format uymuyorsa (ör. eski tek-mesaj kullanımı,
// ya da mesajın içinde rastgele backtick geçmesi) null döner ve çağıran taraf
// tüm metni tek (hoşgeldin) mesajı olarak ele almaya devam eder — böylece eski
// kullanım biçimi bozulmaz.
function parseTwoFencedSegments(rest: string): { first: string; second: string } | null {
  const segments: string[] = [];
  let i = 0;
  const n = rest.length;

  while (segments.length < 2 && i < n) {
    while (i < n && /\s/.test(rest[i])) i++;
    if (i >= n || rest[i] !== "`") break;

    const fenceLen = rest.slice(i, i + 3) === "```" ? 3 : 1;
    const fence = "`".repeat(fenceLen);
    const contentStart = i + fenceLen;
    const closeIdx = rest.indexOf(fence, contentStart);
    if (closeIdx === -1) break;

    segments.push(rest.slice(contentStart, closeIdx).trim());
    i = closeIdx + fenceLen;
  }

  if (segments.length !== 2) return null;
  if (rest.slice(i).trim().length > 0) return null; // segmentlerden sonra fazladan metin varsa güvenilir değil
  if (!segments[0] || !segments[1]) return null;
  return { first: segments[0], second: segments[1] };
}

function usage() {
  return new EmbedBuilder()
    .setColor(0xf4a017)
    .setTitle(`${EMOJIS.usage} Kullanım`)
    .setDescription(
      [
        `**\`!hosgeldin\`** — interaktif paneli açar (kanal seç, mesaj/görsel butonları, aç-kapat). Çoğu şey için sadece bunu kullanman yeterli.`,
        "",
        "Aşağıdakiler panel yerine metinle/otomasyonla ayarlamak isteyenler için hâlâ çalışır:",
        "`!hosgeldin ayarla #kanal <mesaj>` — kanalı ve hoşgeldin mesajını tek seferde ayarlar, sistemi açar",
        "`!hosgeldin ayarla #kanal `<hoşgeldin mesajı>` `<görüşürüz mesajı>`` — aynı anda hem hoşgeldin hem görüşürüz mesajını ayarlar (her ikisi de backtick ` veya kod bloğu ``` içinde olmalı)",
        "`!hosgeldin kanal #kanal` — sadece kanalı değiştirir",
        "`!hosgeldin mesaj <mesaj>` — sadece hoşgeldin mesaj şablonunu değiştirir",
        "`!hosgeldin görüşürüz <mesaj>` — sadece ayrılış (görüşürüz) mesaj şablonunu değiştirir",
        "`!hosgeldin görüşürüz kaldır` — sadece görüşürüz mesajını kapatır (hoşgeldin sistemi etkilenmez)",
        "`!hosgeldin aç` / `!hosgeldin kapat` — sistemi aç/kapat (ayarlar korunur)",
        "`!hosgeldin test` — şu anki hoşgeldin (ve varsa görüşürüz) mesajının nasıl göründüğünü bu kanalda gösterir",
        "`!hosgeldin kaldır` — tüm ayarları sıfırlar",
        "`!hosgeldin ayarlar` — mevcut durumu gösterir",
        "",
        `Placeholder'lar: ${PLACEHOLDER_HELP}`,
        "",
        "Mesajı \\`\\`\\` kod bloğu içine yazabilirsin, birden fazla satır olabilir.",
        `Mesaj uzunluğu en fazla ${MAX_TEMPLATE_LENGTH} karakter olabilir.`,
      ].join("\n"),
    );
}

const command: Command = {
  name: "hosgeldin",
  aliases: ["welcome", "karsilama"],
  description: "Yeni üyelere otomatik hoşgeldin/görüşürüz mesajı sistemini yönetir (interaktif panel)",
  usage: "!hosgeldin — paneli açar",
  category: "mod",

  async execute(message: Message, args: string[]) {
    if (!message.guild || !message.member) return;
    if (message.author.id !== OWNER_ID && !message.member.permissions.has(PermissionFlagsBits.ManageGuild)) {
      return message.reply(`${EMOJIS.error} Bu komutu kullanmak için **Sunucuyu Yönet** yetkisine ihtiyacın var.`);
    }

    const guildId = message.guild.id;
    const prefix = getGuildPrefix(guildId);
    const sub = (args[0] ?? "").toLowerCase();

    switch (sub) {
      case "":
      case "panel":
      case "ayarlar":
      case "durum": {
        return message.reply(await buildWelcomePanelView(guildId));
      }

      case "ayarla": {
        const channel = message.mentions.channels.first();
        if (!channel || channel.type !== ChannelType.GuildText) {
          return message.reply({ embeds: [usage()] });
        }
        const rawRest = extractRawRest(message.content, 3, prefix); // hosgeldin ayarla #kanal
        if (!rawRest) {
          return message.reply(`${EMOJIS.error} Bir mesaj metni girmelisin.\n${PLACEHOLDER_HELP}`);
        }

        // İki backtick/kod-bloğu segmenti bulunursa: birincisi hoşgeldin,
        // ikincisi görüşürüz mesajıdır. Bulunamazsa (eski kullanım) tüm metin
        // AYNEN hoşgeldin mesajı olarak kaydedilir — görüşürüz mesajı önceki
        // haliyle korunur (üzerine yazılmaz).
        const parsed = parseTwoFencedSegments(rawRest);
        const welcomeTemplate = parsed ? parsed.first : rawRest;
        const leaveTemplate = parsed ? parsed.second : undefined;

        if (isTemplateTooLong(welcomeTemplate) || (leaveTemplate && isTemplateTooLong(leaveTemplate))) {
          return message.reply(
            `${EMOJIS.error} Mesaj çok uzun. En fazla ${MAX_TEMPLATE_LENGTH} karakter olabilir.`,
          );
        }

        await updateGuildWelcomeConfig(guildId, {
          channelId: channel.id,
          message: welcomeTemplate,
          ...(leaveTemplate !== undefined ? { leaveMessage: leaveTemplate } : {}),
          enabled: true,
        });
        const leaveNote = leaveTemplate ? " Görüşürüz mesajı da ayarlandı." : "";
        return message.reply(
          `${EMOJIS.success} Hoşgeldin sistemi ${channel} kanalına ayarlandı ve açıldı.${leaveNote}\nÖnizleme için \`${prefix}hosgeldin test\` yazabilirsin.`,
        );
      }

      case "kanal": {
        const channel = message.mentions.channels.first();
        if (!channel || channel.type !== ChannelType.GuildText) {
          return message.reply({ embeds: [usage()] });
        }
        await updateGuildWelcomeConfig(guildId, { channelId: channel.id });
        return message.reply(`${EMOJIS.success} Hoşgeldin kanalı ${channel} olarak güncellendi.`);
      }

      case "mesaj": {
        const template = extractRawRest(message.content, 2, prefix); // hosgeldin mesaj
        if (!template) {
          return message.reply({ embeds: [usage()] });
        }
        if (isTemplateTooLong(template)) {
          return message.reply(
            `${EMOJIS.error} Mesaj çok uzun. En fazla ${MAX_TEMPLATE_LENGTH} karakter olabilir.`,
          );
        }
        await updateGuildWelcomeConfig(guildId, { message: template });
        return message.reply(`${EMOJIS.success} Hoşgeldin mesajı güncellendi.\nÖnizleme için \`${prefix}hosgeldin test\` yazabilirsin.`);
      }

      case "görüşürüz":
      case "gorusuruz":
      case "ayril":
      case "leave": {
        const sub2 = (args[1] ?? "").toLowerCase();
        if (sub2 === "kaldır" || sub2 === "kaldir" || sub2 === "sifirla" || sub2 === "reset") {
          await updateGuildWelcomeConfig(guildId, { leaveMessage: null });
          return message.reply(`${EMOJIS.success} Görüşürüz mesajı kaldırıldı.`);
        }
        const template = extractRawRest(message.content, 2, prefix); // hosgeldin görüşürüz
        if (!template) {
          return message.reply({ embeds: [usage()] });
        }
        if (isTemplateTooLong(template)) {
          return message.reply(
            `${EMOJIS.error} Mesaj çok uzun. En fazla ${MAX_TEMPLATE_LENGTH} karakter olabilir.`,
          );
        }
        await updateGuildWelcomeConfig(guildId, { leaveMessage: template });
        return message.reply(`${EMOJIS.success} Görüşürüz mesajı güncellendi.\nÖnizleme için \`${prefix}hosgeldin test\` yazabilirsin.`);
      }

      case "aç": {
        const cfg = await getGuildWelcomeConfig(guildId);
        if (!cfg.channelId || !cfg.message) {
          return message.reply(
            `${EMOJIS.error} Önce bir kanal ve mesaj ayarlamalısın: \`${prefix}hosgeldin ayarla #kanal <mesaj>\``,
          );
        }
        await updateGuildWelcomeConfig(guildId, { enabled: true });
        return message.reply(`${EMOJIS.success} Hoşgeldin sistemi açıldı.`);
      }

      case "kapat": {
        await updateGuildWelcomeConfig(guildId, { enabled: false });
        return message.reply(`${EMOJIS.timeout} Hoşgeldin sistemi kapatıldı.`);
      }

      case "kaldır":
      case "sifirla":
      case "reset": {
        await updateGuildWelcomeConfig(guildId, {
          enabled: false,
          channelId: null,
          message: null,
          leaveMessage: null,
          welcomeImage: null,
          leaveImage: null,
        });
        return message.reply(`${EMOJIS.success} Hoşgeldin ayarları sıfırlandı.`);
      }

      case "test": {
        const cfg = await getGuildWelcomeConfig(guildId);
        if (!cfg.message) {
          return message.reply(
            `${EMOJIS.error} Henüz bir mesaj ayarlanmamış: \`${prefix}hosgeldin ayarla #kanal <mesaj>\``,
          );
        }
        const welcomePreview = renderWelcomeMessage(cfg.message, message.member);
        const parts = [
          `${EMOJIS.info} **Hoşgeldin önizlemesi:**\n${welcomePreview}${cfg.welcomeImage ? `\n${cfg.welcomeImage}` : ""}`,
        ];
        if (cfg.leaveMessage) {
          const leavePreview = renderWelcomeMessage(cfg.leaveMessage, message.member);
          parts.push(`${EMOJIS.info} **Görüşürüz önizlemesi:**\n${leavePreview}${cfg.leaveImage ? `\n${cfg.leaveImage}` : ""}`);
        }
        return message.reply(parts.join("\n\n"));
      }

      default:
        return message.reply({ embeds: [usage()] });
    }
  },
};

export default command;
