","commands/mod/izin.ts":"import type { Message } from "discord.js";
import { EmbedBuilder } from "discord.js";
import { db } from "../../db/index.js";
import { userPermissionsTable } from "../../db/schema.js";
import { eq, and } from "drizzle-orm";
import { EMOJIS } from "../../utils/emojis.js";
import { invalidatePermissionCache } from "../../utils/permissions.js";
import { OWNER_ID } from "../../config.js";

const PERMISSIONS = ["ban", "kick", "mute", "unmute", "unban", "warn", "uyarilar", "say", "duyuru"];

export const izin = {
  name: "izin",
  aliases: ["permit", "yetki"],
  description: "Kullanıcı veya role mod yetkisi ver (Admin)",
  usage: "!izin <yetki> <@kullanıcı|@rol>",
  category: "mod" as const,
  async execute(message: Message, args: string[]) {
    if (message.author.id !== OWNER_ID && !message.member?.permissions.has("Administrator")) {
      await message.reply(`${EMOJIS.error} Bu komutu sadece **Yönetici** kullanabilir.`);
      return;
    }

    const subCommand = args[0]?.toLowerCase();

    if (subCommand === "list") {
      const perms = await db
        .select()
        .from(userPermissionsTable)
        .where(eq(userPermissionsTable.guildId, message.guildId!));

      if (perms.length === 0) {
        await message.reply(`${EMOJIS.error} Hiç yetki verilmemiş.`);
        return;
      }

      const grouped: Record<string, string[]> = {};
      for (const p of perms) {
        if (!grouped[p.permission]) grouped[p.permission] = [];
        const label = p.targetType === "user" ? `<@${p.targetId}>` : `<@&${p.targetId}>`;
        grouped[p.permission].push(label);
      }

      const desc = Object.entries(grouped)
        .map(([perm, targets]) => `**${perm}:** ${targets.join(", ")}`)
        .join("\n");

      const embed = new EmbedBuilder()
        .setColor(0x5865f2)
        .setTitle(`${EMOJIS.info} Yetki Listesi`)
        .setDescription(desc)
        .setTimestamp();
      await message.reply({ embeds: [embed] });
      return;
    }

    if (subCommand === "remove") {
      const permission = args[1]?.toLowerCase();
      const target = args[2];
      if (!permission || !target) {
        await message.reply(`${EMOJIS.error} Kullanım: \`!izin remove <yetki> <@kullanıcı veya @rol>\``);
        return;
      }

      const targetId = target.replace(/[<@!&>]/g, "");
      const targetType = target.includes("&") ? "role" : "user";

      await db
        .delete(userPermissionsTable)
        .where(
          and(
            eq(userPermissionsTable.guildId, message.guildId!),
            eq(userPermissionsTable.targetId, targetId),
            eq(userPermissionsTable.targetType, targetType),
            eq(userPermissionsTable.permission, permission)
          )
        );

      await message.reply(`${EMOJIS.success} **${permission}** yetkisi ${target} kişisinden/rolünden kaldırıldı.`);
      invalidatePermissionCache(message.guildId!, permission);
      return;
    }

    if (subCommand === "resetall") {
      if (args[1]?.toLowerCase() !== "onayla") {
        await message.reply(
          `${EMOJIS.timeout} Bu sunucudaki **TÜM** \`!izin\` yetkilerini (silinmiş rollere ait olanlar dahil) kalıcı olarak siler.\n` +
          "Onaylamak için: `!izin resetall onayla`"
        );
        return;
      }

      const deleted = await db
        .delete(userPermissionsTable)
        .where(eq(userPermissionsTable.guildId, message.guildId!))
        .returning();

      await message.reply(`${EMOJIS.success} ${deleted.length} izin kaydı silindi. Sunucu artık temiz.`);
      invalidatePermissionCache(message.guildId!);
      return;
    }

    if (!subCommand || !PERMISSIONS.includes(subCommand)) {
      const embed = new EmbedBuilder()
        .setColor(0xfe5a5a)
        .setTitle(`${EMOJIS.error} Hatalı Kullanım`)
        .setDescription(
          "`!izin <yetki> <@kullanıcı veya @rol>`\n\n" +
          "**Yetkiler:**\n" +
          PERMISSIONS.map(p => `• \`${p}\``).join("\n") +
          "\n\n**Alt komutlar:**\n" +
          "• `list` - Yetkileri listele\n" +
          "• `remove` - Yetkiyi geri al\n" +
          "• `resetall onayla` - TÜM izinleri sil (dikkat!)"
        )
        .addFields({ name: "Örnek", value: "`!izin ban @Mqxtcc`\n`!izin mute @&Moderatör`" })
        .setTimestamp();
      await message.reply({ embeds: [embed] });
      return;
    }

    const permission = subCommand;
    const target = args[1];
    if (!target) {
      await message.reply(`${EMOJIS.error} Kullanım: \`!izin ${permission} <@kullanıcı veya @rol>\``);
      return;
    }

    const targetId = target.replace(/[<@!&>]/g, "");
    const targetType = target.includes("&") ? "role" : "user";

    if (!targetId || !/^\d{15,20}$/.test(targetId)) {
      await message.reply(`${EMOJIS.error} Geçersiz hedef.`);
      return;
    }

    await db
      .insert(userPermissionsTable)
      .values({
        guildId: message.guildId!,
        targetId,
        targetType,
        permission,
        grantedBy: message.author.id,
      })
      .onConflictDoNothing();

    await message.reply(`${EMOJIS.success} ${target} kişisine/rolüne **${permission}** yetkisi verildi.`);
    invalidatePermissionCache(message.guildId!, permission);
  },
};

export default izin;
","commands/mod/kick.ts":"import { PermissionFlagsBits, type Message, TextChannel } from "discord.js";
import type { Command } from "../../types.js";
import { generateCaseId, notifCard } from "../../utils/modUtils.js";
import { parseMention } from "../../utils/parse.js";
import { hasPermission } from "../../utils/permissions.js";
import { canModerate, getBotModerationBlockReason, botModerationBlockMessage } from "../../utils/hierarchy.js";
import { getChannelSetting } from "../../utils/channelSettings.js";
import { EMOJIS } from "../../utils/emojis.js";
import { COLORS, errorEmbed, moderationEmbed, permissionErrorEmbed } from "../../utils/embeds.js";
import { OWNER_ID } from "../../config.js";

const command: Command = {
  name: "kick",
  description: "Kullanıcıyı sunucudan atar",
  usage: "!kick <@kullanıcı> [sebep]",
  category: "mod",

  async execute(message: Message, args: string[]) {
    if (!message.guild || !message.member) return;

    const hasPerm = await hasPermission(message, "kick");
    if (!hasPerm) {
      if (!message.member.permissions.has(PermissionFlagsBits.KickMembers)) {
        return message.reply({ embeds: [errorEmbed("Yetkin Yok", "Kick yetkin yok. Admin'den: `!izin kick @senin-adın`")] });
      }
    }

    const targetId = parseMention(args[0] ?? "");
    if (!targetId) {
      return message.reply({ embeds: [errorEmbed("Eksik Kullanım", "Kullanım: `!kick <@kullanıcı> [sebep]`")] });
    }
    if (targetId === message.author.id) {
      return message.reply({ embeds: [errorEmbed("Olmaz", "Kendini atamazsın.")] });
    }
    if (targetId === message.client.user.id) {
      return message.reply({ embeds: [errorEmbed("Olmaz", "Beni atamazsın.")] });
    }
    if (targetId === OWNER_ID) {
      return message.reply({ embeds: [errorEmbed("Olmaz", "Sahibimi atamam lol 💗")] });
    }

    const reason = args.slice(1).join(" ") || "Sebep belirtilmedi";
    const member = await message.guild.members.fetch(targetId).catch(() => null);

    if (!member) {
      return message.reply({ embeds: [errorEmbed("Bulunamadı", "Kullanıcı sunucuda değil.")] });
    }
    const blockReason = getBotModerationBlockReason(
      await message.guild.members.fetchMe().catch(() => message.guild!.members.me),
      member,
      PermissionFlagsBits.KickMembers,
      message.author.id,
    );
    if (blockReason) {
      return message.reply({
        embeds: [permissionErrorEmbed(
          botModerationBlockMessage(blockReason, "atamam", "Üyeleri At"),
          message.client.user.displayAvatarURL(),
        )],
      });
    }
    if (!canModerate(message.member, member)) {
      return message.reply({ embeds: [errorEmbed("Hiyerarşi Engeli", "Bu kullanıcının rolü seninkiyle aynı ya da daha yüksek.")] });
    }

    const caseId = generateCaseId();
    const card = notifCard("Kullanıcı atıldı", member.user, reason, message.author.tag);

    let dmGonderildi = true;
    try {
      await member.send({ embeds: [card] });
    } catch {
      dmGonderildi = false;
    }

    await member.kick(`[${caseId}] ${message.author.tag}: ${reason}`);

    const mainEmbed = moderationEmbed({
      action: "Kullanıcı Atıldı",
      emoji: EMOJIS.mod,
      color: COLORS.warning,
      targetTag: `${member.user}`,
      targetId: member.id,
      targetAvatar: member.user.displayAvatarURL({ size: 256 }),
      moderatorTag: `${message.author}`,
      reason,
      caseId,
      extraFields: dmGonderildi ? undefined : [{ name: `${EMOJIS.error} Not`, value: "DM gönderilemedi", inline: true }],
    });

    await message.reply({ embeds: [mainEmbed] });

    // Log işlemi — sunucuya özel kanal ayarlanmışsa
    try {
      const logChannelId = await getChannelSetting(message.guild.id, "ceza");
      const logChannel = logChannelId ? await message.guild.channels.fetch(logChannelId).catch(() => null) : null;
      if (logChannel && logChannel.isTextBased()) {
        const logEmbed = moderationEmbed({
          action: "Kick İşlemi",
          emoji: EMOJIS.mod,
          color: COLORS.warning,
          targetTag: `${member.user}`,
          targetId: member.id,
          targetAvatar: member.user.displayAvatarURL({ size: 256 }),
          moderatorTag: `${message.author}`,
          reason,
          caseId,
        });
        await (logChannel as TextChannel).send({ embeds: [logEmbed] });
      }
    } catch (err) {
      console.error("Kick log kanalına gönderilemedi:", err);
    }
  },
};

export default command;","commands/mod/logkanal.ts":"import { EmbedBuilder, PermissionFlagsBits, type Message, ChannelType } from "discord.js";
import type { Command } from "../../types.js";
import { getAllLogChannels, LOG_CATEGORIES, setLogChannel, type LogCategory } from "../../utils/logger.js";
import { EMOJIS } from "../../utils/emojis.js";
import { COLORS } from "../../utils/embeds.js";
import { OWNER_ID } from "../../config.js";

function findCategory(input: string): LogCategory | null {
  const normalized = input.toLowerCase().trim();
  const found = LOG_CATEGORIES.find((c) => c.id === normalized);
  return found ? found.id : null;
}

const command: Command = {
  name: "logkanal",
  aliases: ["logchannel", "logayarla"],
  description: "Log kategorilerinin hangi kanala yazacağını ayarlar",
  usage: "!logkanal <kategori> #kanal  |  !logkanal <kategori> kapat  |  !logkanal durum",
  category: "mod",

  async execute(message: Message, args: string[]) {
    if (!message.guild || !message.member) return;
    if (message.author.id !== OWNER_ID && !message.member.permissions.has(PermissionFlagsBits.ManageGuild)) {
      return message.reply(`${EMOJIS.error} Bu komutu kullanmak için **Sunucuyu Yönet** yetkisine ihtiyacın var.`);
    }

    const sub = args[0]?.toLowerCase();

    // !logkanal durum -> tüm kategorilerin şu anki ayarını göster
    if (sub === "durum" || sub === "status" || !sub) {
      const settings = await getAllLogChannels(message.guild.id);
      const embed = new EmbedBuilder()
        .setColor(COLORS.info)
        .setTitle(`${EMOJIS.info} Log Kanalı Durumu`)
        .setDescription(
          LOG_CATEGORIES.map((c) => {
            const channelId = settings[c.id];
            const value = channelId ? `<#${channelId}>` : "*ayarlanmamış*";
            return `${c.emoji} **${c.label}** (\`${c.id}\`) — ${value}`;
          }).join("\n"),
        )
        .setFooter({ text: `Ayarlamak için: !logkanal <kategori> #kanal — Kapatmak için: !logkanal <kategori> kapat` });
      return message.reply({ embeds: [embed] }).catch(() => null);
    }

    const category = findCategory(sub);
    if (!category) {
      const list = LOG_CATEGORIES.map((c) => `\`${c.id}\` — ${c.label}`).join("\n");
      return message.reply(`${EMOJIS.error} Kategori şunlardan biri olmalı:\n${list}`);
    }

    const secondArg = args[1]?.toLowerCase();

    // !logkanal mesaj kapat -> kategoriyi devre dışı bırak
    if (secondArg === "kapat" || secondArg === "off" || secondArg === "disable") {
      await setLogChannel(message.guild.id, category, null);
      return message.reply(`${EMOJIS.success} **${category}** logları kapatıldı.`);
    }

    const channel = message.mentions.channels.first() ?? message.guild.channels.cache.get(args[1] ?? "");
    if (!channel || channel.type !== ChannelType.GuildText) {
      return message.reply(`${EMOJIS.error} Kanal bulunamadı.\nKullanım: \`!logkanal ${category} #kanal\` ya da \`!logkanal ${category} kapat\``);
    }

    await setLogChannel(message.guild.id, category, channel.id);
    const meta = LOG_CATEGORIES.find((c) => c.id === category)!;
    await message.reply(`${EMOJIS.success} ${meta.emoji} **${meta.label}** artık ${channel} kanalına yazılacak.`).catch(() => null);
  },
};

export default command;
","commands/mod/otomod.ts":"import { EmbedBuilder, type Message } from "discord.js";
import type { Command } from "../../types.js";
import { getGuildConfig, updateGuildConfig } from "../../automod/store.js";
import { EMOJIS } from "../../utils/emojis.js";
import { OWNER_ID } from "../../config.js";

function statusLine(label: string, on: boolean) {
  return `${on ? "🟢" : "🔴"} ${label}`;
}

async function settingsEmbed(guildId: string) {
  const cfg = await getGuildConfig(guildId);
  return new EmbedBuilder()
    .setColor(0x5865f2)
    .setTitle(`${EMOJIS.mod} Otomod Ayarları`)
    .setDescription(
      [
        statusLine("Otomod genel", cfg.enabled),
        statusLine("Yasaklı kelime filtresi", cfg.bannedWords),
        statusLine("Davet linki engeli", cfg.inviteLinks),
        statusLine("Spam/flood koruması", cfg.spamFlood),
      ].join("\n"),
    )
    .addFields(
      { name: "Timeout eşiği", value: `${cfg.strikesBeforeTimeout}. ihlalden sonra`, inline: true },
      { name: "Başlangıç süresi", value: `${cfg.baseTimeoutMinutes} dk (katlanarak artar)`, inline: true },
      { name: "Üst sınır", value: `${cfg.maxTimeoutMinutes} dk`, inline: true },
      { name: "İhlal sıfırlama", value: `${cfg.strikeResetMinutes} dk sessizlikten sonra`, inline: true },
      { name: "Ek yasaklı kelimeler", value: cfg.wordList.length ? cfg.wordList.join(", ") : "-", inline: false },
      {
        name: "Davet linkine izinli kanallar",
        value: cfg.inviteAllowedChannelIds.length
          ? cfg.inviteAllowedChannelIds.map((id) => `<#${id}>`).join(", ")
          : "-",
        inline: false,
      },
      {
        name: "Muaf roller",
        value: cfg.exemptRoleIds.length ? cfg.exemptRoleIds.map((id) => `<@&${id}>`).join(", ") : "-",
        inline: false,
      },
      { name: "Muafiyet", value: "Sunucu sahibi, bot sahibi ve muaf roller", inline: false },
      { name: "Log kanalı", value: cfg.logChannelId ? `<#${cfg.logChannelId}>` : "-", inline: false },
    );
}

const SNOWFLAKE_REGEX = /^\d{15,25}$/;
const MAX_CUSTOM_WORDS = 500;
const MAX_WORD_LENGTH = 64;

function usage() {
  return new EmbedBuilder()
    .setColor(0xf4a017)
    .setTitle(`${EMOJIS.usage} Kullanım`)
    .setDescription(
      [
        "`!otomod ayarlar` — mevcut durumu gösterir",
        "`!otomod aç` / `!otomod kapat` — otomod'u tamamen aç/kapat",
        "`!otomod kelime aç|kapat` — yasaklı kelime filtresini aç/kapat",
        "`!otomod davet aç|kapat` — davet linki engelini aç/kapat",
        "`!otomod davet-izin #kanal` — verilen kanalda davet linkine izin ver (tekrar yazılırsa izni kaldırır)",
        "`!otomod spam aç|kapat` — flood/spam korumasını aç/kapat",
        "`!otomod kelime-ekle <kelime>` / `!otomod kelime-sil <kelime>`",
        "`!otomod rol-izin @rol` — verilen role sahip üyeleri otomodun tamamından muaf tutar",
        "`!otomod log #kanal` — detaylı log kanalını ayarlar (`kapat` ile kapatılır)",
        "`!otomod esik <sayı>` — kaç ihlalden sonra timeout başlasın (varsayılan 3)",
        "`!otomod sure <dakika>` — ilk timeout süresi, sonrakiler katlanarak artar (varsayılan 1)",
        "`!otomod ust-sinir <dakika>` — timeout süresinin katlanarak ulaşabileceği üst sınır (varsayılan 60)",
        "",
        "Not: bu komutu sadece sunucu sahibi ve bot sahibi kullanabilir. Otomod filtresini ise sunucu sahibi, bot sahibi ve `rol-izin` ile eklenen roller atlatabilir.",
      ].join("\n"),
    );
}

const command: Command = {
  name: "otomod",
  aliases: ["automod"],
  description: "Küfür/spam/davet linki koruma sistemini yönetir",
  usage: "!otomod <ayarlar|aç|kapat|kelime|davet|spam|...>",
  category: "mod",

  async execute(message: Message, args: string[]) {
    if (!message.guild || !message.member) return;

    const isServerOwner = message.author.id === message.guild.ownerId;
    const isBotOwner = message.author.id === OWNER_ID;

    if (!isServerOwner && !isBotOwner) {
      return message.reply(`${EMOJIS.error} Bu komutu sadece sunucu sahibi veya bot sahibi kullanabilir.`);
    }

    const guildId = message.guild.id;
    const sub = (args[0] ?? "").toLowerCase();

    switch (sub) {
      case "":
      case "ayarlar": {
        return message.reply({ embeds: [await settingsEmbed(guildId)] });
      }
      case "aç": {
        await updateGuildConfig(guildId, { enabled: true });
        return message.reply(`${EMOJIS.success} Otomod açıldı.`);
      }
      case "kapat": {
        await updateGuildConfig(guildId, { enabled: false });
        return message.reply(`${EMOJIS.timeout} Otomod kapatıldı.`);
      }
      case "kelime": {
        const val = (args[1] ?? "").toLowerCase();
        if (val !== "aç" && val !== "kapat") return message.reply({ embeds: [usage()] });
        await updateGuildConfig(guildId, { bannedWords: val === "aç" });
        return message.reply(`${EMOJIS.success} Yasaklı kelime filtresi ${val === "aç" ? "açıldı" : "kapatıldı"}.`);
      }
      case "davet": {
        const val = (args[1] ?? "").toLowerCase();
        if (val !== "aç" && val !== "kapat") return message.reply({ embeds: [usage()] });
        await updateGuildConfig(guildId, { inviteLinks: val === "aç" });
        return message.reply(`${EMOJIS.success} Davet linki engeli ${val === "aç" ? "açıldı" : "kapatıldı"}.`);
      }
      case "davet-izin": {
        const channelId = args[1]?.replace(/[<#>]/g, "");
        if (!channelId || !SNOWFLAKE_REGEX.test(channelId) || !message.guild.channels.cache.has(channelId)) return message.reply(`${EMOJIS.uyari} Bu sunucuda geçerli bir kanal seçmelisin.`);
        const cfg = await getGuildConfig(guildId);
        const exists = cfg.inviteAllowedChannelIds.includes(channelId);
        await updateGuildConfig(guildId, {
          inviteAllowedChannelIds: exists
            ? cfg.inviteAllowedChannelIds.filter((id) => id !== channelId)
            : [...cfg.inviteAllowedChannelIds, channelId],
        });
        return message.reply(
          exists
            ? `${EMOJIS.success} <#${channelId}> kanalında davet linki izni kaldırıldı.`
            : `${EMOJIS.success} <#${channelId}> kanalında artık davet linki paylaşılabilir (kelime/spam koruması yine çalışır).`,
        );
      }
      case "spam": {
        const val = (args[1] ?? "").toLowerCase();
        if (val !== "aç" && val !== "kapat") return message.reply({ embeds: [usage()] });
        await updateGuildConfig(guildId, { spamFlood: val === "aç" });
        return message.reply(`${EMOJIS.success} Spam/flood koruması ${val === "aç" ? "açıldı" : "kapatıldı"}.`);
      }
      case "kelime-ekle": {
        // .toLowerCase() (İngilizce kurallar) yerine .toLocaleLowerCase("tr-TR")
        // kullanılıyor — aksi halde "KIRIK" gibi Türkçe dotless-I içeren bir
        // kelime "kirik" olarak kaydediliyordu ("ı" yerine "i"), ve otomodun
        // mesaj eşleştirmesi (normalize() -> toLocaleLowerCase("tr-TR"))
        // gerçek "kırık" kelimesiyle bunu ASLA eşleştiremiyordu.
        const word = args.slice(1).join(" ").toLocaleLowerCase("tr-TR").trim();
        if (!word || word.length > MAX_WORD_LENGTH) return message.reply(`${EMOJIS.usage} Kelime 1-${MAX_WORD_LENGTH} karakter arasında olmalı.`);
        const cfg = await getGuildConfig(guildId);
        if (!cfg.wordList.includes(word)) {
          if (cfg.wordList.length >= MAX_CUSTOM_WORDS) return message.reply(`${EMOJIS.uyari} Özel kelime listesi en fazla ${MAX_CUSTOM_WORDS} kayıt içerebilir.`);
          await updateGuildConfig(guildId, { wordList: [...cfg.wordList, word] });
        }
        return message.reply(`${EMOJIS.success} "${word}" yasaklı kelime listesine eklendi.`);
      }
      case "kelime-sil": {
        const word = args.slice(1).join(" ").toLocaleLowerCase("tr-TR").trim();
        if (!word) return message.reply({ embeds: [usage()] });
        const cfg = await getGuildConfig(guildId);
        if (cfg.wordList.includes(word)) {
          await updateGuildConfig(guildId, { wordList: cfg.wordList.filter((w) => w !== word) });
          return message.reply(`${EMOJIS.success} "${word}" ek listeden kaldırıldı.`);
        }
        // varsayılan listede varsa "removedDefaults"a ekleyerek etkisiz hale getir
        await updateGuildConfig(guildId, { removedDefaults: [...new Set([...cfg.removedDefaults, word])] });
        return message.reply(`${EMOJIS.success} "${word}" filtreden çıkarıldı.`);
      }
      case "rol-izin": {
        const roleId = args[1]?.replace(/[<@&>]/g, "");
        if (!roleId || !SNOWFLAKE_REGEX.test(roleId) || !message.guild.roles.cache.has(roleId)) return message.reply(`${EMOJIS.uyari} Bu sunucuda geçerli bir rol seçmelisin.`);
        const cfg = await getGuildConfig(guildId);
        const exists = cfg.exemptRoleIds.includes(roleId);
        await updateGuildConfig(guildId, {
          exemptRoleIds: exists
            ? cfg.exemptRoleIds.filter((id) => id !== roleId)
            : [...cfg.exemptRoleIds, roleId],
        });
        return message.reply(
          exists
            ? `${EMOJIS.success} <@&${roleId}> rolünün otomod muafiyeti kaldırıldı.`
            : `${EMOJIS.success} <@&${roleId}> rolüne sahip üyeler artık otomodun tamamından muaf.`,
        );
      }
      case "log": {
        const val = args[1];
        if (!val) return message.reply({ embeds: [usage()] });
        if (val.toLowerCase() === "kapat") {
          await updateGuildConfig(guildId, { logChannelId: null });
          return message.reply(`${EMOJIS.success} Log kanalı kapatıldı.`);
        }
        const channelId = val.replace(/[<#>]/g, "");
        if (!SNOWFLAKE_REGEX.test(channelId) || !message.guild.channels.cache.has(channelId)) return message.reply(`${EMOJIS.uyari} Bu sunucuda geçerli bir log kanalı seçmelisin.`);
        await updateGuildConfig(guildId, { logChannelId: channelId });
        return message.reply(`${EMOJIS.success} Log kanalı <#${channelId}> olarak ayarlandı.`);
      }
      case "esik": {
        const n = Number(args[1]);
        if (!Number.isInteger(n) || n < 1 || n > 100) return message.reply(`${EMOJIS.uyari} Eşik 1-100 arasında tam sayı olmalı.`);
        await updateGuildConfig(guildId, { strikesBeforeTimeout: n });
        return message.reply(`${EMOJIS.success} Timeout eşiği ${n}. ihlal olarak ayarlandı.`);
      }
      case "sure": {
        const n = Number(args[1]);
        if (!Number.isInteger(n) || n < 1 || n > 40_320) return message.reply(`${EMOJIS.uyari} Süre 1-40.320 dakika arasında tam sayı olmalı.`);
        await updateGuildConfig(guildId, { baseTimeoutMinutes: n });
        return message.reply(`${EMOJIS.success} Başlangıç timeout süresi ${n} dakika olarak ayarlandı.`);
      }
      case "ust-sinir": {
        const n = Number(args[1]);
        if (!Number.isInteger(n) || n < 1 || n > 40_320) return message.reply(`${EMOJIS.uyari} Üst sınır 1-40.320 dakika arasında tam sayı olmalı.`);
        await updateGuildConfig(guildId, { maxTimeoutMinutes: n });
        return message.reply(`${EMOJIS.success} Timeout üst sınırı ${n} dakika olarak ayarlandı.`);
      }
      default:
        return message.reply({ embeds: [usage()] });
    }
  },
};

export default command;
","commands/mod/setnick.ts":"import type { Message, TextChannel } from "discord.js";
import { getChannelSetting } from "../../utils/channelSettings.js";
import { errorEmbed, successEmbed, permissionErrorEmbed } from "../../utils/embeds.js";
import { OWNER_ID } from "../../config.js";

export const setnick = {
  name: "setnick",
  aliases: ["nick", "nickname"],
  description: "Kullanıcının takma adını değiştir (Admin/Üyeleri Yönet)",
  usage: "!setnick <@kullanıcı> <yeni isim>",
  category: "mod" as const,
  async execute(message: Message, args: string[]) {
    if (message.author.id !== OWNER_ID && !message.member?.permissions.has("ManageNicknames")) {
      await message.reply({ embeds: [errorEmbed("Yetkin Yok", "Bu komutu kullanmak için **Takma Adları Yönet** yetkisine sahip olmalısın.")] });
      return;
    }

    const me = await message.guild?.members.fetchMe().catch(() => message.guild?.members.me);
    if (!me?.permissions.has("ManageNicknames")) {
      await message.reply({
        embeds: [permissionErrorEmbed(
          "Maalesef bunu gerçekleştirmek için sunucuda yeterli yetkim yok :(\nRolümü kontrol edip gerekli izinleri (ör. **Takma Adları Yönet**) verdiğinden emin olabilir misin?",
          message.client.user.displayAvatarURL(),
        )],
      });
      return;
    }

    if (args.length < 2) {
      await message.reply({ embeds: [errorEmbed("Eksik Kullanım", "Kullanım: `!setnick <@kullanıcı> <yeni isim>`\nÖrnek: `!setnick @Mqxtcc Aslan`")] });
      return;
    }

    const userMention = args[0];
    const userId = userMention.replace(/[<@!>]/g, "");
    const newNick = args.slice(1).join(" ").trim();

    if (!userId || !/^\d{15,25}$/.test(userId)) {
      await message.reply({ embeds: [errorEmbed("Geçersiz Kullanıcı", "Lütfen bir kullanıcıyı etiketle.")] });
      return;
    }

    try {
      const member = await message.guild.members.fetch(userId);
      if (!member) {
        await message.reply({ embeds: [errorEmbed("Bulunamadı", "Kullanıcı sunucuda bulunamadı.")] });
        return;
      }

      if (member.roles.highest.position >= (me?.roles.highest.position ?? 0)) {
        await message.reply({
          embeds: [permissionErrorEmbed(
            "Maalesef bu kullanıcının takma adını değiştiremem çünkü sunucuda yeterli yetkim yok :(\nRolümün, hedef kullanıcı/rolden daha üstte olduğundan emin olabilir misin?",
            message.client.user.displayAvatarURL(),
          )],
        });
        return;
      }

      const oldName = member.displayName;
      if (!newNick || newNick.length > 32) {
        await message.reply({ embeds: [errorEmbed("Geçersiz İsim", "Yeni takma ad 1-32 karakter arasında olmalı.")] });
        return;
      }
      await member.setNickname(newNick, `${message.author.tag} tarafından değiştirildi`);

      await message.reply({
        embeds: [successEmbed(
          "Takma Ad Değiştirildi",
          `**${member.user.tag}** kişisinin takma adı değiştirildi: \`${oldName || "(yok)"}\` → \`${newNick}\``,
        )],
      });

      // Log işlemi — sunucuya özel kanal ayarlanmışsa
      try {
        const logChannelId = await getChannelSetting(message.guild.id, "ceza");
        const logChannel = logChannelId ? await message.guild.channels.fetch(logChannelId).catch(() => null) : null;
        if (logChannel && logChannel.isTextBased()) {
          const logEmbed = successEmbed(
            "Takma Ad Değiştirildi",
            `**Kullanıcı:** ${member.user}\n**Yeni İsim:** ${newNick}\n**Moderatör:** ${message.author}`,
          );
          await (logChannel as TextChannel).send({ embeds: [logEmbed], allowedMentions: { parse: [] } });
        }
      } catch (err) {
        console.error("Setnick log kanalına gönderilemedi:", err);
      }
    } catch (err) {
      console.error("setnick hatası:", err);
      await message.reply({ embeds: [errorEmbed("Hata", "Takma ad değiştirilirken bir hata oluştu.")] });
    }
  },
};

export default setnick;
","commands/mod/timeout.ts":"import { PermissionFlagsBits, type Message, TextChannel } from "discord.js";
import type { Command } from "../../types.js";
import { generateCaseId, notifCard } from "../../utils/modUtils.js";
import { parseMention, formatDuration } from "../../utils/parse.js";
import { hasPermission } from "../../utils/permissions.js";
import { canModerate, getBotModerationBlockReason, botModerationBlockMessage } from "../../utils/hierarchy.js";
import { getChannelSetting } from "../../utils/channelSettings.js";
import { EMOJIS } from "../../utils/emojis.js";
import { COLORS, errorEmbed, moderationEmbed, permissionErrorEmbed } from "../../utils/embeds.js";
import { OWNER_ID } from "../../config.js";

const command: Command = {
  name: "timeout",
  aliases: ["mute", "sus"],
  description: "Kullanıcıyı susturur",
  usage: "!timeout <@kullanıcı> <dakika> [sebep]",
  category: "mod",

  async execute(message: Message, args: string[]) {
    if (!message.guild || !message.member) return;

    const hasPerm = await hasPermission(message, "mute");
    if (!hasPerm) {
      if (message.author.id !== OWNER_ID && !message.member.permissions.has(PermissionFlagsBits.ModerateMembers)) {
        return message.reply({ embeds: [errorEmbed("Yetkin Yok", "Mute yetkin yok. Admin'den: `!izin mute @senin-adın`")] });
      }
    }

    const targetId = parseMention(args[0] ?? "");
    const minutes = parseInt(args[1] ?? "", 10);
    if (!targetId || isNaN(minutes) || minutes < 1 || minutes > 40320) {
      return message.reply({ embeds: [errorEmbed("Eksik Kullanım", "Kullanım: `!timeout <@kullanıcı> <dakika> [sebep]`\nSüre: 1–40320 dakika (maks. 28 gün)")] });
    }
    if (targetId === message.author.id) {
      return message.reply({ embeds: [errorEmbed("Olmaz", "Kendini susturamazsın.")] });
    }
    if (targetId === message.client.user.id) {
      return message.reply({ embeds: [errorEmbed("Olmaz", "Beni susturamazsın.")] });
    }

    const reason = args.slice(2).join(" ") || "Sebep belirtilmedi";
    const member = await message.guild.members.fetch(targetId).catch(() => null);

    if (!member) {
      return message.reply({ embeds: [errorEmbed("Bulunamadı", "Kullanıcı sunucuda değil.")] });
    }
    const blockReason = getBotModerationBlockReason(
      await message.guild.members.fetchMe().catch(() => message.guild!.members.me),
      member,
      PermissionFlagsBits.ModerateMembers,
      message.author.id,
    );
    if (blockReason) {
      return message.reply({
        embeds: [permissionErrorEmbed(
          botModerationBlockMessage(blockReason, "susturamam", "Üyeleri Yönet (Timeout)"),
          message.client.user.displayAvatarURL(),
        )],
      });
    }
    if (!canModerate(message.member, member)) {
      return message.reply({ embeds: [errorEmbed("Hiyerarşi Engeli", "Bu kullanıcının rolü seninkiyle aynı ya da daha yüksek.")] });
    }

    const caseId = generateCaseId();
    const durationMs = minutes * 60 * 1000;
    const durationLabel = formatDuration(minutes);
    const card = notifCard("Kullanıcı susturuldu", member.user, reason, message.author.tag, durationLabel);

    let dmGonderildi = true;
    try {
      await member.send({ embeds: [card] });
    } catch {
      dmGonderildi = false;
    }

    try {
      await member.timeout(durationMs, `[${caseId}] ${message.author.tag}: ${reason}`);
    } catch (err) {
      const code = (err as { code?: number })?.code;
      if (code === 50013) {
        return message.reply({
          embeds: [permissionErrorEmbed(
            "Maalesef bunu gerçekleştirmek için sunucuda yeterli yetkim yok :(\nDiscord isteği reddetti (Missing Permissions). Rolümün hedef kullanıcının TÜM rollerinden yüksekte olduğundan ve **Üyeleri Yönet (Timeout)** iznine sahip olduğundan emin olabilir misin?",
            message.client.user.displayAvatarURL(),
          )],
        });
      }
      throw err;
    }

    const mainEmbed = moderationEmbed({
      action: "Kullanıcı Susturuldu",
      emoji: EMOJIS.timeout,
      color: COLORS.error,
      targetTag: `${member.user}`,
      targetId: member.id,
      targetAvatar: member.user.displayAvatarURL({ size: 256 }),
      moderatorTag: `${message.author}`,
      reason,
      caseId,
      duration: durationLabel,
      extraFields: dmGonderildi ? undefined : [{ name: `${EMOJIS.error} Not`, value: "DM gönderilemedi", inline: true }],
    });

    await message.reply({ embeds: [mainEmbed] });

    // Log işlemi — sunucuya özel kanal ayarlanmışsa
    try {
      const logChannelId = await getChannelSetting(message.guild.id, "ceza");
      const logChannel = logChannelId ? await message.guild.channels.fetch(logChannelId).catch(() => null) : null;
      if (logChannel && logChannel.isTextBased()) {
        const logEmbed = moderationEmbed({
          action: "Timeout İşlemi",
          emoji: EMOJIS.timeout,
          color: COLORS.error,
          targetTag: `${member.user}`,
          targetId: member.id,
          targetAvatar: member.user.displayAvatarURL({ size: 256 }),
          moderatorTag: `${message.author}`,
          reason,
          caseId,
          duration: durationLabel,
        });
        await (logChannel as TextChannel).send({ embeds: [logEmbed] });
      }
    } catch (err) {
      console.error("Timeout log kanalına gönderilemedi:", err);
    }
  },
};

export default command;
","commands/mod/unban.ts":"import { PermissionFlagsBits, type Message, TextChannel } from "discord.js";
import type { Command } from "../../types.js";
import { hasPermission } from "../../utils/permissions.js";
import { getChannelSetting } from "../../utils/channelSettings.js";
import { errorEmbed, successEmbed } from "../../utils/embeds.js";

const command: Command = {
  name: "unban",
  description: "Yasaklı bir kullanıcının yasağını kaldırır",
  usage: "!unban <kullanıcı-id>",
  category: "mod",

  async execute(message: Message, args: string[]) {
    if (!message.guild || !message.member) return;

    const hasPerm = await hasPermission(message, "unban");
    if (!hasPerm) {
      if (!message.member.permissions.has(PermissionFlagsBits.BanMembers)) {
        return message.reply({ embeds: [errorEmbed("Yetkin Yok", "Unban yetkin yok. Admin'den: `!izin unban @senin-adın`")] });
      }
    }

    const userId = args[0]?.trim();
    if (!userId || !/^\d{17,20}$/.test(userId)) {
      return message.reply({ embeds: [errorEmbed("Eksik Kullanım", `Kullanım: \`${command.usage}\`\nGeçerli bir Discord kullanıcı ID'si gir.`)] });
    }

    const ban = await message.guild.bans.fetch(userId).catch(() => null);
    if (!ban) {
      return message.reply({ embeds: [errorEmbed("Bulunamadı", "Bu kullanıcı sunucudan yasaklı değil.")] });
    }

    try {
      await message.guild.members.unban(userId, `${message.author.tag} tarafından yasak kaldırıldı`);
    } catch (err) {
      const code = (err as { code?: number })?.code;
      if (code === 10026) {
        return message.reply({ embeds: [errorEmbed("Bulunamadı", "Bu kullanıcı sunucudan yasaklı değil.")] });
      }
      throw err;
    }

    await message.reply({
      embeds: [successEmbed(
        "Yasak Kaldırıldı",
        `**${ban.user.tag}** kullanıcısının yasağı kaldırıldı.`,
        { fields: [{ name: "🛡️ Yetkili", value: `${message.author}`, inline: true }] },
      )],
    });

    // Log işlemi — sunucuya özel kanal ayarlanmışsa
    try {
      const logChannelId = await getChannelSetting(message.guild.id, "ceza");
      const logChannel = logChannelId ? await message.guild.channels.fetch(logChannelId).catch(() => null) : null;
      if (logChannel && logChannel.isTextBased()) {
