","commands/mod/unmute.ts":"import { PermissionFlagsBits, type Message } from "discord.js";
import type { Command } from "../../types.js";
import { parseMention } from "../../utils/parse.js";
import { hasPermission } from "../../utils/permissions.js";
import { canModerate, getBotModerationBlockReason, botModerationBlockMessage } from "../../utils/hierarchy.js";
import { errorEmbed, successEmbed, permissionErrorEmbed } from "../../utils/embeds.js";

const command: Command = {
  name: "unmute",
  aliases: ["unsus", "susturma-kaldir"],
  description: "Kullanıcının susturulmasını (timeout) kaldırır",
  usage: "!unmute <@kullanıcı>",
  category: "mod",

  async execute(message: Message, args: string[]) {
    if (!message.guild || !message.member) return;

    const hasPerm = await hasPermission(message, "unmute");
    if (!hasPerm) {
      if (!message.member.permissions.has(PermissionFlagsBits.ModerateMembers)) {
        return message.reply({ embeds: [errorEmbed("Yetkin Yok", "Unmute yetkin yok. Admin'den: `!izin unmute @senin-adın`")] });
      }
    }

    const targetId = parseMention(args[0] ?? "");
    if (!targetId) {
      return message.reply({ embeds: [errorEmbed("Eksik Kullanım", "Kullanım: `!unmute <@kullanıcı>`")] });
    }
    if (targetId === message.author.id) {
      return message.reply({ embeds: [errorEmbed("Olmaz", "Kendinin susturmasını kaldıramazsın.")] });
    }
    if (targetId === message.client.user.id) {
      return message.reply({ embeds: [errorEmbed("Olmaz", "Beni susturamazsın.")] });
    }

    const member = await message.guild.members.fetch(targetId).catch(() => null);
    if (!member) {
      return message.reply({ embeds: [errorEmbed("Bulunamadı", "Kullanıcı sunucuda değil.")] });
    }
    const blockReason = getBotModerationBlockReason(
      await message.guild.members.fetchMe().catch(() => message.guild!.members.me),
      member,
      PermissionFlagsBits.ModerateMembers,
      message.author.id,
    );
    if (blockReason) {
      return message.reply({
        embeds: [permissionErrorEmbed(
          botModerationBlockMessage(blockReason, "susturmasını kaldıramam", "Üyeleri Yönet (Timeout)"),
          message.client.user.displayAvatarURL(),
        )],
      });
    }
    if (!canModerate(message.member, member)) {
      return message.reply({ embeds: [errorEmbed("Hiyerarşi Engeli", "Bu kullanıcının rolü seninkiyle aynı ya da daha yüksek.")] });
    }
    if (!member.isCommunicationDisabled()) {
      return message.reply({ embeds: [errorEmbed("Zaten Susturulmamış", `${member.user} zaten susturulmamış.`)] });
    }

    try {
      await member.timeout(null, `${message.author.tag} tarafından susturma kaldırıldı`);
    } catch (err) {
      const code = (err as { code?: number })?.code;
      if (code === 50013) {
        return message.reply({
          embeds: [permissionErrorEmbed(
            "Maalesef bunu gerçekleştirmek için sunucuda yeterli yetkim yok :(\nDiscord isteği reddetti (Missing Permissions). Rolümün hedef kullanıcının TÜM rollerinden yüksekte olduğundan ve **Üyeleri Yönet (Timeout)** iznine sahip olduğundan emin olabilir misin?",
            message.client.user.displayAvatarURL(),
          )],
        });
      }
      throw err;
    }

    const embed = successEmbed(
      "Susturma Kaldırıldı",
      `${member.user} kişisinin susturması kaldırıldı.`,
      { fields: [{ name: "🛡️ Yetkili", value: `${message.author}`, inline: true }] },
    );

    return message.reply({ embeds: [embed] });
  },
};

