","commands/mod/uyarilar.ts":"import { EmbedBuilder, PermissionFlagsBits, type Message } from "discord.js";
import { eq, and, desc, count } from "drizzle-orm";
import type { Command } from "../../types.js";
import { parseMention } from "../../utils/parse.js";
import { db, warningsTable } from "../../db/index.js";
import { COLORS, errorEmbed } from "../../utils/embeds.js";
import { hasPermission } from "../../utils/permissions.js";
import { EMOJIS } from "../../utils/emojis.js";

const command: Command = {
  name: "uyarilar",
  aliases: ["warnings", "warns"],
  description: "Kullanıcının uyarı geçmişini gösterir",
  usage: "!uyarilar <@kullanıcı>",
  category: "mod",

  async execute(message: Message, args: string[]) {
    if (!message.guild || !message.member) return;

    const hasPerm = await hasPermission(message, "uyarilar");
    if (!hasPerm) {
      if (!message.member.permissions.has(PermissionFlagsBits.ModerateMembers)) {
        return message.reply({ embeds: [errorEmbed("Yetkin Yok", "Uyarilar yetkin yok. Admin'den: `!izin uyarilar @senin-adın`")] });
      }
    }

    const targetId = parseMention(args[0] ?? "");
    if (!targetId) {
      return message.reply({ embeds: [errorEmbed("Eksik Kullanım", "Kullanım: `!uyarilar <@kullanıcı>`")] });
    }

    const target = await message.client.users.fetch(targetId).catch(() => null);
    if (!target) {
      return message.reply({ embeds: [errorEmbed("Bulunamadı", "Kullanıcı bulunamadı.")] });
    }

    const [{ value: total }] = await db
      .select({ value: count() })
      .from(warningsTable)
      .where(and(eq(warningsTable.userId, target.id), eq(warningsTable.guildId, message.guild.id)));

    const warnings = await db
      .select()
      .from(warningsTable)
      .where(and(eq(warningsTable.userId, target.id), eq(warningsTable.guildId, message.guild.id)))
      .orderBy(desc(warningsTable.createdAt))
      .limit(10);

    const embed = new EmbedBuilder()
      .setColor(total === 0 ? COLORS.success : COLORS.warning)
      .setAuthor({ name: target.tag, iconURL: target.displayAvatarURL() })
      .setTitle(`${EMOJIS.warn} Uyarı Geçmişi — Toplam: ${total}`);

    if (total === 0) {
      embed.setDescription("Bu kullanıcının hiç uyarısı yok.");
    } else {
      embed.setDescription(
        warnings
          .map(
            (w, i) =>
              `\`${i + 1}.\` **${w.reason}**\n└ <@${w.moderatorId}> • <t:${Math.floor(w.createdAt.getTime() / 1000)}:d>`,
          )
          .join("\n\n"),
      );
      if (total > 10) {
        embed.setFooter({ text: `Son 10 uyarı gösteriliyor (toplam ${total})` });
      }
    }

    return message.reply({ embeds: [embed] });
  },
};

