","commands/mod/warn.ts":"import { PermissionFlagsBits, type Message, TextChannel } from "discord.js";
import { eq, and, count } from "drizzle-orm";
import type { Command } from "../../types.js";
import { generateCaseId, warnBar, notifCard } from "../../utils/modUtils.js";
import { parseMention } from "../../utils/parse.js";
import { db, warningsTable } from "../../db/index.js";
import { hasPermission } from "../../utils/permissions.js";
import { canModerate } from "../../utils/hierarchy.js";
import { getChannelSetting } from "../../utils/channelSettings.js";
import { EMOJIS } from "../../utils/emojis.js";
import { COLORS, errorEmbed, moderationEmbed } from "../../utils/embeds.js";

function getMuteDurationMs(totalWarns: number): number | null {
  if (totalWarns < 3) return null;
  return (totalWarns - 2) * 60 * 60 * 1000;
}

function formatHours(ms: number): string {
  const h = ms / 3600000;
  return h === 1 ? "1 saat" : `${h} saat`;
}

const command: Command = {
  name: "warn",
  aliases: ["uyar"],
  description: "Kullanıcıyı uyarır",
  usage: "!warn <@kullanıcı> <sebep>",
  category: "mod",

  async execute(message: Message, args: string[]) {
    if (!message.guild || !message.member) return;

    const hasPerm = await hasPermission(message, "warn");
    if (!hasPerm) {
      if (!message.member.permissions.has(PermissionFlagsBits.ModerateMembers)) {
        return message.reply({ embeds: [errorEmbed("Yetkin Yok", "Warn yetkin yok. Admin'den: `!izin warn @senin-adın`")] });
      }
    }

    const targetId = parseMention(args[0] ?? "");
    const reason = args.slice(1).join(" ");
    if (!targetId || !reason) {
      return message.reply({ embeds: [errorEmbed("Eksik Kullanım", "Kullanım: `!warn <@kullanıcı> <sebep>`")] });
    }
    if (targetId === message.author.id) {
      return message.reply({ embeds: [errorEmbed("Olmaz", "Kendini uyaramazsın.")] });
    }

    const target = await message.client.users.fetch(targetId).catch(() => null);
    if (!target || target.bot) {
      return message.reply({ embeds: [errorEmbed("Bulunamadı", "Böyle bir kullanıcı yok ya da bot.")] });
    }

    const targetMember = await message.guild.members.fetch(targetId).catch(() => null);
    if (targetMember && !canModerate(message.member, targetMember)) {
      return message.reply({ embeds: [errorEmbed("Hiyerarşi Engeli", "Bu kullanıcının rolü seninkiyle aynı ya da daha yüksek.")] });
    }

    await db.insert(warningsTable).values({
      userId: target.id,
      guildId: message.guild.id,
      reason,
      moderatorId: message.author.id,
    });

    const [{ value: totalWarns }] = await db
      .select({ value: count() })
      .from(warningsTable)
      .where(and(eq(warningsTable.userId, target.id), eq(warningsTable.guildId, message.guild.id)));

    let muteLabel: string | undefined;
    const muteDurationMs = getMuteDurationMs(totalWarns);
    if (muteDurationMs !== null && targetMember?.moderatable) {
      try {
        await targetMember.timeout(muteDurationMs, `Otomatik: ${totalWarns}. uyarı`);
        muteLabel = `Otomatik susturma: ${formatHours(muteDurationMs)}`;
      } catch (err) {
        console.error("Otomatik susturma uygulanamadı:", err);
      }
    }

    const caseId = generateCaseId();
    const card = notifCard(`${totalWarns} uyarı verildi`, target, reason, message.author.tag, muteLabel);

    let dmGonderildi = true;
    try {
      await target.send({ embeds: [card] });
    } catch {
      dmGonderildi = false;
    }

    const warnExtraFields = [
      { name: "📊 Toplam", value: warnBar(totalWarns), inline: true },
      ...(muteLabel ? [{ name: `${EMOJIS.timeout} Otomatik İşlem`, value: muteLabel, inline: true }] : []),
      ...(dmGonderildi ? [] : [{ name: `${EMOJIS.error} Not`, value: "DM gönderilemedi", inline: true }]),
    ];

    const mainEmbed = moderationEmbed({
      action: `${totalWarns}. Uyarı`,
      emoji: EMOJIS.warn,
      color: COLORS.warning,
      targetTag: `${target}`,
      targetId: target.id,
      targetAvatar: target.displayAvatarURL({ size: 256 }),
      moderatorTag: `${message.author}`,
      reason,
      caseId,
      extraFields: warnExtraFields,
    });

    await message.reply({ embeds: [mainEmbed] });

    // Log işlemi — sunucuya özel kanal ayarlanmışsa
    try {
      const logChannelId = await getChannelSetting(message.guild.id, "ceza");
      const logChannel = logChannelId ? await message.guild.channels.fetch(logChannelId).catch(() => null) : null;
      if (logChannel && logChannel.isTextBased()) {
        const logEmbed = moderationEmbed({
          action: "Uyarı İşlemi",
          emoji: EMOJIS.warn,
          color: COLORS.warning,
          targetTag: `${target}`,
          targetId: target.id,
          targetAvatar: target.displayAvatarURL({ size: 256 }),
          moderatorTag: `${message.author}`,
          reason,
          caseId,
          extraFields: [
            { name: "📊 Toplam Uyarı", value: `${totalWarns}`, inline: true },
            ...(muteLabel ? [{ name: `${EMOJIS.timeout} Otomatik İşlem`, value: muteLabel, inline: true }] : []),
          ],
        });
        await (logChannel as TextChannel).send({ embeds: [logEmbed] });
      }
    } catch (err) {
      console.error("Warn log kanalına gönderilemedi:", err);
    }
  },
};

