","commands/owner/eval.ts":"import util from "node:util";
import { EmbedBuilder, AttachmentBuilder, type Message } from "discord.js";
import type { Command } from "../../types.js";
import { EMOJIS } from "../../utils/emojis.js";
import { requireOwner, getGuildPrefix } from "../../events/messageCreate.js";

// Güvenlik: message.author.id, Discord'un gateway bağlantısı üzerinden
// doğrulanan gerçek gönderen kimliğidir; bir kullanıcı başka birinin
// ID'sini taklit ederek mesaj gönderemez. Bu yüzden aşağıdaki tek satırlık
// OWNER_ID karşılaştırması dışarıdan kırılamaz — tek zayıf halka OWNER_ID
// sahibinin kendi Discord hesabının veya bot TOKEN'ının çalınması olur ki
// bu zaten her türlü owner-only komutun ortak riskidir.
function maskSecrets(text: string): string {
  let out = text;
  for (const [key, val] of Object.entries(process.env)) {
    if (val && val.length >= 6) {
      out = out.split(val).join(`[GİZLİ:${key}]`);
    }
  }
  return out;
}

const EVAL_TIMEOUT_MS = 120_000;

const command: Command = {
  name: "eval",
  aliases: ["ev"],
  description: "JS/TS kodu çalıştırır (owner-only)",
  usage: "!eval <kod>",
  category: "owner",

  async execute(message: Message) {
    if (!(await requireOwner(message))) return;

    const prefix = getGuildPrefix(message.guild?.id);
    const codeBody = message.content.slice(prefix.length).replace(/^ev(al)?\s*/i, "").trim();
    if (!codeBody) {
      await message
        .reply(`${EMOJIS.usage} Kullanım: \`${prefix}eval <js/ts kodu>\`\nÖrnek: \`${prefix}eval message.guild?.name\``)
        .catch(() => null);
      return;
    }

    // Audit log: kim ne çalıştırdı, konsolda (ve dolayısıyla !console-log'da) kalıcı iz bırakır.
    console.log(
      ` ${EMOJIS.uyari} EVAL — kullanıcı: ${message.author.tag} (${message.author.id}) — kanal: ${message.channel.id} — kod: ${maskSecrets(codeBody)}`,
    );

    try {
      const evalPromise = (async () => {
        // eslint-disable-next-line no-eval
        return await eval(`(async () => {\n${codeBody}\n})()`);
      })();
      let timeoutHandle: ReturnType<typeof setTimeout> | undefined;
      const timeoutPromise = new Promise<never>((_, reject) => {
        timeoutHandle = setTimeout(
          () => reject(new Error(`⏱️ ${EVAL_TIMEOUT_MS / 1000} saniyede tamamlanmadı (timeout).`)),
          EVAL_TIMEOUT_MS,
        );
      });
      let result: unknown;
      try {
        result = await Promise.race([evalPromise, timeoutPromise]);
      } finally {
        if (timeoutHandle) clearTimeout(timeoutHandle);
      }

      const rawOutput = typeof result === "string" ? result : util.inspect(result, { depth: 2 });
      const output = maskSecrets(rawOutput);
      const EMBED_SAFE_LIMIT = 3900;

      if (output.length <= EMBED_SAFE_LIMIT) {
        const embed = new EmbedBuilder()
          .setColor(0x57f287)
          .setTitle(`${EMOJIS.usage} Eval sonucu`)
          .setDescription("```js\n" + (output || "undefined") + "\n```")
          .setTimestamp();
        await message.reply({ embeds: [embed] }).catch(() => null);
      } else {
        const buffer = Buffer.from(output, "utf-8");
        const file = new AttachmentBuilder(buffer, { name: "eval-sonuc.txt" });
        await message.reply({ content: `${EMOJIS.usage} Eval sonucu (dosya olarak, çok uzun):`, files: [file] }).catch(() => null);
      }
    } catch (err: unknown) {
      const errMsg = maskSecrets(err instanceof Error ? err.stack ?? err.message : String(err));
      const embed = new EmbedBuilder()
        .setColor(0xed4245)
        .setTitle(`${EMOJIS.error} Eval hatası`)
        .setDescription("```\n" + errMsg.slice(0, 3900) + "\n```")
        .setTimestamp();
      await message.reply({ embeds: [embed] }).catch(() => null);
    }
  },
};

export default command;
","commands/owner/halfowner.ts":"import type { Message } from "discord.js";
import type { Command } from "../../types.js";
import {
  requireOwner,
  resolveTargetUserId,
  getGuildPrefix,
  OWNER_ID,
} from "../../events/messageCreate.js";
import {
  addHalfOwner,
  removeHalfOwner,
  listHalfOwnerIds,
  ensureHalfOwnersLoaded,
} from "../../premium/halfOwners.js";
import { warningEmbed, infoEmbed, successEmbed } from "../../utils/embeds.js";

// Half-owner: bot sahibinin, GERİ ALINABİLİR ve zararsız birkaç owner
// yetkisini devrettiği kişi. Şu an half-owner'ların erişebildiği komutlar:
//   • !premium        — premium verir
//   • !premium-kaldir — premium geri alır
//   • !premium-liste  — premium listesini görür (salt okunur)
//   • !özelüye        — VIP rozeti verir/alır
// Half-owner'lar eval/restart/panel-ac/ownerrole gibi
// TEHLİKELİ hiçbir owner komutuna ASLA erişemez — bu komutların hepsi
// doğrudan OWNER_ID kontrolü yapıyor, half-owner listesine hiç bakmıyor.
// Bu komutun kendisi de owner-only: half-owner başka bir half-owner
// ekleyemez/çıkaramaz, kendi yetkisini genişletemez.
const command: Command = {
  name: "halfowner",
  aliases: ["yariyetkili", "halfowners"],
  description:
    "Premium ve VIP yönetimi yetkisine sahip half-owner ekler/çıkarır/listeler (owner-only)",
  usage: "!halfowner ekle|sil|liste [@kullanıcı]",
  category: "owner",

  async execute(message: Message, args: string[]) {
    if (!(await requireOwner(message))) return;

    const prefix = getGuildPrefix(message.guild?.id);
    const sub = args[0]?.toLowerCase();

    if (
      !sub ||
      !["ekle", "add", "sil", "kaldir", "remove", "liste", "list"].includes(sub)
    ) {
      await message
        .reply({
          embeds: [
            warningEmbed(
              "Eksik kullanım",
              [
                `Kullanım:`,
                `\`${prefix}halfowner ekle @kullanıcı\``,
                `\`${prefix}halfowner sil @kullanıcı\``,
                `\`${prefix}halfowner liste\``,
                ``,
                `Half-owner'lar şunları yapabilir: \`${prefix}premium\`, \`${prefix}premium-kaldir\`, \`${prefix}premium-liste\`, \`${prefix}özelüye\`. Bunların dışında (restart, eval, panel-ac, ownerrole, half-owner ekleme/çıkarma vb.) HİÇBİR owner komutuna erişemezler.`,
              ].join("\n"),
            ),
          ],
        })
        .catch(() => null);
      return;
    }

    if (sub === "liste" || sub === "list") {
      await ensureHalfOwnersLoaded();
      const ids = listHalfOwnerIds();
      if (ids.length === 0) {
        await message
          .reply({
            embeds: [
              infoEmbed("Half-Owner Listesi", "Henüz hiç half-owner yok."),
            ],
          })
          .catch(() => null);
        return;
      }
      await message
        .reply({
          embeds: [
            infoEmbed(
              `Half-Owner Listesi — Toplam: ${ids.length}`,
              ids.map((id, i) => `\`${i + 1}.\` <@${id}>`).join("\n"),
            ),
          ],
        })
        .catch(() => null);
      return;
    }

    const targetId = resolveTargetUserId(message, args.slice(1));
    if (!targetId) {
      await message
        .reply({
          embeds: [
            warningEmbed(
              "Eksik kullanım",
              `Kullanım: \`${prefix}halfowner ${sub} @kullanıcı\``,
            ),
          ],
        })
        .catch(() => null);
      return;
    }

    if (targetId === OWNER_ID) {
      await message
        .reply({
          embeds: [
            warningEmbed(
              "Geçersiz hedef",
              "Bot sahibi zaten tüm yetkilere sahip, half-owner yapılamaz.",
            ),
          ],
        })
        .catch(() => null);
      return;
    }

    if (sub === "ekle" || sub === "add") {
      const added = await addHalfOwner(targetId, message.author.id);
      if (!added) {
        await message
          .reply({
            embeds: [
              warningEmbed(
                "Zaten half-owner",
                `<@${targetId}> zaten half-owner.`,
              ),
            ],
          })
          .catch(() => null);
        return;
      }
      await message
        .reply({
          embeds: [
            successEmbed(
              "Half-Owner Eklendi",
              `<@${targetId}> artık **half-owner**. \`${prefix}premium\`, \`${prefix}premium-kaldir\`, \`${prefix}premium-liste\` ve \`${prefix}özelüye\` komutlarını kullanabilir — başka hiçbir owner yetkisi yok.`,
              {
                fields: [
                  {
                    name: "👤 Half-Owner",
                    value: `<@${targetId}>`,
                    inline: true,
                  },
                  {
                    name: "🎁 Ekleyen",
                    value: `${message.author}`,
                    inline: true,
                  },
                ],
              },
            ),
          ],
        })
        .catch(() => null);
      return;
    }

    // sil / kaldir / remove
    const removed = await removeHalfOwner(targetId);
    if (!removed) {
      await message
        .reply({
          embeds: [
            warningEmbed(
              "Half-owner değil",
              `<@${targetId}> zaten half-owner değil.`,
            ),
          ],
        })
        .catch(() => null);
      return;
    }
    await message
      .reply({
        embeds: [
          infoEmbed(
            "Half-Owner Kaldırıldı",
            `<@${targetId}> kişisinin half-owner yetkisi geri alındı.`,
          ),
        ],
      })
      .catch(() => null);
  },
};

export default command;
","commands/owner/mentionai.ts":"import type { Message } from "discord.js";
import { PermissionFlagsBits } from "discord.js";
import type { Command } from "../../types.js";
import {
  requireOwner,
  getGuildPrefix,
  OWNER_ID,
} from "../../events/messageCreate.js";
import {
  getMentionAiModel,
  getMentionAiImageModel,
  getMentionAiRules,
  addMentionAiRule,
  removeMentionAiRule,
  isMentionAiEnabled,
  setMentionAiImageModel,
  setMentionAiEnabled,
  getMentionAiChannel,
  setMentionAiChannel,
  ensureMentionAiLoaded,
} from "../../utils/mentionai.js";
import { EMOJIS } from "../../utils/emojis.js";

/** Owner, half-owner veya sunucu Administrator. */
async function requireMentionAiAdmin(message: Message): Promise<boolean> {
  if (message.author.id === OWNER_ID) return true;
  const { ensureHalfOwnersLoaded, isHalfOwner } = await import(
    "../../premium/halfOwners.js"
  );
  await ensureHalfOwnersLoaded();
  if (isHalfOwner(message.author.id)) return true;
  if (message.member?.permissions.has(PermissionFlagsBits.Administrator))
    return true;
  await message
    .reply(
      `${EMOJIS.error} Bu komutu yalnızca bot sahibi, half-owner veya **Yönetici (Administrator)** yetkisine sahip üyeler kullanabilir.`,
    )
    .catch(() => null);
  return false;
}

/**
 * Türkçe karakterleri ASCII'ye indirger: görsel→gorsel, aç→ac.
 * Unicode farklarından kaynaklı eşleşme hatalarını önler.
 */
function normalizeAction(raw: string | undefined): string {
  if (!raw) return "";
  return raw
    .toLocaleLowerCase("tr-TR")
    .normalize("NFKD")
    .replace(/\p{M}/gu, "")
    .replace(/ı/g, "i")
    .replace(/ç/g, "c")
    .replace(/ş/g, "s")
    .replace(/ğ/g, "g")
    .replace(/ü/g, "u")
    .replace(/ö/g, "o")
    .trim();
}

const command: Command = {
  name: "mentionai",
  aliases: [],
  description:
    "MentionAI aç/kapat, kanal kısıtı, model ve kurallar (admin / owner)",
  usage:
    "!mentionai aç|kapat | kanal #kanal | model <model> | görsel <model> | kural-ekle <kural> | kural-sil <kural>",
  category: "owner",

  async execute(message: Message, args: string[]) {
    if (!message.guild)
      return message.reply(
        `${EMOJIS.error} Bu komut yalnızca sunucularda kullanılabilir.`,
      );

    await ensureMentionAiLoaded();
    const action = normalizeAction(args[0]);
    const prefix = getGuildPrefix(message.guild.id);

    if (action === "kural-ekle" || action === "kuralekle") {
      if (!(await requireOwner(message))) return;
      const rule = args.slice(1).join(" ").trim();
      if (!rule)
        return message.reply(
          `Kullanım: \`${prefix}mentionai kural-ekle <kural>\``,
        );
      const rules = await addMentionAiRule(rule);
      return message.reply(
        `${EMOJIS.success} MentionAI sistem promptuna kural eklendi. Aktif özel kural sayısı: **${rules.length}**`,
      );
    }
    if (action === "kural-sil" || action === "kuralsil") {
      if (!(await requireOwner(message))) return;
      const rule = args.slice(1).join(" ").trim();
      if (!rule)
        return message.reply(
          `Kullanım: \`${prefix}mentionai kural-sil <kural>\``,
        );
      const result = await removeMentionAiRule(rule);
      return message.reply(
        result.removed
          ? `${EMOJIS.success} MentionAI sistem promptundaki kural silindi. Kalan özel kural sayısı: **${result.rules.length}**`
          : `${EMOJIS.error} Bu kural sistem promptunda bulunamadı. Silme işlemi için kuralı metin olarak aynı yazmalısın.`,
      );
    }
    if (action === "model") {
      if (!(await requireOwner(message))) return;
      return message.reply(
        [
          "MentionAI sohbet modeli **!modeller** → **groq** grubuna bağlı (AFK vb. ile aynı).",
          "Aktif model: **" + getMentionAiModel() + "**",
          "Değiştirmek için: `" + prefix + "modeller`",
        ].join("\n"),
      );
    }

    // görsel / gorsel / image / imagemodel / visual
    if (
      action === "gorsel" ||
      action === "image" ||
      action === "imagemodel" ||
      action === "image-model" ||
      action === "visual" ||
      action === "img"
    ) {
      if (!(await requireOwner(message))) return;
      const model = args.slice(1).join(" ").trim();
      if (!model) {
        return message.reply(
          `Kullanım: \`${prefix}mentionai görsel <model adı>\`\nMevcut görsel modeli: **${getMentionAiImageModel()}**`,
        );
      }
      try {
        await setMentionAiImageModel(model);
      } catch (error) {
        return message.reply(
          `${EMOJIS.error} Görsel modeli ayarlanamadı: ${error instanceof Error ? error.message : String(error)}`,
        );
      }
      return message.reply(
        `${EMOJIS.success} MentionAI görsel modeli **${getMentionAiImageModel()}** olarak ayarlandı.\nÇiz isteklerinde bu model kullanılacak.`,
      );
    }

    // aç / kapat / kanal → yönetici (Administrator) + owner/half-owner
    // normalizeAction: aç→ac, kapat→kapat, kanal→kanal
    if (
      action === "ac" ||
      action === "kapat" ||
      action === "kapa" ||
      action === "kanal" ||
      action === "channel"
    ) {
      if (!(await requireMentionAiAdmin(message))) return;

      if (action === "kanal" || action === "channel") {
        const mentioned =
          message.mentions.channels.first() ??
          (args[1] &&
            message.guild.channels.cache.get(
              args[1].replace(/[<#>]/g, ""),
            ));
        const channelId =
          mentioned && "id" in mentioned
            ? mentioned.id
            : args[1]?.replace(/[<#>]/g, "") &&
                /^\d{15,25}$/.test(args[1].replace(/[<#>]/g, ""))
              ? args[1].replace(/[<#>]/g, "")
              : null;

        if (!channelId && !args[1]) {
          const current = getMentionAiChannel(message.guild.id);
          return message.reply(
            current
              ? `MentionAI şu an yalnızca <#${current}> kanalında çalışıyor.\nKapatmak için: \`${prefix}mentionai kanal <#${current}>\` (aynı kanalı tekrar ver = toggle)\nTüm kanallara açmak için de aynı komutu kullanabilirsin.`
              : `MentionAI kanal kısıtı **yok** (tüm kanallar).\nBelirli bir kanala kilitlemek: \`${prefix}mentionai kanal #kanal\``,
          );
        }

        if (!channelId) {
          return message.reply(
            `Kullanım: \`${prefix}mentionai kanal #kanal\` — toggle (aynı kanalı tekrar verirsen kısıt kalkar)`,
          );
        }

        const channel = message.guild.channels.cache.get(channelId);
        if (!channel || !channel.isTextBased()) {
          return message.reply(
            `${EMOJIS.error} Geçerli bir metin kanalı belirtmelisin.`,
          );
        }

        const result = await setMentionAiChannel(message.guild.id, channelId);
        if (result.toggledOff || !result.channelId) {
          return message.reply(
            `${EMOJIS.success} MentionAI kanal kısıtı kaldırıldı. Artık sunucuda MentionAI açıksa **tüm kanallarda** yanıt verebilir.`,
          );
        }
        return message.reply(
          `${EMOJIS.success} MentionAI artık yalnızca <#${result.channelId}> kanalında çalışacak. Diğer kanallarda mention/reply istekleri **gönderilmeyecek**.`,
        );
      }

      const enabled = action === "ac";
      await setMentionAiEnabled(message.guild.id, enabled);
      const channelNote = (() => {
        const ch = getMentionAiChannel(message.guild!.id);
        return ch ? ` (yalnızca <#${ch}>)` : "";
      })();
      return message.reply(
        enabled
          ? `${EMOJIS.success} MentionAI bu sunucuda açıldı${channelNote}. Kullanıcılar beni etiketleyerek veya bot mesajına reply vererek konuşabilir. "çiz …" dersen görsel de üretir.`
          : `${EMOJIS.success} MentionAI bu sunucuda kapatıldı.`,
      );
    }

    // Durum / yardım
    if (!(await requireMentionAiAdmin(message))) return;
    const status = isMentionAiEnabled(message.guild.id) ? "açık" : "kapalı";
    const channel = getMentionAiChannel(message.guild.id);
    return message.reply(
      [
        `Kullanım:`,
        `\`${prefix}mentionai aç|kapat\` — aç/kapat *(yönetici / owner / half-owner)*`,
        `\`${prefix}mentionai kanal #kanal\` — yalnızca o kanalda çalışsın (toggle)`,
        `\`${prefix}mentionai model <model adı>\` — sohbet modeli *(sadece owner)*`,
        `\`${prefix}mentionai görsel <model adı>\` — görsel modeli *(sadece owner)*`,
        `\`${prefix}mentionai kural-ekle|kural-sil <kural>\` — sistem kuralı *(sadece owner)*`,
        ``,
        `Şu anki durum: **${status}**`,
        `Sohbet modeli: **${getMentionAiModel()}**`,
        `Görsel modeli: **${getMentionAiImageModel()}**`,
        `Kanal kısıtı: **${channel ? `<#${channel}>` : "yok (tüm kanallar)"}**`,
        `Özel kural sayısı: **${(await getMentionAiRules()).length}**`,
      ].join("\n"),
    );
  },
};

export default command;
","commands/owner/mesaj.ts":"import { EmbedBuilder, PermissionFlagsBits, type Message } from "discord.js";
import type { Command } from "../../types.js";
import { EMOJIS } from "../../utils/emojis.js";
import { requireOwner, getGuildPrefix } from "../../events/messageCreate.js";
import { extractRawRest } from "../../utils/parse.js";
import { hasPermission } from "../../utils/permissions.js";

// !duyuru ve !say: "Sunucuyu Yönet" (Manage Guild) yetkisi olan HERKES
// kullanabilir, AMA bunun dışında sunucu sahibi/adminler `!izin say @kişi`
// veya `!izin duyuru @kişi` ile bu iznin olmadığı kullanıcılara da özel
// olarak izin verebilsin diye ban/kick/mute'la aynı `hasPermission` (izin
// sistemi) kontrolüne de bakıyoruz — ikisinden biri yeterli. (bkz. !izin)
async function canUseAnnounceCommands(message: Message, permName: "say" | "duyuru"): Promise<boolean> {
  if (message.member?.permissions.has(PermissionFlagsBits.ManageGuild)) return true;
  return hasPermission(message, permName);
}

// `!duyuru [#kanal] <metin>` / `!say [#kanal] <metin>` ortak ayrıştırması.
// İlk argüman bir #kanal mention'ıysa onu hedef alır, değilse mevcut kanalı
// kullanır. Metin, `args.join(" ")` ile DEĞİL ham mesaj içeriğinden
// (extractRawRest) alınır — aksi halde çok satırlı duyuru/mesaj metinleri
// tek satıra sıkışıyordu (bkz. customevent'teki aynı hata).
function parseChannelAndText(message: Message, args: string[], prefix: string) {
  const isChannelMention = /^<#\d+>$/.test(args[0] ?? "");
  const mentionedChannel = isChannelMention ? message.mentions.channels.first() ?? null : null;
  const targetChannel = mentionedChannel ?? message.channel;
  const tokenCount = mentionedChannel ? 2 : 1; // komut adı (+ varsa #kanal)
  const text = (extractRawRest(message.content, tokenCount, prefix) ?? "").trim();
  return { targetChannel, text };
}

export const duyuru: Command = {
  name: "duyuru",
  aliases: ["announce"],
  description: "Bot ağzından duyuru gönderir (Sunucuyu Yönet yetkisi veya !izin ile verilen özel izin gerekir)",
  usage: "!duyuru [#kanal] <metin>",
  category: "mod",

  async execute(message: Message, args: string[]) {
    if (!message.guild || !message.member) return;
    if (!(await canUseAnnounceCommands(message, "duyuru"))) {
      return message.reply(`${EMOJIS.error} Bu komutu kullanmak için **Sunucuyu Yönet** yetkisine veya \`!izin duyuru\` ile verilmiş özel izne ihtiyacın var.`);
    }

    const prefix = getGuildPrefix(message.guild.id);
    const { targetChannel, text } = parseChannelAndText(message, args, prefix);

    if (!text) {
      return message.reply(`${EMOJIS.uyari} Kullanım: \`${prefix}duyuru [#kanal] mesaj\``).catch(() => null);
    }
    if (text.length > 1_900) {
      return message.reply(`${EMOJIS.uyari} Duyuru metni en fazla 1.900 karakter olabilir.`).catch(() => null);
    }
    if (!("send" in targetChannel)) {
      return message.reply(`${EMOJIS.uyari} O kanal metin kanalı değil.`).catch(() => null);
    }
    if (!message.guild.members.me?.permissionsIn(targetChannel.id).has(PermissionFlagsBits.SendMessages)) {
      return message.reply(`${EMOJIS.uyari} O kanalda mesaj gönderme iznim yok.`).catch(() => null);
    }

    try {
      await targetChannel.send({ content: `📢 **Duyuru**\n${text}`, allowedMentions: { parse: [] } });
      await message.reply(`${EMOJIS.success} Duyuru gönderildi.`).catch(() => null);
    } catch (err) {
      console.error("Duyuru hatası:", err);
      await message.reply(`${EMOJIS.error} Duyuru gönderilemedi.`).catch(() => null);
    }
  },
};

