export const yeniEmbed: Command = {
  name: "yeniembed",
  aliases: ["newembed", "embedgonder"],
  description: "Bot ağzından embed gönderir (owner-only)",
  usage: "!yeniembed [#kanal] Başlık | Açıklama | #renk",
  category: "owner",

  async execute(message: Message, args: string[]) {
    if (!(await requireOwner(message))) return;
    const targetChannel = message.mentions.channels.first() ?? message.channel;
    const rawArgs = args.filter((a) => !/^<#\d+>$/.test(a)).join(" ");
    if (!rawArgs.includes("|")) {
      const tutorial = new EmbedBuilder()
        .setColor(0x5865f2)
        .setTitle("📘 !yeniembed Kullanımı")
        .setDescription(`\`${getGuildPrefix(message.guild?.id)}yeniembed [#kanal] Başlık | Açıklama | #renk\``)
        .setTimestamp();
      await message.reply({ embeds: [tutorial] }).catch(() => null);
      return;
    }
    const [title, description, colorRaw] = rawArgs.split("|").map((p) => p.trim());
    if (!title || !description) {
      await message.reply(` ${EMOJIS.uyari} Başlık ve açıklama zorunlu.`).catch(() => null);
      return;
    }
    if (title.length > 256 || description.length > 4_096) {
      await message.reply(` ${EMOJIS.uyari} Başlık en fazla 256, açıklama en fazla 4.096 karakter olabilir.`).catch(() => null);
      return;
    }
    let color = 0x5865f2;
    if (colorRaw) {
      const hex = colorRaw.replace("#", "");
      if (/^[0-9a-fA-F]{6}$/.test(hex)) color = parseInt(hex, 16);
    }
    if (!("send" in targetChannel)) {
      await message.reply(`${EMOJIS.uyari} O kanal metin kanalı değil.`).catch(() => null);
      return;
    }
    const embed = new EmbedBuilder().setColor(color).setTitle(title).setDescription(description).setTimestamp();
    try {
      await targetChannel.send({ embeds: [embed], allowedMentions: { parse: [] } });
      await message.reply(` ${EMOJIS.success} Embed gönderildi.`).catch(() => null);
    } catch (err) {
      console.error("yeniembed hatası:", err);
      await message.reply(` ${EMOJIS.error} Embed gönderilemedi.`).catch(() => null);
    }
  },
};
