","commands/prefix.ts":"import type { Message } from "discord.js";
import type { Command } from "../types.js";
import { DEFAULT_PREFIX } from "../config.js";
import { EMOJIS } from "../utils/emojis.js";
import { getGuildPrefix, setGuildPrefix, resetGuildPrefix, requireOwnerOrGuildOwner } from "../events/messageCreate.js";

// Kötüye kullanımı önlemek için: boşluksuz, makul uzunlukta, mention/kod
// bloğu gibi Discord'u karıştıracak karakterler içermeyen bir prefix.
const PREFIX_REGEX = /^[^\sA-Za-z0-9@#:`]{1,5}$|^[!.+?$%^&*\-_=~]{1,5}$/;

const command: Command = {
  name: "prefix",
  description: "Bu sunucuya özel komut prefix'ini değiştirir (sadece sunucu sahibi/taç sahibi ya da bot sahibi)",
  usage: "!prefix <yeni-prefix | sıfırla>",
  category: "genel",

  async execute(message: Message, args: string[]) {
    // Prefix artık sunucu bazlı olduğu için bu komut sadece sunucu içinde
    // anlamlıdır — DM'lerde ayarlanacak bir "sunucu" yok.
    if (!message.guild) {
      return message.reply(`${EMOJIS.error} Bu komut sadece bir sunucu içinde kullanılabilir.`);
    }

    // Yetki: bot sahibi (owner) ya da bu sunucunun sahibi (taç sahibi).
    // Önceden sadece bot sahibi kullanabiliyordu; artık her sunucu kendi
    // prefix'ini kendi sahibi üzerinden de yönetebiliyor.
    if (!(await requireOwnerOrGuildOwner(message))) return;

    const guildId = message.guild.id;
    const currentPrefix = getGuildPrefix(guildId);
    const firstArg = args[0]?.toLowerCase();

    if (!firstArg) {
      return message.reply(
        `${EMOJIS.info} Bu sunucudaki şu anki prefix: \`${currentPrefix}\`\n` +
        `Değiştirmek için: \`${currentPrefix}prefix <yeni-prefix>\` (ör. \`${currentPrefix}prefix +\`)\n` +
        `Varsayılana (\`${DEFAULT_PREFIX}\`) döndürmek için: \`${currentPrefix}prefix sıfırla\``,
      );
    }

    if (firstArg === "sıfırla" || firstArg === "reset") {
      if (currentPrefix === DEFAULT_PREFIX) {
        return message.reply(`${EMOJIS.info} Bu sunucu zaten varsayılan prefix'i (\`${DEFAULT_PREFIX}\`) kullanıyor.`);
      }
      await resetGuildPrefix(guildId);
      return message.reply(
        `${EMOJIS.success} Prefix varsayılana döndürüldü: \`${currentPrefix}\` ${EMOJIS.next} \`${DEFAULT_PREFIX}\`\n` +
        `Artık bu sunucuda komutlar \`${DEFAULT_PREFIX}\` ile başlamalı (ör. \`${DEFAULT_PREFIX}ping\`).`,
      );
    }

    const newPrefix = args[0];

    if (newPrefix.length > 5 || !PREFIX_REGEX.test(newPrefix)) {
      return message.reply(`${EMOJIS.usage} Kullanım: \`${currentPrefix}prefix <yeni-prefix>\` (ör. \`${currentPrefix}prefix +\`)`);
    }

    if (newPrefix === currentPrefix) {
      return message.reply(`${EMOJIS.info} Bu sunucunun prefix'i zaten \`${currentPrefix}\`.`);
    }

    await setGuildPrefix(guildId, newPrefix);

    return message.reply(
      `${EMOJIS.success} Bu sunucunun prefix'i güncellendi: \`${currentPrefix}\` ${EMOJIS.next} \`${newPrefix}\`\n` +
      `Artık bu sunucuda komutlar \`${newPrefix}\` ile başlamalı (ör. \`${newPrefix}ping\`). Bu ayar sadece bu sunucuyu etkiler, diğer sunucular kendi prefix'lerini korur.`,
    );
  },
};

export default command;
","commands/restart.ts":"import type { Message } from "discord.js";
import type { Command } from "../types.js";
import { OWNER_ID } from "../config.js";
import { prepareRestartChangelog } from "../utils/changelog.js";

const command: Command = {
  name: "restart",
  aliases: ["yenidenbaşlat", "reboot"],
  description: "Botu yeniden başlatır. (owner-only)",
  usage: "!restart",
  category: "owner",

  async execute(message: Message) {
    if (message.author.id !== OWNER_ID) {
      await message.reply("<a:1000021813:1540389526873317518> Bu komutu sadece bot sahibi kullanabilir.").catch(() => {});
      return;
    }

    await message.reply(" <a:1000021907:1540738818297303111> Yeniden başlatılıyor... (tekrar açıldığında değişiklik raporu buraya gelecek)").catch(() => {});

    // Restart'tan önce kaynak kodun anlık görüntüsünü al ve raporun nereye
    // gönderileceğini kaydet — böylece bot tekrar ayağa kalktığında (bkz.
    // utils/changelog.ts + ready event) AI ile özetlenmiş bir değişiklik
    // raporu otomatik olarak buraya gönderilir. Bu adım ASLA restart'ı
    // engellememeli; hata olursa changelog.ts sessizce loglar.
    await prepareRestartChangelog({
      guildId: message.guild?.id ?? null,
      channelId: message.channel.id,
      triggeredBy: message.author.id,
    }).catch(() => {});

    // Pterodactyl (/home/container) ortamında çalışıyoruz: "npm start" container'ın
    // ana process'i. Süreci kapatıyoruz, panelin "crash detection" / otomatik
    // yeniden başlatma özelliği botu tekrar ayağa kaldırıyor.
    setTimeout(() => process.exit(1), 500);
  },
};

