          typeof event !== "object" ||
          typeof (event as { name?: unknown }).name !== "string" ||
          typeof (event as { code?: unknown }).code !== "string" ||
          typeof (event as { createdBy?: unknown }).createdBy !== "string"
        ) {
          continue;
        }
        const item = event as { name: string; code: string; createdBy: string; createdAt?: string };
        const name = item.name.toLowerCase().trim();
        if (!NAME_REGEX.test(name) || validateCustomEventCode(item.code)) continue;

        await pool.query(
          `INSERT INTO discord_custom_commands
             (guild_id, name, description, type, config, created_by, created_at, updated_at)
           VALUES ($1, $2, $3, $4, $5::jsonb, $6, $7, NOW())
           ON CONFLICT (guild_id, name) DO NOTHING`,
          [
            guildId,
            name,
            "Güvenli YAGPDB uyumlu custom event",
            "safe-template-v2",
            JSON.stringify(emptyConfig(item.code)),
            item.createdBy,
            item.createdAt && !Number.isNaN(Date.parse(item.createdAt)) ? new Date(item.createdAt) : new Date(),
          ],
        );
      }
    }

    const backup = `${legacyFile}.migrated`;
    fs.renameSync(legacyFile, backup);
    console.log("[CustomEvent] Eski JSON custom event'leri veritabanına taşındı.");
  } catch (err) {
    legacyMigrationPromise = null;
    console.error("[CustomEvent] Eski JSON taşıması başarısız:", err);
  }
