let reservedNames = new Set<string>();
export function setReservedCommandNames(names: Iterable<string>): void {
  reservedNames = new Set(names);
}

export type CreateResult = { ok: true; event: CustomEvent } | { ok: false; error: string };

export async function createCustomEvent(
  guildId: string,
  name: string,
  code: string,
  authorId: string,
): Promise<CreateResult> {
  const normalizedName = name.toLowerCase().trim();
  if (!NAME_REGEX.test(normalizedName)) {
    return { ok: false, error: "İsim 2-20 karakter olmalı, sadece küçük harf/rakam/`-`/`_` içerebilir ve harfle başlamalı." };
  }
  if (reservedNames.has(normalizedName)) {
    return { ok: false, error: `\`${normalizedName}\` botun kendi komutlarından biri, başka bir isim seç.` };
  }

  const codeError = validateCustomEventCode(code);
  if (codeError) return { ok: false, error: codeError };

  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    // Aynı sunucuda eşzamanlı iki create isteğinin limit kontrolünü aşmasını
    // önlemek için kontrol ve upsert aynı transaction içinde kilitlenir.
    await client.query("SELECT pg_advisory_xact_lock(hashtextextended($1, 0))", [guildId]);

    const existingResult = await client.query<DbRow>(
      `SELECT guild_id, name, config, created_by, created_at, updated_at
       FROM discord_custom_commands
       WHERE guild_id = $1 AND name = $2 AND type = 'safe-template-v2'
       LIMIT 1`,
      [guildId, normalizedName],
    );
    const existing = existingResult.rows[0] ? toCustomEvent(existingResult.rows[0]) : null;

    if (!existing) {
      const count = await client.query<{ count: string }>(
        `SELECT COUNT(*)::text AS count FROM discord_custom_commands
         WHERE guild_id = $1 AND type = 'safe-template-v2'`,
        [guildId],
      );
      if (Number(count.rows[0]?.count ?? 0) >= MAX_CUSTOM_EVENTS_PER_GUILD) {
        await client.query("ROLLBACK");
        return {
          ok: false,
          error: `Bu sunucuda en fazla ${MAX_CUSTOM_EVENTS_PER_GUILD} custom event olabilir. Önce \`custom-sil\` ile birini silmelisin.`,
        };
      }
    }

    const result = await client.query<DbRow>(
      `INSERT INTO discord_custom_commands
         (guild_id, name, description, type, config, created_by, created_at, updated_at)
       VALUES ($1, $2, $3, 'safe-template-v2', $4::jsonb, $5, COALESCE($6, NOW()), NOW())
       ON CONFLICT (guild_id, name)
       DO UPDATE SET config = EXCLUDED.config, description = EXCLUDED.description,
                     type = EXCLUDED.type, updated_at = NOW()
       RETURNING guild_id, name, config, created_by, created_at, updated_at`,
      [
        guildId,
        normalizedName,
        "Güvenli YAGPDB uyumlu custom event",
        JSON.stringify({
          code,
          enabled: existing?.enabled ?? true,
          restrictions: existing?.restrictions ?? DEFAULT_RESTRICTIONS,
        }),
        existing?.createdBy ?? authorId,
        existing?.createdAt ?? null,
      ],
    );
    await client.query("COMMIT");
    return { ok: true, event: toCustomEvent(result.rows[0]) };
  } catch (error) {
    await client.query("ROLLBACK").catch(() => undefined);
    throw error;
  } finally {
    client.release();
  }
}

export async function updateCustomEventSettings(
  guildId: string,
  name: string,
  patch: Partial<CustomEventRestrictions> & { enabled?: boolean },
): Promise<CustomEvent | null> {
  const event = await getCustomEvent(guildId, name);
  if (!event) return null;

  const restrictions = normalizeRestrictions({
    ...event.restrictions,
    ...patch,
  });
  const enabled = patch.enabled ?? event.enabled;
  const result = await pool.query<DbRow>(
    `UPDATE discord_custom_commands
     SET config = $3::jsonb, updated_at = NOW()
     WHERE guild_id = $1 AND name = $2 AND type = 'safe-template-v2'
     RETURNING guild_id, name, config, created_by, created_at, updated_at`,
    [guildId, name.toLowerCase().trim(), JSON.stringify({ code: event.code, enabled, restrictions })],
  );
  return result.rows[0] ? toCustomEvent(result.rows[0]) : null;
}

export async function deleteCustomEvent(guildId: string, name: string): Promise<boolean> {
  const result = await pool.query(
    `DELETE FROM discord_custom_commands
     WHERE guild_id = $1 AND name = $2 AND type = 'safe-template-v2'`,
    [guildId, name.toLowerCase().trim()],
  );
  return (result.rowCount ?? 0) > 0;
