    CREATE TABLE IF NOT EXISTS discord_premium_users (
      user_id TEXT PRIMARY KEY,
      granted_by TEXT NOT NULL,
      granted_at TIMESTAMP NOT NULL DEFAULT NOW()
    );
  `);
  await pool.query(`
    CREATE TABLE IF NOT EXISTS discord_command_trials (
      key TEXT PRIMARY KEY,
      user_id TEXT NOT NULL,
      command_name TEXT NOT NULL,
      uses INTEGER NOT NULL DEFAULT 0
    );
  `);
  await pool.query(`
    CREATE INDEX IF NOT EXISTS idx_command_trials_user ON discord_command_trials(user_id);
  `);

  // 🪪 Yarı-yetkili (half-owner) listesi
  await pool.query(`
    CREATE TABLE IF NOT EXISTS discord_half_owners (
      user_id TEXT PRIMARY KEY,
      added_by TEXT NOT NULL,
      added_at TIMESTAMP NOT NULL DEFAULT NOW()
    );
  `);

  // 🧠 Bilgi Yarışması sistemi
  await pool.query(`
    CREATE TABLE IF NOT EXISTS discord_quiz_scores (
      key TEXT PRIMARY KEY,
      guild_id TEXT NOT NULL,
      user_id TEXT NOT NULL,
      wins INTEGER NOT NULL DEFAULT 0,
      updated_at TIMESTAMP NOT NULL DEFAULT NOW()
    );
  `);
  await pool.query(`
    CREATE INDEX IF NOT EXISTS idx_quiz_scores_guild ON discord_quiz_scores(guild_id, wins DESC);
  `);

  // 🔤 Kelime Zinciri: kalıcı kanal + kalıcı oyun durumu (bkz. schema.ts)
  await pool.query(`
    CREATE TABLE IF NOT EXISTS discord_wordchain_channels (
      guild_id TEXT PRIMARY KEY,
      channel_id TEXT NOT NULL,
      last_word TEXT,
      required_letter TEXT,
      used_words TEXT NOT NULL DEFAULT '[]',
      streak INTEGER NOT NULL DEFAULT 0,
      last_player_id TEXT,
      best_streak INTEGER NOT NULL DEFAULT 0,
      best_holder_id TEXT,
      set_by TEXT NOT NULL,
      created_at TIMESTAMP NOT NULL DEFAULT NOW(),
      updated_at TIMESTAMP NOT NULL DEFAULT NOW()
    );
  `);
  await pool.query(`
    CREATE INDEX IF NOT EXISTS idx_wordchain_channel ON discord_wordchain_channels(channel_id);
  `);

  // 🔤 Kelime Zinciri: kullanılmış kelimeler artık ayrı tabloda (bkz. schema.ts
  // üstündeki açıklama — eski tek-satırlık büyüyen JSON kolonu yer/I-O israfıydı).
  await pool.query(`
    CREATE TABLE IF NOT EXISTS discord_wordchain_used_words (
      channel_id TEXT NOT NULL,
      word TEXT NOT NULL,
      created_at TIMESTAMP NOT NULL DEFAULT NOW(),
      PRIMARY KEY (channel_id, word)
    );
  `);

  // Tek seferlik geçiş: eski `used_words` JSON kolonunda hâlâ veri varsa yeni
  // tabloya aktar, sonra eski kolonu boşalt (satırı küçültmek için — kolonu
  // DROP etmiyoruz, geri dönüş kolaylığı ve başka bir yerde referans kalmış
  // olma ihtimaline karşı zararsız duruyor).
  const { rows: legacyRows } = await pool.query<{ channel_id: string; used_words: string }>(
    `SELECT channel_id, used_words FROM discord_wordchain_channels WHERE used_words IS NOT NULL AND used_words <> '[]';`,
  );
  let migratedLegacyRows = 0;
  for (const row of legacyRows) {
    let words: string[];
    try {
      const parsed = JSON.parse(row.used_words);
      if (!Array.isArray(parsed)) {
        console.warn(`[db] Kelime zinciri legacy verisi dizi değil, korunuyor: ${row.channel_id}`);
        continue;
      }
      words = parsed.filter((w): w is string => typeof w === "string");
    } catch {
      // Bozuk bir satırdaki veriyi sessizce silme; yönetici daha sonra manuel
      // inceleyebilsin ve diğer sunucuların migrasyonu devam edebilsin.
      console.warn(`[db] Kelime zinciri legacy JSON'u okunamadı, korunuyor: ${row.channel_id}`);
      continue;
    }
    if (words.length > 0) {
      await pool.query(
        `INSERT INTO discord_wordchain_used_words (channel_id, word)
         SELECT $1, w FROM unnest($2::text[]) AS w
         ON CONFLICT (channel_id, word) DO NOTHING;`,
        [row.channel_id, words],
      );
    }
    // Yalnızca başarıyla parse edilen ve işlenen satırı küçült; bozuk/şüpheli
    // kayıtları toplu UPDATE ile yanlışlıkla kaybetme.
    await pool.query(`UPDATE discord_wordchain_channels SET used_words = '[]' WHERE channel_id = $1;`, [row.channel_id]);
    migratedLegacyRows++;
  }
  if (migratedLegacyRows > 0) {
    console.log(`🔤 Kelime Zinciri: ${migratedLegacyRows} kanalın kelime geçmişi yeni tabloya taşındı.`);
  }

  await pool.query(`
    CREATE INDEX IF NOT EXISTS idx_wordchain_used_words_channel ON discord_wordchain_used_words(channel_id);
  `);

  // 🔤 Kelime Zinciri: sunucu bazında gerçek oyuncu skorları.
  await pool.query(`
    CREATE TABLE IF NOT EXISTS discord_wordchain_scores (
      guild_id TEXT NOT NULL,
      user_id TEXT NOT NULL,
      words INTEGER NOT NULL DEFAULT 0,
      updated_at TIMESTAMP NOT NULL DEFAULT NOW(),
      PRIMARY KEY (guild_id, user_id)
    );
  `);
  await pool.query(`
    CREATE INDEX IF NOT EXISTS idx_wordchain_scores_guild ON discord_wordchain_scores(guild_id, words DESC);
  `);

  console.log("✅ Tüm tablolar hazır.");
}

