// Premium olmayan kullanıcılar için, komut başına sınırlı sayıda ücretsiz
// deneme hakkı. `key` = "userId:commandName" — her komut kendi hakkını
// ayrı sayar (ör. kod-yaz'daki 3 hak bitince ozetle hâlâ kullanılabilir).
export const commandTrialsTable = pgTable("discord_command_trials", {
