","deploy.ts":"import { REST, Routes } from "discord.js";
import type { Command } from "./types.js";

/**
 * Slash komutlarını Discord'a kaydeder.
 *
 * Komutlar bot hazır olmadan da REST üzerinden kaydedilebilir; ancak client
 * ID'sini token'ın ilk parçasından çıkarmak kırılgan ve hata ayıklaması zor.
 * Ready event'inden gelen clientId'yi tercih ediyoruz. `SLASH_GUILD_ID`
 * (veya mevcut kurulumlarda kullanılan `GUILD_ID`) verilirse komutlar anında
 * o sunucuya, verilmezse global olarak kaydedilir.
 */
export async function deploySlashCommands(
  token: string,
  commands: Command[],
  clientId: string,
): Promise<void> {
  const slashCommands = commands
    .filter((c) => c.slashData != null)
    .map((c) => c.slashData!.toJSON());

  if (slashCommands.length === 0) return;

  const rest = new REST({ version: "10" }).setToken(token);
  const guildId = (process.env.SLASH_GUILD_ID ?? process.env.GUILD_ID)?.trim();
  const route = guildId
    ? Routes.applicationGuildCommands(clientId, guildId)
    : Routes.applicationCommands(clientId);
  const scopeLabel = guildId ? `sunucu (${guildId})` : "global";

  console.log(`📡 ${slashCommands.length} slash komutu ${scopeLabel} olarak kaydediliyor...`);
  try {
    await rest.put(route, { body: slashCommands });
    console.log(`✅ ${slashCommands.length} slash komutu ${scopeLabel} olarak kaydedildi.`);
  } catch (err: unknown) {
    console.error("❌ Slash komutlar kaydedilirken hata:", err instanceof Error ? err.message : String(err));
  }
}
","events/bulkSelection.ts":"import type { Interaction } from "discord.js";

/**
 * Panel "toplu silme" akışı için geçici seçim state'i.
 * interactionCreate.ts içinden ayrıldı — dosya boyutunu ve yan etki riskini
 * azaltmak için.
 */

const bulkDeleteSelections = new Map<
  string,
  { channels: string[]; roles: string[] }
>();
const bulkSelectionLastTouched = new Map<string, number>();
const BULK_SELECTION_TTL_MS = 15 * 60_000;

export function bulkSelectionKey(interaction: Interaction): string {
  return `${interaction.guildId ?? "dm"}:${interaction.user.id}`;
}

export function getBulkSelection(
  key: string,
): { channels: string[]; roles: string[] } | undefined {
  return bulkDeleteSelections.get(key);
}

export function saveBulkSelection(
  key: string,
  selection: { channels: string[]; roles: string[] },
): void {
  bulkDeleteSelections.set(key, selection);
  bulkSelectionLastTouched.set(key, Date.now());
}

export function deleteBulkSelection(key: string): void {
  bulkDeleteSelections.delete(key);
  bulkSelectionLastTouched.delete(key);
}

const bulkSelectionCleanup = setInterval(() => {
  const cutoff = Date.now() - BULK_SELECTION_TTL_MS;
  for (const [key, touchedAt] of bulkSelectionLastTouched) {
    if (touchedAt < cutoff) deleteBulkSelection(key);
  }
}, BULK_SELECTION_TTL_MS);
bulkSelectionCleanup.unref?.();
