          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    await updateGuardConfig(interaction.guildId!, {
      actionPunishment: punishment as GuardConfig["actionPunishment"],
      restoreDeletedChannels: restoreRaw === "true",
    });
    await interaction
      .reply({
        content: "✅ Ceza ve kanal kurtarma ayarları kaydedildi.",
        ephemeral: true,
      })
      .catch(() => null);
    return;
