      .update(await buildGuardAdvancedPanel(interaction.guildId!))
      .catch(() => null);
    return;
  }
  if (
    interaction.isStringSelectMenu() &&
    (interaction.customId === "guard_select_core" ||
      interaction.customId === "guard_select_nuke")
  ) {
    if (!interaction.inGuild() || !hasGuardPanelAccess(interaction)) {
      await interaction
        .reply({
          content: MSG.error(
            "Bu paneli yalnızca sunucu sahibi veya bot sahibi kullanabilir.",
          ),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    const allowedKeys =
      interaction.customId === "guard_select_core"
        ? GUARD_CORE_SELECT_KEYS
        : GUARD_NUKE_SELECT_KEYS;
    const selected = new Set(interaction.values);
    const updates = Object.fromEntries(
      allowedKeys.map((key) => [key, selected.has(key)]),
    ) as Partial<GuardConfig>;
    try {
      await updateGuardConfig(interaction.guildId!, updates);
      await interaction
        .update(await buildGuardPanel(interaction.guildId!))
        .catch(() => null);
    } catch (error) {
      console.error("Guard panel güncelleme hatası:", error);
      await interaction
        .reply({
          content: MSG.error("Guard ayarı kaydedilemedi."),
          ephemeral: true,
        })
        .catch(() => null);
    }
    return;
  }

  // -------------------------------------------------------------------
  // !hosgeldin paneli — kanal seçimi, mesaj/görsel modalları, aç-kapat,
  // sıfırlama ve yenileme. Tüm "welcome_panel_" customId'leri burada.
  // -------------------------------------------------------------------
  if (
    interaction.isChannelSelectMenu() &&
    interaction.customId === "welcome_panel_channel"
  ) {
    if (!hasWelcomePanelAccess(interaction)) {
      await interaction
        .reply({
          content: MSG.error(
            "Bu paneli kullanmak için Sunucuyu Yönet yetkisine ihtiyacın var.",
          ),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    const channelId = interaction.values[0];
    await updateGuildWelcomeConfig(interaction.guildId!, { channelId });
    await interaction
      .update(await buildWelcomePanelView(interaction.guildId!))
      .catch(() => null);
    return;
  }

  if (
    interaction.isButton() &&
    (interaction.customId === "welcome_panel_msg_welcome" ||
      interaction.customId === "welcome_panel_msg_leave")
  ) {
    if (!hasWelcomePanelAccess(interaction)) {
      await interaction
        .reply({
          content: MSG.error(
            "Bu paneli kullanmak için Sunucuyu Yönet yetkisine ihtiyacın var.",
          ),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    const side =
      interaction.customId === "welcome_panel_msg_welcome"
        ? "welcome"
        : "leave";
    const cfg = await getGuildWelcomeConfig(interaction.guildId!);
    const current = (side === "welcome" ? cfg.message : cfg.leaveMessage) ?? "";
    const modal = new ModalBuilder()
      .setCustomId(`welcome_panel_submit_msg_${side}`)
      .setTitle(side === "welcome" ? "Giriş Mesajı" : "Çıkış Mesajı");
    const input = new TextInputBuilder()
      .setCustomId("value")
      .setLabel("Mesaj metni ({n} {kullanici} {isim} {sunucu})")
      .setStyle(TextInputStyle.Paragraph)
      .setRequired(true)
      .setMaxLength(MAX_TEMPLATE_LENGTH);
    if (current) input.setValue(current);
    modal.addComponents(
      new ActionRowBuilder<TextInputBuilder>().addComponents(input),
    );
    await interaction.showModal(modal).catch(() => null);
    return;
  }

  if (
    interaction.isModalSubmit() &&
    (interaction.customId === "welcome_panel_submit_msg_welcome" ||
      interaction.customId === "welcome_panel_submit_msg_leave")
  ) {
    if (!hasWelcomePanelAccess(interaction)) return;
    const side =
      interaction.customId === "welcome_panel_submit_msg_welcome"
        ? "welcome"
        : "leave";
    const value = interaction.fields.getTextInputValue("value").trim();
    if (!value) {
      await interaction
        .reply({ content: MSG.error("Mesaj boş olamaz."), ephemeral: true })
        .catch(() => null);
      return;
    }
    if (isTemplateTooLong(value)) {
      await interaction
        .reply({
          content: MSG.error(
            `Mesaj çok uzun. En fazla ${MAX_TEMPLATE_LENGTH} karakter olabilir.`,
          ),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    await updateGuildWelcomeConfig(
      interaction.guildId!,
      side === "welcome" ? { message: value } : { leaveMessage: value },
    );
    await interaction
      .reply({
        content: `✅ ${side === "welcome" ? "Giriş" : "Çıkış"} mesajı kaydedildi. Paneli görmek için \`Yenile\`ye bas.`,
        ephemeral: true,
      })
      .catch(() => null);
    return;
  }

  if (
    interaction.isButton() &&
    (interaction.customId === "welcome_panel_img_welcome" ||
      interaction.customId === "welcome_panel_img_leave")
  ) {
    if (!hasWelcomePanelAccess(interaction)) {
      await interaction
        .reply({
          content: MSG.error(
            "Bu paneli kullanmak için Sunucuyu Yönet yetkisine ihtiyacın var.",
          ),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    const side =
      interaction.customId === "welcome_panel_img_welcome"
        ? "welcome"
        : "leave";
    const cfg = await getGuildWelcomeConfig(interaction.guildId!);
    const current =
      (side === "welcome" ? cfg.welcomeImage : cfg.leaveImage) ?? "";
    const modal = new ModalBuilder()
      .setCustomId(`welcome_panel_submit_img_${side}`)
      .setTitle(side === "welcome" ? "Giriş Görseli" : "Çıkış Görseli");
    const input = new TextInputBuilder()
      .setCustomId("value")
      .setLabel("Resim URL'si (boş bırak = kaldır)")
      .setPlaceholder("https://...")
      .setStyle(TextInputStyle.Short)
      .setRequired(false)
      .setMaxLength(500);
    if (current) input.setValue(current);
    modal.addComponents(
      new ActionRowBuilder<TextInputBuilder>().addComponents(input),
    );
    await interaction.showModal(modal).catch(() => null);
    return;
  }

  if (
    interaction.isModalSubmit() &&
    (interaction.customId === "welcome_panel_submit_img_welcome" ||
      interaction.customId === "welcome_panel_submit_img_leave")
  ) {
    if (!hasWelcomePanelAccess(interaction)) return;
    const side =
      interaction.customId === "welcome_panel_submit_img_welcome"
        ? "welcome"
        : "leave";
    const raw = interaction.fields.getTextInputValue("value").trim();
    if (raw && !/^https?:\/\/\S+$/i.test(raw)) {
      await interaction
        .reply({
          content: MSG.error(
            "Geçerli bir http(s):// resim linki gir, ya da boş bırakıp kaydet.",
          ),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    await updateGuildWelcomeConfig(
      interaction.guildId!,
      side === "welcome"
        ? { welcomeImage: raw || null }
        : { leaveImage: raw || null },
    );
    await interaction
      .reply({
        content: `✅ ${side === "welcome" ? "Giriş" : "Çıkış"} görseli ${raw ? "kaydedildi" : "kaldırıldı"}. Paneli görmek için \`Yenile\`ye bas.`,
        ephemeral: true,
      })
      .catch(() => null);
    return;
  }

  if (
    interaction.isButton() &&
    (interaction.customId === "welcome_panel_reset_welcome" ||
      interaction.customId === "welcome_panel_reset_leave")
  ) {
    if (!hasWelcomePanelAccess(interaction)) {
      await interaction
        .reply({
          content: MSG.error(
            "Bu paneli kullanmak için Sunucuyu Yönet yetkisine ihtiyacın var.",
          ),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    const side =
      interaction.customId === "welcome_panel_reset_welcome"
        ? "welcome"
        : "leave";
    await updateGuildWelcomeConfig(
      interaction.guildId!,
      side === "welcome"
        ? { message: null, welcomeImage: null }
        : { leaveMessage: null, leaveImage: null },
    );
    await interaction
      .update(await buildWelcomePanelView(interaction.guildId!))
      .catch(() => null);
    return;
  }

  if (
    interaction.isButton() &&
    interaction.customId === "welcome_panel_toggle"
  ) {
    if (!hasWelcomePanelAccess(interaction)) {
      await interaction
        .reply({
          content: MSG.error(
            "Bu paneli kullanmak için Sunucuyu Yönet yetkisine ihtiyacın var.",
          ),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    const cfg = await getGuildWelcomeConfig(interaction.guildId!);
    if (!cfg.enabled && (!cfg.channelId || !cfg.message)) {
      await interaction
        .reply({
          content: MSG.error(
            "Sistemi açmadan önce bir kanal ve giriş mesajı ayarlamalısın.",
          ),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    await updateGuildWelcomeConfig(interaction.guildId!, {
      enabled: !cfg.enabled,
    });
    await interaction
      .update(await buildWelcomePanelView(interaction.guildId!))
      .catch(() => null);
    return;
  }

  if (
    interaction.isButton() &&
    interaction.customId === "welcome_panel_refresh"
  ) {
    if (!hasWelcomePanelAccess(interaction)) {
      await interaction
        .reply({
          content: MSG.error(
            "Bu paneli kullanmak için Sunucuyu Yönet yetkisine ihtiyacın var.",
          ),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    await interaction
      .update(await buildWelcomePanelView(interaction.guildId!))
      .catch(() => null);
    return;
  }

  // -------------------------------------------------------------------
  // !panel: sekme (tab) butonları — panel_tab_genel / panel_tab_mod / ...
  // -------------------------------------------------------------------
  if (interaction.isButton() && interaction.customId.startsWith("panel_tab_")) {
    if (!hasPanelAccess(interaction)) {
      await interaction
        .reply({
          content: MSG.error(
            'Paneli görüntülemek için "Üyeleri Yönet" iznine sahip olman gerekiyor.',
          ),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    try {
      const tab = interaction.customId.replace("panel_tab_", "") as PanelTab;
      await interaction.update(
        buildPanelView(tab, {
          guild: interaction.guild,
          client: interaction.client,
        }),
      );
    } catch (err) {
      console.error("Panel sekme geçişi hatası:", err);
    }
    return;
  }

  // -------------------------------------------------------------------
  // !panel: "Durum" sekmesindeki "Yenile" butonu — üye/kanal/rol sayısı ve
  // ping gibi anlık verileri günceller. panel_tab_info ile çakışmaması için
  // ayrı bir customId kullanıyor (aynı mesajda iki bileşen aynı customId'yi
  // paylaşamaz).
  // -------------------------------------------------------------------
  if (interaction.isButton() && interaction.customId === "panel_refresh_info") {
    if (!hasPanelAccess(interaction)) {
      await interaction
        .reply({
          content: MSG.error("Paneli görüntüleme iznin yok."),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    try {
      await interaction.update(
        buildPanelView("info", {
          guild: interaction.guild,
          client: interaction.client,
        }),
      );
    } catch (err) {
      console.error("Durum yenileme hatası:", err);
    }
    return;
  }

  // -------------------------------------------------------------------
  // !panel: "Durum" sekmesindeki "Log Kanalları" butonu — modal değil,
  // doğrudan görünümü Log Kanalları alt-sekmesine günceller (interaction.update).
  // "panel_open_" öneki genel modal yönlendirmesine ayrıldığı için burada
  // kasıtlı olarak farklı bir önek ("panel_shortcut_") kullanılıyor.
  // -------------------------------------------------------------------
  if (
    interaction.isButton() &&
    interaction.customId === "panel_shortcut_logpanel"
  ) {
    if (
      !interaction.inGuild() ||
      (interaction.user.id !== OWNER_ID &&
        !interaction.memberPermissions?.has("ManageGuild"))
    ) {
      await interaction
        .reply({
          content: MSG.error(
            'Bu bölüm için "Sunucuyu Yönet" iznine sahip olman gerekiyor.',
          ),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    try {
      await interaction.update(await buildLogTab(interaction.guildId!));
    } catch (err) {
      console.error("Log paneli açma hatası:", err);
    }
    return;
  }

  // !panel: "Durum" sekmesindeki "Diğer Kanallar" butonu — log kategorisi
  // sayılmayan tek-kanal ayarlarını (ceza logları vb.) gösterir.
  // "Log Kanalları" ile aynı desen: "panel_shortcut_" öneki + interaction.update.
  if (
    interaction.isButton() &&
    interaction.customId === "panel_shortcut_extrapanel"
  ) {
    if (
      !interaction.inGuild() ||
      (interaction.user.id !== OWNER_ID &&
        !interaction.memberPermissions?.has("ManageGuild"))
    ) {
      await interaction
        .reply({
          content: MSG.error(
            'Bu bölüm için "Sunucuyu Yönet" iznine sahip olman gerekiyor.',
          ),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    try {
      await interaction.update(
        await buildExtraChannelsTab(interaction.guildId!),
      );
    } catch (err) {
      console.error("Diğer kanallar paneli açma hatası:", err);
    }
    return;
  }

  // Log Kanalları / Diğer Kanallar alt-sekmelerindeki "Geri" butonu — Durum sekmesine döner.
  if (
    interaction.isButton() &&
    interaction.customId === "panel_shortcut_infoback"
  ) {
    if (!hasPanelAccess(interaction)) {
      await interaction
        .reply({
          content: MSG.error("Paneli görüntüleme iznin yok."),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    try {
      await interaction.update(
        buildPanelView("info", {
          guild: interaction.guild,
          client: interaction.client,
        }),
      );
    } catch (err) {
      console.error("Log paneli geri dönüş hatası:", err);
    }
    return;
  }

  // -------------------------------------------------------------------
  // Genel: Duyuru Gönder — 1. adım, kanal seçimi (panel_duyuru_open)
  // -------------------------------------------------------------------
  if (interaction.isButton() && interaction.customId === "panel_duyuru_open") {
    if (!hasActionPermission(interaction, "duyuru")) {
      await interaction
        .reply({
          content: MSG.error(
            `Duyuru göndermek için ${permissionLabelFor("duyuru")} iznine sahip olman gerekiyor.`,
          ),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    const channelSelect = new ChannelSelectMenuBuilder()
      .setCustomId("panel_duyuru_channel")
      .setPlaceholder("📢 Duyurunun gönderileceği kanalı seç...")
      .setChannelTypes(ChannelType.GuildText, ChannelType.GuildAnnouncement)
      .setMinValues(1)
      .setMaxValues(1);
    const row = new ActionRowBuilder<ChannelSelectMenuBuilder>().addComponents(
      channelSelect,
    );
    await interaction
      .reply({
        content: "Duyurunun gönderileceği kanalı seç:",
        components: [row],
        ephemeral: true,
      })
      .catch(() => null);
    return;
  }

  // -------------------------------------------------------------------
  // Genel: Duyuru Gönder — 2. adım, kanal seçildi, içerik modalı açılır
  // (panel_duyuru_channel). Kanal ID'si sonraki adıma modal customId'sinin
  // içine gömülerek taşınıyor (panel_submit_duyuru_<channelId>).
  // -------------------------------------------------------------------
  if (
    interaction.isChannelSelectMenu() &&
    interaction.customId === "panel_duyuru_channel"
  ) {
    if (!hasActionPermission(interaction, "duyuru")) {
      await interaction
        .reply({
          content: MSG.error(
            `Duyuru göndermek için ${permissionLabelFor("duyuru")} iznine sahip olman gerekiyor.`,
          ),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    const channelId = interaction.values[0];
    if (!channelId) {
      await interaction
        .reply({ content: MSG.error("Bir kanal seçmedin."), ephemeral: true })
        .catch(() => null);
      return;
    }
    const modal = buildModal(
      `panel_submit_duyuru_${channelId}`,
      "Duyuru İçeriği",
      [
        textInput("baslik", "Başlık", {
          placeholder: "ör. Sunucu Güncellemesi",
          required: true,
          maxLength: 256,
        }),
        textInput("icerik", "İçerik", {
          long: true,
          required: true,
          maxLength: 4_000,
        }),
      ],
    );
    await interaction.showModal(modal).catch(() => null);
    return;
  }

  // -------------------------------------------------------------------
  // Genel: Duyuru Gönder — 3. adım, modal gönderimi
  // (panel_submit_duyuru_<channelId>). ÖNEMLİ: bu blok, aşağıdaki genel
  // "panel_submit_" işleyicisinden ÖNCE gelmeli — customId aynı önekle
  // başlıyor ("panel_submit_") ama sonuna kanal ID'si ekli.
  // -------------------------------------------------------------------
  if (
    interaction.isModalSubmit() &&
    interaction.customId.startsWith("panel_submit_duyuru_")
  ) {
    if (!interaction.inGuild()) return;
    if (!hasActionPermission(interaction, "duyuru")) {
      await interaction
        .reply({
          content: `❌ Duyuru göndermek için ${permissionLabelFor("duyuru")} iznine sahip olman gerekiyor.`,
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    const channelId = interaction.customId.replace("panel_submit_duyuru_", "");
    try {
      await interaction.deferReply({ ephemeral: true });
      const channel = await interaction
        .guild!.channels.fetch(channelId)
        .catch(() => null);
      if (!channel || !channel.isTextBased()) {
        await interaction.editReply(
          MSG.error("Seçilen kanal bulunamadı veya bir metin kanalı değil."),
        );
        return;
      }
      const baslik = interaction.fields.getTextInputValue("baslik");
      const icerik = interaction.fields.getTextInputValue("icerik");
      const announceEmbed = new EmbedBuilder()
        .setColor(0x5865f2)
        .setTitle(`📢 ${baslik}`)
        .setDescription(icerik)
        .setFooter({ text: `Gönderen: ${interaction.user.tag}` })
        .setTimestamp();
      await channel.send({
        embeds: [announceEmbed],
        allowedMentions: { parse: [] },
      });
      await interaction.editReply(
        MSG.success(`Duyuru <#${channelId}> kanalına gönderildi.`),
      );
    } catch (err) {
      console.error("Duyuru gönderme hatası:", err);
      await interaction
        .editReply(
          MSG.error(
            "Duyuru gönderilirken bir hata oluştu — kanala yazma iznim olmayabilir.",
          ),
        )
        .catch(() => null);
    }
    return;
  }

  // -------------------------------------------------------------------
  // Toplu silme: Rol Filtresi butonu (panel_bulksilme_rolefilter)
  // -------------------------------------------------------------------
  if (
    interaction.isButton() &&
    interaction.customId === "panel_bulksilme_rolefilter"
  ) {
    if (!hasActionPermission(interaction, "bulksilme")) {
      await interaction
        .reply({
          content: MSG.error(
            `Toplu silme işlemi için ${permissionLabelFor("bulksilme")} iznine sahip olman gerekiyor.`,
          ),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    const builder = MODAL_BUILDERS["bulksilme_rolefilter"];
    if (builder) {
      await interaction.showModal(builder()).catch(() => null);
    }
    return;
  }

  // -------------------------------------------------------------------
  // Toplu silme: Rol Filtresi Modal Submit (panel_submit_bulksilme_rolefilter)
  // -------------------------------------------------------------------
  if (
    interaction.isModalSubmit() &&
    interaction.customId === "panel_submit_bulksilme_rolefilter"
  ) {
    if (!interaction.inGuild()) return;
    if (!hasActionPermission(interaction, "bulksilme")) {
      await interaction
        .reply({
          content: MSG.error(
            `Toplu silme işlemi için ${permissionLabelFor("bulksilme")} iznine sahip olman gerekiyor.`,
          ),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }

    try {
      await interaction.deferReply({ ephemeral: true });

      const filter = interaction.fields
        .getTextInputValue("filter")
        .trim()
        .toLowerCase();
      if (!filter) {
        await interaction.editReply(MSG.error("Filtre metni boş olamaz."));
        return;
      }

      // Sunucudan tüm rolleri getir
      const roles = await interaction.guild!.roles.fetch().catch(() => null);
      if (!roles || roles.size === 0) {
        await interaction.editReply(MSG.error("Sunucuda hiç rol bulunamadı."));
        return;
      }

      // Filtreleme: rol adında veya emojisinde filter string'ini içeren rolleri bul.
      // NOT: role.icon özel yüklenmiş rol ikonunun hash'idir (ör. "a1b2c3..."),
      // emoji karakteri değildir — unicode emoji için role.unicodeEmoji kullanılmalı,
      // yoksa 💎 gibi bir emoji hiçbir zaman eşleşmez.
      const matchedRoles = roles.filter((role) => {
        const name = role.name.toLowerCase();
        const emoji = role.unicodeEmoji || "";
        return name.includes(filter) || emoji.includes(filter);
      });

      if (matchedRoles.size === 0) {
        await interaction.editReply(
          MSG.error(`"${filter}" ile eşleşen rol bulunamadı.`),
        );
        return;
      }

      // Eşleşen rolleri listele ve select menüsünde göster
      const roleList = matchedRoles.map((r) => `${r.name}`).join("\n");
      const listEmbed = new EmbedBuilder()
        .setColor(0x5865f2)
        .setTitle(MSG.info("Rol Filtresi Sonuçları"))
        .setDescription(
          `**Filtre:** \`${filter}\`\n\n**Bulunan Roller (${matchedRoles.size}):**\n${roleList.slice(0, 3_600)}${roleList.length > 3_600 ? "\n… (liste kısaltıldı)" : ""}`,
        )
        .setFooter({ text: "Aşağıdan bu rolleri seç (hepsi önceden işaretli)" })
        .setTimestamp();

      // Rol seçim menüsü (eşleşen rolleri setDefaultRoles ile önceden seçilmiş göster)
      const defaultRoleIds = matchedRoles.first(25).map((r) => r.id);
      const roleSelect = new RoleSelectMenuBuilder()
        .setCustomId("panel_bulksilme_roles_filtered")
        .setPlaceholder("Seçili rolleri kişiselleştir...")
        .setMinValues(0)
        .setMaxValues(Math.min(25, matchedRoles.size))
        .setDefaultRoles(...defaultRoleIds);

      const roleRow =
        new ActionRowBuilder<RoleSelectMenuBuilder>().addComponents(roleSelect);

      const confirmButton = new ButtonBuilder()
        .setCustomId("panel_bulksilme_filtered_confirm")
        .setLabel("Seçimleri Kaydet")
        .setEmoji("<a:1000021814:1540389540513194066>")
        .setStyle(ButtonStyle.Success);

      const confirmRow = new ActionRowBuilder<ButtonBuilder>().addComponents(
        confirmButton,
      );

      await interaction.editReply({
        embeds: [listEmbed],
        components: [roleRow, confirmRow],
      });
    } catch (err) {
      console.error("Rol filtresi hatası:", err);
      await interaction
        .editReply(MSG.error("Rol filtresi sırasında bir hata oluştu."))
        .catch(() => null);
    }
    return;
  }

  // -------------------------------------------------------------------
  // Toplu silme: Tüm Roller butonu (panel_bulksilme_roledirect)
  // -------------------------------------------------------------------
  if (
    interaction.isButton() &&
    interaction.customId === "panel_bulksilme_roledirect"
  ) {
    if (!hasActionPermission(interaction, "bulksilme")) {
      await interaction
        .reply({
          content: MSG.error(
            `Toplu silme işlemi için ${permissionLabelFor("bulksilme")} iznine sahip olman gerekiyor.`,
          ),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    try {
      await interaction.deferReply({ ephemeral: true });

      const roleSelect = new RoleSelectMenuBuilder()
        .setCustomId("panel_bulksilme_roles")
        .setPlaceholder("👤 Silinecek rolleri seç...")
        .setMinValues(0)
        .setMaxValues(25);

      const roleRow =
        new ActionRowBuilder<RoleSelectMenuBuilder>().addComponents(roleSelect);

      await interaction.editReply({
        content: "Silinecek rolleri seç:",
        components: [roleRow],
      });
    } catch (err) {
      console.error("Rol seçim açma hatası:", err);
      await interaction
        .editReply(MSG.error("Rol seçim menüsü açılırken bir hata oluştu."))
        .catch(() => null);
    }
    return;
  }

  // -------------------------------------------------------------------
  // Toplu silme: Filtrelenmiş rolleri kaydet (panel_bulksilme_filtered_confirm)
  // -------------------------------------------------------------------
  if (
    interaction.isButton() &&
    interaction.customId === "panel_bulksilme_filtered_confirm"
  ) {
    if (!hasActionPermission(interaction, "bulksilme")) {
      await interaction
        .reply({
          content: MSG.error(
            `Toplu silme işlemi için ${permissionLabelFor("bulksilme")} iznine sahip olman gerekiyor.`,
          ),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    await interaction.update(buildPanelView("bulksilme")).catch(() => null);
    return;
  }

  // -------------------------------------------------------------------
  // Toplu silme: Kanal seçimi (panel_bulksilme_channels)
  // -------------------------------------------------------------------
  if (
    interaction.isChannelSelectMenu() &&
    interaction.customId === "panel_bulksilme_channels"
  ) {
    if (!hasActionPermission(interaction, "bulksilme")) {
      await interaction
        .reply({
          content: MSG.error(
            `Toplu silme işlemi için ${permissionLabelFor("bulksilme")} iznine sahip olman gerekiyor.`,
          ),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    const selectionKey = bulkSelectionKey(interaction);
    const selection = getBulkSelection(selectionKey) || {
      channels: [],
      roles: [],
    };
    selection.channels = interaction.values;
    saveBulkSelection(selectionKey, selection);
    await interaction.deferUpdate().catch(() => null);
    return;
  }

  // -------------------------------------------------------------------
  // Toplu silme: Filtrelenmiş rol seçimi (panel_bulksilme_roles_filtered)
  // -------------------------------------------------------------------
  if (
    interaction.isRoleSelectMenu() &&
    interaction.customId === "panel_bulksilme_roles_filtered"
  ) {
    if (!hasActionPermission(interaction, "bulksilme")) {
      await interaction
        .reply({
          content: `❌ Toplu silme işlemi için ${permissionLabelFor("bulksilme")} iznine sahip olman gerekiyor.`,
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    const selectionKey = bulkSelectionKey(interaction);
    const selection = getBulkSelection(selectionKey) || {
      channels: [],
      roles: [],
    };
    selection.roles = interaction.values;
    saveBulkSelection(selectionKey, selection);

    await interaction.update(buildPanelView("bulksilme")).catch(() => null);
    return;
  }

  // -------------------------------------------------------------------
  // Toplu silme: Rol seçimi (panel_bulksilme_roles)
  // -------------------------------------------------------------------
  if (
    interaction.isRoleSelectMenu() &&
    interaction.customId === "panel_bulksilme_roles"
  ) {
    if (!hasActionPermission(interaction, "bulksilme")) {
      await interaction
        .reply({
          content: `❌ Toplu silme işlemi için ${permissionLabelFor("bulksilme")} iznine sahip olman gerekiyor.`,
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    const selectionKey = bulkSelectionKey(interaction);
    const selection = getBulkSelection(selectionKey) || {
      channels: [],
      roles: [],
    };
    selection.roles = interaction.values;
    saveBulkSelection(selectionKey, selection);

    await interaction.update(buildPanelView("bulksilme")).catch(() => null);
    return;
  }

  // -------------------------------------------------------------------
  // Toplu silme: Silme işlemini onayla (panel_bulksilme_confirm)
  // -------------------------------------------------------------------
  if (
    interaction.isButton() &&
    interaction.customId === "panel_bulksilme_confirm"
  ) {
    if (!interaction.inGuild()) return;
    if (!hasActionPermission(interaction, "bulksilme")) {
      await interaction
        .reply({
          content: `❌ Toplu silme işlemi için ${permissionLabelFor("bulksilme")} iznine sahip olman gerekiyor.`,
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }

    try {
      const selectionKey = bulkSelectionKey(interaction);
      const selection = getBulkSelection(selectionKey);

      if (
        !selection ||
        (selection.channels.length === 0 && selection.roles.length === 0)
      ) {
        await interaction
          .reply({
            content: MSG.error(
              "Hiçbir kanal veya rol seçilmedi. Lütfen silmek istediğin kanalları ve/veya rolleri seç.",
            ),
            ephemeral: true,
          })
          .catch(() => null);
        return;
      }

      await interaction.deferReply({ ephemeral: true });

      const guild = interaction.guild!;
      const deletedChannels: string[] = [];
      const failedChannels: string[] = [];
      const deletedRoles: string[] = [];
      const failedRoles: string[] = [];

      // Kanalları sil
      for (const channelId of selection.channels) {
        try {
          const channel = await guild.channels
            .fetch(channelId)
            .catch(() => null);
          if (channel) {
            await channel.delete(
              `${interaction.user.tag} (panel): Toplu silme`,
            );
            deletedChannels.push(`<#${channelId}>`);
          }
        } catch (err) {
          console.error(`Kanal silme hatası (${channelId}):`, err);
          failedChannels.push(channelId);
        }
      }

      // Rolleri sil
      for (const roleId of selection.roles) {
        try {
          const role = await guild.roles.fetch(roleId).catch(() => null);
          if (role) {
            await role.delete(`${interaction.user.tag} (panel): Toplu silme`);
            deletedRoles.push(`<@&${roleId}>`);
          }
        } catch (err) {
          console.error(`Rol silme hatası (${roleId}):`, err);
          failedRoles.push(roleId);
        }
      }

      // Sonuç embed'i
      const resultEmbed = new EmbedBuilder()
        .setColor(
          deletedChannels.length > 0 || deletedRoles.length > 0
            ? 0x57f287
            : 0xed4245,
        )
        .setTitle("🗑️ Toplu Silme İşlemi Tamamlandı")
        .setDescription(
          [
            deletedChannels.length > 0
              ? `✅ **Silinen Kanallar (${deletedChannels.length}):**\n${deletedChannels.slice(0, 10).join(", ")}${deletedChannels.length > 10 ? `\n...+${deletedChannels.length - 10} kanal daha` : ""}`
              : "",
            deletedRoles.length > 0
              ? `✅ **Silinen Roller (${deletedRoles.length}):**\n${deletedRoles.slice(0, 10).join(", ")}${deletedRoles.length > 10 ? `\n...+${deletedRoles.length - 10} rol daha` : ""}`
              : "",
            failedChannels.length > 0 || failedRoles.length > 0
              ? `⚠️ **Hata:**\n${failedChannels.length > 0 ? `${failedChannels.length} kanal silinemedi\n` : ""}${failedRoles.length > 0 ? `${failedRoles.length} rol silinemedi` : ""}`
              : "",
          ]
            .filter((x) => x)
            .join("\n\n") || "Hiçbir kanal veya rol silinmedi.",
        )
        .setFooter({ text: `İşlemi yapan: ${interaction.user.tag}` })
        .setTimestamp();

      await interaction.editReply({ embeds: [resultEmbed] }).catch(() => null);

      // Seçimleri temizle
      deleteBulkSelection(selectionKey);
    } catch (err) {
      console.error("Toplu silme işlemi hatası:", err);
      await interaction
        .editReply(MSG.error("Toplu silme işlemi sırasında bir hata oluştu."))
        .catch(() => null);
    }
    return;
  }

  // -------------------------------------------------------------------
  // Toplu silme: İptal et (panel_bulksilme_cancel)
  // -------------------------------------------------------------------
  if (
    interaction.isButton() &&
    interaction.customId === "panel_bulksilme_cancel"
  ) {
    if (!hasActionPermission(interaction, "bulksilme")) {
      await interaction
        .reply({
          content: `❌ Toplu silme işlemi için ${permissionLabelFor("bulksilme")} iznine sahip olman gerekiyor.`,
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    try {
      deleteBulkSelection(bulkSelectionKey(interaction));
      await interaction.update(buildPanelView("mod"));
    } catch (err) {
      console.error("Toplu silme iptal hatası:", err);
    }
    return;
  }

  // -------------------------------------------------------------------
  // Panel: Modal açma butonları (panel_open_* kalıbı)
  // Panel_open_* butonları, sahip olduğu aksiyonun modali varsa, onu açar.
  // Aksiyonun izni yoksa hata verir.
  // -------------------------------------------------------------------
  if (
    interaction.isButton() &&
    interaction.customId.startsWith("panel_open_")
  ) {
    const action = interaction.customId.replace("panel_open_", "");
    if (!hasActionPermission(interaction, action)) {
      await interaction
        .reply({
          content: MSG.error(
            `Bu işlem için ${permissionLabelFor(action)} iznine sahip olman gerekiyor.`,
          ),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }
    const builder = MODAL_BUILDERS[action];
    if (builder) {
      await interaction.showModal(builder()).catch(() => null);
    }
    return;
  }

  // -------------------------------------------------------------------
  // Panel: Modal gönderimi işlemleri (panel_submit_* kalıbı)
  // Her modal form, panel_submit_<action> olarak geri döner.
  // -------------------------------------------------------------------
  if (
    interaction.isModalSubmit() &&
    interaction.customId.startsWith("panel_submit_")
  ) {
    if (!interaction.inGuild()) return;

    const action = interaction.customId.replace("panel_submit_", "");
    if (!hasActionPermission(interaction, action)) {
      await interaction
        .reply({
          content: MSG.error(
            `Bu işlem için ${permissionLabelFor(action)} iznine sahip olman gerekiyor.`,
          ),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }

    try {
      await interaction.deferReply({ ephemeral: true });

      // -----------------------------------------------------------------
      // Moderasyon (ban / kick / mute / unmute / unban / warn)
      // -----------------------------------------------------------------
      if (
        action === "ban" ||
        action === "kick" ||
        action === "mute" ||
        action === "unmute" ||
        action === "unban" ||
        action === "warn"
      ) {
        const rawUserId = safeGetField(interaction, "userId");
        const userId = parseUserId(rawUserId);
        if (!userId) {
          await interaction.editReply(MSG.error("Geçersiz kullanıcı ID'si."));
          return;
        }

        const guild = interaction.guild!;

        if (action === "ban") {
          const identityError = panelTargetIdentityError(interaction, userId);
          if (identityError) {
            await interaction.editReply(MSG.error(identityError));
            return;
          }
          const botMember = guild.members.me;
          if (
            interaction.user.id !== OWNER_ID &&
            !botMember?.permissions.has(PermissionFlagsBits.BanMembers)
          ) {
            await interaction.editReply(
              MSG.error(
                "Bu kullanıcıyı yasaklayamam. Botun Üyeleri Yasakla izni yok.",
              ),
            );
            return;
          }
          const targetMember = await guild.members
            .fetch(userId)
            .catch(() => null);
          if (targetMember) {
            const botBlock = getBotModerationBlockReason(
              botMember,
              targetMember,
              PermissionFlagsBits.BanMembers,
              interaction.user.id,
            );
            if (botBlock) {
              await interaction.editReply(
                MSG.error(botModerationBlockMessage(botBlock, "yasaklayamam")),
              );
              return;
            }
            const executor = await guild.members
              .fetch(interaction.user.id)
              .catch(() => null);
            if (!executor || !canModerate(executor, targetMember)) {
              await interaction.editReply(
                MSG.error(
                  "Bu kullanıcının rolü seninkiyle aynı ya da daha yüksek.",
                ),
              );
              return;
            }
          }
          const reason = panelReason(interaction);
          await guild.members.ban(userId, {
            reason: `${interaction.user.tag} (panel): ${reason}`,
          });
          await interaction.editReply(
            MSG.success(`<@${userId}> banlandı.\n**Sebep:** ${reason}`),
          );
          return;
        }

        if (action === "unban") {
          const identityError = panelTargetIdentityError(interaction, userId);
          if (identityError && userId !== interaction.user.id) {
            await interaction.editReply(MSG.error(identityError));
            return;
          }
          const reason = panelReason(interaction);
          await guild.members.unban(
            userId,
            `${interaction.user.tag} (panel): ${reason}`,
          );
          await interaction.editReply(
            MSG.success(`<@${userId}> kişisinin banı kaldırıldı.`),
          );
          return;
        }

        const permission =
          action === "kick"
            ? PermissionFlagsBits.KickMembers
            : PermissionFlagsBits.ModerateMembers;
        const validation = await validatePanelMember(
          interaction,
          userId,
          permission,
          action === "kick"
            ? "atamam"
            : action === "mute" || action === "unmute"
              ? "susturamam"
              : "uyaramam",
        );
        if (validation.error || !validation.member) {
          await interaction.editReply(
            MSG.error(validation.error ?? "Hedef kullanıcı doğrulanamadı."),
          );
          return;
        }
        const member = validation.member;

        if (action === "kick") {
          const reason = panelReason(interaction);
          await member.kick(`${interaction.user.tag} (panel): ${reason}`);
          await interaction.editReply(
            MSG.success(`<@${userId}> sunucudan atıldı.\n**Sebep:** ${reason}`),
          );
          return;
        }

        if (action === "mute") {
          const durationRaw = safeGetField(interaction, "duration").trim();
          const minutes = Number(durationRaw);
          if (!Number.isInteger(minutes) || minutes < 1 || minutes > 40_320) {
            await interaction.editReply(
              MSG.error(
                "Süre 1 ile 40.320 dakika arasında tam sayı olmalı (ör. 60).",
              ),
            );
            return;
          }
          const reason = panelReason(interaction);
          await member.timeout(
            minutes * 60_000,
            `${interaction.user.tag} (panel): ${reason}`,
          );
          await interaction.editReply(
            MSG.success(
              `<@${userId}> ${minutes} dakika susturuldu.\n**Sebep:** ${reason}`,
            ),
          );
          return;
        }

        if (action === "unmute") {
          if (
            !member.communicationDisabledUntilTimestamp ||
            member.communicationDisabledUntilTimestamp <= Date.now()
          ) {
            await interaction.editReply(
              MSG.info(`<@${userId}> zaten susturulmuş değil.`),
            );
            return;
          }
          const reason = panelReason(interaction);
          await member.timeout(
            null,
            `${interaction.user.tag} (panel): ${reason}`,
          );
          await interaction.editReply(
            MSG.success(`<@${userId}> kişisinin susturması kaldırıldı.`),
          );
          return;
        }

        const warnReason = panelReason(interaction);
        await db.insert(warningsTable).values({
          guildId: guild.id,
          userId,
          moderatorId: interaction.user.id,
          reason: warnReason,
        });
        const totalWarnings = await db
          .select()
          .from(warningsTable)
          .where(
            and(
              eq(warningsTable.userId, userId),
              eq(warningsTable.guildId, guild.id),
            ),
          );
        await interaction.editReply(
          MSG.success(
            `<@${userId}> uyarıldı (toplam ${totalWarnings.length}. uyarı).\n**Sebep:** ${warnReason}`,
          ),
        );
        return;
      }

      // -----------------------------------------------------------------
      // Üye yönetimi (bir kullanıcının kayıtlı uyarılarını görüntüle)
      // -----------------------------------------------------------------
      if (action === "uyarigor") {
        const rawUserId = interaction.fields.getTextInputValue("userId");
        const userId = parseUserId(rawUserId);
        if (!userId) {
          await interaction.editReply(MSG.error("Geçersiz kullanıcı ID'si."));
          return;
        }
        const rows = await db
          .select()
          .from(warningsTable)
          .where(
            and(
              eq(warningsTable.userId, userId),
              eq(warningsTable.guildId, interaction.guild!.id),
            ),
          );
        if (rows.length === 0) {
          await interaction.editReply(
            MSG.info(
              `<@${userId}> kişisinin bu sunucuda kayıtlı bir uyarısı yok.`,
            ),
          );
          return;
        }
        const gosterilecek = rows.slice(-10);
        const list = gosterilecek
          .map(
            (w: typeof warningsTable.$inferSelect, i: number) =>
              `**${i + 1}.** ${w.reason || "*(sebep belirtilmemiş)*"} — <@${w.moderatorId}>`,
          )
          .join("\n");
        const warnListEmbed = new EmbedBuilder()
          .setColor(0xfee75c)
          .setTitle(MSG.info(`<@${userId}> — Uyarılar (${rows.length})`))
          .setDescription(
            rows.length > gosterilecek.length
              ? `${list}\n\n...+${rows.length - gosterilecek.length} uyarı daha`
              : list,
          )
          .setTimestamp();
        await interaction.editReply({ embeds: [warnListEmbed] });
        return;
      }

      // -----------------------------------------------------------------
      // Üye yönetimi (özel üye toggle)
      // -----------------------------------------------------------------
      if (action === "ozelde") {
        const rawUserId = interaction.fields.getTextInputValue("userId");
        const userId = parseUserId(rawUserId);
        if (!userId) {
          await interaction.editReply(MSG.error("Geçersiz kullanıcı ID'si."));
          return;
        }
        const isNowVip = await toggleVipById(userId);
        await interaction.editReply(
          isNowVip
            ? MSG.success(`<@${userId}> artık özel üye!`)
            : MSG.info(`<@${userId}> kişisinin özel üyeliği geri çekildi.`),
        );
        return;
      }

      await interaction.editReply(MSG.error("Bilinmeyen aksiyon."));
    } catch (err) {
      console.error("Panel modal aksiyonu hatası:", err);
      await interaction
        .editReply(
          MSG.error(
            "İşlem sırasında bir hata oldu — yetkim olmayabilir ya da kullanıcı bulunamadı.",
          ),
        )
        .catch(() => null);
    }
    return;
  }

  // -------------------------------------------------------------------
  // Log Kanalları menüleri (panel_log_* kalıbı)
  // -------------------------------------------------------------------
  if (
    interaction.isChannelSelectMenu() &&
    interaction.customId.startsWith("panel_log_")
  ) {
    if (
      !interaction.inGuild() ||
      (interaction.user.id !== OWNER_ID &&
        !interaction.memberPermissions?.has("ManageGuild"))
    ) {
      await interaction
        .reply({
          content: MSG.error(
            'Bu bölüm için "Sunucuyu Yönet" iznine sahip olman gerekiyor.',
          ),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }

    const categoryId = interaction.customId.replace(
      "panel_log_",
      "",
    ) as LogCategory;
    const channelId = interaction.values?.[0] ?? null;

    try {
      await setLogChannel(interaction.guildId!, categoryId, channelId);
      // deferUpdate() sadece etkileşimi onaylar, mesajı DEĞİŞTİRMEZ — bu yüzden
      // panel eskiden "ayarlanmamış" yazmaya devam ediyordu. Paneli güncel
      // ayarlarla yeniden çizip interaction.update() ile göndermek gerekiyor.
      await interaction
        .update(await buildLogTab(interaction.guildId!))
        .catch(() => null);
    } catch (err) {
      console.error("Log kanalı ayarlama hatası:", err);
      await interaction
        .reply({
          content: MSG.error("Kanal ayarı yapılırken bir hata oldu."),
          ephemeral: true,
        })
        .catch(() => null);
    }
    return;
  }

  // -------------------------------------------------------------------
  // Diğer Kanallar menüleri (panel_chset_* kalıbı) — panel_log_* ile aynı desen.
  // -------------------------------------------------------------------
  if (
    interaction.isChannelSelectMenu() &&
    interaction.customId.startsWith("panel_chset_")
  ) {
    if (
      !interaction.inGuild() ||
      (interaction.user.id !== OWNER_ID &&
        !interaction.memberPermissions?.has("ManageGuild"))
    ) {
      await interaction
        .reply({
          content: MSG.error(
            'Bu bölüm için "Sunucuyu Yönet" iznine sahip olman gerekiyor.',
          ),
          ephemeral: true,
        })
        .catch(() => null);
      return;
    }

    const settingId = interaction.customId.replace(
      "panel_chset_",
      "",
    ) as ChannelSettingId;
    const channelId = interaction.values?.[0] ?? null;

    try {
      await setChannelSetting(interaction.guildId!, settingId, channelId);
      await interaction
        .update(await buildExtraChannelsTab(interaction.guildId!))
        .catch(() => null);
    } catch (err) {
      console.error("Kanal ayarı yapma hatası:", err);
      await interaction
        .reply({
          content: MSG.error("Kanal ayarı yapılırken bir hata oldu."),
          ephemeral: true,
        })
        .catch(() => null);
    }
    return;
  }

  // -------------------------------------------------------------------
  // Mevcut: slash komutları (değişmedi)
  // -------------------------------------------------------------------
  if (!interaction.isChatInputCommand()) return;

  const command = commands.get(interaction.commandName);
  if (!command?.slashExecute) {
    console.warn(
      `Kayıtlı olmayan slash komutu alındı: /${interaction.commandName}`,
    );
    await interaction
      .reply({
        content: MSG.error(
          "Bu slash komutu artık aktif değil. Komutlar yeniden senkronize ediliyor.",
        ),
        ephemeral: true,
      })
      .catch(() => null);
    return;
  }

  // Genel komut rate-limit (slash). Owner muaf.
  {
    const { checkCommandRateLimit } = await import("../utils/rateLimit.js");
    if (
      !(await checkCommandRateLimit(
        interaction,
        interaction.user.id,
        interaction.commandName,
      ))
    ) {
      return;
    }
  }

  let success = true;
  try {
    await command.slashExecute(interaction);
  } catch (err) {
    success = false;
    console.error(`Slash komut hatası (${interaction.commandName}):`, err);
    const embed = errorEmbed(
      "Bir Hata Oluştu",
      "Komut çalıştırılırken bir hata oluştu.",
    );
    if (interaction.replied || interaction.deferred) {
      await interaction
        .followUp({ embeds: [embed], ephemeral: true })
        .catch(() => null);
    } else {
      await interaction
        .reply({ embeds: [embed], ephemeral: true })
        .catch(() => null);
    }
  }
  void notifyOwnerCommandUsed(interaction.client, {
    commandName: interaction.commandName,
    user: interaction.user,
    guild: interaction.guild,
    success,
    source: "slash",
  });
}

/** Modalda olmayabilecek (opsiyonel) bir text input'u güvenle okur. */
function safeGetField(
  interaction: import("discord.js").ModalSubmitInteraction,
  customId: string,
): string {
  try {
    return interaction.fields.getTextInputValue(customId)?.trim() ?? "";
  } catch {
    return "";
  }
}
","events/loggingEvents.ts":"import {
  AttachmentBuilder,
  AuditLogEvent,
  ChannelType,
  Client,
  Events,
  type AnyThreadChannel,
  type GuildChannel,
  type GuildEmoji,
  type GuildMember,
  type Invite,
  type Message,
  type PartialGuildMember,
  type PartialMessage,
  type Role,
  type Sticker,
  type VoiceState,
} from "discord.js";
import {
  baseLogEmbed,
  classifyMemberRemoval,
  findAuditExecutor,
  LOG_COLORS,
  sendLog,
  truncate,
} from "../utils/logger.js";

// ---------------------------------------------------------------------------
// SUNUCU LOG SİSTEMİ — OLAY DİNLEYİCİLERİ
// ---------------------------------------------------------------------------
// Bu dosya index.ts'te (client oluşturulup login olmadan önce/sonra fark
// etmez, sadece bir kere) şöyle çağrılmalı:
//
//   import { registerLoggingEvents } from "./events/loggingEvents.js";
//   registerLoggingEvents(client);
//
// GEREKLİ INTENT'LER (client oluşturulurken GatewayIntentBits içine eklenmeli):
//   Guilds, GuildMessages, MessageContent, GuildMembers, GuildModeration
//   (ban/unban için — eski adıyla GuildBans), GuildVoiceStates
//
// GEREKLİ PARTIALS (mesaj sil/düzenle olayları cache'te olmayan eski
// mesajlarda da tetiklensin diye):
//   Partials.Message, Partials.Channel, Partials.Reaction
//
// Örnek:
//   new Client({
//     intents: [
//       GatewayIntentBits.Guilds,
//       GatewayIntentBits.GuildMessages,
//       GatewayIntentBits.MessageContent,
//       GatewayIntentBits.GuildMembers,
//       GatewayIntentBits.GuildModeration,
//       GatewayIntentBits.GuildVoiceStates,
//     ],
//     partials: [Partials.Message, Partials.Channel, Partials.Reaction],
//   });
//
// Bu intent'lerden biri (özellikle GuildMembers ve MessageContent, ikisi de
// "privileged") Discord Developer Portal'da bot sayfasında açık olmalı,
// yoksa bot login sırasında hata verir.
// ---------------------------------------------------------------------------

function authorTag(entity: { id: string; tag?: string; username?: string } | null | undefined): string {
  if (!entity) return "Bilinmiyor";
  return entity.tag ?? entity.username ?? entity.id;
}

export function registerLoggingEvents(client: Client): void {
  // ---------------------------------------------------------------------
  // MESAJ LOGLARI
  // ---------------------------------------------------------------------

  client.on(Events.MessageDelete, async (message: Message | PartialMessage) => {
    if (!message.guild || message.author?.bot) return;
    const executor = message.id
      ? await findAuditExecutor(message.guild, AuditLogEvent.MessageDelete, message.author?.id ?? "")
      : null;

    const embed = baseLogEmbed(LOG_COLORS.mesajSil, "🗑️ Mesaj Silindi")
      .setDescription(message.partial ? "*(Mesaj cache'te yoktu, içerik yakalanamadı)*" : truncate(message.content ?? ""))
      .setThumbnail(message.author?.displayAvatarURL?.() ?? null)
      .addFields(
        { name: "Yazar", value: message.author ? `<@${message.author.id}> (\`${authorTag(message.author)}\`)` : "Bilinmiyor", inline: true },
        { name: "Kanal", value: message.channel ? `<#${message.channel.id}>` : "Bilinmiyor", inline: true },
      );
    if (executor) embed.addFields({ name: "Silen", value: executor, inline: true });

    if (message.attachments?.size) {
      const tumEkler = [...message.attachments.values()];
      // Resim/gif olan ekleri ayır: bunlar embed içine görsel olarak gömülecek,
      // diğerleri (video, ses, dosya vb.) eskisi gibi link listesi olarak kalacak.
      const gorseller = tumEkler.filter(
        (a) => a.contentType?.startsWith("image/") ?? /\.(png|jpe?g|gif|webp)$/i.test(a.name ?? a.url),
      );
      const digerEkler = tumEkler.filter((a) => !gorseller.includes(a));

      if (gorseller.length > 0) {
        // Discord embed'i tek görsel gösterebiliyor; ilkini büyük gösteriyoruz.
        embed.setImage(gorseller[0].url);
        if (gorseller.length > 1) {
          embed.addFields({
            name: `Diğer Görseller (${gorseller.length - 1})`,
            value: gorseller.slice(1).map((a) => a.url).join("\n").slice(0, 1000),
          });
        }
      }

      if (digerEkler.length > 0) {
        embed.addFields({ name: "Ekler", value: digerEkler.map((a) => a.url).join("\n").slice(0, 1000) });
      }
    }

    embed.addFields({ name: "Mesaj ID", value: `\`${message.id}\``, inline: true });

    await sendLog(message.guild, "mesaj", embed);
  });

  client.on(Events.MessageBulkDelete, async (messages, channel) => {
    const guild = channel.guild;
    if (!guild) return;

    // Silen kişiyi/botu audit log'dan bulmayı dene. Bu hem kendi !purge
    // komutumuzla hem de başka bir moderasyon botuyla yapılan toplu silmeleri
    // kapsar — Discord, bot token'ıyla yapılan bulk delete'leri de audit
    // log'a "executor: <bot>" olarak yazar.
    const executor = await findAuditExecutor(guild, AuditLogEvent.MessageBulkDelete, channel.id, 15_000);

    // Silinen mesajları eskiden yeniye doğru sırala ve okunabilir bir .txt
    // dosyasına dök (embed'e sığmayacak kadar çok mesaj olabilir, ör. 100).
    const sirali = [...messages.values()].sort(
      (a, b) => (a.createdTimestamp ?? 0) - (b.createdTimestamp ?? 0),
    );

    const satirlar = sirali.map((m) => {
      const zaman = m.createdAt
        ? m.createdAt.toLocaleString("tr-TR", { timeZone: "Europe/Istanbul" })
        : "Bilinmiyor";
      const yazar = m.author ? `${authorTag(m.author)} (${m.author.id})` : "Bilinmiyor";

      let icerik: string;
      if (m.partial) {
        icerik = "*(mesaj cache'te yoktu, içerik yakalanamadı)*";
      } else if (m.content) {
        icerik = m.content;
      } else if (m.embeds?.length) {
        icerik = "*(metin içeriği yok — embed içeriyor)*";
      } else {
        icerik = "*(içerik yok)*";
      }

      const ekler = m.attachments?.size
        ? `\n    Ekler: ${[...m.attachments.values()].map((a) => a.url).join(", ")}`
        : "";

      return `[${zaman}] ${yazar} (ID: ${m.id}): ${icerik}${ekler}`;
    });

    const txtIcerik =
      satirlar.length > 0 ? satirlar.join("\n") : "(Hiçbir mesajın içeriği cache'te yoktu.)";

    const dosya = new AttachmentBuilder(Buffer.from(txtIcerik, "utf-8"), {
      name: `silinen-mesajlar-${channel.id}-${Date.now()}.txt`,
    });

    const embed = baseLogEmbed(LOG_COLORS.mesajSil, "🗑️ Toplu Mesaj Silme")
      .setDescription(`**${messages.size}** mesaj toplu silindi.`)
      .addFields({ name: "Kanal", value: `<#${channel.id}>`, inline: true });
    if (executor) embed.addFields({ name: "Silen", value: executor, inline: true });
    embed.addFields({ name: "Not", value: "📄 Silinen mesajların tamamı ekteki `.txt` dosyasında." });

    await sendLog(guild, "mesaj", embed, [dosya]);
  });

  client.on(Events.MessageUpdate, async (oldMessage: Message | PartialMessage, newMessage: Message | PartialMessage) => {
    if (!newMessage.guild || newMessage.author?.bot) return;

    // Sabitleme (pin) durumu değiştiyse ayrı ve kısa bir log bas.
    if (oldMessage.pinned !== newMessage.pinned) {
      const pinEmbed = baseLogEmbed(
        LOG_COLORS.mesajDuzenle,
        newMessage.pinned ? "📌 Mesaj Sabitlendi" : "📌 Mesaj Sabitlemesi Kaldırıldı",
      )
        .setDescription(truncate(newMessage.content ?? "", 500))
        .addFields(
          { name: "Yazar", value: newMessage.author ? `<@${newMessage.author.id}> (\`${authorTag(newMessage.author)}\`)` : "Bilinmiyor", inline: true },
          { name: "Kanal", value: `<#${newMessage.channel.id}>`, inline: true },
        )
        .addFields({ name: "Mesaj ID", value: `\`${newMessage.id}\``, inline: true });
      if ("url" in newMessage && newMessage.url) {
        pinEmbed.addFields({ name: "Bağlantı", value: `[Mesaja git](${newMessage.url})` });
      }
      await sendLog(newMessage.guild, "mesaj", pinEmbed);
    }

    // İçerik gerçekten değişmediyse (embed önizlemesi vb. de bu olayı
    // tetikler) düzenleme logu basmaya gerek yok.
    if (oldMessage.content === newMessage.content) return;

    const embed = baseLogEmbed(LOG_COLORS.mesajDuzenle, "✏️ Mesaj Düzenlendi")
      .setThumbnail(newMessage.author?.displayAvatarURL?.() ?? null)
      .addFields(
        { name: "Yazar", value: newMessage.author ? `<@${newMessage.author.id}> (\`${authorTag(newMessage.author)}\`)` : "Bilinmiyor", inline: true },
        { name: "Kanal", value: `<#${newMessage.channel.id}>`, inline: true },
        { name: "Öncesi", value: truncate(oldMessage.content ?? "*(cache'te yoktu)*", 500) },
        { name: "Sonrası", value: truncate(newMessage.content ?? "", 500) },
      )
      .addFields({ name: "Mesaj ID", value: `\`${newMessage.id}\``, inline: true });

    if ("url" in newMessage && newMessage.url) {
      embed.addFields({ name: "Bağlantı", value: `[Mesaja git](${newMessage.url})` });
    }

    await sendLog(newMessage.guild, "mesaj", embed);
  });

  // ---------------------------------------------------------------------
  // ÜYE LOGLARI (giriş / çıkış / ban / unban / kick / timeout)
  // ---------------------------------------------------------------------

  client.on(Events.GuildMemberAdd, async (member: GuildMember) => {
    const accountAgeMs = Date.now() - member.user.createdTimestamp;
    const accountAgeDays = Math.floor(accountAgeMs / 86_400_000);
    const embed = baseLogEmbed(LOG_COLORS.uyeGiris, "📥 Üye Katıldı")
      .setThumbnail(member.user.displayAvatarURL())
      .addFields(
        { name: "Kullanıcı", value: `<@${member.id}> (\`${authorTag(member.user)}\`)`, inline: true },
        { name: "Hesap yaşı", value: `${accountAgeDays} gün`, inline: true },
        { name: "Sunucu üye sayısı", value: `${member.guild.memberCount}`, inline: true },
      )
      .addFields({ name: "Kullanıcı ID", value: `\`${member.id}\``, inline: true });

    if (accountAgeDays < 7) {
      embed.addFields({ name: "⚠️ Dikkat", value: "Hesap 7 günden yeni, olası alt hesap/spam olabilir." });
    }

    await sendLog(member.guild, "uye", embed);
  });

  client.on(Events.GuildMemberRemove, async (member: GuildMember | PartialGuildMember) => {
    const { type, executor } = await classifyMemberRemoval(member.guild, member.id);
    // Ban ile ayrılanlar zaten ayrı GuildBanAdd olayında loglanıyor;
    // burada tekrar basmayalım, mükerrer log kirliliği olmasın.
    if (type === "ban") return;

    const title = type === "kick" ? "👢 Üye Atıldı (Kick)" : "📤 Üye Ayrıldı";
    const color = type === "kick" ? LOG_COLORS.kick : LOG_COLORS.uyeCikis;
    const roles = "roles" in member && member.roles && "cache" in member.roles
      ? [...member.roles.cache.values()].filter((r) => r.id !== member.guild.id).map((r) => `<@&${r.id}>`).join(", ") || "—"
      : "—";

    const embed = baseLogEmbed(color, title)
      .setThumbnail(member.user?.displayAvatarURL() ?? null)
      .addFields(
        { name: "Kullanıcı", value: `<@${member.id}> (\`${authorTag(member.user)}\`)`, inline: true },
        { name: "Rolleri", value: truncate(roles, 500) },
      )
      .addFields({ name: "Kullanıcı ID", value: `\`${member.id}\``, inline: true });
    if (type === "kick" && executor) embed.addFields({ name: "Atan", value: executor, inline: true });

    await sendLog(member.guild, "uye", embed);
  });

  client.on(Events.GuildBanAdd, async (ban) => {
    const executor = await findAuditExecutor(ban.guild, AuditLogEvent.MemberBanAdd, ban.user.id);
    const embed = baseLogEmbed(LOG_COLORS.ban, "🔨 Üye Banlandı")
      .setThumbnail(ban.user.displayAvatarURL())
      .addFields({ name: "Kullanıcı", value: `<@${ban.user.id}> (\`${authorTag(ban.user)}\`)`, inline: true })
      .addFields({ name: "Kullanıcı ID", value: `\`${ban.user.id}\``, inline: true });
    if (executor) embed.addFields({ name: "Banlayan", value: executor, inline: true });
    if (ban.reason) embed.addFields({ name: "Sebep", value: truncate(ban.reason, 500) });

    await sendLog(ban.guild, "uye", embed);
  });

  client.on(Events.GuildBanRemove, async (ban) => {
    const executor = await findAuditExecutor(ban.guild, AuditLogEvent.MemberBanRemove, ban.user.id);
    const embed = baseLogEmbed(LOG_COLORS.unban, "🔓 Ban Kaldırıldı")
      .setThumbnail(ban.user.displayAvatarURL())
      .addFields({ name: "Kullanıcı", value: `<@${ban.user.id}> (\`${authorTag(ban.user)}\`)`, inline: true })
      .addFields({ name: "Kullanıcı ID", value: `\`${ban.user.id}\``, inline: true });
    if (executor) embed.addFields({ name: "Kaldıran", value: executor, inline: true });

    await sendLog(ban.guild, "uye", embed);
  });

  client.on(Events.GuildMemberUpdate, async (oldMember: GuildMember | PartialGuildMember, newMember: GuildMember) => {
    // Timeout (iletişimi engelleme) değişikliği
    const oldTimeout = oldMember.communicationDisabledUntilTimestamp ?? null;
    const newTimeout = newMember.communicationDisabledUntilTimestamp ?? null;
    if (oldTimeout !== newTimeout) {
      const executor = await findAuditExecutor(newMember.guild, AuditLogEvent.MemberUpdate, newMember.id);
      if (newTimeout && newTimeout > Date.now()) {
        const embed = baseLogEmbed(LOG_COLORS.timeout, "🔇 Üyeye Zaman Aşımı (Timeout) Verildi")
          .setThumbnail(newMember.user.displayAvatarURL())
          .addFields(
            { name: "Kullanıcı", value: `<@${newMember.id}> (\`${authorTag(newMember.user)}\`)`, inline: true },
            { name: "Süre bitişi", value: `<t:${Math.floor(newTimeout / 1000)}:R>`, inline: true },
          )
          .addFields({ name: "Kullanıcı ID", value: `\`${newMember.id}\``, inline: true });
        if (executor) embed.addFields({ name: "Uygulayan", value: executor, inline: true });
        await sendLog(newMember.guild, "uye", embed);
      } else if (oldTimeout) {
        const embed = baseLogEmbed(LOG_COLORS.unban, "🔊 Üyenin Zaman Aşımı Kaldırıldı")
          .addFields({ name: "Kullanıcı", value: `<@${newMember.id}> (\`${authorTag(newMember.user)}\`)`, inline: true })
          .addFields({ name: "Kullanıcı ID", value: `\`${newMember.id}\``, inline: true });
        if (executor) embed.addFields({ name: "Kaldıran", value: executor, inline: true });
        await sendLog(newMember.guild, "uye", embed);
      }
    }

    // Rol değişikliği
    const oldRoles = new Set(oldMember.roles?.cache?.keys() ?? []);
    const newRoles = new Set(newMember.roles.cache.keys());
    const added = [...newRoles].filter((r) => !oldRoles.has(r));
    const removed = [...oldRoles].filter((r) => !newRoles.has(r));
    if (added.length || removed.length) {
      const embed = baseLogEmbed(LOG_COLORS.rolKanal, "🎭 Üye Rolleri Değişti")
        .setThumbnail(newMember.user.displayAvatarURL())
        .addFields({ name: "Kullanıcı", value: `<@${newMember.id}> (\`${authorTag(newMember.user)}\`)`, inline: true })
        .addFields({ name: "Kullanıcı ID", value: `\`${newMember.id}\``, inline: true });
      if (added.length) embed.addFields({ name: "Eklenen", value: added.map((r) => `<@&${r}>`).join(", ") });
      if (removed.length) embed.addFields({ name: "Kaldırılan", value: removed.map((r) => `<@&${r}>`).join(", ") });
      await sendLog(newMember.guild, "uye", embed);
    }

    // Takma ad değişikliği
    if (oldMember.nickname !== newMember.nickname) {
      const embed = baseLogEmbed(LOG_COLORS.uyeCikis, "✏️ Takma Ad Değişti")
        .setThumbnail(newMember.user.displayAvatarURL())
        .addFields(
          { name: "Kullanıcı", value: `<@${newMember.id}> (\`${authorTag(newMember.user)}\`)`, inline: true },
          { name: "Öncesi", value: oldMember.nickname ?? "*(yoktu)*", inline: true },
          { name: "Sonrası", value: newMember.nickname ?? "*(kaldırıldı)*", inline: true },
        )
        .addFields({ name: "Kullanıcı ID", value: `\`${newMember.id}\``, inline: true });
      await sendLog(newMember.guild, "uye", embed);
    }
  });

  // ---------------------------------------------------------------------
  // ROL & KANAL LOGLARI
  // ---------------------------------------------------------------------

  client.on(Events.ChannelCreate, async (channel: GuildChannel) => {
    const executor = await findAuditExecutor(channel.guild, AuditLogEvent.ChannelCreate, channel.id);
    const embed = baseLogEmbed(LOG_COLORS.rolKanal, "📁 Kanal Oluşturuldu")
      .addFields(
        { name: "Kanal", value: `${channel} (\`${channel.name}\`)`, inline: true },
        { name: "Tip", value: ChannelType[channel.type], inline: true },
      )
      .addFields({ name: "Kanal ID", value: `\`${channel.id}\``, inline: true });
    if (executor) embed.addFields({ name: "Oluşturan", value: executor, inline: true });
    await sendLog(channel.guild, "rolkanal", embed);
  });

  client.on(Events.ChannelDelete, async (channel) => {
    if (!("guild" in channel) || !channel.guild) return;
    const executor = await findAuditExecutor(channel.guild, AuditLogEvent.ChannelDelete, channel.id);
    const embed = baseLogEmbed(LOG_COLORS.mesajSil, "🗑️ Kanal Silindi")
      .addFields(
        { name: "Kanal", value: `\`#${channel.name}\``, inline: true },
        { name: "Tip", value: ChannelType[channel.type], inline: true },
      )
      .addFields({ name: "Kanal ID", value: `\`${channel.id}\``, inline: true });
    if (executor) embed.addFields({ name: "Silen", value: executor, inline: true });
    await sendLog(channel.guild, "rolkanal", embed);
  });

  client.on(Events.ChannelUpdate, async (oldChannel, newChannel) => {
    if (!("guild" in newChannel) || !newChannel.guild) return;
    const changes: string[] = [];
    if ("name" in oldChannel && "name" in newChannel && oldChannel.name !== newChannel.name) {
      changes.push(`**İsim:** \`${oldChannel.name}\` → \`${newChannel.name}\``);
    }
    if ("topic" in oldChannel && "topic" in newChannel && oldChannel.topic !== newChannel.topic) {
      changes.push(`**Konu:** \`${oldChannel.topic ?? "—"}\` → \`${newChannel.topic ?? "—"}\``);
    }
    if ("nsfw" in oldChannel && "nsfw" in newChannel && oldChannel.nsfw !== newChannel.nsfw) {
      changes.push(`**NSFW:** \`${oldChannel.nsfw}\` → \`${newChannel.nsfw}\``);
    }
    if (changes.length === 0) return; // izin/permission overwrite değişiklikleri gürültü yaratmasın diye burada takip edilmiyor

    const executor = await findAuditExecutor(newChannel.guild, AuditLogEvent.ChannelUpdate, newChannel.id);
    const embed = baseLogEmbed(LOG_COLORS.rolKanal, "🛠️ Kanal Güncellendi")
      .addFields({ name: "Kanal", value: `${newChannel}`, inline: true })
      .setDescription(changes.join("\n"))
      .addFields({ name: "Kanal ID", value: `\`${newChannel.id}\``, inline: true });
    if (executor) embed.addFields({ name: "Değiştiren", value: executor, inline: true });
    await sendLog(newChannel.guild, "rolkanal", embed);
  });

  client.on(Events.GuildRoleCreate, async (role: Role) => {
    const executor = await findAuditExecutor(role.guild, AuditLogEvent.RoleCreate, role.id);
    const embed = baseLogEmbed(LOG_COLORS.rolKanal, "🎭 Rol Oluşturuldu")
      .setColor(role.color || LOG_COLORS.rolKanal)
      .addFields(
        { name: "Rol", value: `${role} (\`${role.name}\`)`, inline: true },
        { name: "Renk", value: `\`${role.hexColor}\``, inline: true },
      )
      .addFields({ name: "Rol ID", value: `\`${role.id}\``, inline: true });
    if (executor) embed.addFields({ name: "Oluşturan", value: executor, inline: true });
    await sendLog(role.guild, "rolkanal", embed);
  });

  client.on(Events.GuildRoleDelete, async (role: Role) => {
    const executor = await findAuditExecutor(role.guild, AuditLogEvent.RoleDelete, role.id);
    const embed = baseLogEmbed(LOG_COLORS.mesajSil, "🗑️ Rol Silindi")
      .addFields({ name: "Rol", value: `\`@${role.name}\``, inline: true })
      .addFields({ name: "Rol ID", value: `\`${role.id}\``, inline: true });
    if (executor) embed.addFields({ name: "Silen", value: executor, inline: true });
    await sendLog(role.guild, "rolkanal", embed);
  });

  client.on(Events.GuildRoleUpdate, async (oldRole: Role, newRole: Role) => {
    const changes: string[] = [];
    if (oldRole.name !== newRole.name) changes.push(`**İsim:** \`${oldRole.name}\` → \`${newRole.name}\``);
    if (oldRole.hexColor !== newRole.hexColor) changes.push(`**Renk:** \`${oldRole.hexColor}\` → \`${newRole.hexColor}\``);
    if (oldRole.permissions.bitfield !== newRole.permissions.bitfield) changes.push("**İzinler değişti**");
    if (changes.length === 0) return;

    const executor = await findAuditExecutor(newRole.guild, AuditLogEvent.RoleUpdate, newRole.id);
    const embed = baseLogEmbed(LOG_COLORS.rolKanal, "🛠️ Rol Güncellendi")
      .setDescription(changes.join("\n"))
      .addFields({ name: "Rol", value: `${newRole}`, inline: true })
      .addFields({ name: "Rol ID", value: `\`${newRole.id}\``, inline: true });
    if (executor) embed.addFields({ name: "Değiştiren", value: executor, inline: true });
    await sendLog(newRole.guild, "rolkanal", embed);
  });

  // ---------------------------------------------------------------------
  // SES KANALI LOGLARI
  // ---------------------------------------------------------------------

  client.on(Events.VoiceStateUpdate, async (oldState: VoiceState, newState: VoiceState) => {
    const guild = newState.guild;
    const member = newState.member ?? oldState.member;
    if (!member) return;

    if (!oldState.channelId && newState.channelId) {
      // Kanala katıldı
      const embed = baseLogEmbed(LOG_COLORS.ses, "🔊 Ses Kanalına Katıldı")
        .addFields(
          { name: "Kullanıcı", value: `<@${member.id}>`, inline: true },
          { name: "Kanal", value: `${newState.channel}`, inline: true },
        )
        .addFields({ name: "Kullanıcı ID", value: `\`${member.id}\``, inline: true });
