export { OWNER_ID };
export const BOT_START_TIME = Date.now();

// ---------- Hata kaydı (console.error sarmalama) ----------
export type ErrorLogEntry = { message: string; timestamp: number };
const ERROR_LOG_MAX = 20;
export const errorLog: ErrorLogEntry[] = [];
const originalConsoleError = console.error.bind(console);
function formatLogValue(value: unknown): string {
  if (value instanceof Error) return `${value.name}: ${value.message}`;
  if (typeof value === "string") return value;
  try {
    return JSON.stringify(value);
  } catch {
    return "[serileştirilemeyen değer]";
  }
}

console.error = (...args: unknown[]) => {
  originalConsoleError(...args);
  const message = args.map(formatLogValue).join(" ");
  errorLog.push({ message, timestamp: Date.now() });
  if (errorLog.length > ERROR_LOG_MAX) errorLog.shift();
};

// ---------- Konsol log buffer ----------
export type ConsoleLogEntry = {
  level: "log" | "warn" | "info" | "error";
  message: string;
  timestamp: number;
};
const CONSOLE_LOG_MAX_ENTRIES = 1500;
const CONSOLE_LOG_MAX_AGE_MS = 60 * 60_000;
export const consoleLogBuffer: ConsoleLogEntry[] = [];

function formatConsoleArgs(args: unknown[]): string {
  return args.map(formatLogValue).join(" ");
}

function pushConsoleLog(level: ConsoleLogEntry["level"], args: unknown[]) {
  consoleLogBuffer.push({
    level,
    message: formatConsoleArgs(args),
    timestamp: Date.now(),
  });
  const cutoff = Date.now() - CONSOLE_LOG_MAX_AGE_MS;
  while (consoleLogBuffer.length > 0 && consoleLogBuffer[0].timestamp < cutoff)
    consoleLogBuffer.shift();
  while (consoleLogBuffer.length > CONSOLE_LOG_MAX_ENTRIES)
    consoleLogBuffer.shift();
}

const originalConsoleLog = console.log.bind(console);
const originalConsoleWarn = console.warn.bind(console);
const originalConsoleInfo = console.info.bind(console);
const errorLogWrappedConsoleError = console.error;

console.log = (...args: unknown[]) => {
  originalConsoleLog(...args);
  pushConsoleLog("log", args);
};
console.warn = (...args: unknown[]) => {
  originalConsoleWarn(...args);
  pushConsoleLog("warn", args);
};
console.info = (...args: unknown[]) => {
  originalConsoleInfo(...args);
  pushConsoleLog("info", args);
};
console.error = (...args: unknown[]) => {
  errorLogWrappedConsoleError(...args);
  pushConsoleLog("error", args);
};

// ---------- Yardımcı fonksiyonlar ----------
export function formatDuration(ms: number): string {
  const totalSec = Math.floor(ms / 1000);
  const days = Math.floor(totalSec / 86400);
  const hours = Math.floor((totalSec % 86400) / 3600);
  const minutes = Math.floor((totalSec % 3600) / 60);
  const seconds = totalSec % 60;
  const parts: string[] = [];
  if (days) parts.push(`${days}g`);
  if (hours) parts.push(`${hours}s`);
  if (minutes) parts.push(`${minutes}dk`);
  if (seconds || parts.length === 0) parts.push(`${seconds}sn`);
  return parts.join(" ");
}

export function formatAgo(ts: number): string {
  if (!ts) return "hiç kullanılmadı";
  return `${formatDuration(Date.now() - ts)} önce`;
}

export async function requireOwner(message: Message): Promise<boolean> {
  if (message.author.id === OWNER_ID) return true;
  await message
    .reply(
      MSG.error(`Bu komutu kullanamazsın, sadece <@${OWNER_ID}> kullanabilir.`),
    )
    .catch(() => null);
  return false;
}

/**
 * Bot sahibi VEYA half-owner (bkz. premium/halfOwners.ts) kullanabilir.
 * Şu an kullanan komutlar: !premium, !premium-kaldir, !premium-liste,
 * !özelüye (vip).
 *
 * ⚠️ SADECE düşük riskli, tamamen geri alınabilir, sunucu/bot güvenliğini
 * etkilemeyen işlemler için kullanılmalı. Tehlikeli owner komutları
 * (restart, eval, panel-ac, ownerrole, ytdlp-güncelle, !halfowner'ın
 * kendisi vb.) bunu KULLANMAMALI; onlar `requireOwner` ile veya doğrudan
 * `OWNER_ID` karşılaştırmasıyla owner-only kalmaya devam etmeli.
 */
export async function requireOwnerOrHalfOwner(
  message: Message,
): Promise<boolean> {
  if (message.author.id === OWNER_ID) return true;
  await ensureHalfOwnersLoaded();
  if (isHalfOwner(message.author.id)) return true;
  await message
    .reply(
      MSG.error(
        `Bu komutu kullanamazsın, sadece <@${OWNER_ID}> ve yetkilendirilmiş half-owner'lar kullanabilir.`,
      ),
    )
    .catch(() => null);
  return false;
}

export async function requirePanelAccess(
  message: Message,
  action: string = "paneli açmak",
): Promise<boolean> {
  if (message.author.id === OWNER_ID) return true;
  const hasAccess = message.member?.permissions.has("ModerateMembers") ?? false;
  if (hasAccess) return true;
  await message
    .reply(
      MSG.error(
        `${action[0].toUpperCase()}${action.slice(1)} için "Üyeleri Yönet" (Timeout/Moderate Members) iznine sahip olman gerekiyor.`,
      ),
    )
    .catch(() => null);
  return false;
}

export function resolveTargetUserId(
  message: Message,
  args: string[],
): string | null {
  const mentioned = message.mentions.users.first();
  if (mentioned) return mentioned.id;
  const raw = args[0]?.replace(/[<@!>]/g, "");
  return raw && /^\d{15,25}$/.test(raw) ? raw : null;
}

// Komutu sadece bot sahibi veya sunucu sahibi kullanabilir.
export async function requireOwnerOrGuildOwner(
  message: Message,
): Promise<boolean> {
  if (message.author.id === OWNER_ID) return true;
  if (message.guild && message.guild.ownerId === message.author.id) return true;
  await message
    .reply(
      MSG.error(
        `Bu komutu sadece sunucu sahibi ve <@${OWNER_ID}> kullanabilir.`,
      ),
    )
    .catch(() => null);
  return false;
}

// ---------- Özel üyeler (VIP) ----------
export const vipUsers = new Set<string>();

/** Startup'ta çağrılır; ilk mesajın veritabanı yüklemesini beklemesini önler. */
export async function initializePersistentState(): Promise<void> {
  await ensurePersistedStateLoaded();
  await ensureAfkLoaded();
  await ensurePremiumLoaded();
  await ensureHalfOwnersLoaded();
  await migrateLegacyCustomEvents();
  await loadWordChainChannels();
  ensureWelcomeBackActivityLoaded();
}

// ---------- Sunucu bazlı prefix (!prefix) ----------
const GUILD_PREFIX_KEY_PREFIX = "guild_prefix:";
const guildPrefixMap = new Map<string, string>();

export function getGuildPrefix(guildId: string | null | undefined): string {
  if (!guildId) return DEFAULT_PREFIX;
  return guildPrefixMap.get(guildId) ?? DEFAULT_PREFIX;
}

export async function setGuildPrefix(
  guildId: string,
  newPrefix: string,
): Promise<void> {
  guildPrefixMap.set(guildId, newPrefix);
  try {
    await db
      .insert(botSettingsTable)
      .values({ key: `${GUILD_PREFIX_KEY_PREFIX}${guildId}`, value: newPrefix })
      .onConflictDoUpdate({
        target: botSettingsTable.key,
        set: { value: newPrefix, updatedAt: new Date() },
      });
  } catch (err) {
    console.error(`Sunucu prefix'i kaydedilirken hata (${guildId}):`, err);
  }
}

export async function resetGuildPrefix(guildId: string): Promise<void> {
  guildPrefixMap.delete(guildId);
  try {
    await db
      .delete(botSettingsTable)
      .where(eq(botSettingsTable.key, `${GUILD_PREFIX_KEY_PREFIX}${guildId}`));
  } catch (err) {
    console.error(`Sunucu prefix'i sıfırlanırken hata (${guildId}):`, err);
  }
}

// ---------- Otomatik cevap sistemi ----------
export const autoResponses = new Map<string, string>();
const AUTO_RESPONSE_KEY_PREFIX = "auto_responses:";

export function autoResponseMapKey(guildId: string, trigger: string): string {
  return `${guildId}::${trigger}`;
}

export async function saveAutoResponsesForGuild(
  guildId: string,
): Promise<void> {
  try {
    const prefix = `${guildId}::`;
    const obj: Record<string, string> = {};
    for (const [mapKey, response] of autoResponses) {
      if (mapKey.startsWith(prefix))
        obj[mapKey.slice(prefix.length)] = response;
    }
    const value = JSON.stringify(obj);
    await db
      .insert(botSettingsTable)
      .values({ key: `${AUTO_RESPONSE_KEY_PREFIX}${guildId}`, value })
      .onConflictDoUpdate({
        target: botSettingsTable.key,
        set: { value, updatedAt: new Date() },
      });
  } catch (err) {
    console.error("Otomatik cevaplar kaydedilirken hata:", err);
  }
}

// ---------- VIP ----------
export async function toggleVipById(targetId: string): Promise<boolean> {
  if (vipUsers.has(targetId)) {
    vipUsers.delete(targetId);
    await db.delete(vipUsersTable).where(eq(vipUsersTable.userId, targetId));
    return false;
  }
  vipUsers.add(targetId);
  await db
    .insert(vipUsersTable)
    .values({ userId: targetId })
    .onConflictDoNothing();
  return true;
}

// ---------- Kalıcı veri yükleme ----------
let persistedStateLoaded = false;
let persistedStateLoadingPromise: Promise<void> | null = null;

async function loadPersistedState(): Promise<void> {
  try {
    const [vip, settings] = await Promise.all([
      db.select().from(vipUsersTable),
      db.select().from(botSettingsTable),
    ]);
    for (const row of vip) vipUsers.add(row.userId);

    let restoredGuildPrefixes = 0;
    for (const row of settings) {
      if (row.key.startsWith(GUILD_PREFIX_KEY_PREFIX) && row.value) {
        guildPrefixMap.set(
          row.key.slice(GUILD_PREFIX_KEY_PREFIX.length),
          row.value,
        );
        restoredGuildPrefixes++;
      }
    }

    let restoredAutoResponses = 0;
    for (const row of settings) {
      if (row.key.startsWith(AUTO_RESPONSE_KEY_PREFIX) && row.value) {
        const guildId = row.key.slice(AUTO_RESPONSE_KEY_PREFIX.length);
        try {
          const parsed = JSON.parse(row.value);
          if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
            for (const [trigger, response] of Object.entries(parsed)) {
              if (typeof response === "string") {
                autoResponses.set(
                  autoResponseMapKey(guildId, trigger),
                  response,
                );
                restoredAutoResponses++;
              }
            }
          }
        } catch (err) {
          console.error(
            `Otomatik cevap verisi (JSON) okunurken hata (${row.key}):`,
            err,
          );
        }
      }
    }

    console.log(
      `[state] Kalıcı veri yüklendi: ${vip.length} özel üye, ${restoredGuildPrefixes} özel sunucu prefix'i, ${restoredAutoResponses} otomatik cevap.`,
    );
  } catch (err) {
    console.error("Kalıcı veri yüklenirken hata:", err);
  } finally {
    persistedStateLoaded = true;
  }
}

async function ensurePersistedStateLoaded(): Promise<void> {
  if (persistedStateLoaded) return;
  if (!persistedStateLoadingPromise)
    persistedStateLoadingPromise = loadPersistedState();
  await persistedStateLoadingPromise;
}

export async function messageCreateEvent(
  message: Message,
  commands: Collection<string, Command>,
): Promise<void> {
  if (message.author.bot || message.webhookId) return;
  if (!message.guild) return;

  const guildId = message.guild.id;
  await ensurePersistedStateLoaded();
  await ensureMentionAiLoaded();

  const guildPrefix = getGuildPrefix(guildId);

  // ---------- Tekrar hoşgeldin sistemi ----------
  // Sistem açıksa: kullanıcı ayarlanan süre boyunca bu sunucuda hiç
  // mesaj/komut yazmadıysa (son aktiflik kaydı yoksa veya süre dolmuşsa)
  // karşılama mesajı gönderilir. AFK kontrolünden ÖNCE çalışır ki komut
  // filtresine takılmadan HER mesaj (komut olsun olmasın) aktiflik sayılsın.
  {
    const wbSettings = getWelcomeBackSettings(guildId);
    if (wbSettings.enabled) {
      const lastActivity = getLastActivity(guildId, message.author.id);
      const thresholdMs = wbSettings.durationMinutes * 60_000;
      if (lastActivity !== null && Date.now() - lastActivity >= thresholdMs) {
        const welcomeBackNotice = await message
          .reply({
            content: `<a:1000060632:1548019144304099349> Tekrar hoşgeldin, ${message.author}!`,
            allowedMentions: { users: [message.author.id] },
          })
          .catch(() => null);
        if (welcomeBackNotice) {
          setTimeout(() => {
            void welcomeBackNotice.delete().catch(() => null);
          }, 3_500);
        }
      }
    }
    touchActivity(guildId, message.author.id);
  }

  // ---------- AFK sistemi ----------
  await ensureAfkLoaded();
  const contentLower = message.content.trim().toLocaleLowerCase("tr-TR");
  const AFK_COMMAND_NAMES = ["afk", "uzakta"];
  const guildPrefixLower = guildPrefix.toLocaleLowerCase("tr-TR");
  const afkFirstWord = contentLower.startsWith(guildPrefixLower)
    ? contentLower.slice(guildPrefixLower.length).split(/\s+/)[0]
    : "";
  const isAfkCommand = AFK_COMMAND_NAMES.includes(afkFirstWord);
  if (!isAfkCommand) {
    const previousAfk = await clearAfk(message.author.id);
    if (previousAfk) {
      const away = formatDuration(Date.now() - previousAfk.since);
      const notice = await message
        .reply(
          `${EMOJIS.afkReturn} Tekrar hoşgeldin ${message.author}, AFK durumun kaldırıldı. (${away} uzaktaydın)`,
        )
        .catch(() => null);
      if (notice) setTimeout(() => notice.delete().catch(() => null), 8_000);
    }
  }

  const repliedUser = message.mentions.repliedUser;
  const mentionedUsers = [...message.mentions.users.values()];
  if (repliedUser && !mentionedUsers.some((u) => u.id === repliedUser.id)) {
    mentionedUsers.push(repliedUser);
  }
  if (mentionedUsers.length > 0) {
    const afkMentions = mentionedUsers
      .filter((u) => u.id !== message.author.id)
      .map((u) => ({ user: u, afk: getAfk(u.id) }))
      .filter(
        (m): m is { user: typeof m.user; afk: NonNullable<typeof m.afk> } =>
          m.afk !== null,
      );
    if (afkMentions.length > 0) {
      const staticLines = afkMentions.map(({ user, afk }) => {
        const timeAgo = formatDuration(Date.now() - afk.since);
        return `${EMOJIS.afkActive} **${user.username}** şu an AFK (${timeAgo} önce): ${afk.reason}`;
      });

      // Groq ile daha doğal/bağlama uygun bir mesaj denenir; başarısız
      // olursa (timeout, key hatası vb.) yukarıdaki eski statik mesaja düşülür.
      const aiReply = await generateAfkMentionReply(
        afkMentions.map(({ user, afk }) => ({
          userId: user.id,
          info: {
            displayName: user.username,
            reason: afk.reason,
            minutesAgo: Math.floor((Date.now() - afk.since) / 60_000),
          },
        })),
        message.content,
      );

      const finalReply = aiReply
        ? `${EMOJIS.afkActive} ${aiReply}`
        : staticLines.join("\n");
      await message.reply(finalReply).catch(() => null);
    }
  }

  // ---------- MentionAI ----------
  // Yalnızca sunucuda etkinleştirildiğinde, (varsa) kısıtlı kanalda ve
  // doğrudan bota mention/reply geldiğinde çalışır; diğer kanallarda istek
  // bile PixRouter'a gitmez.
  const botId = message.client.user?.id;
  const isBotMentioned = Boolean(botId && message.mentions.users.has(botId));
  const isReplyToBot =
    message.reference?.messageId !== undefined && repliedUser?.id === botId;
  if (isMentionAiEnabled(guildId) && (isBotMentioned || isReplyToBot)) {
    // Kanal kısıtı: izin yoksa sessizce çık (API çağrısı yok).
    if (!isMentionAiAllowedInChannel(guildId, message.channel.id)) return;

    // Mention-AI de maliyetli; komut rate-limit'i ile aynı korumayı uygula.
    const { checkAiRateLimit } = await import("../utils/rateLimit.js");
    if (!(await checkAiRateLimit(message, "mention-ai"))) return;

    const prompt = botId
      ? message.content.replace(new RegExp(`<@!?${botId}>`, "g"), " ").trim()
      : message.content.trim();
    let repliedMessageContent: string | undefined;
    let repliedImageUrls: string[] = [];
    if (isReplyToBot && message.reference?.messageId) {
      try {
        const referenced = await message.fetchReference();
        repliedMessageContent = referenced.content;
        repliedImageUrls = [...referenced.attachments.values()]
          .filter(
            (attachment) =>
              attachment.contentType?.startsWith("image/") ||
              /\.(png|jpe?g|gif|webp|bmp|avif)$/i.test(attachment.name ?? ""),
          )
          .map((attachment) => attachment.url);
      } catch {
        // Mesaj cache/API erişimi yoksa mevcut prompt ile devam edilir.
      }
    }
    const imageUrls = [...message.attachments.values()]
      .filter(
        (attachment) =>
          attachment.contentType?.startsWith("image/") ||
          /\.(png|jpe?g|gif|webp|bmp|avif)$/i.test(attachment.name ?? ""),
      )
      .map((attachment) => attachment.url)
      .concat(repliedImageUrls)
      .slice(0, 4);
    await message.channel.sendTyping().catch(() => null);
    const typingRefresh = setInterval(() => {
      void message.channel.sendTyping().catch(() => null);
    }, 8_000);
    try {
      // "çiz …" / "draw …" → görsel üret (PixRouter images/generations)
      if (isMentionAiImageRequest(prompt)) {
        const image = await generateMentionAiImage(prompt);
        let attachment: AttachmentBuilder;
        if (image.buffer) {
          attachment = new AttachmentBuilder(image.buffer, {
            name: `mentionai-draw.${image.extension}`,
          });
        } else if (image.url) {
          const imgRes = await fetch(image.url);
          if (!imgRes.ok) {
            throw new Error(
              `Üretilen görsel indirilemedi (${imgRes.status}).`,
            );
          }
          const buf = Buffer.from(await imgRes.arrayBuffer());
          attachment = new AttachmentBuilder(buf, {
            name: `mentionai-draw.${image.extension}`,
          });
        } else {
          throw new Error("Görsel verisi alınamadı.");
        }
        await message
          .reply({
            files: [attachment],
            allowedMentions: { repliedUser: false, parse: [] },
          })
          .catch(() => null);
        return;
      }

      const response = await answerMentionAi({
        guildId,
        userId: message.author.id,
        username: message.author.username,
        prompt,
        repliedMessage: repliedMessageContent,
        imageUrls,
      });
      const extracted = extractMentionAiCodeFiles(response);
      const chunks = extracted.text
        ? splitMentionAiResponse(extracted.text)
        : [];
      const files = extracted.files.map(
        (file) =>
          new AttachmentBuilder(Buffer.from(file.content, "utf8"), {
            name: file.name,
          }),
      );
      const typeScriptNotice = extracted.files.some((file) => file.isTypeScript)
        ? "Not: TypeScript dosyaları Discord'un .ts dosya kısıtı nedeniyle .txt olarak gönderildi."
        : "";
      if (files.length > 0) {
        const firstPayload = {
          ...(chunks.length > 0 || typeScriptNotice
            ? {
                content: [chunks.shift(), typeScriptNotice]
                  .filter(Boolean)
                  .join("\n\n"),
              }
            : {}),
          files,
          allowedMentions: { repliedUser: false, parse: [] },
        };
        await message.reply(firstPayload).catch(() => null);
      }
      if (chunks.length === 0 && files.length === 0)
        chunks.push("AI bir cevap üretemedi, tekrar dene.");
      for (let index = 0; index < chunks.length; index++) {
        const payload = {
          content: chunks[index],
          allowedMentions: { repliedUser: false, parse: [] },
        };
        if (index === 0) await message.reply(payload).catch(() => null);
        else await message.channel.send(payload).catch(() => null);
      }
    } catch (error) {
      console.error("MentionAI hatası:", error);
      await message
        .reply({
          content: `${EMOJIS.error} MentionAI yanıt veremedi: ${mentionAiErrorMessage(error)}`,
          allowedMentions: { repliedUser: false, parse: [] },
        })
        .catch(() => null);
    } finally {
      clearInterval(typingRefresh);
    }
    return;
  }

  const isCommand = message.content.startsWith(guildPrefix);
  if (!isCommand) {
    // ---------- Kelime Zinciri oyunu ----------
    // Bu kanalda aktif bir oyun varsa, kanal SADECE oyun için kullanılır:
    // tek kelimelik geçerli denemeler değerlendirilir, uymayan HER mesaj
    // (birden fazla kelime, komut olmayan cümleler vb.) silinir — Nraphy'deki
    // gibi kanal kelime oyununa tahsis edilmiş sayılır.
    if (isGameActive(message.channel.id)) {
      // Bot sahibi, "!kelime izin aç" ile açtığında kelime zinciri kanalına
      // da normal mesaj (duyuru vb.) atabilir — mesajı silinmez, kelime
      // denemesi olarak da sayılmaz. Kapalıyken (varsayılan) bot sahibi de
      // herkes gibi oyuna dahildir.
      const isExempt = message.author.id === OWNER_ID && isOwnerBypassEnabled();
      if (!isExempt) {
        if (!looksLikeWordAttempt(message.content)) {
          await message.delete().catch(() => null);
          return;
        }

        const result = await submitWord(
          message.channel.id,
          message.author.id,
          message.content,
        );
        if (result) {
          if (result.ok) {
            await message.react(EMOJIS.prm3).catch(() => null);
          } else {
            const requiredLetter = getRequiredLetter(message.channel.id);
            const reasonText: Record<typeof result.reason, string> = {
              consecutive:
                "2 kere üst üste sen oynayamazsın, sırayı başkasına bırak.",
              used: "Bu kelime son 2 saat içinde kullanıldı; cooldown bitince yeniden oynanabilir.",
              "wrong-letter": `Kelime \"${requiredLetter ?? ""}\" harfiyle başlamalı.`,
              "invalid-format": "Geçersiz kelime.",
              "not-a-word": "Bu kelime TDK sözlüğünde bulunamadı.",
              "too-short":
                "1, 2 ve 3 harfli kelimeler sayılmaz; en az 4 harfli bir kelime yazmalısın.",
            };
            const notice = await message
              .reply(`${EMOJIS.uyari} ${reasonText[result.reason]}`)
              .catch(() => null);
            setTimeout(() => {
              void message.delete().catch(() => null);
              void notice?.delete().catch(() => null);
            }, 1500);
          }
          return;
        }
      }
    }

    const normalizedContent = message.content.trim().toLocaleLowerCase("tr-TR");
    const autoResponse = autoResponses.get(
      autoResponseMapKey(guildId, normalizedContent),
    );
    if (autoResponse) {
      await message
        .reply({
          content: autoResponse.slice(0, 2_000),
          allowedMentions: { parse: [] },
        })
        .catch(() => null);
    }
    return;
  }

  const args = message.content.slice(guildPrefix.length).trim().split(/\s+/);
  const commandName = args.shift()?.toLowerCase();
  if (!commandName) return;

  const command = commands.get(commandName);
  if (command) {
    // Genel komut rate-limit (spam / flood koruması). Owner muaf.
    const { checkCommandRateLimit } = await import("../utils/rateLimit.js");
    if (
      !(await checkCommandRateLimit(
        message,
        message.author.id,
        commandName,
      ))
    ) {
      return;
    }

    let success = true;
    try {
      await command.execute(message, args);
    } catch (err) {
      success = false;
      // Ham hata objesini (rawError/requestBody/stack dahil) basmak yerine
      // kısa, okunabilir bir özet + stack basıyoruz — aksi halde Discord API
      // hataları console'u sayfalarca gereksiz JSON ile dolduruyor ve gerçek
      // sebep (örn. "Missing Permissions") kaybolup gidiyor.
      console.error(`Komut hatası (${commandName}): ${getErrorMessage(err)}`);
      if (err instanceof Error && err.stack) console.error(err.stack);
      await message
        .reply({
          embeds: [errorEmbed("Bir Hata Oluştu", getErrorMessage(err))],
        })
        .catch(() => null);
    }
    void notifyOwnerCommandUsed(message.client, {
      commandName,
      user: message.author,
      guild: message.guild,
      success,
      source: "prefix",
    });
    return;
  }

  // ---------- Sunucuya özel custom event'ler ----------
  const customEvent = await getCustomEvent(guildId, commandName).catch(
    () => null,
  );
  if (!customEvent) return;

  {
    const { checkCommandRateLimit } = await import("../utils/rateLimit.js");
    if (
      !(await checkCommandRateLimit(
        message,
        message.author.id,
        `custom:${commandName}`,
      ))
    ) {
      return;
    }
  }

  try {
    const result = await executeCustomEvent(customEvent.code, customEvent, {
      message,
      args,
    });
    if (!result) return;
    if (result.kind === "embed") {
      await message.reply({
        embeds: [result.embed],
        allowedMentions: { parse: [] },
      });
    } else if (result.content !== "\u200b") {
      await message.reply({
        content: result.content,
        allowedMentions: { parse: [] },
      });
    }
  } catch (err) {
    console.error(`Custom event hatası (${commandName}):`, err);
    await message
      .reply("❌ Bu custom event çalıştırılırken bir hata oluştu.")
      .catch(() => null);
  }
}
","events/modellerPanel.ts":"// src/events/modellerPanel.ts
// !modeller komutunun görünümünü (tek embed + select menu'ler) oluşturur.
// Owner-only: sadece bot sahibi hangi komut grubunun hangi AI modelini
// kullandığını buradan değiştirebilir (bkz. utils/modelSettings.ts).
//
// Üç grup var — kullanıcı hiçbirini değiştirmediği sürece koddaki orijinal
// varsayılan modeller (utils/modelSettings.ts'teki defaultModel) kullanılmaya
// devam eder.
//
// Tasarım: 4 ayrı embed yerine TEK embed, her grup bir field. Tüm modeller
// hâlâ listeleniyor ve aktif olan ✅ ile işaretleniyor (select menüden de
// seçilebiliyor) — sadece tekrar eden başlık/footer/renk gibi dolgu
// kaldırılarak toplam boy kısaltıldı. Gruplar sağlayıcı adıyla değil
// (Gemini/Groq/OpenRouter), modelin fiilen kullanıldığı yer/komutlarla
// etiketleniyor — owner "hangi model neyi çalıştırıyor" diye sağlayıcı
// isimlerini ezberlemek zorunda kalmasın diye.

import {
  EmbedBuilder,
  ActionRowBuilder,
  StringSelectMenuBuilder,
  StringSelectMenuOptionBuilder,
  ButtonBuilder,
  ButtonStyle,
} from "discord.js";
import { MODEL_GROUPS, getActiveModel, hasOverride, type ModelGroup } from "../utils/modelSettings.js";

export const MODELLER_SELECT_PREFIX = "modeller_select_";
export const MODELLER_RESET_PREFIX = "modeller_reset_";

const GROUP_ORDER: ModelGroup[] = ["gemini", "groq", "openrouter"];

// Sağlayıcı adı yerine gösterilecek başlık: modelin kullanıldığı yer.
const GROUP_USAGE_LABEL: Record<ModelGroup, string> = {
  gemini: "Çeviri, Özet & Yazı",
  groq: "Sohbet, Fikir & AFK Cevap",
  openrouter: "Kod Araçları",
};

const GROUP_USAGE_COMMANDS: Record<ModelGroup, string> = {
  gemini: "`!ceviri` `!ozetle` `!yaz` `!bilgiyarismasi`",
  groq: "`!fikir` `!özet` `!sor` AFK otomatik cevap",
  openrouter: "`!kod-yaz` `!kod-analiz` `!kod-duzelt` `!kod-test`",
};

function providerPrefix(value: string): string {
  const sep = value.indexOf(":");
  return sep > 0 ? value.slice(0, sep) : "groq";
}

// Sadece görünüm için: aynı komut grubu (ör. "groq") altında birden fazla
// sağlayıcı olduğunda (Groq/Cerebras + NVIDIA gibi), liste içinde sağlayıcı
// değiştiğinde kalın bir alt başlık basılıyor. Fonksiyonel olarak hepsi aynı
// select menüde/komut grubunda kalmaya devam ediyor — bu sadece okunabilirlik
// için bir ayraç.
const SUBHEADER_LABEL: Record<string, string> = {
  nvidia: "**NVIDIA**",
  gemini: "**Gemini**",
  groq: "**Groq**",
  aimlapi: "**AIML API**",
  pixrouter: "**PixRouter**",
};

function groupField(group: ModelGroup): { name: string; value: string; inline: boolean } {
  const info = MODEL_GROUPS[group];
  const active = getActiveModel(group);

  let lastPrefix: string | null = null;
  const optionLines = info.options
    .flatMap((opt) => {
      const prefix = providerPrefix(opt.value);
      const header = prefix !== lastPrefix && SUBHEADER_LABEL[prefix] ? [SUBHEADER_LABEL[prefix]] : [];
      lastPrefix = prefix;
      const marker = opt.value === active ? "<a:1000021814:1540389540513194066>" : "▫️";
      const star = opt.value === info.defaultModel ? " ⭐" : "";
      return [...header, `${marker} ${opt.label}${star}`];
    })
    .join("\n");

  return {
    name: `${info.emoji} ${GROUP_USAGE_LABEL[group]}`,
    value: `-# ${GROUP_USAGE_COMMANDS[group]}\n${optionLines}`,
    inline: false,
  };
}

function selectRowFor(group: ModelGroup): ActionRowBuilder<StringSelectMenuBuilder> {
  const info = MODEL_GROUPS[group];
  const active = getActiveModel(group);

  const select = new StringSelectMenuBuilder()
    .setCustomId(`${MODELLER_SELECT_PREFIX}${group}`)
    .setPlaceholder(`${info.emoji} ${GROUP_USAGE_LABEL[group]} — model seç`)
    .addOptions(
      info.options.map((opt) => {
        const option = new StringSelectMenuOptionBuilder()
          .setLabel(opt.label)
          .setValue(opt.value)
          .setDefault(opt.value === active);
        if (opt.value === info.defaultModel) option.setDescription("Varsayılan");
        return option;
      }),
    );

  return new ActionRowBuilder<StringSelectMenuBuilder>().addComponents(select);
}

function resetButtonRow(): ActionRowBuilder<ButtonBuilder> {
  return new ActionRowBuilder<ButtonBuilder>().addComponents(
    new ButtonBuilder()
      .setCustomId(`${MODELLER_RESET_PREFIX}all`)
      .setLabel("Tümünü Varsayılana Sıfırla")
      .setEmoji("↩️")
      .setStyle(ButtonStyle.Secondary),
  );
}

export function buildModellerView(): { embeds: EmbedBuilder[]; components: ActionRowBuilder<StringSelectMenuBuilder | ButtonBuilder>[] } {
  const embed = new EmbedBuilder()
    .setColor(0x2b2d31)
    .setTitle("🧠 AI Model Ayarları")
    .setDescription("<a:1000021814:1540389540513194066> aktif · ⭐ varsayılan — menülerden değiştirebilirsin.")
    .addFields(GROUP_ORDER.map((group) => groupField(group)));

  const components: ActionRowBuilder<StringSelectMenuBuilder | ButtonBuilder>[] = [
    ...GROUP_ORDER.map((group) => selectRowFor(group)),
    resetButtonRow(),
  ];

  return { embeds: [embed], components };
}
","events/panel.ts":"import { EmbedBuilder, ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelSelectMenuBuilder, ChannelType, RoleSelectMenuBuilder, type Guild, type Client } from "discord.js";
import { getGuildPrefix, vipUsers } from "./messageCreate.js";
import { getAllLogChannels, LOG_CATEGORIES } from "../utils/logger.js";
import { getAllChannelSettings, CHANNEL_SETTINGS } from "../utils/channelSettings.js";

// ---------------------------------------------------------------------------
// !panel komutu için sekme (tab) görünümleri. messageCreate.ts (ilk gönderim)
// ve interactionCreate.ts (sekme geçişleri + buton/modal aksiyonları)
// tarafından ortak kullanılıyor.
//
// 4 sekme: Genel / Moderasyon / Üyeler / Durum. Her sekme, o alanda mevcut
// olan neredeyse her komutu butona/modala bağlıyor — böylece owner çoğu şeyi
// Discord'dan yazmadan panelden yönetebiliyor.
// ---------------------------------------------------------------------------

export type PanelTab = "genel" | "mod" | "uyeler" | "info" | "bulksilme";

function tabRow(active: PanelTab): ActionRowBuilder<ButtonBuilder> {
  return new ActionRowBuilder<ButtonBuilder>().addComponents(
    new ButtonBuilder()
      .setCustomId("panel_tab_genel")
      .setLabel("Genel")
      .setEmoji("⚙️")
      .setStyle(ButtonStyle.Primary)
      .setDisabled(active === "genel"),
    new ButtonBuilder()
      .setCustomId("panel_tab_mod")
      .setLabel("Moderasyon")
      .setEmoji("🔨")
      .setStyle(ButtonStyle.Danger)
      .setDisabled(active === "mod"),
    new ButtonBuilder()
      .setCustomId("panel_tab_uyeler")
      .setLabel("Üyeler")
      .setEmoji("👥")
      .setStyle(ButtonStyle.Secondary)
      .setDisabled(active === "uyeler"),
    new ButtonBuilder()
      .setCustomId("panel_tab_info")
      .setLabel("Durum")
      .setEmoji("📊")
      .setStyle(ButtonStyle.Secondary)
      .setDisabled(active === "info"),
  );
}

// ---------------------------------------------------------------------------
// ⚙️ Genel
// ---------------------------------------------------------------------------
export function buildGenelTab(guildId?: string | null) {
  const prefix = getGuildPrefix(guildId);
  const embed = new EmbedBuilder()
    .setColor(0x5865f2)
    .setTitle("🎛️ Bot Kontrol Merkezi")
    .setDescription("Sunucu yönetim araçlarına hızlı erişim. Aşağıdaki sekmelerden bir alan seç.")
    .addFields(
      { name: "⚙️ Sunucu Ayarı", value: `Prefix: \`${prefix}\`\nÇalışma süresi: **${formatUptime(process.uptime())}**`, inline: true },
      { name: "✨ Özel Üyeler", value: `Kayıtlı özel üye: **${vipUsers.size}**`, inline: true },
      { name: "💡 Hızlı Bilgi", value: `Detaylar için \`${prefix}istatistik\` ve \`${prefix}uptime\` komutlarını kullanabilirsin.`, inline: false },
    )
    .setFooter({ text: "Discord v14 Yönetim Paneli • Bir sekme seçerek devam et" })
    .setTimestamp();

  const row = new ActionRowBuilder<ButtonBuilder>().addComponents(
    new ButtonBuilder()
      .setCustomId("panel_duyuru_open")
      .setLabel("Duyuru Gönder")
      .setEmoji("📢")
      .setStyle(ButtonStyle.Primary),
  );

  return { embeds: [embed], components: [tabRow("genel"), row] };
}

// ---------------------------------------------------------------------------
// 🔨 Moderasyon
// ---------------------------------------------------------------------------
export function buildModTab() {
  const embed = new EmbedBuilder()
    .setColor(0xed4245)
    .setTitle("🔨 Moderasyon Merkezi")
    .setDescription("Üye işlemlerini butonlara dokunarak açılan güvenli formlarla yönet.")
    .addFields(
      { name: "🚨 Cezalandırma", value: "🔨 Ban\n👢 Kick\n🔇 Mute / Unmute", inline: true },
      { name: "🛡️ Kayıt & İnceleme", value: "⚠️ Warn\n👁️ Uyarılar\n♻️ Unban", inline: true },
      { name: "🗑️ Toplu İşlemler", value: "Toplu Silme; kanal ve rol seçimleriyle ayrı, onaylı bir ekranda çalışır.", inline: false },
    )
    .setFooter({ text: "Her işlem kendi Discord yetkisini kontrol eder" })
    .setTimestamp();
  const row1 = new ActionRowBuilder<ButtonBuilder>().addComponents(
    new ButtonBuilder().setCustomId("panel_open_ban").setLabel("Ban").setEmoji("🔨").setStyle(ButtonStyle.Danger),
    new ButtonBuilder().setCustomId("panel_open_kick").setLabel("Kick").setEmoji("👢").setStyle(ButtonStyle.Danger),
    new ButtonBuilder().setCustomId("panel_open_mute").setLabel("Mute").setEmoji("🔇").setStyle(ButtonStyle.Secondary),
