    healthServer = http.createServer((req, res) => {
      if (req.url !== "/healthz") {
        res.writeHead(404);
        res.end("Not Found");
        return;
      }
      const ready = client.isReady();
      res.writeHead(ready ? 200 : 503, {
        "content-type": "application/json; charset=utf-8",
      });
      res.end(
        JSON.stringify({ ok: ready, ping: ready ? client.ws.ping : null }),
      );
    });
    healthServer.listen(HTTP_PORT, () => {
      console.log(`🌐 Health check sunucusu :${HTTP_PORT} portunda dinliyor`);
    });
  } else {
    console.error(`❌ Geçersiz PORT değeri: ${process.env.PORT}`);
  }
}

// 🔎 Bağlantı tanı modu: yalnızca DEBUG_NETWORK=true iken çalışır. Login
// takılıp kalırsa (ne başarılı ne hatalı döner) ağ/DNS seviyesinde bir
// sorunu ayıklamak için kullanılır — üretimde varsayılan olarak kapalıdır.
const DEBUG_NETWORK = process.env.DEBUG_NETWORK === "true";
if (DEBUG_NETWORK) {
  fetch("https://discord.com/api/v10/users/@me", {
    headers: { Authorization: `Bot ${TOKEN}` },
  })
    .then((res) => res.json())
    .then((data) => console.log("🌐 REST testi sonucu:", data.username ?? data))
    .catch((err) => console.error("🌐 REST testi HATASI:", err));
}

// Başlangıç sırasında (ör. Neon compute henüz uyanmadıysa) DB'ye ilk erişim
// başarısız olursa artan gecikmelerle birkaç kez daha dener; hepsi başarısız
// olursa hatayı olduğu gibi yukarı fırlatır (start() zaten bunu yakalayıp
// düzgün kapatıyor).
async function withStartupRetry<T>(
  fn: () => Promise<T>,
  label: string,
  maxAttempts = 5,
): Promise<T> {
  const delays = [1_000, 2_000, 5_000, 10_000, 15_000];
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await fn();
    } catch (err) {
      if (attempt === maxAttempts) throw err;
      const delay = delays[attempt - 1] ?? 15_000;
      console.warn(
        `⚠️ Başlangıç adımı "${label}" başarısız (deneme ${attempt}/${maxAttempts}), ${delay}ms sonra tekrar denenecek:`,
        err instanceof Error ? err.message : err,
      );
      await new Promise((resolve) => setTimeout(resolve, delay));
    }
  }
  throw new Error("unreachable");
}

let shuttingDown = false;

async function shutdown(exitCode = 0): Promise<void> {
  if (shuttingDown) return;
  shuttingDown = true;
  healthServer?.close();
  client.destroy();
  flushWelcomeBackActivityNow();
  try {
    await closeDatabase();
  } catch (err) {
    console.error("⚠️ Veritabanı bağlantısı kapatılırken hata:", err);
    exitCode = 1;
  }
  process.exit(exitCode);
}

process.once("SIGINT", () => void shutdown(0));
process.once("SIGTERM", () => void shutdown(0));

async function start(): Promise<void> {
  try {
    // Discord'a bağlanmadan önce şema ve bellekteki kalıcı ayarlar hazır olur.
    // Böylece ilk mesajlar yarış durumuna girmez ve DB hatası gizlenmez.
    // Neon (özellikle ücretsiz plan) süreç ilk ayağa kalktığında henüz
    // "uyanmamış" olabilir; ilk deneme koptursa bile birkaç kez daha
    // deneyip vazgeçiyoruz, tek seferlik geçici bir hata yüzünden bot
    // başlamadan kapanmasın diye.
    await withStartupRetry(() => ensureTables(), "ensureTables");
    await warmAutomodConfigCache().catch((err: unknown) => {
      console.error(
        "⚠️ Otomod cache başlangıçta ısıtılamadı; ayarlar ilk istekte yüklenecek:",
        err,
      );
    });
    await warmGuardConfigCache().catch((err: unknown) => {
      console.error(
        "⚠️ Guard cache başlangıçta ısıtılamadı; ayarlar ilk istekte yüklenecek:",
        err,
      );
    });
    await initializePersistentState();
    console.log("✅ Veritabanı ve kalıcı bot durumu hazır.");

    console.log("🔑 Discord'a giriş deneniyor...");
    const loginStuckTimer = setTimeout(() => {
      console.warn(
        "⏳ 15 saniyedir giriş tamamlanmadı. Gateway/DNS erişimini kontrol et; " +
          "ayrıntılı tanı için DEBUG_NETWORK=true kullanabilirsin.",
      );
    }, 15_000);
    loginStuckTimer.unref?.();

    try {
      await client.login(TOKEN);
    } finally {
      clearTimeout(loginStuckTimer);
    }
  } catch (err) {
    console.error("❌ Bot başlatılamadı:", err);
    await shutdown(1);
  }
}

void start();
","premium/gate.ts":"import type { Message } from "discord.js";
import { OWNER_ID } from "../config.js";
import { premiumEmbed, warningEmbed } from "../utils/embeds.js";
import { checkAiRateLimit } from "../utils/rateLimit.js";
import { ensurePremiumLoaded, isPremium, checkAndConsumeTrial } from "./store.js";

// Premium olmayan bir kullanıcı, premium'a özel komutları en fazla bu kadar
// deneyebilir (komut başına — bkz. store.ts checkAndConsumeTrial).
export const TRIAL_LIMIT = 3;

/**
 * Gemini / Groq / diğer ücretli-limitli kaynak tüketen komutların en başında
 * çağrılır.
 *
 * Sıra:
 *  1) Rate limit (premium dahil, owner muaf) — spam / çift tıklama koruması
 *  2) Premium ise geç
 *  3) Trial hakkı varsa harca ve geç
 *  4) Aksi halde reddet
 */
export async function requirePremiumOrTrial(
  message: Message,
  commandName: string,
): Promise<boolean> {
  if (!(await checkAiRateLimit(message, commandName))) return false;

  await ensurePremiumLoaded();
  const userId = message.author.id;

  if (isPremium(userId)) return true;

  const { allowed, usedBefore } = await checkAndConsumeTrial(
    userId,
    commandName,
    TRIAL_LIMIT,
  );

  if (allowed) {
    const remaining = TRIAL_LIMIT - (usedBefore + 1);
    if (remaining === 0) {
      await message
        .reply({
          embeds: [
            warningEmbed(
              "Son ücretsiz denemen",
              `Bu, \`${commandName}\` için ücretsiz deneme haklarının SONUNCUSUYDU. Bundan sonra bu komutu kullanmak için premium gerekiyor — premium almak için <@${OWNER_ID}> ile iletişime geç.`,
            ),
          ],
        })
        .catch(() => null);
    }
    return true;
  }

  await message
    .reply({
      embeds: [
        premiumEmbed(
          "Bu komut artık premium",
          `\`${commandName}\` için ücretsiz deneme hakların bitti (${TRIAL_LIMIT}/${TRIAL_LIMIT} kullanıldı). ` +
            `Bu komutu kullanmaya devam etmek için premium üyelik gerekiyor — <@${OWNER_ID}> ile iletişime geç.`,
        ),
      ],
    })
    .catch(() => null);
  return false;
}

/**
 * requirePremiumOrTrial ile aynı mantık, ama TRIAL_LIMIT yerine sabit 1
 * hak kullanır. Sadece !agent gibi tek seferlik deneme sunulması istenen
 * komutlar için — genel TRIAL_LIMIT'i (3) etkilemez.
 */
export async function requirePremiumOrSingleTrial(
  message: Message,
  commandName: string,
): Promise<boolean> {
  if (!(await checkAiRateLimit(message, commandName))) return false;

  await ensurePremiumLoaded();
  const userId = message.author.id;
  const SINGLE_TRIAL_LIMIT = 1;

  if (isPremium(userId)) return true;

  const { allowed } = await checkAndConsumeTrial(
    userId,
    commandName,
    SINGLE_TRIAL_LIMIT,
  );

  if (allowed) {
    await message
      .reply({
        embeds: [
          warningEmbed(
            "Tek seferlik ücretsiz deneme",
            `Bu, \`${commandName}\` için sahip olduğun TEK ücretsiz denemeydi. Bundan sonra bu komutu kullanmak için premium gerekiyor — premium almak için <@${OWNER_ID}> ile iletişime geç.`,
          ),
        ],
      })
      .catch(() => null);
    return true;
  }

  await message
    .reply({
      embeds: [
        premiumEmbed(
          "Bu komut artık premium",
          `\`${commandName}\` için tek seferlik ücretsiz denemeni zaten kullandın. Bu komutu kullanmaya devam etmek için premium üyelik gerekiyor — <@${OWNER_ID}> ile iletişime geç.`,
        ),
      ],
    })
    .catch(() => null);
  return false;
}
","premium/halfOwners.ts":"import { eq } from "drizzle-orm";
import { db, halfOwnersTable } from "../db/index.js";
import { OWNER_ID } from "../config.js";

// ---------------------------------------------------------------------------
// Yarı-yetkili (half-owner) listesi.
//
// Bot sahibinin (OWNER_ID) devrettiği, SADECE premium VERME yetkisine sahip
// kullanıcılar. Kalıcıdır (süresi yok), sadece !halfowner sil ile geri
// alınır. Premium/AFK/VIP sistemleriyle aynı desen: açılışta DB'den belleğe
// yüklenir, her değişiklikte hem bellek hem DB güncellenir.
//
// ⚠️ GÜVENLİK: Bu liste SADECE bilinçli olarak half-owner'a açılan komutlar
// için geçerlidir (ör. !premium, !özelüye). eval / restart / modeller /
// hata-log gibi tehlikeli komutlar doğrudan OWNER_ID kontrolü yapar ve bu
// listeye HİÇ bakmaz — half-owner olmak owner olmak anlamına gelmez.
// ---------------------------------------------------------------------------

const halfOwners = new Set<string>();

let loaded = false;
let loadingPromise: Promise<void> | null = null;

async function loadHalfOwners(): Promise<void> {
  const rows = await db.select().from(halfOwnersTable);
  halfOwners.clear();
  for (const row of rows) halfOwners.add(row.userId);
  loaded = true;
  console.log(`[HalfOwner] ${rows.length} half-owner yüklendi.`);
}

export async function ensureHalfOwnersLoaded(): Promise<void> {
  if (loaded) return;
  if (!loadingPromise) {
    loadingPromise = loadHalfOwners().finally(() => {
      loadingPromise = null;
    });
  }
  await loadingPromise;
}

export function isHalfOwner(userId: string): boolean {
  return halfOwners.has(userId);
}

/** Şu an yüklü tüm half-owner ID'lerini döner (eklenme sırasına özel bir garanti yok). */
export function listHalfOwnerIds(): string[] {
  return [...halfOwners];
}

/**
 * Half-owner ekler. Zaten half-owner ise false döner (no-op).
 * Bot sahibi (OWNER_ID) hiçbir zaman bu listeye eklenmez/eklenemez — zaten
 * tüm yetkilere sahip ve half-owner kısıtlamalarına tabi değil.
 */
export async function addHalfOwner(userId: string, addedBy: string): Promise<boolean> {
  if (userId === OWNER_ID) return false;
  await ensureHalfOwnersLoaded();
  const inserted = await db
    .insert(halfOwnersTable)
    .values({ userId, addedBy })
    .onConflictDoNothing()
    .returning({ userId: halfOwnersTable.userId });
  if (inserted.length === 0) {
    halfOwners.add(userId);
    return false;
  }
  halfOwners.add(userId);
  return true;
}

/** Half-owner yetkisini geri alır. Kişi zaten half-owner değilse false döner (no-op). */
export async function removeHalfOwner(userId: string): Promise<boolean> {
  await ensureHalfOwnersLoaded();
  const deleted = await db
    .delete(halfOwnersTable)
    .where(eq(halfOwnersTable.userId, userId))
    .returning({ userId: halfOwnersTable.userId });
  halfOwners.delete(userId);
  return deleted.length > 0;
}
","premium/store.ts":"import { eq } from "drizzle-orm";
import { OWNER_ID } from "../config.js";
import { db, pool, premiumUsersTable } from "../db/index.js";

// ---------------------------------------------------------------------------
// Premium kullanıcı listesi.
//
// KALICI: süresi/expiry'si yok, sadece revokePremium() (bkz. !premium-kaldir)
// ile geri alınır. AFK/VIP sistemleriyle aynı desen: açılışta DB'den belleğe
// yüklenir, her değişiklikte hem bellek hem DB güncellenir.
// ---------------------------------------------------------------------------

const premiumUsers = new Set<string>();

let loaded = false;
let loadingPromise: Promise<void> | null = null;

async function loadPremium(): Promise<void> {
  const rows = await db.select().from(premiumUsersTable);
  premiumUsers.clear();
  for (const row of rows) premiumUsers.add(row.userId);
  loaded = true;
  console.log(`[Premium] ${rows.length} premium kullanıcı yüklendi.`);
}

export async function ensurePremiumLoaded(): Promise<void> {
  if (loaded) return;
  if (!loadingPromise) {
    loadingPromise = loadPremium().finally(() => {
      loadingPromise = null;
    });
  }
  await loadingPromise;
}

export function isPremium(userId: string): boolean {
  // Bot sahibi her zaman premium sayılır — kendine !premium vermek zorunda kalmasın.
  if (userId === OWNER_ID) return true;
  return premiumUsers.has(userId);
}

/** Premium verir. Kişi zaten premium ise false döner (no-op). */
export async function grantPremium(userId: string, grantedBy: string): Promise<boolean> {
  await ensurePremiumLoaded();
  const inserted = await db
    .insert(premiumUsersTable)
    .values({ userId, grantedBy })
    .onConflictDoNothing()
    .returning({ userId: premiumUsersTable.userId });
  if (inserted.length === 0) {
    premiumUsers.add(userId);
    return false;
  }
  premiumUsers.add(userId);
  return true;
}

export interface PremiumUserInfo {
  userId: string;
  grantedBy: string;
  grantedAt: Date;
}

/** Tüm premium kullanıcıları döner (verilme tarihine göre, en eski önce) — bkz. !premium-liste. */
export async function getAllPremiumUsers(): Promise<PremiumUserInfo[]> {
  await ensurePremiumLoaded();
  const rows = await db.select().from(premiumUsersTable).orderBy(premiumUsersTable.grantedAt);
  return rows.map((r) => ({ userId: r.userId, grantedBy: r.grantedBy, grantedAt: r.grantedAt }));
}

/** Premium'u geri alır. Kişi zaten premium değilse false döner (no-op). */
export async function revokePremium(userId: string): Promise<boolean> {
  // Bot sahibi her zaman premium; listeden silinse bile isPremium true döner.
  // Half-owner'ın owner'ı "premium değil" sanmasını engellemek için no-op.
  if (userId === OWNER_ID) return false;
  await ensurePremiumLoaded();
  const deleted = await db
    .delete(premiumUsersTable)
    .where(eq(premiumUsersTable.userId, userId))
    .returning({ userId: premiumUsersTable.userId });
  premiumUsers.delete(userId);
  return deleted.length > 0;
}

// ---------------------------------------------------------------------------
// Ücretsiz deneme hakları: premium olmayan kullanıcılar için, KOMUT BAŞINA
// (ör. kod-yaz'daki haklar bitse bile ozetle hâlâ kendi hakkına sahiptir)
// sınırlı sayıda kullanım. Kalıcıdır (DB'de tutulur) — bot yeniden başlasa
// bile haklar sıfırlanmaz.
// ---------------------------------------------------------------------------

export interface TrialResult {
  allowed: boolean;
  usedBefore: number; // bu çağrıdan ÖNCEKİ kullanım sayısı
}

export async function checkAndConsumeTrial(
  userId: string,
  commandName: string,
  limit: number,
): Promise<TrialResult> {
  const safeLimit = Number.isFinite(limit) ? Math.max(0, Math.floor(limit)) : 0;
  if (safeLimit === 0) return { allowed: false, usedBefore: 0 };

  const key = `${userId}:${commandName}`;
  // INSERT + ON CONFLICT UPDATE + WHERE tek SQL ifadesi olduğundan, aynı
  // kullanıcıdan gelen eşzamanlı iki istek aynı son hakkı birlikte kullanamaz.
  const result = await pool.query<{ uses: number }>(
    `INSERT INTO discord_command_trials (key, user_id, command_name, uses)
     VALUES ($1, $2, $3, 1)
     ON CONFLICT (key) DO UPDATE
       SET uses = discord_command_trials.uses + 1
       WHERE discord_command_trials.uses < $4
     RETURNING uses`,
    [key, userId, commandName, safeLimit],
  );
  if (result.rows[0]) {
    const usesAfter = Number(result.rows[0].uses);
    return { allowed: true, usedBefore: Math.max(0, usesAfter - 1) };
  }

  const current = await pool.query<{ uses: number }>(
    "SELECT uses FROM discord_command_trials WHERE key = $1",
    [key],
  );
  return { allowed: false, usedBefore: Number(current.rows[0]?.uses ?? safeLimit) };
}
