const SOURCE_ROOT = path.resolve(__dirname, "..");
// Bu dosyanın kendi uzantısı neyse (ts geliştirmede, js derlenmiş halde)
// taranan dosyalar da o uzantıda olsun — ortamdan bağımsız çalışsın diye.
const SOURCE_EXT = path.extname(__filename) || ".ts";

const MAX_SNAPSHOT_FILE_BYTES = 300_000; // tek dosya için üst sınır (anlık görüntüde şişmeyi önler)
const MAX_DIFF_CHARS = 12_000; // AI'ya gönderilecek toplam diff üst sınırı
const MAX_PER_FILE_DIFF_LINES = 120; // tek dosya için diff satırı üst sınırı
const MAX_LCS_CELLS = 3_000_000; // O(n*m) diff için güvenlik sınırı

export interface PendingChangelog {
  guildId: string | null;
  channelId: string;
  triggeredBy: string;
  requestedAt: number;
  firstRun?: boolean;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function walkSourceFiles(dir: string, out: string[] = []): string[] {
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return out;
  }
  for (const entry of entries) {
    if (entry.name.startsWith(".")) continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (IGNORED_DIR_NAMES.has(entry.name)) continue;
      walkSourceFiles(full, out);
    } else if (entry.isFile() && entry.name.endsWith(SOURCE_EXT)) {
      out.push(full);
    }
  }
  return out;
}

/** Diskteki mevcut kaynak dosyaların { göreli yol -> içerik } anlık görüntüsü. */
export function buildSourceSnapshot(): Record<string, string> {
  const snapshot: Record<string, string> = {};
  for (const file of walkSourceFiles(SOURCE_ROOT)) {
    try {
      const stat = fs.statSync(file);
      if (stat.size > MAX_SNAPSHOT_FILE_BYTES) {
        snapshot[path.relative(SOURCE_ROOT, file)] =
          `(dosya çok büyük, atlandı: ${stat.size} bayt)`;
        continue;
      }
      snapshot[path.relative(SOURCE_ROOT, file)] = fs.readFileSync(
        file,
        "utf8",
      );
    } catch {
      // Okunamayan dosya diff'ten sessizce dışlanır — restart'ı asla engellemez.
    }
  }
  return snapshot;
}

/** İki metin arasında basit LCS tabanlı satır diff'i (unified benzeri +/-). Büyük dosyalarda güvenlik sınırına düşer. */
function diffLines(oldText: string, newText: string): string[] {
  const oldLines = oldText.split("\n");
  const newLines = newText.split("\n");
  const n = oldLines.length;
  const m = newLines.length;
  if (n * m > MAX_LCS_CELLS) {
    return [
      `~ dosya değişti (${n} → ${m} satır, ayrıntılı diff çok büyük olduğu için atlandı)`,
    ];
  }
  const dp: Uint32Array[] = Array.from(
    { length: n + 1 },
    () => new Uint32Array(m + 1),
  );
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      dp[i][j] =
        oldLines[i] === newLines[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);
    }
  }
  const result: string[] = [];
  let i = 0;
  let j = 0;
  while (i < n && j < m) {
    if (oldLines[i] === newLines[j]) {
      i++;
      j++;
      continue;
    }
    if (dp[i + 1][j] >= dp[i][j + 1]) {
      result.push(`- ${oldLines[i]}`);
      i++;
    } else {
      result.push(`+ ${newLines[j]}`);
      j++;
    }
  }
  while (i < n) {
    result.push(`- ${oldLines[i]}`);
    i++;
  }
  while (j < m) {
    result.push(`+ ${newLines[j]}`);
    j++;
  }
  return result;
}

/** İki anlık görüntü arasındaki farkı AI'ya verilecek düz metin diff'e çevirir. Değişiklik yoksa boş döner. */
export function computeSnapshotDiff(
  oldSnapshot: Record<string, string>,
  newSnapshot: Record<string, string>,
): string {
  const paths = new Set([
    ...Object.keys(oldSnapshot),
    ...Object.keys(newSnapshot),
  ]);
  const blocks: string[] = [];
  for (const file of [...paths].sort()) {
    const before = oldSnapshot[file];
    const after = newSnapshot[file];
    if (before === after) continue;
    if (before === undefined) {
      blocks.push(
        `### YENİ DOSYA: ${file}\n(${after.split("\n").length} satır)`,
      );
      continue;
    }
    if (after === undefined) {
      blocks.push(`### SİLİNDİ: ${file}`);
      continue;
    }
    const lines = diffLines(before, after).slice(0, MAX_PER_FILE_DIFF_LINES);
    blocks.push(`### DEĞİŞTİ: ${file}\n${lines.join("\n")}`);
  }
  let combined = blocks.join("\n\n");
  if (combined.length > MAX_DIFF_CHARS) {
    combined = `${combined.slice(0, MAX_DIFF_CHARS)}\n\n… (diff çok uzun olduğu için kırpıldı)`;
  }
  return combined;
}

async function readSetting(key: string): Promise<unknown> {
  const rows = await db
    .select()
    .from(botSettingsTable)
    .where(eq(botSettingsTable.key, key));
  const raw = rows[0]?.value;
  if (!raw) return undefined;
  try {
    return JSON.parse(raw);
  } catch {
    return undefined;
  }
}

async function writeSetting(key: string, value: unknown): Promise<void> {
  const serialized = JSON.stringify(value);
  await db
    .insert(botSettingsTable)
    .values({ key, value: serialized })
    .onConflictDoUpdate({
      target: botSettingsTable.key,
      set: { value: serialized, updatedAt: new Date() },
    });
}

async function deleteSetting(key: string): Promise<void> {
  await db.delete(botSettingsTable).where(eq(botSettingsTable.key, key));
}

/**
 * !restart çalıştırılırken çağrılır: mevcut anlık görüntüyü alır, önceki
 * anlık görüntüyle karşılaştırır, sonucu ve "nereye rapor gönderilecek"
 * bilgisini DB'ye yazar. Restart'ın kendisini ASLA engellememesi için tüm
 * hata durumlarında sessizce başarısız olur.
 */
export async function prepareRestartChangelog(target: {
  guildId: string | null;
  channelId: string;
  triggeredBy: string;
}): Promise<void> {
  try {
    const previous = await readSetting(SNAPSHOT_KEY);
    // Daha önce hiç anlık görüntü kaydedilmemişse (bu özelliğin ilk kurulumu
    // ya da DB sıfırlanmışsa), "önceki durum" olarak boş {} kullanıp mevcut
    // TÜM dosyaları "yeni eklendi" diye raporlamak YANLIŞ olur — proje zaten
    // vardı, sadece kıyaslanacak bir temel (baseline) yoktu. Bu durumda
    // sessizce yalnızca temel çizgiyi kaydet, sahte bir "her şey yeni" raporu
    // üretme.
    const hasBaseline = isRecord(previous);
    const oldSnapshot = hasBaseline ? (previous as Record<string, string>) : {};
    const newSnapshot = buildSourceSnapshot();
    const diff = hasBaseline
      ? computeSnapshotDiff(oldSnapshot, newSnapshot)
      : "";

    await writeSetting(SNAPSHOT_KEY, newSnapshot);
    if (diff) await writeSetting(DIFF_KEY, diff);
    else await deleteSetting(DIFF_KEY).catch(() => null);

    const pending: PendingChangelog = {
      ...target,
      requestedAt: Date.now(),
      firstRun: !hasBaseline,
    };
    await writeSetting(PENDING_KEY, pending);
  } catch (error) {
    console.error(
      "[Changelog] Restart öncesi anlık görüntü hazırlanamadı (restart yine de devam ediyor):",
      error,
    );
  }
}

const CHANGELOG_SYSTEM_PROMPT = `Sen bir Discord botunun kaynak kodundaki değişiklikleri incelip kullanıcıya (bot sahibine) Türkçe bir "changelog" raporu sunan bir asistansın.
Sana "### DEĞİŞTİ / YENİ DOSYA / SİLİNDİ" başlıklarıyla ayrılmış, "+" eklenen ve "-" silinen satırları gösteren bir kod diff'i verilecek.
Bu diff'e dayanarak, AŞAĞIDAKİ TAM BAŞLIK YAPISINI kullanarak Discord markdown formatında kısa bir rapor yaz:

✨ **Yenilikler**
(yeni komut/özellik/davranış varsa maddeler; yoksa "(Hiç bulunamadı)")

🔧 **İyileştirmeler**
(mevcut bir şeyin geliştirilmesi/değiştirilmesi; yoksa "(Hiç bulunamadı)")

🐛 **Hata Düzeltmeleri**
(bug fix niteliğindeki değişiklikler; yoksa "(Hiç bulunamadı)")

⚙️ **Küçük İç İyileştirmeler**
(refactor, yorum, performans, kod temizliği gibi kullanıcıyı doğrudan etkilemeyen değişiklikler; yoksa "(Hiç bulunamadı)")

Kurallar:
- Sadece diff'te GERÇEKTEN görünen değişikliklere dayan, uydurma.
- Dosya adı veya fonksiyon adı gibi teknik terimleri \`kod\` biçiminde yaz.
- Her madde tek satır, kısa ve net olsun. Gereksiz süsleme yapma.
- Diff çok teknik/anlamsızsa (örn. sadece boşluk/format değişikliği), bunu "Küçük İç İyileştirmeler" altına yaz.
- Başlıkları ve emojileri birebir yukarıdaki gibi koru, ekstra başlık ekleme.`;

const CHANGELOG_MAX_TOKENS = 1024; // Groq'un tek çağrıda izin verdiği tavan (bkz. groq.ts MAX_TOKENS_PER_CALL)
const CHANGELOG_MAX_CONTINUATIONS = 2; // model hâlâ "length" ile kesiliyorsa en fazla bu kadar ek istek at

/**
 * Groq'un yanıtı max_tokens sınırına takılıp cümle ortasında kesmesi
 * ("finish_reason: length") durumunda, kesilen kısmı context'e ekleyip
 * modelden kaldığı yerden devam etmesini ister. Böylece rapor cümle
 * ortasında yarım kalmaz.
 */
export async function generateChangelogReport(diff: string): Promise<string> {
  let full = "";
  let userPrompt = diff;
  for (let attempt = 0; attempt <= CHANGELOG_MAX_CONTINUATIONS; attempt++) {
    const result = await generateWithGroqDetailed(
      CHANGELOG_SYSTEM_PROMPT,
      userPrompt,
      {
        maxTokens: CHANGELOG_MAX_TOKENS,
        temperature: 0.3,
      },
    );
    full += (full && result.content ? "\n" : "") + result.content;
    if (result.finishReason !== "length") return full;
    if (attempt === CHANGELOG_MAX_CONTINUATIONS) break;
    // Devam isteği: modele şu ana kadar ürettiğini gösterip kaldığı yerden
    // sürdürmesini söylüyoruz (yeni bir baştan yazım değil).
    userPrompt = `${diff}\n\n---\nBuraya kadar yazdığın rapor (kesilmiş, aynen böyle devam et, baştan tekrar yazma):\n${full}`;
  }
  console.warn(
    "[Changelog] Groq yanıtı birkaç denemeden sonra hâlâ 'length' ile kesildi, rapor eksik olabilir.",
  );
  return full;
}

export async function takePendingChangelog(): Promise<{
  pending: PendingChangelog;
  diff: string | null;
} | null> {
  const pendingRaw = await readSetting(PENDING_KEY);
  if (
    !isRecord(pendingRaw) ||
    typeof pendingRaw.channelId !== "string" ||
    typeof pendingRaw.triggeredBy !== "string"
  )
    return null;
  const pending: PendingChangelog = {
    guildId: typeof pendingRaw.guildId === "string" ? pendingRaw.guildId : null,
    channelId: pendingRaw.channelId,
    triggeredBy: pendingRaw.triggeredBy,
    requestedAt:
      typeof pendingRaw.requestedAt === "number"
        ? pendingRaw.requestedAt
        : Date.now(),
    firstRun: pendingRaw.firstRun === true,
  };
  const diffRaw = await readSetting(DIFF_KEY);
  const diff =
    typeof diffRaw === "string" && diffRaw.length > 0 ? diffRaw : null;
  // Aynı raporun ikinci bir crash-loop restart'ında tekrar gönderilmemesi için hemen temizle.
  await deleteSetting(PENDING_KEY).catch(() => null);
  await deleteSetting(DIFF_KEY).catch(() => null);
  return { pending, diff };
}

/**
 * Bot ready olduğunda (bkz. index.ts) çağrılır. Bekleyen bir restart raporu
 * varsa, diff'i Groq ile Türkçe bir changelog'a çevirip !restart'ın
 * çalıştırıldığı kanala gönderir. Hiçbir aşamadaki hata botun açılışını
 * engellemez — yalnızca loglanır.
 */
export async function reportPendingChangelog(
  client: Client<true>,
): Promise<void> {
  let entry: Awaited<ReturnType<typeof takePendingChangelog>>;
  try {
    entry = await takePendingChangelog();
  } catch (error) {
    console.error("[Changelog] Bekleyen rapor okunamadı:", error);
    return;
  }
  if (!entry) return;
  const { pending, diff } = entry;

  const channel = await client.channels
    .fetch(pending.channelId)
    .catch(() => null);
  if (!channel?.isTextBased()) return;

  if (!diff) {
    const message = pending.firstRun
      ? "Değişiklik raporu sistemi yeni kuruldu — bu restart, sonraki karşılaştırmalar için temel (baseline) kod görüntüsünü kaydetti. Bir sonraki `!restart`'tan itibaren gerçek değişiklik raporları burada görünecek."
      : "Son restart'tan bu yana kaynak kodda bir değişiklik tespit edilmedi.";
    await channel
      .send({ embeds: [infoEmbed("🔄 Bot Yeniden Başlatıldı", message)] })
      .catch(() => null);
    return;
  }

  let report: string;
  try {
    report = await generateChangelogReport(diff);
    if (!report) throw new Error("Groq boş yanıt döndürdü.");
  } catch (error) {
    console.error(
      "[Changelog] AI raporu oluşturulamadı, ham diff özetiyle devam ediliyor:",
      error,
    );
    const fileCount = diff.split("\n### ").length;
    report = `⚠️ AI özeti oluşturulamadı, ancak kodda değişiklik tespit edildi (yaklaşık ${fileCount} dosya bloğu). Ayrıntı için sunucu loglarına bakabilirsin.`;
  }

  const embed = infoEmbed(
    "🔄 Bot Yeniden Başlatıldı — Değişiklik Raporu",
    report.slice(0, 4_000),
    {
      footer: `İsteyen: ${pending.triggeredBy}`,
    },
  );
  await channel
    .send({ embeds: [embed] })
    .catch((error: unknown) =>
      console.error("[Changelog] Rapor gönderilemedi:", error),
    );
}
","utils/channelSettings.ts":"import { eq } from "drizzle-orm";
import { db } from "../db/index.js";
import { botSettingsTable } from "../db/schema.js";

// ---------------------------------------------------------------------------
// AYAR SİSTEMİ — TEK KANALLI, LOG KATEGORİSİ OLMAYAN AYARLAR
// ---------------------------------------------------------------------------
// utils/logger.ts'teki LOG_CATEGORIES listesi panel.ts'te "Log Kanalları"
// görünümünde her kategori için bir seçim menüsü (action row) açıyor.
// Discord bir mesajda en fazla 5 action row'a izin veriyor ve o görünüm
// zaten (1 geri butonu + 4 kategori menüsü =) 5 satırla dolu — yeni bir
// log kategorisi oraya eklenemez.
//
// Bu yüzden "log" sayılmayan ama yine de sunucuya özel TEK bir kanala
// ihtiyaç duyan ayarlar (ör. ceza duyuruları) burada,
// ayrı bir küçük panel alt-görünümünde ("Diğer Kanallar") yönetiliyor.
// Aynı botSettingsTable'ı kullanıyor, sadece farklı bir key prefix'iyle —
// yeni tabloya gerek yok. İleride benzer "tek kanal" ihtiyaçları çıkarsa
// CHANNEL_SETTINGS listesine eklemek yeterli.
// ---------------------------------------------------------------------------

export type ChannelSettingId = "ceza";

export const CHANNEL_SETTINGS: { id: ChannelSettingId; label: string; emoji: string; ornek: string }[] = [
  { id: "ceza", label: "Ceza Logları", emoji: "🚨", ornek: "ban/kick/warn/unban/nick bildirimleri" },
];

const KEY_PREFIX = "channel_setting:";

// setLogChannel/getLogChannelId'deki aynı önbellek deseni.
const settingCache = new Map<string, string | null>(); // `${guildId}:${id}` -> channelId | null

function cacheKey(guildId: string, id: ChannelSettingId): string {
  return `${guildId}:${id}`;
}

function settingKey(guildId: string, id: ChannelSettingId): string {
  return `${KEY_PREFIX}${guildId}:${id}`;
}

/** Bir sunucunun bir kanal ayarını değiştirir. `channelId: null` verilirse ayar kaldırılır. */
export async function setChannelSetting(guildId: string, id: ChannelSettingId, channelId: string | null): Promise<void> {
  const key = settingKey(guildId, id);
  try {
    if (channelId === null) {
      await db.delete(botSettingsTable).where(eq(botSettingsTable.key, key));
    } else {
      await db
        .insert(botSettingsTable)
        .values({ key, value: channelId })
        .onConflictDoUpdate({
          target: botSettingsTable.key,
          set: { value: channelId, updatedAt: new Date() },
        });
    }
    settingCache.set(cacheKey(guildId, id), channelId);
  } catch (err) {
    console.error(`Kanal ayarı kaydedilirken hata (${id}):`, err);
    throw err;
  }
}

/** Bir sunucunun bir kanal ayarını döner (ayarlı değilse null). */
export async function getChannelSetting(guildId: string, id: ChannelSettingId): Promise<string | null> {
  const ck = cacheKey(guildId, id);
  if (settingCache.has(ck)) return settingCache.get(ck)!;

  try {
    const rows = await db.select().from(botSettingsTable).where(eq(botSettingsTable.key, settingKey(guildId, id))).limit(1);
    const channelId = rows[0]?.value ?? null;
    settingCache.set(ck, channelId);
    return channelId;
  } catch (err) {
    console.error(`Kanal ayarı okunurken hata (${id}):`, err);
    return null;
  }
}

/** Bir sunucudaki tüm ayarların ayarlı kanallarını tek seferde döner (panel görünümü için). */
export async function getAllChannelSettings(guildId: string): Promise<Record<ChannelSettingId, string | null>> {
  const entries = await Promise.all(CHANNEL_SETTINGS.map(async (c) => [c.id, await getChannelSetting(guildId, c.id)] as const));
  return Object.fromEntries(entries) as Record<ChannelSettingId, string | null>;
}
","utils/codeFiles.ts":"// src/utils/codeFiles.ts
// !kod-yaz gibi komutların, modelin döndürdüğü metinden bir ya da birden
// fazla dosya çıkarmasını sağlar.
//
// Model, birden fazla dosya üretmesi gerektiğinde her dosyadan hemen önce
// kendi satırında "===FILE: dosya-adi.uzanti===" başlığı koyacak şekilde
// yönlendirilir (bkz. kod-yaz.ts -> buildSystemPrompt). Bu başlık hiç
// bulunamazsa (tek dosyalık normal cevap), eski davranışla tek bir kod
// bloğu (veya tüm metin) tek dosya olarak kabul edilir.
//
// TRUNCATION (yarıda kesilme) GÜVENLİĞİ:
// utils/openrouter.ts ve utils/gemini.ts artık token limiti yüzünden
// yarıda kesilen (finish_reason: "length"/"MAX_TOKENS") cevapları otomatik
// olarak devam ettirip birleştiriyor. Ama sağlayıcı bu bilgiyi hiç
// döndürmezse ya da devam ettirme son denemede de tamamlanamazsa, elimizde
// kapanmamış (``` ile bitmeyen) bir kod bloğu kalabilir — tam olarak
// "yarım index.html, script kapanmadığı için butonlar çalışmıyor / scroll'da
// çöküyor" hatasının kaynağı budur. Bu yüzden her ayrıştırılan dosya için
// kod bloğunun düzgün kapanıp kapanmadığını da işaretliyoruz; çağıran taraf
// (kod-yaz.ts) bunu görüp kullanıcıyı uyarabilir.

export interface ParsedCodeFile {
  filename: string;
  code: string;
  /** true ise, bu dosyanın kod bloğu kapanmamış/yarıda kesilmiş görünüyor. */
  truncated: boolean;
}

// !kod-analiz / !kod-test / !kod-duzelt üçünün de eklenmiş dosyayı indirme
// mantığı birebir aynıydı (ve üçünde de aynı eksik vardı): fetch() için hiç
// timeout yoktu. Discord CDN yavaşlarsa/takılırsa komut sonsuza kadar
// "işleniyor..." mesajında asılı kalıyordu — hiç hata bile vermiyordu. Ayrıca
// res.ok kontrol edilmiyordu, yani CDN bir hata sayfası dönerse o metin
// sessizce "kod" olarak kabul edilip analiz ediliyordu. Tek yerden, hem
// zaman aşımlı hem hataya karşı sağlam bir indirme fonksiyonu:
const ATTACHMENT_FETCH_TIMEOUT_MS = 15_000;

export async function fetchAttachmentText(url: string): Promise<string> {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), ATTACHMENT_FETCH_TIMEOUT_MS);
  try {
    const res = await fetch(url, { signal: controller.signal });
    if (!res.ok) {
      throw new Error(`Dosya indirilemedi (HTTP ${res.status}).`);
    }
    return await res.text();
  } catch (err) {
    if (err instanceof Error && err.name === "AbortError") {
      throw new Error(`Dosya indirme zaman aşımına uğradı (${ATTACHMENT_FETCH_TIMEOUT_MS / 1000}sn) — tekrar dene.`);
    }
    throw err;
  } finally {
    clearTimeout(timeoutId);
  }
}

const FILE_MARKER_RE = /===\s*FILE:\s*(.+?)\s*===/gi;

interface ExtractedBlock {
  code: string;
  /** Bloğun kapanış ``` işaretiyle düzgün bitip bitmediği. */
  closed: boolean;
}

/** İlk kod bloğunu çıkarır: önce verilen `fence` diline özel, sonra genel, sonra "açık kalmış" blok. */
function extractFirstCodeBlockDetailed(raw: string, fence?: string): ExtractedBlock | null {
  if (fence) {
    const named = raw.match(new RegExp("```(?:" + fence + ")\\n([\\s\\S]*?)```", "i"));
    if (named) return { code: named[1].trim(), closed: true };
  }
  const generic = raw.match(/```[a-zA-Z0-9_+-]*\n([\s\S]*?)```/);
  if (generic) return { code: generic[1].trim(), closed: true };
  // Kapanış ``` bulunamadı: cevap muhtemelen token limiti yüzünden yarıda
  // kesilmiş. Yine de elimizdeki kısmi kodu döndürüyoruz (hiç dosya
  // vermemekten daha iyi) ama "closed: false" ile işaretliyoruz.
  const openOnly = raw.match(/```[a-zA-Z0-9_+-]*\n([\s\S]*)$/);
  if (openOnly) return { code: openOnly[1].trim(), closed: false };
  return null;
}

/** Geriye uyumluluk için: sadece kod metnini döner (kapanış durumunu görmezden gelir). */
export function extractFirstCodeBlock(raw: string, fence?: string): string | null {
  return extractFirstCodeBlockDetailed(raw, fence)?.code ?? null;
}

export interface CodeBlockWithRest {
  /** Kod bloğunun içeriği. */
  code: string;
  /** Kod bloğundan sonra kalan metin (ör. "DEĞİŞİKLİKLER:" / "TEST SENARYOLARI:" bölümü). */
  rest: string;
  /** true ise kod bloğu kapanmamış görünüyor (muhtemelen token limiti yüzünden yarıda kesildi). */
  truncated: boolean;
}

/**
 * !kod-duzelt ve !kod-test gibi "önce kod bloğu, sonra açıklama metni"
 * formatındaki cevapları ayrıştırır. extractFirstCodeBlockDetailed'dan
 * farkı: kod bloğundan SONRAKİ metni de ("rest") ayrıca döndürür.
 */
export function extractCodeBlockWithRest(raw: string, fence?: string): CodeBlockWithRest {
  if (fence) {
    const named = raw.match(new RegExp("```(?:" + fence + ")\\n([\\s\\S]*?)```", "i"));
    if (named) {
      return {
        code: named[1].trim(),
        rest: raw.slice(named.index! + named[0].length).trim(),
        truncated: false,
      };
    }
  }
  const generic = raw.match(/```[a-zA-Z0-9_+-]*\n([\s\S]*?)```/);
  if (generic) {
    return {
      code: generic[1].trim(),
      rest: raw.slice(generic.index! + generic[0].length).trim(),
      truncated: false,
    };
  }
  // Kapanış ``` yok: cevap muhtemelen yarıda kesildi. Devam ettirme
  // mekanizması (bkz. utils/openrouter.ts / utils/gemini.ts) çoğu zaman
  // bunu zaten önler, ama son çare olarak burada da işaretliyoruz.
  const openOnly = raw.match(/```[a-zA-Z0-9_+-]*\n([\s\S]*)$/);
  if (openOnly) {
    return { code: openOnly[1].trim(), rest: "", truncated: true };
  }
  // Hiç kod bloğu yok (fence hiç kullanılmamış) — modelin format
  // hatasıdır, kesilme değil; ham metni olduğu gibi döndürüyoruz.
  return { code: raw.trim(), rest: "", truncated: false };
}

function sanitizeFilename(raw: string, fallbackExt: string): string {
  const cleaned = raw
    .replace(/[`"'*]/g, "")
    .replace(/^[./\\]+/, "")
    .replace(/[\\/]/g, "-") // olası dizin ayraçlarını düzleştir, path traversal'ı engelle
    .trim()
    .slice(0, 80);
  if (!cleaned) return `dosya.${fallbackExt}`;
  return cleaned.includes(".") ? cleaned : `${cleaned}.${fallbackExt}`;
}

/**
 * Modelin döndürdüğü ham metinden bir veya birden fazla dosya çıkarır.
 * "===FILE: ...===" başlığı yoksa tek dosyalık eski davranışa düşer.
 * Her dosyanın `truncated` alanı, kod bloğunun düzgün kapanıp kapanmadığını
 * gösterir (bkz. dosya başındaki not).
 */
export function extractCodeFiles(
  raw: string,
  fallbackFilename: string,
  fallbackFence?: string,
): ParsedCodeFile[] {
  const hits: { filename: string; matchStart: number; contentStart: number }[] = [];
  const re = new RegExp(FILE_MARKER_RE.source, FILE_MARKER_RE.flags);
  let m: RegExpExecArray | null;
  while ((m = re.exec(raw)) !== null) {
    hits.push({ filename: m[1].trim(), matchStart: m.index, contentStart: m.index + m[0].length });
  }

  const fallbackExt = fallbackFilename.includes(".") ? fallbackFilename.split(".").pop()! : "txt";

  if (hits.length === 0) {
    const block = extractFirstCodeBlockDetailed(raw, fallbackFence);
    return block ? [{ filename: fallbackFilename, code: block.code, truncated: !block.closed }] : [];
  }

  const files: ParsedCodeFile[] = [];
  for (let i = 0; i < hits.length; i++) {
    const isLast = i + 1 >= hits.length;
    const segmentEnd = isLast ? raw.length : hits[i + 1].matchStart;
    const segment = raw.slice(hits[i].contentStart, segmentEnd);
    const block = extractFirstCodeBlockDetailed(segment);
    const code = block?.code ?? segment.trim();
    if (!code) continue;
    // Bir sonraki "===FILE:" başlığıyla düzgün bir şekilde bitmiş segmentler
    // (son dosya hariç) zaten model tarafından tamamlanmış demektir; kapanış
    // ``` işareti eksik olsa bile bunu "kesilmiş" saymıyoruz. Yalnızca en
    // sonuncu dosya (metnin gerçekten bittiği yer) için kapanış kontrolü
    // truncation göstergesi olarak anlamlıdır.
    const truncated = isLast ? !(block?.closed ?? true) : false;
    files.push({ filename: sanitizeFilename(hits[i].filename, fallbackExt), code, truncated });
  }

  // Başlıklar bulundu ama hiçbirinin içinde geçerli kod yoksa yine de eski
  // davranışa (tek dosya, tüm metinden çıkarım) düş.
  if (files.length === 0) {
    const block = extractFirstCodeBlockDetailed(raw, fallbackFence);
    return block ? [{ filename: fallbackFilename, code: block.code, truncated: !block.closed }] : [];
  }

  return files;
}
","utils/codeModel.ts":"// src/utils/codeModel.ts
// !kod-yaz / !kod-duzelt / !kod-analiz / !kod-test için ortak model seçici.
//
// Ana model: OpenRouter üzerinden MiniMax M3 (free) — bkz. utils/openrouter.ts
// Yanıt alınamazsa (anahtar yok, rate limit, ağ hatası vb.): Gemini'ye düşer
// — bkz. utils/gemini.ts. Böylece bu dört komut için tek bir davranış
// tanımlanmış olur; hangi modelin cevap verdiği çağıran tarafa (embed'de
// göstermek için) `model` alanıyla döner.
//
// generateCodeText(), buna ek olarak bir "beklenen dil" doğrulaması yapar:
// model, örneğin TypeScript istendiğinde düz JavaScript döndürürse (gerçekte
// yaşanmış bir hata), bu bariz uyumsuzluk yakalanır ve TEK SEFERLİK bir
// düzeltme denemesiyle modele "bu yanlış dildeydi, sadece X dilinde yeniden
// yaz" diyerek tekrar sorulur. Kusursuz bir dil tespiti değildir (imkansız),
// sadece somut/bariz karışıklıkları yakalamayı hedefler — bkz. utils/langs.ts.

import { generateWithGemini } from "./gemini.js";
import { generateWithOpenRouter } from "./openrouter.js";
import { generateWithGroq } from "./groq.js";
import { generateWithAimlapi } from "./aimlapi.js";
import { generateWithPixRouter } from "./pixrouter.js";
import { extractFirstCodeBlock } from "./codeFiles.js";
import { validateLanguage } from "./langs.js";
import { getActiveModel, MODEL_GROUPS } from "./modelSettings.js";

export interface CodeModelResult {
  text: string;
  model: string;
}

// Model etiketi artık sabit değil — !modeller ile hangi OpenRouter/Gemini
// modeli seçiliyse (bkz. utils/modelSettings.ts) embed'de o gösterilir.
function labelFor(group: "openrouter" | "gemini", model: string): string {
  const option = MODEL_GROUPS[group].options.find((opt) => opt.value === model);
  return option?.label ?? model;
}

// "Kod modeli" (!modeller > Kod Araçları menüsü) artık sadece OpenRouter
// modelleri değil, Gemini 3.5/3.6 Flash gibi Gemini modellerini de
// seçenek olarak sunabiliyor — bkz. utils/modelSettings.ts'teki
// "gemini:<model>" önekli seçenekler. groq grubundaki cerebras:/nvidia:
// önek sistemiyle aynı yaklaşım.
const GEMINI_PREFIX = "gemini:";
const GROQ_PREFIX = "groq:";
const NVIDIA_PREFIX = "nvidia:";
const AIMLAPI_PREFIX = "aimlapi:";
const PIXROUTER_PREFIX = "pixrouter:";
function geminiOverrideFor(codeModelValue: string): string | null {
  return codeModelValue.startsWith(GEMINI_PREFIX) ? codeModelValue.slice(GEMINI_PREFIX.length) : null;
}

export interface GenerateForCodeOptions {
  /** PixRouter'a özel: tek kelimelik sınıflandırma gibi hafif istekler için
   * daha kısa token/süre bütçesi kullanmayı sağlar (bkz. detectAutoLangKey). */
  maxTokens?: number;
  pixrouterTotalTimeoutMs?: number;
}

export async function generateForCode(
  systemPrompt: string,
  userPrompt: string,
  opts: GenerateForCodeOptions = {},
): Promise<CodeModelResult> {
  const selected = getActiveModel("openrouter");
  const geminiOverride = geminiOverrideFor(selected);

  if (selected.startsWith(GROQ_PREFIX)) {
    const text = await generateWithGroq(systemPrompt, userPrompt, { model: selected.slice(GROQ_PREFIX.length), maxTokens: 16_384 });
    return { text, model: `${labelFor("openrouter", selected)} (Groq)` };
  }

  if (selected.startsWith(NVIDIA_PREFIX)) {
    try {
      const text = await generateWithGroq(systemPrompt, userPrompt, {
        model: selected,
        maxTokens: 16_384,
      });
      return { text, model: `${labelFor("openrouter", selected)} (NVIDIA)` };
    } catch (err) {
      console.warn("⚠️ Seçili kod modeli (NVIDIA) başarısız, OpenRouter varsayılanına düşülüyor:", err instanceof Error ? err.message : err);
      const fallbackModel = MODEL_GROUPS.openrouter.defaultModel;
      const text = await generateWithOpenRouter(systemPrompt, userPrompt, fallbackModel);
      return { text, model: `${labelFor("openrouter", fallbackModel)} (fallback)` };
    }
  }

  // Seçili "kod modeli" AIML API üzerinden Claude Fable 5.1 ise doğrudan
  // AIML API'yi çağır (bkz. utils/aimlapi.ts, anahtar: AIMLAPI_API). Sadece
  // istek başarısız olursa (anahtar yok, rate limit, ağ hatası vb.)
  // OpenRouter'ın gerçek varsayılan modeline düşülür.
  if (selected.startsWith(AIMLAPI_PREFIX)) {
    try {
      const text = await generateWithAimlapi(systemPrompt, userPrompt, selected.slice(AIMLAPI_PREFIX.length));
      return { text, model: `${labelFor("openrouter", selected)} (AIML API)` };
    } catch (err) {
      console.warn(`⚠️ Seçili kod modeli (AIML API) başarısız, OpenRouter varsayılanına düşülüyor:`, err instanceof Error ? err.message : err);
      const fallbackModel = MODEL_GROUPS.openrouter.defaultModel;
      const text = await generateWithOpenRouter(systemPrompt, userPrompt, fallbackModel);
      return { text, model: `${labelFor("openrouter", fallbackModel)} (fallback)` };
    }
  }

  if (selected.startsWith(PIXROUTER_PREFIX)) {
    try {
      const text = await generateWithPixRouter(systemPrompt, userPrompt, {
        model: selected.slice(PIXROUTER_PREFIX.length),
        maxTokens: opts.maxTokens ?? 16_384,
        totalTimeoutMs: opts.pixrouterTotalTimeoutMs,
      });
      return { text, model: `${labelFor("openrouter", selected)} (PixRouter)` };
    } catch (pixrouterErr) {
      const pixrouterDetail = pixrouterErr instanceof Error ? pixrouterErr.message : String(pixrouterErr);
      console.warn("⚠️ Seçili kod modeli (PixRouter) başarısız, OpenRouter varsayılanına düşülüyor:", pixrouterDetail);
      const fallbackModel = MODEL_GROUPS.openrouter.defaultModel;
      try {
        const text = await generateWithOpenRouter(systemPrompt, userPrompt, fallbackModel);
        return { text, model: `${labelFor("openrouter", fallbackModel)} (fallback)` };
      } catch (fallbackErr) {
        // Fallback de başarısız olursa PixRouter'ın asıl hatasını KAYBETMEDEN
        // ikisini birden fırlat — eskiden burada sadece fallback'in (alakasız
        // görünebilen) hatası kullanıcıya ulaşıyor, PixRouter'ın gerçek sebebi
        // sadece console.warn'da kalıyordu.
        const fallbackDetail = fallbackErr instanceof Error ? fallbackErr.message : String(fallbackErr);
        throw new Error(`PixRouter başarısız (${pixrouterDetail}); OpenRouter fallback de başarısız (${fallbackDetail}).`);
      }
    }
  }

  // Seçili "kod modeli" bir Gemini modeliyse (ör. Gemini 3.6 Flash),
  // OpenRouter'a hiç gitmeden doğrudan Gemini'yi çağır. Sadece Gemini
  // isteğinin kendisi başarısız olursa (kota, ağ hatası vb.) OpenRouter'ın
  // GERÇEK varsayılan modeline (MiniMax M3) düşülür — "gemini:..." değeri
  // asla OpenRouter'a model adı olarak gönderilmez.
  if (geminiOverride) {
    try {
      const text = await generateWithGemini(systemPrompt, userPrompt, geminiOverride);
      return { text, model: labelFor("openrouter", selected) };
    } catch (err) {
      console.warn(`⚠️ Seçili kod modeli (${geminiOverride}) başarısız, OpenRouter varsayılanına düşülüyor:`, err instanceof Error ? err.message : err);
      const fallbackModel = MODEL_GROUPS.openrouter.defaultModel;
      const text = await generateWithOpenRouter(systemPrompt, userPrompt, fallbackModel);
      return { text, model: `${labelFor("openrouter", fallbackModel)} (fallback)` };
    }
  }

  try {
    const text = await generateWithOpenRouter(systemPrompt, userPrompt);
    return { text, model: `${labelFor("openrouter", selected)} (OpenRouter)` };
  } catch (err) {
    console.warn("⚠️ OpenRouter başarısız, Gemini'ye düşülüyor:", err instanceof Error ? err.message : err);
    const text = await generateWithGemini(systemPrompt, userPrompt);
    return { text, model: `${labelFor("gemini", getActiveModel("gemini"))} (fallback)` };
  }
}

export interface CodeGenOptions extends GenerateForCodeOptions {
  /** Kanonik dil anahtarı (bkz. utils/langs.ts LangInfo.key). Verilmezse doğrulama atlanır. */
  expectedLangKey?: string | null;
  /** Hata mesajında/düzeltme isteminde kullanılacak insan-okunur dil adı. */
  expectedLabel?: string;
  /** İlk kod bloğunu bulmayı hızlandırmak için markdown fence adı (ör. "typescript"). */
  fence?: string;
}

export interface CodeGenResult extends CodeModelResult {
  /** Beklenen dille bariz bir uyumsuzluk yakalanıp ikinci bir deneme yapıldıysa true. */
  retried: boolean;
}

/**
 * generateForCode()'u sarar ve isteğe bağlı olarak çıktının beklenen dilde
 * olup olmadığını denetler. Uyumsuzluk bulunursa modele TEK SEFER daha,
 * hatayı açıkça belirten güçlendirilmiş bir istekle sorar. İkinci deneme de
 * uyuşmasa bile onu (en iyi çaba olarak) döner — sonsuz döngüye girilmez.
 */
export async function generateCodeText(
  systemPrompt: string,
  userPrompt: string,
  opts: CodeGenOptions = {},
): Promise<CodeGenResult> {
  const forwardedOpts: GenerateForCodeOptions = { maxTokens: opts.maxTokens, pixrouterTotalTimeoutMs: opts.pixrouterTotalTimeoutMs };
  const first = await generateForCode(systemPrompt, userPrompt, forwardedOpts);

  if (!opts.expectedLangKey) {
    return { ...first, retried: false };
  }

  const firstBlock = extractFirstCodeBlock(first.text, opts.fence);
  if (!firstBlock || validateLanguage(firstBlock, opts.expectedLangKey)) {
    return { ...first, retried: false };
  }

  const label = opts.expectedLabel ?? opts.expectedLangKey;
  console.warn(`⚠️ Üretilen kod beklenen dille (${label}) eşleşmiyor gibi görünüyor, düzeltme denemesi yapılıyor...`);

  const correctionPrompt =
    `${userPrompt}\n\n` +
    `⚠️ ÖNEMLİ DÜZELTME: Önceki cevabın "${label}" dilinde DEĞİLDİ — yanlış dilde ya da yanlış söz dizimiyle ` +
    `yazılmıştı. Bu sefer KESİNLİKLE ve SADECE "${label}" dilinin gerçek söz dizimini kullanarak (gerekiyorsa tip ` +
    `anotasyonları, o dile özgü anahtar kelimeler, standart kütüphane çağrıları vb. dahil) baştan yaz. Başka bir ` +
    `dile ASLA geçme, bu bir hatadır.`;

  const second = await generateForCode(systemPrompt, correctionPrompt, forwardedOpts);
  return { ...second, retried: true };
}
","utils/embeds.ts":"import { EmbedBuilder, ButtonBuilder, ButtonStyle } from "discord.js";
import { EMOJIS } from "./emojis.js";
import { BOT_NAME } from "../config.js";

// ─────────────────────────────────────────────────────────────
// TATLIŞ MUHAFIZ — Görsel Kimlik ("Marin Kitagawa" tema)
// Pembe/fuşya ana marka rengi + duruma göre yardımcı renkler.
// Tüm görsel değişiklikler burada; komut mantığına dokunulmadı.
// ─────────────────────────────────────────────────────────────

export const COLORS = {
  success: 0x3ba55c, // Discord'un standart yeşili — göz yormayan, doğal
  error: 0xed4245,   // Discord'un standart kırmızısı
  warning: 0xfaa61a, // amber — uyarı/dikkat
  info: 0x2b2d31,    // koyu nötr gri — Discord karanlık tema arkaplanına yakın, göze batmıyor
  level: 0xf1c40f,   // sarı — seviye/rozet
  premium: 0xf1c40f, // aynı sade sarı — abartılı altın/parlak degrade yok
  brand: 0x2b2d31,   // nötr, arkaplanla uyumlu
} as const;

/**
 * Her embed'e ortak zaman damgası + sade footer ekler.
 *
 * Referans alınan tasarımda footer'da slogan/pazarlama metni YOK — sadece
 * bot adı. Abartı yerine sadelik "premium" hissi veriyor. extras.footer
 * verilirse (applyExtras her zaman brand()'dan SONRA çalıştığı için) bu
 * varsayılan footer'ın üzerine yazılır.
 */
function brand(embed: EmbedBuilder): EmbedBuilder {
  embed.setFooter({ text: BOT_NAME });
  return embed.setTimestamp();
}

type EmbedExtras = {
  thumbnail?: string;
  image?: string;
  fields?: { name: string; value: string; inline?: boolean }[];
  footer?: string;
};

function applyExtras(embed: EmbedBuilder, extras?: EmbedExtras): EmbedBuilder {
  if (!extras) return embed;
  if (extras.thumbnail) embed.setThumbnail(extras.thumbnail);
  if (extras.image) embed.setImage(extras.image);
  if (extras.fields?.length) embed.addFields(extras.fields);
  if (extras.footer) embed.setFooter({ text: extras.footer });
  return embed;
}

export function successEmbed(title: string, description?: string, extras?: EmbedExtras): EmbedBuilder {
  const embed = new EmbedBuilder().setColor(COLORS.success).setTitle(`${EMOJIS.success} ${title}`);
  if (description) embed.setDescription(description);
  return applyExtras(brand(embed), extras);
}

export function errorEmbed(title: string, description?: string, extras?: EmbedExtras): EmbedBuilder {
  const embed = new EmbedBuilder().setColor(COLORS.error).setTitle(`${EMOJIS.error} ${title}`);
  if (description) embed.setDescription(description);
  return applyExtras(brand(embed), extras);
}

/**
 * Botun KENDİ yetkisi/rolü yetersiz olduğu için bir işlemi
 * gerçekleştiremediği durumlar için ortak kart (ban/kick/timeout/unmute/
 * setnick vb. TÜM mod komutlarında aynı görünüm). "Yetkin Yok" (kullanıcının
 * Discord izni yok) ile KARIŞTIRILMAMALI — bu, botun kendi yetki/hiyerarşi
 * sorunu içindir.
 *
 * botAvatarUrl verilirse köşede thumbnail olarak gösterilir (referans
 * tasarımdaki gibi); footer "{BOT_NAME} • Yetki Hatası" biçiminde sabittir.
 */
export function permissionErrorEmbed(description: string, botAvatarUrl?: string): EmbedBuilder {
  const embed = new EmbedBuilder()
    .setColor(COLORS.error)
    .setTitle(`${EMOJIS.error} Yetkim Yok`)
    .setDescription(description)
    .setFooter({ text: `${BOT_NAME} • Yetki Hatası` })
    .setTimestamp();
  if (botAvatarUrl) embed.setThumbnail(botAvatarUrl);
  return embed;
}

export function warningEmbed(title: string, description?: string, extras?: EmbedExtras): EmbedBuilder {
  const embed = new EmbedBuilder().setColor(COLORS.warning).setTitle(`${EMOJIS.uyari} ${title}`);
  if (description) embed.setDescription(description);
  return applyExtras(brand(embed), extras);
}

export function infoEmbed(title: string, description?: string, extras?: EmbedExtras): EmbedBuilder {
  const embed = new EmbedBuilder().setColor(COLORS.info).setTitle(`${EMOJIS.general} ${title}`);
  if (description) embed.setDescription(description);
  return applyExtras(brand(embed), extras);
}

// Premium/VIP içerikler için sade bir stil — renk farkıyla ayrışıyor,
// başlığa fazladan emoji yığmadan.
export function premiumEmbed(title: string, description?: string, extras?: EmbedExtras): EmbedBuilder {
  const embed = new EmbedBuilder().setColor(COLORS.premium).setTitle(`${EMOJIS.prm1} ${title}`);
  if (description) embed.setDescription(description);
  return applyExtras(brand(embed), extras);
}

/** Tek satırlık "Premium: Aktif/Pasif" gibi durum göstergeleri için. */
export function premiumStatusLine(label: string, active: boolean): string {
  return `${EMOJIS.prm3} **${label}** ${active ? "✅ Aktif" : "❌ Pasif"}`;
}

export function levelEmbed(title: string, description?: string, extras?: EmbedExtras): EmbedBuilder {
  const embed = new EmbedBuilder().setColor(COLORS.level).setTitle(`${EMOJIS.yildirim} ${title}`);
  if (description) embed.setDescription(description);
  return applyExtras(brand(embed), extras);
}

/**
 * Moderasyon işlemleri (ban/kick/timeout/warn vb.) için ortak "case" kartı.
 * Kullanıcı/moderatör/sebep/no her zaman aynı düzende Field olarak görünür,
 * uzun tek paragraflar yerine düzenli bloklar halinde okunur.
 */
export function moderationEmbed(opts: {
  action: string;
  emoji?: string;
  color?: number;
  targetTag: string;
  targetId: string;
  targetAvatar?: string;
  moderatorTag: string;
  reason: string;
  caseId: string;
  duration?: string;
  extraFields?: { name: string; value: string; inline?: boolean }[];
}): EmbedBuilder {
  const embed = new EmbedBuilder()
    .setColor(opts.color ?? COLORS.error)
    .setTitle(`${opts.emoji ?? EMOJIS.mod} ${opts.action}`)
    .addFields(
      { name: "👤 Kullanıcı", value: `${opts.targetTag}\n\`${opts.targetId}\``, inline: true },
      { name: "🛡️ Yetkili", value: opts.moderatorTag, inline: true },
      { name: "🆔 Vaka No", value: `\`${opts.caseId}\``, inline: true },
      { name: "📋 Sebep", value: opts.reason || "Belirtilmedi", inline: false },
    );
  if (opts.duration) embed.addFields({ name: "⏱️ Süre", value: opts.duration, inline: true });
  if (opts.extraFields?.length) embed.addFields(opts.extraFields);
  if (opts.targetAvatar) embed.setThumbnail(opts.targetAvatar);
  return brand(embed);
}

/** Standart buton stilleri — duruma uygun renk seçimini tek yerden garanti eder. */
export const ButtonStyles = {
  primary: (customId: string, label: string, emoji?: string) =>
    new ButtonBuilder().setCustomId(customId).setLabel(label).setStyle(ButtonStyle.Primary).setEmoji(emoji ?? EMOJIS.general),
  success: (customId: string, label: string, emoji?: string) =>
    new ButtonBuilder().setCustomId(customId).setLabel(label).setStyle(ButtonStyle.Success).setEmoji(emoji ?? EMOJIS.success),
  danger: (customId: string, label: string, emoji?: string) =>
    new ButtonBuilder().setCustomId(customId).setLabel(label).setStyle(ButtonStyle.Danger).setEmoji(emoji ?? EMOJIS.error),
  secondary: (customId: string, label: string, emoji?: string) =>
    new ButtonBuilder().setCustomId(customId).setLabel(label).setStyle(ButtonStyle.Secondary).setEmoji(emoji ?? EMOJIS.info),
  premium: (customId: string, label: string, emoji?: string) =>
    new ButtonBuilder().setCustomId(customId).setLabel(label).setStyle(ButtonStyle.Success).setEmoji(emoji ?? EMOJIS.prm2),
};

/** Eski uyumluluk için korunur; artık hiçbir banner görseli eklemez. */
export function brandBanner<T extends EmbedBuilder>(embed: T): T {
  return embed;
}

export function progressBar(current: number, max: number, length = 15): string {
  const filled = Math.min(length, Math.round((current / max) * length));
  const empty = length - filled;
  return `\`${"▰".repeat(filled)}${"▱".repeat(empty)}\` **${Math.round((current / max) * 100)}%**`;
}
