","utils/gemini.ts":"// src/utils/gemini.ts
// Google Gemini 3.6 Flash entegrasyonu (503 -> alt modele otomatik düşer)
// https://ai.google.dev/

import { getActiveModel, MODEL_GROUPS } from "./modelSettings.js";

const GEMINI_BASE_URL = "https://generativelanguage.googleapis.com/v1beta";

// Sırayla denenecek modeller. İlki aşırı yoğunluktan (503 UNAVAILABLE) hata
// verirse otomatik olarak bir sonrakine düşülür.
//
// Bu, KODDAKİ orijinal/varsayılan sıralamadır. !modeller ile owner farklı bir
// Gemini modeli seçerse (bkz. utils/modelSettings.ts), o model bu zincirin
// EN BAŞINA konur (aynı model zaten listedeyse yer değiştirir, listede yoksa
// eklenir) — böylece seçilen model önce denenir ama 503 durumunda yine de bu
// güvenlik ağına (fallback) düşülebilir.
const DEFAULT_MODEL_FALLBACK_CHAIN = [
  "gemini-3.1-pro-preview",
  "gemini-3.6-flash",
  "gemini-3.5-flash-lite",
] as const;

function resolveModelFallbackChain(): string[] {
  const selected = getActiveModel("gemini");
  if (selected === MODEL_GROUPS.gemini.defaultModel) {
    return [...DEFAULT_MODEL_FALLBACK_CHAIN];
  }
  return [selected, ...DEFAULT_MODEL_FALLBACK_CHAIN.filter((m) => m !== selected)];
}

// Gemini 3.x modelleri tek istekte 65.536 token'a kadar çıktı destekliyor.
// Kullanıcı "uzun" bir şey istediğinde burada sınır olmasın diye bu tavanı
// kullanıyoruz; pratik olarak hiçbir kod dosyası bunu doldurmaz.
const MAX_TOKENS_PER_CALL = 65_536;

// Devam mekanizması için güvenlik freni (sonsuz döngüye girmesin diye).
// 65.536 x 5 zaten aşırı büyük bir bütçe, kullanıcı için gerçek bir sınır
// gibi hissettirmez.
const MAX_CONTINUATIONS = 5;

// Tek bir HTTP isteği için zaman aşımı.
const REQUEST_TIMEOUT_MS = 120_000;

type ChatMessage = { role: "user" | "model"; content: string };

class RateLimitError extends Error {
  status = 429;
  constructor(message = "Rate limit / kota (429)") {
    super(message);
  }
}

// Model aşırı yoğun olduğunda (503 UNAVAILABLE) fırlatılır; bunu yakalayıp
// bir alt/farklı modele otomatik geçiyoruz.
class ModelUnavailableError extends Error {
  status = 503;
  constructor(message = "Model şu an aşırı yoğun (503)") {
    super(message);
  }
}

// Key'in bağlı olduğu Google Cloud projesi engellenmiş/reddedilmişse
// (403 PERMISSION_DENIED) fırlatılır; bu key artık kullanılamaz demektir,
// otomatik olarak sıradaki key'e geçiyoruz.
class KeyDeniedError extends Error {
  status = 403;
  constructor(message = "Key reddedildi (403)") {
    super(message);
  }
}

type CallResult = { content: string; finishReason: string | null };

type JsonRecord = Record<string, unknown>;
function isRecord(value: unknown): value is JsonRecord {
  return typeof value === "object" && value !== null;
}

async function callOnce(
  apiKey: string,
  model: string,
  systemPrompt: string,
  messages: ChatMessage[],
  maxTokens: number,
): Promise<CallResult> {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);

  try {
    const res = await fetch(
      `${GEMINI_BASE_URL}/models/${model}:generateContent?key=${apiKey}`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        signal: controller.signal,
        body: JSON.stringify({
          systemInstruction: { parts: [{ text: systemPrompt }] },
          contents: messages.map((m) => ({
            role: m.role,
            parts: [{ text: m.content }],
          })),
          // NOT: temperature/top_p/top_k Gemini 3.x'te deprecated ve
          // yakında 400 hatasına yol açacağı belirtiliyor, o yüzden
          // bilinçli olarak göndermiyoruz.
          generationConfig: {
            maxOutputTokens: maxTokens,
          },
        }),
      },
    );

    clearTimeout(timeoutId);

    if (res.status === 429) throw new RateLimitError();
    if (res.status === 503) throw new ModelUnavailableError();
    if (res.status === 403) {
      const body = await res.text().catch(() => "");
      throw new KeyDeniedError(`Key reddedildi (403): ${body.slice(0, 200)}`);
    }
    if (!res.ok) {
      const body = await res.text().catch(() => "");
      throw new Error(`API hatası (${res.status}): ${body.slice(0, 300)}`);
    }

    const data: unknown = await res.json();
    const candidate = isRecord(data) && Array.isArray(data.candidates) && isRecord(data.candidates[0])
      ? data.candidates[0]
      : undefined;
    const parts = candidate && isRecord(candidate.content) && Array.isArray(candidate.content.parts)
      ? candidate.content.parts
      : [];
    const text = parts
      .filter(isRecord)
      .map((part) => typeof part.text === "string" ? part.text : "")
      .join("");
    const finishReason: string | null = candidate && typeof candidate.finishReason === "string"
      ? candidate.finishReason
      : null;

    return { content: text, finishReason };
  } catch (err) {
    clearTimeout(timeoutId);
    if (err instanceof Error && err.name === "AbortError") {
      throw new Error("Timeout (120sn) — model çok uzun sürdü, tekrar dene.");
    }
    throw err;
  } finally {
    clearTimeout(timeoutId);
  }
}

// Gemini'nin cevabı token limiti yüzünden yarıda kesilirse (MAX_TOKENS),
// kaldığı yerden devam ettirip parçaları birleştirir. Böylece kullanıcı
// "uzun" bir şey isterse dosya yarıda kalmaz.
async function callWithContinuation(
  apiKey: string,
  model: string,
  systemPrompt: string,
  userPrompt: string,
): Promise<string> {
  const messages: ChatMessage[] = [{ role: "user", content: userPrompt }];

  let fullText = "";

  for (let i = 0; i <= MAX_CONTINUATIONS; i++) {
    const { content, finishReason } = await callOnce(
      apiKey,
      model,
      systemPrompt,
      messages,
      MAX_TOKENS_PER_CALL,
    );

    fullText += content;

    if (finishReason !== "MAX_TOKENS") {
      // Model normal şekilde bitirdi (STOP) ya da başka bir sebeple durdu.
      return fullText;
    }

    if (i === MAX_CONTINUATIONS) {
      break;
    }

    messages.push({ role: "model", content });
    messages.push({
      role: "user",
      content:
        "Cevabın token limiti yüzünden yarıda kesildi. Kaldığın YERDEN " +
        "devam et. Baştan tekrar başlama, önceki kısmı tekrar yazma, " +
        "hiçbir açıklama ekleme — sadece kesildiğin noktadan itibaren " +
        "kodun geri kalanını yaz.",
    });
  }

  return fullText;
}

// .env'den okunan anahtarlar arasında otomatik round-robin: her komut
// çağrısı sırayla farklı bir anahtarla başlar (GEMINI_KOD, GEMINI_KOD_2,
// GEMINI_API_KEY_1, ..., GEMINI_API_KEY_7 — toplam 9 key'e kadar).
// Boş/tanımsız olan key'ler otomatik atlanır. Ayrıca model bazında da
// otomatik fallback var:
// - 429 (kota/rate limit)     -> aynı model, sıradaki anahtar
// - 403 (key reddedildi)      -> aynı model, sıradaki anahtar (bu key artık
//                                hiç denenmez)
// - 503 (aşırı yoğun)         -> aynı anahtar(lar), MODEL_FALLBACK_CHAIN'deki
//                                bir sonraki model
const GEMINI_KEY_ENV_NAMES = [
  "GEMINI_KOD",
  "GEMINI_KOD_2",
  "GEMINI_API_KEY_1",
  "GEMINI_API_KEY_2",
  "GEMINI_API_KEY_3",
  "GEMINI_API_KEY_4",
  "GEMINI_API_KEY_5",
  "GEMINI_API_KEY_6",
  "GEMINI_API_KEY_7",
] as const;

let keyRotationIndex = 0;

// Loglarda anahtarı ASLA kısmi olarak bile göstermiyoruz — hangi env
// değişkeninden geldiğini (ör. "GEMINI_API_KEY_3") gösteriyoruz. Anahtarın
// ilk 8 karakteri önceden loga yazılıyordu; bu, host sağlayıcı loglarına
// (Wispbyte/Pterodactyl vb.) sızabilecek gereksiz bir bilgi ifşasıydı —
// env adı hata ayıklama için zaten yeterli ve hiçbir gizli veri içermiyor.
function getConfiguredKeys(): { key: string; label: string }[] {
  return GEMINI_KEY_ENV_NAMES.map((name) => ({ key: process.env[name], label: name })).filter(
    (entry): entry is { key: string; label: string } => Boolean(entry.key && entry.key.trim()),
  );
}

async function generateRequest(
  systemPrompt: string,
  userPrompt: string,
  modelOverride?: string,
): Promise<string> {
  const keys = getConfiguredKeys();

  if (keys.length === 0) {
    throw new Error(
      "GEMINI_API_KEY bulunamadı!\n\n" +
      "1. https://aistudio.google.com/apikey adresine git\n" +
      "2. Bir veya daha fazla API key oluştur\n" +
      "3. .env'ye ekle (en az bir tanesi yeterli, round-robin için birden fazlası önerilir):\n\n" +
      "GEMINI_KOD=your_key_here\n" +
      "GEMINI_KOD_2=your_key_here\n" +
      "GEMINI_API_KEY_1=your_key_here\n" +
      "...\n" +
      "GEMINI_API_KEY_7=your_key_here",
    );
  }

  const startIndex = keyRotationIndex % keys.length;
  keyRotationIndex = (keyRotationIndex + 1) % Number.MAX_SAFE_INTEGER;

  let lastErr: unknown;

  // modelOverride verildiyse (ör. !kod-yaz için "kod modeli" olarak açıkça
  // bir Gemini modeli seçilmişse — bkz. utils/codeModel.ts), o modeli
  // zincirin başına koyup dener; olmazsa yine standart fallback zincirine
  // düşer. Verilmezse eskisi gibi !modeller'daki genel Gemini seçimi kullanılır.
  const chain = modelOverride
    ? [modelOverride, ...DEFAULT_MODEL_FALLBACK_CHAIN.filter((m) => m !== modelOverride)]
    : resolveModelFallbackChain();

  for (const model of chain) {
    for (let offset = 0; offset < keys.length; offset++) {
      const { key, label } = keys[(startIndex + offset) % keys.length];
      try {
        return await callWithContinuation(key, model, systemPrompt, userPrompt);
      } catch (err) {
        lastErr = err;

        if (err instanceof RateLimitError) {
          continue; // aynı modeli sıradaki anahtarla dene
        }
        if (err instanceof KeyDeniedError) {
          console.warn(`⚠️ Gemini key reddedildi (403), sıradaki anahtara geçiliyor: ${label}`);
          continue; // bu key kalıcı olarak reddedilmiş, sıradaki anahtarla dene
        }
        if (err instanceof ModelUnavailableError) {
          break; // bu modelde ısrar etme, fallback zincirinde sıradakine geç
        }
        // Beklenmeyen bir hata (ağ hatası, geçersiz model adı, 400/404 vs.).
        // Eskiden burada hemen `throw err` yapılıyordu; bu da elimizde hâlâ
        // denenmemiş anahtar/model kombinasyonu varken (örn. tek bir anahtarda
        // geçici bir ağ sorunu olduğunda) TÜM isteğin gereksiz yere tamamen
        // başarısız olmasına yol açıyordu — kullanıcı "her denediğimde hata
        // veriyor" şikayetinin asıl kaynağı buydu. Artık diğer anahtarlarla
        // (ve gerekirse diğer modellerle) denemeye devam ediyoruz, sadece
        // hiçbiri işe yaramazsa en sondaki hatayı fırlatıyoruz.
        console.warn(`⚠️ Gemini isteği başarısız (${model}, key ${label}), sıradaki denenecek:`, err);
        continue;
      }
    }
  }

  throw lastErr instanceof Error ? lastErr : new Error("İstek başarısız.");
}

export async function generateWithGemini(
  systemPrompt: string,
  userPrompt: string,
  modelOverride?: string,
): Promise<string> {
  return generateRequest(systemPrompt, userPrompt, modelOverride);
}
","utils/groq.ts":"import { getActiveModel } from "./modelSettings.js";
import { generateWithPixRouter } from "./pixrouter.js";
import { generateWithGemini } from "./gemini.js";

const GROQ_BASE_URL = "https://api.groq.com/openai/v1";
// Varsayılan model artık utils/modelSettings.ts'te (MODEL_GROUPS.groq.defaultModel)
// tek kaynaktan tanımlı; !modeller ile owner değiştirirse getActiveModel("groq")
// bunun yerine geçer.
const MAX_TOKENS_PER_CALL = 16_384;
const REQUEST_TIMEOUT_MS = 60_000;
const GROQ_KEY_ENV_NAMES = ["GROQ_API_KEY_1", "GROQ_API_KEY_2", "GROQ_API_KEY_3"] as const;
const PIXROUTER_PREFIX = "pixrouter:";
const GEMINI_PREFIX = "gemini:";

// ---------------------------------------------------------------------------
// "groq" kategorisi artık tek sağlayıcıya bağlı değil. !modeller menüsünde
// bu kategori altında Groq'un kendi modellerinin YANI SIRA, aynı OpenAI-
// uyumlu /v1/chat/completions şemasını kullanan başka ÜCRETSİZ sağlayıcıların
// modelleri de seçilebiliyor: Cerebras ve NVIDIA NIM (bkz.
// utils/modelSettings.ts MODEL_GROUPS.groq.options).
//
// NOT: Mistral ve SambaNova buradan çıkarıldı — ikisi de artık gerçekten
// ücretsiz bir kullanım sunmuyor (kredi kartı / ücretli plan gerektiriyor).
// GitHub Models de 30 Temmuz 2026'da tamamen kapatıldığı için kaldırılıp
// yerine NVIDIA NIM (integrate.api.nvidia.com) bağlandı.
//
// Bunu ayırt etmek için modelSettings.ts'teki değerler "sağlayıcı:model"
// önekiyle saklanıyor (ör. "cerebras:llama-3.3-70b"). Önek yoksa (Groq'un
// kendi modelleri "openai/gpt-oss-120b" gibi zaten "/" kullanıyor, ":"
// kullanmıyor) doğrudan Groq'a gidiliyor — eski davranış hiç değişmedi.
// ---------------------------------------------------------------------------
const PROVIDER_CONFIGS: Record<string, { baseUrl: string; keyEnvNames: readonly string[]; missingKeyMessage: string }> = {
  cerebras: {
    baseUrl: "https://api.cerebras.ai/v1",
    keyEnvNames: ["CEREBRAS_API_KEY_1", "CEREBRAS_API_KEY_2", "CEREBRAS_API_KEY_3"],
    missingKeyMessage: "CEREBRAS_API_KEY_1 (veya _2/_3) tanımlı değil. Ücretsiz key: https://cloud.cerebras.ai",
  },
  nvidia: {
    baseUrl: "https://integrate.api.nvidia.com/v1",
    keyEnvNames: ["NVIDIA_API_KEY_1", "NVIDIA_API_KEY_2", "NVIDIA_API_KEY_3"],
    missingKeyMessage:
      "NVIDIA_API_KEY_1 (veya _2/_3) tanımlı değil. Ücretsiz: build.nvidia.com'da ücretsiz bir geliştirici hesabıyla giriş yap, bir model kartını aç ve 'Get API Key' ile 'nvapi-' ile başlayan anahtarı al.",
  },
  // OpenRouter — utils/openrouter.ts ile aynı anahtarlar (OP_KOD_1..6).
  // Model adındaki ":free" son eki korunur: resolveProvider() sadece İLK ":"
  // karakterinden böler ("openrouter:z-ai/glm-5.2:free" -> "z-ai/glm-5.2:free").
  openrouter: {
    baseUrl: "https://openrouter.ai/api/v1",
    keyEnvNames: ["OP_KOD_1", "OP_KOD_2", "OP_KOD_3", "OP_KOD_4", "OP_KOD_5", "OP_KOD_6"],
    missingKeyMessage: "OP_KOD_1 (veya OP_KOD_2..6) tanımlı değil. Key: https://openrouter.ai/keys",
  },
};

interface ResolvedProvider {
  baseUrl: string;
  keyEnvNames: readonly string[];
  missingKeyMessage: string;
  model: string;
  label: string;
}

function resolveProvider(rawModel: string): ResolvedProvider {
  const sep = rawModel.indexOf(":");
  if (sep > 0) {
    const prefix = rawModel.slice(0, sep);
    const config = PROVIDER_CONFIGS[prefix];
    if (config) {
      return { ...config, model: rawModel.slice(sep + 1), label: prefix };
    }
  }
  return {
    baseUrl: GROQ_BASE_URL,
    keyEnvNames: GROQ_KEY_ENV_NAMES,
    missingKeyMessage: "GROQ_API_KEY_1, GROQ_API_KEY_2 veya GROQ_API_KEY_3 tanımlı değil.",
    model: rawModel,
    label: "groq",
  };
}

type ChatMessage = { role: "system" | "user" | "assistant"; content: string };
type CallResult = { content: string; finishReason: string | null };
type JsonRecord = Record<string, unknown>;

class HttpError extends Error {
  constructor(readonly status: number, message: string) {
    super(message);
    this.name = "GroqHttpError";
  }
}

function isRecord(value: unknown): value is JsonRecord {
  return typeof value === "object" && value !== null;
}

// Loglarda anahtarın kendisini (kısmi bile olsa) yazmıyoruz — hangi env
// değişkeninden geldiğini gösteriyoruz. Bu, gemini.ts'deki aynı düzeltmeyle
// tutarlı: host sağlayıcı loglarına sızabilecek gereksiz bilgi ifşasını önler.
function getConfiguredKeys(keyEnvNames: readonly string[]): { key: string; label: string }[] {
  return keyEnvNames.map((name) => ({ key: process.env[name]?.trim(), label: name })).filter(
    (entry): entry is { key: string; label: string } => Boolean(entry.key),
  );
}

function errorBody(providerLabel: string, status: number, body: string): HttpError {
  return new HttpError(status, `${providerLabel} API hatası (${status}): ${body.slice(0, 300)}`);
}

async function callOnce(
  baseUrl: string,
  providerLabel: string,
  apiKey: string,
  model: string,
  messages: ChatMessage[],
  maxTokens: number,
  temperature?: number,
): Promise<CallResult> {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
  try {
    const response = await fetch(`${baseUrl}/chat/completions`, {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${apiKey}` },
      signal: controller.signal,
      body: JSON.stringify({
        model,
        messages,
        max_tokens: maxTokens,
        ...(temperature === undefined ? {} : { temperature }),
      }),
    });
    if (!response.ok) throw errorBody(providerLabel, response.status, await response.text().catch(() => ""));

    const data: unknown = await response.json();
    if (!isRecord(data) || !Array.isArray(data.choices)) return { content: "", finishReason: null };
    const first = data.choices[0];
    if (!isRecord(first)) return { content: "", finishReason: null };
    const message = isRecord(first.message) ? first.message : undefined;
    return {
      content: message && typeof message.content === "string" ? message.content : "",
      finishReason: typeof first.finish_reason === "string" ? first.finish_reason : null,
    };
  } catch (error) {
    if (error instanceof Error && error.name === "AbortError") {
      throw new Error(`${providerLabel} isteği zaman aşımına uğradı (60 sn).`);
    }
    throw error;
  } finally {
    clearTimeout(timeoutId);
  }
}

let keyRotationIndex = 0;

export interface GroqGenerateOptions {
  model?: string;
  maxTokens?: number;
  temperature?: number;
}

export async function generateWithGroq(
  systemPrompt: string,
  userPrompt: string,
  options: GroqGenerateOptions = {},
): Promise<string> {
  const result = await generateWithGroqDetailed(systemPrompt, userPrompt, options);
  return result.content;
}

/**
 * generateWithGroq ile aynı, ancak finishReason'ı da döner — çağıran taraf
 * yanıtın "length" (max_tokens'a takılıp yarıda kesilme) sebebiyle mi
 * bittiğini anlayabilsin diye.
 *
 * NOT: Model adı "provider:model" öneki taşıyorsa (ör. "cerebras:llama-3.3-70b")
 * bu istek Groq'a değil, o sağlayıcıya (aynı OpenAI-uyumlu şema ile) gider —
 * bkz. resolveProvider() ve PROVIDER_CONFIGS yukarıda.
 */
export async function generateWithGroqDetailed(
  systemPrompt: string,
  userPrompt: string,
  options: GroqGenerateOptions = {},
): Promise<CallResult> {
  const selectedModel = options.model ?? getActiveModel("groq");
  // !modeller > Sohbet, Fikir & AFK Cevap içinde PixRouter seçildiyse aynı
  // çağrı sözleşmesini koruyarak PixRouter util’ine devret.
  if (selectedModel.startsWith(PIXROUTER_PREFIX)) {
    const result = await generateWithPixRouter(systemPrompt, userPrompt, {
      model: selectedModel.slice(PIXROUTER_PREFIX.length),
      maxTokens: options.maxTokens,
      temperature: options.temperature,
    });
    return { content: result.content.trim(), finishReason: "stop" };
  }
  if (selectedModel.startsWith(GEMINI_PREFIX)) {
    const content = await generateWithGemini(
      systemPrompt,
      userPrompt,
      selectedModel.slice(GEMINI_PREFIX.length),
    );
    return { content: content.trim(), finishReason: "stop" };
  }
  const provider = resolveProvider(selectedModel);
  const keys = getConfiguredKeys(provider.keyEnvNames);
  if (keys.length === 0) {
    throw new Error(provider.missingKeyMessage);
  }
  const startIndex = keyRotationIndex++ % keys.length;
  const messages: ChatMessage[] = [
    { role: "system", content: systemPrompt },
    { role: "user", content: userPrompt },
  ];
  let lastError: unknown;
  for (let offset = 0; offset < keys.length; offset++) {
    const { key, label } = keys[(startIndex + offset) % keys.length];
    try {
      const result = await callOnce(
        provider.baseUrl,
        provider.label,
        key,
        provider.model,
        messages,
        Math.min(Math.max(options.maxTokens ?? MAX_TOKENS_PER_CALL, 1), MAX_TOKENS_PER_CALL),
        options.temperature,
      );
      return { content: result.content.trim(), finishReason: result.finishReason };
    } catch (error) {
      lastError = error;
      if (error instanceof HttpError && ![401, 403, 429, 500, 502, 503, 504].includes(error.status)) throw error;
      console.warn(`${provider.label} anahtarıyla istek başarısız (${label}); sıradaki deneniyor.`);
    }
  }
  throw lastError instanceof Error ? lastError : new Error(`${provider.label} isteği başarısız oldu.`);
}

export async function summarizeWithGroq(text: string): Promise<string> {
  return generateWithGroq(
    "Türkçe metinleri anlamı korunacak şekilde kısa ve maddeli özetleyen bir asistansın. Yalnızca özeti döndür.",
    text,
    { maxTokens: 700 },
  );
}

export async function answerWithGroq(question: string): Promise<string> {
  return generateWithGroq(
    "Türkçe, kısa ve doğru cevaplar veren bir Discord asistanısın. Emin olmadığın bilgiyi uydurma.",
    question,
    { maxTokens: 700 },
  );
}
