","utils/manus.ts":"// Manus AI API entegrasyonu (!agent komutu için).
//
// Akış: task.create ile bir görev başlatılır (asenkron çalışır) -> task.detail
// ile durum ("running" | "stopped" | "waiting" | "error") periyodik olarak
// kontrol edilir -> tamamlandığında task.listMessages ile son assistant
// mesajı okunup kullanıcıya dönülür.
//
// API anahtarı .env üzerinden MANUS_API_KEY değişkeninden okunur, koda asla
// yazılmaz.
//
// SAĞLAMLIK NOTLARI (bkz. commit geçmişi): ilk sürümde (a) geçici ağ/429/5xx
// hatalarında hiç yeniden deneme yoktu, (b) 5 dakika boyunca kullanıcıya HİÇ
// ilerleme bilgisi gitmiyordu (bu yüzden "hiç cevap vermiyor" gibi
// görünüyordu), (c) aynı kullanıcı komutu üst üste yazarsa paralel görevler
// birbirine karışabiliyordu. Üçü de burada ve agent.ts'te ele alındı.

const MANUS_BASE_URL = "https://api.manus.ai/v2";
const POLL_INTERVAL_MS = 4_000;
const REQUEST_TIMEOUT_MS = 20_000;

// Manus görevleri araştırma/otomasyon adımlarına göre 4 dakikadan uzun sürebilir.
// Varsayılan sınır 30 dakikadır; istenirse .env üzerinden değiştirilebilir.
// MANUS_MAX_WAIT_MS=0 verilirse görev tamamlanana kadar beklenir (API bağlantısı
// koptuğunda tek isteğin zaman aşımı yine REQUEST_TIMEOUT_MS ile sınırlıdır).
const DEFAULT_MAX_WAIT_MS = 30 * 60_000;
const MAX_WAIT_MS = (() => {
  const raw = process.env.MANUS_MAX_WAIT_MS?.trim();
  if (raw === "0") return 0;
  const parsed = raw ? Number(raw) : NaN;
  return Number.isFinite(parsed) && parsed >= 60_000 ? parsed : DEFAULT_MAX_WAIT_MS;
})();
const MAX_RETRIES = 3;

export class ManusError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ManusError";
  }
}

function getApiKey(): string {
  const key = process.env.MANUS_API_KEY?.trim();
  if (!key) {
    throw new ManusError(
      "MANUS_API_KEY tanımlı değil. Botu çalıştıran ortamda .env dosyasına `MANUS_API_KEY=...` ekleyip yeniden başlat.",
    );
  }
  return key;
}

function sleep(ms: number): Promise<void> {
  return new Promise((r) => setTimeout(r, ms));
}

// Geçici sayılan (yeniden denenebilir) HTTP durumları: rate limit + sunucu
// tarafı hatalar. 4xx (400/401/403/404 vb.) yeniden denenmez — bunlar
// isteğin kendisiyle ilgili kalıcı sorunlardır.
function isRetryableStatus(status: number): boolean {
  return status === 429 || status >= 500;
}

class RetryableManusError extends ManusError {}

/**
 * Tek bir Manus API isteği atar. Ağ hatası / timeout / 429 / 5xx durumunda
 * üstel geri çekilmeyle (exponential backoff) MAX_RETRIES kez tekrar dener.
 * Kalıcı hatalarda (400/401/403/404 vb.) hemen ManusError fırlatır.
 */
async function manusFetch(path: string, init: RequestInit): Promise<any> {
  let lastErr: Error = new ManusError("Manus API isteği başarısız oldu.");

  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);

    try {
      const res = await fetch(`${MANUS_BASE_URL}${path}`, {
        ...init,
        signal: controller.signal,
        headers: {
          "Content-Type": "application/json",
          "x-manus-api-key": getApiKey(),
          ...(init.headers ?? {}),
        },
      });
      clearTimeout(timeoutId);

      const data = await res.json().catch(() => null);

      if (!res.ok || !data || data.ok === false) {
        const msg = data?.error?.message || `HTTP ${res.status}`;
        if (isRetryableStatus(res.status)) {
          throw new RetryableManusError(`Manus API hatası: ${msg}`);
        }
        // Kalıcı hata — burada döngüden tamamen çıkıyoruz.
        throw new ManusError(`Manus API hatası: ${msg}`);
      }

      return data;
    } catch (err: unknown) {
      clearTimeout(timeoutId);

      if (err instanceof ManusError && !(err instanceof RetryableManusError)) {
        throw err; // Kalıcı hata, yeniden denemeden çık.
      }

      const isAbort = err instanceof Error && err.name === "AbortError";
      lastErr = isAbort
        ? new ManusError("Manus API isteği zaman aşımına uğradı.")
        : err instanceof Error
          ? err
          : new ManusError(String(err));

      if (attempt >= MAX_RETRIES) throw lastErr;
      await sleep(Math.min(2_000 * 2 ** attempt, 10_000));
    }
  }

  throw lastErr;
}

interface CreateTaskResult {
  taskId: string;
  taskUrl?: string;
}

// 🆕 YENİ ÖZELLİK: Discord mesajına eklenen dosyaları Manus'a gönderme.
//
// Manus task.create, message.content içinde metnin yanına "file" tipinde
// content-part kabul ediyor (bkz. Manus API v2 docs — ContentPart.File):
//   - file_url: Manus'un doğrudan indireceği herkese açık bir URL (≤ 20 MB)
//   - file_id : file.upload ile önceden yüklenmiş bir dosyanın ID'si (≤ 512 MB)
// Discord CDN ekleri zaten public https URL'ler olduğu için ≤20MB'lık
// dosyalarda file_url ile direkt gönderiliyor, daha büyük dosyalarda ise
// file.upload akışıyla önce Manus'a yükleniyor.
const INLINE_FILE_URL_MAX_BYTES = 20 * 1024 * 1024; // Manus file_url sınırı
export const MAX_UPLOADABLE_ATTACHMENT_BYTES = 512 * 1024 * 1024; // file.upload sınırı

export interface TaskAttachmentInput {
  url: string;
  filename: string;
  contentType?: string;
  sizeBytes?: number;
}

interface FileContentPart {
  type: "file";
  file_id?: string;
  file_url?: string;
  filename?: string;
  mime_type?: string;
}

/**
 * Büyük dosyaları (>20MB) Manus'a file.upload akışıyla yükler: önce bir
 * presigned upload_url alınır, dosya Discord CDN'den indirilip bu URL'e PUT
 * edilir, sonra file.id döner. 20MB altındaki dosyalar için bu adıma hiç
 * gerek yok — file_url ile doğrudan gönderilir (aşağıdaki buildFileContentPart).
 */
async function uploadLargeFileToManus(attachment: TaskAttachmentInput): Promise<string> {
  const created = await manusFetch("/file.upload", {
    method: "POST",
    body: JSON.stringify({ filename: attachment.filename }),
  });
  const fileId = created?.file?.id;
  const uploadUrl = created?.upload_url;
  if (typeof fileId !== "string" || !fileId || typeof uploadUrl !== "string" || !uploadUrl) {
    throw new ManusError(`Manus dosya yükleme kaydı oluşturulamadı: ${attachment.filename}`);
  }

  // Discord CDN'den dosyayı indirip Manus'un presigned S3 URL'sine PUT ediyoruz.
  // upload_url 3 dakika içinde dolduğu için bu adım hemen ardından yapılır.
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 60_000);
  try {
    const sourceRes = await fetch(attachment.url, { signal: controller.signal });
    if (!sourceRes.ok) {
      throw new ManusError(`Discord ekindeki dosya indirilemedi: ${attachment.filename}`);
    }
    const bytes = await sourceRes.arrayBuffer();
    const putRes = await fetch(uploadUrl, {
      method: "PUT",
      body: bytes,
      signal: controller.signal,
      headers: attachment.contentType ? { "Content-Type": attachment.contentType } : undefined,
    });
    if (!putRes.ok) {
      throw new ManusError(`Dosya Manus'a yüklenemedi (HTTP ${putRes.status}): ${attachment.filename}`);
    }
  } finally {
    clearTimeout(timeoutId);
  }

  return fileId;
}

/** ≤20MB dosyalar için file_url content-part'ı doğrudan oluşturur (yükleme gerekmez). */
function buildInlineFileContentPart(attachment: TaskAttachmentInput): FileContentPart {
  return {
    type: "file",
    file_url: attachment.url,
    filename: attachment.filename,
    ...(attachment.contentType ? { mime_type: attachment.contentType } : {}),
  };
}

async function buildFileContentParts(attachments: TaskAttachmentInput[]): Promise<FileContentPart[]> {
  const parts: FileContentPart[] = [];
  for (const attachment of attachments) {
    const knownTooBig =
      typeof attachment.sizeBytes === "number" && attachment.sizeBytes > INLINE_FILE_URL_MAX_BYTES;
    if (!knownTooBig) {
      parts.push(buildInlineFileContentPart(attachment));
      continue;
    }
    // >20MB: file_url Manus tarafında reddedilir, file.upload akışı gerekli.
    const fileId = await uploadLargeFileToManus(attachment);
    parts.push({ type: "file", file_id: fileId, filename: attachment.filename });
  }
  return parts;
}

async function createTask(prompt: string, attachments: TaskAttachmentInput[] = []): Promise<CreateTaskResult> {
  const fileParts = attachments.length > 0 ? await buildFileContentParts(attachments) : [];
  const content =
    fileParts.length > 0 ? [{ type: "text", text: prompt }, ...fileParts] : prompt;

  const data = await manusFetch("/task.create", {
    method: "POST",
    body: JSON.stringify({
      message: { content },
      hide_in_task_list: true,
    }),
  });
  // 🛠️ BUG FIX: task_id doğrulanmıyordu. API beklenmedik/boş bir cevap
  // dönerse (data.task_id eksik), bu sessizce sonraki her istekte
  // "task_id=undefined" olarak geçiyor ve anlaşılmaz 4xx hatalarına yol
  // açıyordu. Artık burada net bir hata fırlatılıyor.
  if (typeof data.task_id !== "string" || !data.task_id) {
    throw new ManusError("Manus görevi oluşturuldu ama API geçerli bir task_id döndürmedi.");
  }
  let taskUrl: string | undefined;
  if (typeof data.task_url === "string") {
    try {
      const parsed = new URL(data.task_url);
      if (parsed.protocol === "https:") taskUrl = parsed.toString();
    } catch {
      // Geçersiz/eksik URL owner DM'ine aktarılmaz.
    }
  }
  // URL yalnızca owner-only callback'e verilir; kanal çıktısına taşınmaz.
  return { taskId: data.task_id, taskUrl };
}

type TaskStatus = "running" | "stopped" | "waiting" | "error";

interface TaskProgress {
  status: TaskStatus;
  brief?: string;
  description?: string;
  waitingDescription?: string;
  waitingType?: string;
}

async function getTaskProgress(taskId: string): Promise<TaskProgress> {
  // Manus dokümantasyonu ilerleme ve durum için task.listMessages içindeki
  // status_update event'lerini polling etmeyi öneriyor. task.detail yalnızca
  // özet metadata verir ve ara ilerleme bilgisini taşımaz.
  const data = await manusFetch(
    `/task.listMessages?task_id=${encodeURIComponent(taskId)}&order=desc&limit=50`,
    { method: "GET" },
  );
  const messages: any[] = Array.isArray(data.messages) ? data.messages : [];
  const statusEvent = messages.find((msg) => msg?.status_update?.agent_status);
  if (statusEvent) {
    const update = statusEvent.status_update;
    return {
      status: update.agent_status as TaskStatus,
      brief: update.brief ? String(update.brief) : undefined,
      description: update.description ? String(update.description) : undefined,
      waitingDescription: update.status_detail?.waiting_description
        ? String(update.status_detail.waiting_description)
        : undefined,
      waitingType: update.status_detail?.waiting_for_event_type
        ? String(update.status_detail.waiting_for_event_type)
        : undefined,
    };
  }

  // İlk birkaç saniyede status_update gelmezse eski durum endpoint'ini
  // fallback olarak kullan; bu durumda da görev yanlışlıkla hata sayılmaz.
  const detail = await manusFetch(`/task.detail?task_id=${encodeURIComponent(taskId)}`, { method: "GET" });
  return { status: (detail.task?.status ?? "error") as TaskStatus };
}

export interface ManusAttachment {
  filename: string;
  url: string;
  contentType?: string;
}

interface AssistantMessageResult {
  content: string;
  attachments: ManusAttachment[];
}

async function getLastAssistantMessage(taskId: string): Promise<AssistantMessageResult | null> {
  const data = await manusFetch(
    `/task.listMessages?task_id=${encodeURIComponent(taskId)}&order=desc&limit=20`,
    { method: "GET" },
  );
  const messages: any[] = Array.isArray(data.messages) ? data.messages : [];
  for (const msg of messages) {
    if (msg?.assistant_message?.content || msg?.assistant_message?.attachments?.length) {
      const rawAttachments: any[] = Array.isArray(msg.assistant_message.attachments)
        ? msg.assistant_message.attachments
        : [];
      const attachments: ManusAttachment[] = rawAttachments
        .filter((a) => a?.url)
        .map((a) => ({
          filename: String(a.filename || "dosya"),
          url: String(a.url),
          contentType: a.content_type ? String(a.content_type) : undefined,
        }));
      return { content: String(msg.assistant_message.content || ""), attachments };
    }
  }
  return null;
}

export interface RunAgentResult {
  answer: string;
  attachments: ManusAttachment[];
}

/**
 * Bir Manus görevi oluşturur, tamamlanmasını bekler ve son asistan cevabını
 * döner. Görev "waiting" durumuna geçerse (ör. ek onay/soru gerekiyorsa)
 * bunu da bir hata olarak işaretleriz — Discord komutu tek seferlik bir
 * cevap beklediği için interaktif akışı desteklemiyoruz.
 *
 * onProgress: her poll turunda (durum "running" iken) çağrılır — çağıran
 * taraf bunu kullanarak kullanıcıya "hâlâ çalışıyor" gibi bir ilerleme
 * mesajı gösterebilir (ölü/asılı kalmış gibi görünmesin diye).
 */
export const MAX_DOWNLOADABLE_ATTACHMENT_BYTES = 8 * 1024 * 1024; // Discord'un varsayılan dosya limiti

/**
 * Manus'un döndürdüğü bir dosya URL'sini indirip Buffer olarak döner.
 * Dosya MAX_DOWNLOADABLE_ATTACHMENT_BYTES'tan büyükse veya indirme
 * başarısız olursa null döner — çağıran taraf bunu "eklenemedi" olarak
 * ele almalı, tüm görevi düşürmemeli.
 */
export async function downloadManusAttachment(attachment: ManusAttachment): Promise<Buffer | null> {
  // 🛠️ BUG FIX: eskiden attachment.url hiç doğrulanmadan fetch ediliyordu.
  // Metin içi linkler için zaten var olan https-only kontrolü (safeHttpsUrl)
  // dosya eklerine uygulanmıyordu — beklenmedik/bozuk bir API yanıtı iç ağ
  // adresine veya file:// gibi şemalara işaret ederse SSRF riski doğuruyordu.
  let parsed: URL;
  try {
    parsed = new URL(attachment.url);
  } catch {
    return null;
  }
  if (parsed.protocol !== "https:") return null;

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
  try {
    const res = await fetch(attachment.url, { signal: controller.signal });
    if (!res.ok) return null;

    const contentLength = res.headers.get("content-length");
    if (contentLength && Number(contentLength) > MAX_DOWNLOADABLE_ATTACHMENT_BYTES) return null;

    const arrayBuffer = await res.arrayBuffer();
    if (arrayBuffer.byteLength > MAX_DOWNLOADABLE_ATTACHMENT_BYTES) return null;

    return Buffer.from(arrayBuffer);
  } catch {
    return null;
  } finally {
    clearTimeout(timeoutId);
  }
}

export async function runAgentTask(
  prompt: string,
  onProgress?: (elapsedMs: number, progress?: string) => void,
  onWaiting?: (detail: string, type?: string) => void | Promise<void>,
  onTaskCreated?: (taskUrl: string) => void | Promise<void>,
  attachments: TaskAttachmentInput[] = [],
): Promise<RunAgentResult> {
  const { taskId, taskUrl } = await createTask(prompt, attachments);
  if (taskUrl) await onTaskCreated?.(taskUrl);

  const startedAt = Date.now();
  const hasDeadline = MAX_WAIT_MS > 0;
  let lastWaitingNotice = "";
  // 🛠️ BUG FIX: "waiting" durumunda geçen süre deadline'dan düşülür. Eskiden
  // owner'ın Manus sohbetinde onay vermesini beklerken de sayaç işliyordu;
  // owner DM'i geç görürse görev GERÇEKTEN çalışmıyor olmasına rağmen "zaman
  // aşımına uğradı" hatasıyla düşüyordu. Artık yalnızca aktif çalışma süresi
  // (running) deadline'a sayılıyor.
  let waitingAccumulatedMs = 0;
  while (!hasDeadline || Date.now() - startedAt - waitingAccumulatedMs < MAX_WAIT_MS) {
    await sleep(POLL_INTERVAL_MS);
    const elapsed = Date.now() - startedAt - waitingAccumulatedMs;

    let progress: TaskProgress;
    try {
      progress = await getTaskProgress(taskId);
    } catch (err) {
      // task.detail geçici olarak başarısız oldu (retry'lar tükendi) —
      // görevi tamamen iptal etmek yerine bir sonraki tur tekrar deneriz,
      // MAX_WAIT_MS dolana kadar. Tek bir kontrol hatası tüm görevi
      // düşürmesin.
      onProgress?.(elapsed, "Manus API durum kontrolü geçici olarak başarısız oldu; yeniden denenecek.");
      continue;
    }

    const status = progress.status;
    const progressText = progress.brief || progress.description;
    if (status === "error") {
      throw new ManusError("Manus görevi bir hatayla sonuçlandı.");
    }
    if (status === "waiting") {
      waitingAccumulatedMs += POLL_INTERVAL_MS;
      const waitingDetail = progress.waitingDescription || progress.description || "Manus kullanıcı onayı veya ek bilgi bekliyor.";
      const waitingKey = `${progress.waitingType || "waiting"}:${waitingDetail}`;
      if (waitingKey !== lastWaitingNotice) {
        lastWaitingNotice = waitingKey;
        await onWaiting?.(waitingDetail, progress.waitingType);
      }
      onProgress?.(elapsed, `Onay/bilgi bekleniyor: ${waitingDetail}`);
      continue;
    }
    if (status === "stopped") {
      const result = await getLastAssistantMessage(taskId);
      if (!result || (!result.content && result.attachments.length === 0)) {
        throw new ManusError("Manus görevi tamamlandı ama bir cevap bulunamadı.");
      }
      return { answer: result.content, attachments: result.attachments };
    }

    // "running" ise son status_update özetini de Discord'a yansıt.
    onProgress?.(elapsed, progressText);
  }

  throw new ManusError(
    `Manus görevi zaman aşımına uğradı (${Math.round(MAX_WAIT_MS / 60_000)} dakika). ` +
      "Daha uzun görevler için MANUS_MAX_WAIT_MS değerini artırabilir veya 0 yapabilirsin.",
  );
}
","utils/mentionai.ts":"import fs from "node:fs";
import path from "node:path";
import { db } from "../db/index.js";
import { botSettingsTable } from "../db/schema.js";
import { eq } from "drizzle-orm";
import { PixRouterError } from "./pixrouter.js";
import { generateWithGroq } from "./groq.js";
import { getActiveModel } from "./modelSettings.js";

const SETTING_PREFIX = "mentionai:";
const CHANNEL_SETTING_PREFIX = "mentionai:channel:";
const MODEL_SETTING_KEY = "mentionai:model";
const IMAGE_MODEL_SETTING_KEY = "mentionai:image-model";
const RULES_SETTING_KEY = "mentionai:rules";
const DEFAULT_MODEL = "gpt-4o";
const DEFAULT_IMAGE_MODEL = "veo-3.1-fast-generate-preview";
const IMAGE_GENERATIONS_URL = "https://pixrouter.com/v1/images/generations";
const MAX_QUERY_CHARS = 180;
const MAX_SEARCH_RESULTS = 5;
const MAX_SEARCH_CONTEXT_CHARS = 6_000;
const MAX_MEMORY_MESSAGES = 12; // 6 tur (user+assistant)
const MAX_DISCORD_MESSAGE_LENGTH = 1_900;
// Diğer JSON depolarla aynı kök: process.cwd()/data (Pterodactyl'da genelde /home/container/data)
const MEMORY_FILE = path.resolve(process.cwd(), "data/mentionai-memory.json");

const SYSTEM_PROMPT = `YETENEKLER:
- Gerektiğinde arka planda otomatik olarak web (DuckDuckGo) araması yapılır ve sonuçlar sana "ARAMA SONUÇLARI" bölümünde verilir; bu bilgiyi kendi bilgin gibi kullanabilirsin. Arama yapılmadıysa veya sonuç boşsa, güncel bilgiye erişimin olmadığını söyle.
- Kullanıcının gönderdiği görselleri görebiliyorsun.
- "SON KONUŞMA GEÇMİŞİ" varsa önceki mesajları hatırla; isim, tercih ve bağlamı koru. Kullanıcı "az önce ne demiştim" derse geçmişe bak.
- doğal cevap ver; geçmişi gereksiz yere tekrar etme.`;

async function getStoredRules(): Promise<string[]> {
  const rows = await db
    .select()
    .from(botSettingsTable)
    .where(eq(botSettingsTable.key, RULES_SETTING_KEY));
  const row = rows[0];
  if (!row?.value) return [];
  try {
    const parsed: unknown = JSON.parse(row.value);
    return Array.isArray(parsed)
      ? parsed
          .filter((rule): rule is string => typeof rule === "string")
          .slice(0, 20)
      : [];
  } catch {
    return [];
  }
}

async function saveStoredRules(rules: string[]): Promise<void> {
  await db
    .insert(botSettingsTable)
    .values({
      key: RULES_SETTING_KEY,
      value: JSON.stringify(rules),
      updatedAt: new Date(),
    })
    .onConflictDoUpdate({
      target: botSettingsTable.key,
      set: { value: JSON.stringify(rules), updatedAt: new Date() },
    });
}

export async function getMentionAiRules(): Promise<string[]> {
  return getStoredRules();
}

export async function addMentionAiRule(rule: string): Promise<string[]> {
  const normalized = rule.trim().slice(0, 500);
  if (!normalized) return getStoredRules();
  const rules = await getStoredRules();
  if (rules.length >= 20) return rules;
  if (
    !rules.some(
      (item) =>
        item.toLocaleLowerCase("tr-TR") ===
        normalized.toLocaleLowerCase("tr-TR"),
    )
  ) {
    rules.push(normalized);
    await saveStoredRules(rules);
  }
  return rules;
}

export async function removeMentionAiRule(
  rule: string,
): Promise<{ removed: boolean; rules: string[] }> {
  const normalized = rule.trim().toLocaleLowerCase("tr-TR");
  const previous = await getStoredRules();
  const rules = previous.filter(
    (item) => item.toLocaleLowerCase("tr-TR") !== normalized,
  );
  if (rules.length !== previous.length) await saveStoredRules(rules);
  return { removed: rules.length !== previous.length, rules };
}

async function getSystemPrompt(): Promise<string> {
  const rules = await getStoredRules();
  if (rules.length === 0) return SYSTEM_PROMPT;
  return `${SYSTEM_PROMPT}\n\nOWNER TARAFINDAN EKLENEN EK KURALLAR:\n${rules.map((rule, index) => `${index + 1}. ${rule}`).join("\n")}`;
}

type SearchResult = { title: string; url: string; snippet: string };
type MemoryMessage = {
  role: "user" | "assistant";
  content: string;
  timestamp: string;
};
type MemoryStore = Record<string, MemoryMessage[]>;
export type MentionAiCodeFile = {
  name: string;
  content: string;
  isTypeScript?: boolean;
};

function settingKey(guildId: string): string {
  return `${SETTING_PREFIX}${guildId}`;
}

function channelSettingKey(guildId: string): string {
  return `${CHANNEL_SETTING_PREFIX}${guildId}`;
}

function memoryKey(guildId: string, userId: string): string {
  return `${guildId}:${userId}`;
}

/** Bellek kaynağı: önce RAM, disk yedek. Her process restart'ta diskten yüklenir. */
let memoryStoreCache: MemoryStore | null = null;

function loadMemoryStoreFromDisk(): MemoryStore {
  try {
    if (!fs.existsSync(MEMORY_FILE)) return {};
    const raw = fs.readFileSync(MEMORY_FILE, "utf8");
    const parsed: unknown = JSON.parse(raw);
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed))
      return {};
    return parsed as MemoryStore;
  } catch (error) {
    console.warn("MentionAI hafızası okunamadı:", error);
    return {};
  }
}

function getMemoryStore(): MemoryStore {
  if (!memoryStoreCache) memoryStoreCache = loadMemoryStoreFromDisk();
  return memoryStoreCache;
}

function writeMemoryStore(store: MemoryStore): void {
  memoryStoreCache = store;
  try {
    fs.mkdirSync(path.dirname(MEMORY_FILE), { recursive: true });
    const temporaryFile = `${MEMORY_FILE}.tmp`;
    fs.writeFileSync(temporaryFile, JSON.stringify(store, null, 2), "utf8");
    fs.renameSync(temporaryFile, MEMORY_FILE);
  } catch (error) {
    console.warn(
      `MentionAI hafızası yazılamadı (${MEMORY_FILE}):`,
      error instanceof Error ? error.message : error,
    );
  }
}

function getMemory(guildId: string, userId: string): MemoryMessage[] {
  const value = getMemoryStore()[memoryKey(guildId, userId)];
  if (!Array.isArray(value)) return [];
  return value
    .filter(
      (item): item is MemoryMessage =>
        Boolean(item) &&
        (item.role === "user" || item.role === "assistant") &&
        typeof item.content === "string" &&
        item.content.trim().length > 0,
    )
    .slice(-MAX_MEMORY_MESSAGES);
}

function saveMemory(
  guildId: string,
  userId: string,
  userContent: string,
  assistantContent: string,
): void {
  const store = getMemoryStore();
  const key = memoryKey(guildId, userId);
  const previous = getMemory(guildId, userId);
  const next: MemoryMessage[] = [
    ...previous,
    {
      role: "user",
      content: userContent.slice(0, 4_000),
      timestamp: new Date().toISOString(),
    },
    {
      role: "assistant",
      content: assistantContent.slice(0, 4_000),
      timestamp: new Date().toISOString(),
    },
  ].slice(-MAX_MEMORY_MESSAGES);
  store[key] = next;
  writeMemoryStore(store);
}

function formatMemory(messages: MemoryMessage[]): string {
  if (messages.length === 0) return "";
  const lines = messages.map(
    (item) =>
      `${item.role === "user" ? "Kullanıcı" : "Asistan"}: ${item.content}`,
  );
  return `\n\nSON KONUŞMA GEÇMİŞİ (bu kullanıcıyla; devam ettir, çelişme):\n${lines.join("\n")}`;
}

const MAX_REASONING_CHARS = 1_500;

/** Modelin gerçek reasoning metnini Discord'un "-# " küçük yazı (subtext)
 * biçimine çevirir. Discord subtext satır satır çalışır, bu yüzden her
 * satırın başına "-# " eklenir. Aşırı uzun reasoning'i kısaltır. */
function formatAsDiscordSubtext(reasoning: string): string {
  const trimmed = reasoning.trim();
  const truncated =
    trimmed.length > MAX_REASONING_CHARS
      ? `${trimmed.slice(0, MAX_REASONING_CHARS).trimEnd()}…`
      : trimmed;
  return truncated
    .split("\n")
    .map((line) => (line.trim() ? `-# ${line.trim()}` : "-# \u200b"))
    .join("\n");
}

function removeUnwantedEmojis(content: string): string {
  return content
    .replace(/\p{Extended_Pictographic}/gu, "")
    .replace(/\uFE0F/g, "")
    .replace(/[ \t]{2,}/g, " ")
    .trim();
}

export function splitMentionAiResponse(content: string): string[] {
  const normalized = content.trim();
  if (!normalized) return ["AI bir cevap üretemedi, tekrar dene."];
  const chunks: string[] = [];
  let remaining = normalized;
  while (remaining.length > MAX_DISCORD_MESSAGE_LENGTH) {
    let cut = remaining.lastIndexOf("\n", MAX_DISCORD_MESSAGE_LENGTH);
    if (cut < 900) cut = remaining.lastIndexOf(" ", MAX_DISCORD_MESSAGE_LENGTH);
    if (cut < 900) cut = MAX_DISCORD_MESSAGE_LENGTH;
    chunks.push(remaining.slice(0, cut).trim());
    remaining = remaining.slice(cut).trimStart();
  }
  if (remaining) chunks.push(remaining);
  return chunks;
}

const CODE_EXTENSIONS: Record<string, string> = {
  py: "py",
  python: "py",
  js: "js",
  javascript: "js",
  ts: "ts",
  typescript: "ts",
  tsx: "tsx",
  jsx: "jsx",
  json: "json",
  html: "html",
  css: "css",
  sql: "sql",
  bash: "sh",
  sh: "sh",
  shell: "sh",
  java: "java",
  c: "c",
  cpp: "cpp",
  csharp: "cs",
  cs: "cs",
  go: "go",
  rust: "rs",
  rs: "rs",
  php: "php",
  rb: "rb",
  ruby: "rb",
  yaml: "yml",
  yml: "yml",
  xml: "xml",
};

export function extractMentionAiCodeFiles(content: string): {
  text: string;
  files: MentionAiCodeFile[];
} {
  const files: MentionAiCodeFile[] = [];
  let index = 0;
  const text = content
    .replace(
      /```([\w#+.-]+)\s*\n([\s\S]*?)```/g,
      (_match, language: string, code: string) => {
        const requestedExtension =
          CODE_EXTENSIONS[language.trim().toLowerCase()] ?? "txt";
        const extension = ["ts", "tsx"].includes(requestedExtension)
          ? "txt"
          : requestedExtension;
        index += 1;
        files.push({
          name: `mentionai-code-${index}.${extension}`,
          content: code.replace(/^\n|\n$/g, ""),
          isTypeScript: ["ts", "tsx", "typescript"].includes(
            language.trim().toLowerCase(),
          ),
        });
        return "";
      },
    )
    .replace(/\n{3,}/g, "\n\n")
    .trim();
  return { text, files };
}

export const mentionAiEnabled = new Set<string>();
/** guildId → channelId. Kanal kısıtı yoksa key yoktur. */
export const mentionAiChannel = new Map<string, string>();
let mentionAiModel = DEFAULT_MODEL;
let mentionAiImageModel = DEFAULT_IMAGE_MODEL;
let loaded = false;
let loadingPromise: Promise<void> | null = null;

async function loadMentionAiSettings(): Promise<void> {
  const rows = await db.select().from(botSettingsTable);
  mentionAiEnabled.clear();
  mentionAiChannel.clear();
  for (const row of rows) {
    if (row.key === MODEL_SETTING_KEY && row.value.trim()) {
      mentionAiModel = row.value.trim();
    } else if (row.key === IMAGE_MODEL_SETTING_KEY && row.value.trim()) {
      mentionAiImageModel = row.value.trim();
    } else if (row.key.startsWith(CHANNEL_SETTING_PREFIX)) {
      const guildId = row.key.slice(CHANNEL_SETTING_PREFIX.length);
      const channelId = row.value.trim();
      if (guildId && channelId) mentionAiChannel.set(guildId, channelId);
    } else if (
      row.key.startsWith(SETTING_PREFIX) &&
      !row.key.startsWith(CHANNEL_SETTING_PREFIX) &&
      row.key !== MODEL_SETTING_KEY &&
      row.key !== IMAGE_MODEL_SETTING_KEY &&
      row.key !== RULES_SETTING_KEY &&
      row.value === "1"
    ) {
      mentionAiEnabled.add(row.key.slice(SETTING_PREFIX.length));
    }
  }
  loaded = true;
}

export async function ensureMentionAiLoaded(): Promise<void> {
  if (loaded) return;
  if (!loadingPromise)
    loadingPromise = loadMentionAiSettings().finally(() => {
      loadingPromise = null;
    });
  await loadingPromise;
}

export function isMentionAiEnabled(guildId: string): boolean {
  return mentionAiEnabled.has(guildId);
}

/** Belirtilmiş kanal kısıtı varsa o kanalın ID'sini döner, yoksa null. */
export function getMentionAiChannel(guildId: string): string | null {
  return mentionAiChannel.get(guildId) ?? null;
}

/**
 * MentionAI bu kanalda çalışabilir mi?
 * - Sistem kapalıysa hayır
 * - Kanal kısıtı yoksa her kanalda evet
 * - Kanal kısıtı varsa yalnızca o kanalda evet
 */
export function isMentionAiAllowedInChannel(
  guildId: string,
  channelId: string,
): boolean {
  if (!isMentionAiEnabled(guildId)) return false;
  const restricted = mentionAiChannel.get(guildId);
  if (!restricted) return true;
  return restricted === channelId;
}

/** Sohbet modeli: !modeller > groq (AFK / ozet vb. ile ayni havuz). */
export function getMentionAiModel(): string {
  return getActiveModel("groq");
}

export async function setMentionAiModel(model: string): Promise<void> {
  const normalized = model.trim().slice(0, 160);
  if (!normalized) throw new Error("Model adı boş olamaz.");
  mentionAiModel = normalized;
  await db
    .insert(botSettingsTable)
    .values({ key: MODEL_SETTING_KEY, value: normalized })
    .onConflictDoUpdate({
      target: botSettingsTable.key,
      set: { value: normalized, updatedAt: new Date() },
    });
}

export function getMentionAiImageModel(): string {
  return mentionAiImageModel;
}

export async function setMentionAiImageModel(model: string): Promise<void> {
  const normalized = model.trim().slice(0, 160);
  if (!normalized) throw new Error("Görsel model adı boş olamaz.");
  mentionAiImageModel = normalized;
  await db
    .insert(botSettingsTable)
    .values({ key: IMAGE_MODEL_SETTING_KEY, value: normalized })
    .onConflictDoUpdate({
      target: botSettingsTable.key,
      set: { value: normalized, updatedAt: new Date() },
    });
}

export async function setMentionAiEnabled(
  guildId: string,
  enabled: boolean,
): Promise<void> {
  if (enabled) mentionAiEnabled.add(guildId);
  else mentionAiEnabled.delete(guildId);
  await db
    .insert(botSettingsTable)
    .values({ key: settingKey(guildId), value: enabled ? "1" : "0" })
    .onConflictDoUpdate({
      target: botSettingsTable.key,
      set: { value: enabled ? "1" : "0", updatedAt: new Date() },
    });
}

/**
 * Kanal kısıtını ayarlar veya kaldırır (toggle).
 * - channelId verilirse o kanala kısıtlar
 * - null verilirse kısıtı kaldırır (tüm kanallar)
 * Aynı kanal tekrar verilirse de kaldırır (toggle).
 */
export async function setMentionAiChannel(
  guildId: string,
  channelId: string | null,
): Promise<{ channelId: string | null; toggledOff: boolean }> {
  const current = mentionAiChannel.get(guildId) ?? null;
  let next: string | null = channelId;
  let toggledOff = false;
  if (channelId && current === channelId) {
    next = null;
    toggledOff = true;
  }
  if (next) mentionAiChannel.set(guildId, next);
  else mentionAiChannel.delete(guildId);

  if (next) {
    await db
      .insert(botSettingsTable)
      .values({ key: channelSettingKey(guildId), value: next })
      .onConflictDoUpdate({
        target: botSettingsTable.key,
        set: { value: next, updatedAt: new Date() },
      });
  } else {
    await db
      .delete(botSettingsTable)
      .where(eq(botSettingsTable.key, channelSettingKey(guildId)));
  }
  return { channelId: next, toggledOff };
}

function decodeHtml(value: string): string {
  return value
    .replace(/<[^>]*>/g, "")
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, '"')
    .replace(/&#x27;|&#39;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/\s+/g, " ")
    .trim();
}

async function searchDuckDuckGo(query: string): Promise<SearchResult[]> {
  const url = `https://html.duckduckgo.com/html/?q=${encodeURIComponent(query.slice(0, MAX_QUERY_CHARS))}`;
  const response = await fetch(url, {
    headers: {
      "User-Agent":
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
      Accept: "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
      "Accept-Language": "tr-TR,tr;q=0.9,en-US;q=0.8,en;q=0.7",
    },
  });
  if (!response.ok) {
    console.warn(
      `MentionAI DuckDuckGo isteği başarısız: status=${response.status}`,
    );
    return [];
  }
  const html = await response.text();
  const results: SearchResult[] = [];
  const pattern =
    /<a[^>]+class="result__a"[^>]+href="([^"]+)"[^>]*>([\s\S]*?)<\/a>[\s\S]*?<a[^>]+class="result__snippet"[^>]*>([\s\S]*?)<\/a>/g;
  for (const match of html.matchAll(pattern)) {
    const urlValue = decodeURIComponent(match[1]).replace(/&amp;/g, "&");
    const redirect = urlValue.match(/uddg=([^&]+)/)?.[1];
    results.push({
      title: decodeHtml(match[2]),
      url: redirect ? decodeURIComponent(redirect) : urlValue,
      snippet: decodeHtml(match[3]),
    });
    if (results.length >= MAX_SEARCH_RESULTS) break;
  }
  if (results.length === 0) {
    console.warn(
      `MentionAI DuckDuckGo sonuç bulamadı. HTML uzunluğu: ${html.length}`,
    );
  }
  return results;
}

function shouldSearch(text: string): boolean {
  // \b Türkçe karakterlerde güvenilir değil; boşluk/baş-son sınırları kullan.
  return /(?:^|[\s,.:;!?])(ara|araştır|arastir|güncel|guncel|bugün|bugun|son dakika|haber|fiyat|kur|döviz|doviz|dolar|euro|altın|altin|borsa|hava|kimdir|nedir|ne zaman|kaynak|latest|news|search|price|weather|exchange rate)(?:\s|$|[!?.])/i.test(
    ` ${text} `,
  );
}

function formatSearchContext(results: SearchResult[]): string {
  if (!results.length) return "[DuckDuckGo araması sonuç vermedi.]";
  return results
    .map(
      (item, index) =>
        `${index + 1}. ${item.title}\nURL: ${item.url}\nÖzet: ${item.snippet}`,
    )
    .join("\n\n")
    .slice(0, MAX_SEARCH_CONTEXT_CHARS);
}

/** Kullanıcının "çiz / çizdir / draw / generate image" gibi istekleri.
 * Not: JS \\b yalnızca ASCII kelime karakterlerinde çalışır; "çiz" gibi
 * Türkçe fiiller için boşluk/baş/son sınırları kullanıyoruz. */
export function isMentionAiImageRequest(prompt: string): boolean {
  const text = prompt.trim().toLocaleLowerCase("tr-TR");
  if (!text) return false;
  // "anime kızı çiz", "çiz bir kedi", "şunu çizdir", "draw an anime girl"
  return /(?:^|[\s,.:;!?])(?:lütfen\s+|lutfen\s+|bana\s+)?(?:bir\s+)?(?:resim\s+|görsel\s+|image\s+)?(?:çiz|ciz|çizdir|cizdir|çizer misin|cizer misin|çizebilir misin|çizer misin|draw|paint|generate(?:\s+an?)?\s+image|create(?:\s+an?)?\s+image|make(?:\s+an?)?\s+image)(?:\s|$|[!?.])/i.test(
    ` ${text} `,
  );
}

function extractImagePrompt(prompt: string): string {
  return prompt
    .replace(
      /(?:lütfen|lutfen|bana)?\s*(?:bir\s+)?(?:resim\s+|görsel\s+|image\s+)?(?:çiz|ciz|çizdir|cizdir|çizer misin|cizer misin|çizebilir misin|draw|paint|generate(?:\s+an?)?\s+image|create(?:\s+an?)?\s+image|make(?:\s+an?)?\s+image)/gi,
      " ",
    )
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 2_000);
}

const IMAGE_PROMPT_ENHANCE_SYSTEM = `You convert a user's short image request into ONE detailed English image-generation prompt.
Rules:
- Output ONLY the final prompt text. No quotes, no labels, no reasoning, no markdown.
- Preserve the exact subject: characters, series, names, clothing, pose if mentioned.
- If a known anime/game/movie character is named (e.g. "Aizen Sousuke" from Bleach), describe that character accurately (appearance, signature traits, outfit) — do NOT invent a different character.
- Prefer: subject first, then style, composition, lighting, quality tags.
- Keep under 400 words. No NSFW unless the user asked for it.`;

/**
 * Kısa kullanıcı isteğini görsel modele uygun detaylı İngilizce prompt'a çevirir.
 * Başarısız olursa ham metni kullanır.
 */
async function enhanceImagePrompt(raw: string): Promise<string> {
  const base = raw.trim().slice(0, 500);
  if (!base) return "detailed anime illustration, high quality";
  try {
    const rawEnhanced = await generateWithGroq(
      IMAGE_PROMPT_ENHANCE_SYSTEM,
      `User request: ${base}`,
      {
        maxTokens: 512,
        temperature: 0.35,
      },
    );
    const enhanced = rawEnhanced
      .replace(/^["'`]+|["'`]+$/g, "")
      .replace(/^(prompt|image prompt|final prompt)\s*:\s*/i, "")
      .replace(/^#{1,6}\s+/gm, "")
      .replace(/^-#\s+/gm, "")
      .trim()
      .slice(0, 2_000);
    if (enhanced.length >= 8) return enhanced;
  } catch (error) {
    console.warn(
      "MentionAI görsel prompt geliştirme başarısız, ham prompt kullanılacak:",
      error instanceof Error ? error.message : error,
    );
  }
  // Fallback: subject + generic quality tags (series/character names stay intact)
  return `${base}, highly detailed, sharp focus, best quality, official art style`;
}

/** Model content içine sızmış thinking / -# satırlarını temizler. */
function stripReasoningArtifacts(content: string): string {
  let text = content
    .replace(/<think>[\s\S]*?<\/think>/gi, "")
    .replace(/<\/?think>/gi, "")
    .replace(/<reasoning>[\s\S]*?<\/reasoning>/gi, "")
    .replace(/```(?:thinking|reasoning)[\s\S]*?```/gi, "");
  // Discord subtext satırları (-# ...) — model veya eski format sızıntısı
  text = text
    .split("\n")
    .filter((line) => !/^\s*-#\s/.test(line))
    .join("\n");
  return text.replace(/\n{3,}/g, "\n\n").trim();
}

/** Chat completions ile aynı anahtar seti; sırayla denenir. */
function getPixRouterImageKeys(): { key: string; label: string }[] {
  const names = [
    "PIXROUTER_API_KEY",
    "PIXROUTER_API_KEY_1",
    "PIXROUTER_API_KEY_2",
    "PIXROUTER_API_KEY_3",
  ];
  const seen = new Set<string>();
  const out: { key: string; label: string }[] = [];
  for (const name of names) {
    const value = process.env[name]?.trim();
    if (!value || seen.has(value)) continue;
    seen.add(value);
    out.push({ key: value, label: name });
  }
  return out;
}

/** 401/403/429 anahtara özgü → sıradaki anahtar denenmeli. */
function isImageKeySpecificError(error: unknown): boolean {
  if (!(error instanceof PixRouterError)) return true;
  if (error.kind === "timeout") return false;
  if (error.kind === "http" && typeof error.status === "number") {
    return [401, 403, 429].includes(error.status);
  }
  return true;
}

export type MentionAiImageResult = {
  /** Uzak URL veya data URL */
  url?: string;
  /** Ham buffer (data URL çözüldüyse) */
  buffer?: Buffer;
  /** Dosya uzantısı önerisi */
  extension: string;
  promptUsed: string;
};

let imageKeyRotationIndex = 0;

async function callImageOnce(
  apiKey: string,
  imagePrompt: string,
  deadlineAt: number,
): Promise<MentionAiImageResult> {
  const remaining = deadlineAt - Date.now();
  if (remaining <= 0) {
    throw new PixRouterError(
      "Görsel üretimi için ayrılan süre bütçesi doldu.",
      "timeout",
    );
  }
  const controller = new AbortController();
  const timeoutId = setTimeout(
    () => controller.abort(),
    Math.min(120_000, remaining),
  );
  try {
    const response = await fetch(IMAGE_GENERATIONS_URL, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${apiKey}`,
      },
      signal: controller.signal,
      body: JSON.stringify({
        model: getMentionAiImageModel(),
        prompt: imagePrompt,
        n: 1,
        size: "1024x1024",
      }),
    });
    const raw = await response.text();
    let data: unknown = null;
    try {
      data = raw ? JSON.parse(raw) : null;
    } catch {
      // ham gövde hata mesajında kullanılacak
    }
    if (!response.ok) {
      const detail =
        data &&
        typeof data === "object" &&
        data !== null &&
        "error" in data &&
        typeof (data as { error?: { message?: string } }).error?.message ===
          "string"
          ? (data as { error: { message: string } }).error.message
          : raw.slice(0, 400);
      throw new PixRouterError(
        `Görsel üretimi başarısız (${response.status}): ${detail}`,
        "http",
        response.status,
      );
    }
    const record =
      data && typeof data === "object" && data !== null
        ? (data as Record<string, unknown>)
        : null;
    const items = record && Array.isArray(record.data) ? record.data : [];
    const first =
      items[0] && typeof items[0] === "object" && items[0] !== null
        ? (items[0] as Record<string, unknown>)
        : null;
    if (!first) {
      throw new PixRouterError("Görsel API boş yanıt döndürdü.", "empty");
    }
    if (typeof first.url === "string" && first.url.trim()) {
      return {
        url: first.url.trim(),
        extension: "png",
        promptUsed: imagePrompt,
      };
    }
    if (typeof first.b64_json === "string" && first.b64_json.trim()) {
      return {
        buffer: Buffer.from(first.b64_json, "base64"),
        extension: "png",
        promptUsed: imagePrompt,
      };
    }
    throw new PixRouterError(
      "Görsel API beklenen url/b64_json alanını döndürmedi.",
      "empty",
    );
  } catch (error) {
    if (error instanceof PixRouterError) throw error;
    const isAbort =
      error instanceof Error &&
      (error.name === "AbortError" ||
        error.message.toLowerCase().includes("abort") ||
        error.message.toLowerCase().includes("timeout"));
    if (isAbort) {
      throw new PixRouterError(
        "Görsel üretimi zamanaşımına uğradı.",
        "timeout",
      );
    }
    throw new PixRouterError(
      error instanceof Error ? error.message : String(error),
      "http",
    );
  } finally {
    clearTimeout(timeoutId);
  }
}

/**
 * PixRouter images/generations endpoint'i ile görsel üretir.
 * Model: `getMentionAiImageModel()` (varsayılan: veo-3.1-fast-generate-preview)
 *
 * Anahtar rotasyonu: PIXROUTER_API_KEY, _1, _2, _3 sırayla denenir.
 * 429/401/403 gibi anahtara özgü hatalarda sıradaki anahtara geçilir;
 * timeout/ağ hatalarında diğer anahtarlar denenmez (aynı upstream).
 */
export async function generateMentionAiImage(
  prompt: string,
): Promise<MentionAiImageResult> {
  const keys = getPixRouterImageKeys();
  if (keys.length === 0) {
    throw new PixRouterError(
      "PIXROUTER_API_KEY (veya PIXROUTER_API_KEY_1.._3) tanımlanmalı.",
      "config",
    );
  }
  const rawSubject =
    extractImagePrompt(prompt) ||
    prompt.trim().slice(0, 2_000) ||
    "a beautiful abstract illustration";
  // Karakter/seri adlarını koruyarak detaylı İngilizce prompt üret
  const imagePrompt = await enhanceImagePrompt(rawSubject);

  const deadlineAt = Date.now() + 120_000;
  const startIndex = imageKeyRotationIndex++ % keys.length;
  let lastError: unknown;

  for (let offset = 0; offset < keys.length; offset++) {
    if (Date.now() >= deadlineAt) break;
    const { key, label } = keys[(startIndex + offset) % keys.length];
    try {
      return await callImageOnce(key, imagePrompt, deadlineAt);
    } catch (error) {
      lastError = error;
      const detail = error instanceof Error ? error.message : String(error);
      const keepTrying = isImageKeySpecificError(error);
      console.warn(
        `MentionAI görsel anahtarı başarısız (${label}): ${detail}${
          keepTrying
            ? "; sıradaki anahtar deneniyor."
            : "; vazgeçiliyor (zamanaşımı/ağ hatası)."
        }`,
      );
      if (!keepTrying) break;
    }
  }

  if (lastError instanceof Error) {
    throw new PixRouterError(
      `Görsel üretimi başarısız (${keys.length} anahtar denendi): ${lastError.message}`,
      "http",
    );
  }
  throw new PixRouterError(
    `Görsel üretimi başarısız (${keys.length} anahtar denendi), detay alınamadı.`,
    "http",
  );
}

export async function answerMentionAi(input: {
  guildId: string;
  userId: string;
  username?: string;
  prompt: string;
  repliedMessage?: string;
  imageUrls?: string[];
}): Promise<string> {
  const cleanPrompt = input.prompt.trim().slice(0, 4_000);
  const imageUrls = (input.imageUrls ?? []).slice(0, 4);
  if (!cleanPrompt && imageUrls.length === 0) return "Bir soru veya konu yaz.";
  const effectiveUserPrompt =
    cleanPrompt || "Bu görsele bak ve doğal bir şekilde ne düşündüğünü söyle.";
  const memory = getMemory(input.guildId, input.userId);
  let searchContext = "";
  if (shouldSearch(effectiveUserPrompt)) {
    try {
      searchContext = `\n\nDUCKDUCKGO ARAMA SONUÇLARI (yalnızca gerektiğinde kullan):\n${formatSearchContext(await searchDuckDuckGo(effectiveUserPrompt))}`;
    } catch (error) {
      console.warn("MentionAI DuckDuckGo araması başarısız:", error);
    }
  }
  const replyContext = input.repliedMessage
    ? `\n\nYANITLANAN BOT MESAJI:\n${input.repliedMessage.slice(0, 3_000)}`
    : "";
  try {
    const userIdentity = `\n\nMESAJI YAZAN KULLANICI:\n- Kullanıcı adı: ${input.username ?? "bilinmiyor"}\n- Discord kullanıcı ID'si: ${input.userId}\n- Bot sahibi mi: ${input.userId === "1524388745560981505" ? "Evet" : "Hayır"}`;
    // Vision: paylaşılan groq.ts'ye dokunmadan URL'leri metne ekle.
    const visionNote =
      imageUrls.length > 0
        ? `\n\nEKLENEN GÖRSELLER (URL):\n${imageUrls.map((u, i) => `${i + 1}. ${u}`).join("\n")}`
        : "";
    const effectivePrompt = `${userIdentity}${formatMemory(memory)}\n\n${effectiveUserPrompt}${replyContext}${searchContext}${visionNote}`;

    // Sohbet: !modeller > groq aktif modeli. Ayarlar yalnızca burada.
    const raw = await generateWithGroq(
      await getSystemPrompt(),
      effectivePrompt,
      {
        maxTokens: 8_024,
        temperature: 0.55,
      },
    );
    const content = removeUnwantedEmojis(stripReasoningArtifacts(raw.trim()));
    saveMemory(input.guildId, input.userId, effectiveUserPrompt, content);
    return content;
  } catch (error) {
    if (
      error instanceof Error &&
      /API_KEY|tanımlı değil|tanimli degil/i.test(error.message)
    )
      return error.message.slice(0, 500);
    throw error;
  }
}

export function mentionAiErrorMessage(error: unknown): string {
  return error instanceof Error
    ? error.message.slice(0, 500)
    : String(error).slice(0, 500);
}
