const DATA_FILE = path.resolve(process.cwd(), "data/model-settings.json");

type StoredSettings = Partial<Record<ModelGroup, string>>;

let cache: StoredSettings | null = null;

function isKnownGroup(value: string): value is ModelGroup {
  return value === "gemini" || value === "groq" || value === "openrouter";
}

function isValidOption(group: ModelGroup, model: string): boolean {
  return MODEL_GROUPS[group].options.some((opt) => opt.value === model);
}

function loadFromDisk(): StoredSettings {
  if (cache) return cache;
  try {
    if (!fs.existsSync(DATA_FILE)) {
      cache = {};
      return cache;
    }
    const raw = JSON.parse(fs.readFileSync(DATA_FILE, "utf8")) as unknown;
    const result: StoredSettings = {};
    if (raw && typeof raw === "object") {
      for (const [key, value] of Object.entries(raw as Record<string, unknown>)) {
        if (isKnownGroup(key) && typeof value === "string" && isValidOption(key, value)) {
          result[key] = value;
        }
      }
    }
    cache = result;
  } catch (err) {
    console.error("⚠️ data/model-settings.json okunamadı, varsayılan modeller kullanılacak:", err);
    cache = {};
  }
  return cache;
}

function persist(settings: StoredSettings): void {
  try {
    fs.mkdirSync(path.dirname(DATA_FILE), { recursive: true });
    fs.writeFileSync(DATA_FILE, JSON.stringify(settings, null, 2), "utf8");
  } catch (err) {
    console.error("⚠️ data/model-settings.json yazılamadı:", err);
    throw err;
  }
}

/** O anda aktif olan modeli döner (owner ayarlamadıysa koddaki varsayılan). */
export function getActiveModel(group: ModelGroup): string {
  const settings = loadFromDisk();
  return settings[group] ?? MODEL_GROUPS[group].defaultModel;
}

/** Owner tarafından ayarlanmış (varsayılandan farklı) bir model var mı? */
export function hasOverride(group: ModelGroup): boolean {
  return loadFromDisk()[group] !== undefined;
}

/** Bir sağlayıcı için aktif modeli değiştirir ve JSON dosyasına kalıcı yazar. */
export function setActiveModel(group: ModelGroup, model: string): void {
  if (!isValidOption(group, model)) {
    throw new Error(`Geçersiz model: ${group} için "${model}" desteklenmiyor.`);
  }
  const settings = { ...loadFromDisk() };
  settings[group] = model;
  persist(settings);
  cache = settings;
}

/** Bir sağlayıcıyı koddaki orijinal varsayılan modele geri döndürür. */
export function resetActiveModel(group: ModelGroup): void {
  const settings = { ...loadFromDisk() };
  delete settings[group];
  persist(settings);
  cache = settings;
}
","utils/notifyOwner.ts":"import type { Client, Guild, User } from "discord.js";
import { OWNER_ID } from "../config.js";

async function resolveOwner(client: Client): Promise<User | null> {
  // Öncelik Discord Application owner bilgisinde; böylece eski/yanlış
  // OWNER_ID yüzünden bildirim başka hesaba gitmez.
  try {
    const application = await client.application?.fetch();
    const owner = application?.owner;
    if (owner && "send" in owner && typeof owner.send === "function") {
      return owner as User;
    }
  } catch (error) {
    console.error("Owner Discord application bilgisinden çözülemedi:", error);
  }

  try {
    return await client.users.fetch(OWNER_ID);
  } catch (error) {
    console.error(`OWNER_ID (${OWNER_ID}) kullanıcısı çözülemedi:`, error);
    return null;
  }
}

/** Herhangi bir komut çalıştırıldığında owner'a DM ile haber verir. */
export async function notifyOwnerCommandUsed(
  client: Client,
  params: {
    commandName: string;
    user: User;
    guild: Guild | null;
    success: boolean;
    source: "slash" | "prefix";
  },
): Promise<void> {
  // Agent için siteye özel bildirim ayrı gönderilir; genel komut DM'iyle
  // aynı owner bildiriminin iki kez gitmesini önle.
  if (params.user.id === OWNER_ID || params.commandName === "agent" || params.commandName === "manus") return;

  try {
    const owner = await resolveOwner(client);
    if (!owner) return;
    const durum = params.success ? "✅ başarılı" : "❌ hata";
    const yer = params.guild ? params.guild.name : "DM";
    const prefix = params.source === "slash" ? "/" : "!";

    await owner.send(
      `${durum} — **${prefix}${params.commandName}**\n` +
        `Kullanıcı: ${params.user.tag} (${params.user.id})\n` +
        `Sunucu: ${yer}`,
    );
  } catch (error) {
    console.error("Owner komut bildirimi DM ile gönderilemedi:", error);
  }
}

/**
 * Manus görevi oluşturulur oluşturulmaz sohbet bağlantısını yalnızca owner'a DM yollar.
 * Bu bağlantı kanala, agent sonucuna veya başka kullanıcıya aktarılmaz.
 */
export async function notifyOwnerAgentTaskCreated(
  client: Client,
  params: { requester: User; prompt: string; taskUrl: string },
): Promise<boolean> {
  try {
    const owner = await resolveOwner(client);
    if (!owner) return false;
    await owner.send(
      "🔗 **Manus sohbeti hazır.**\n" +
        `İstek: ${params.prompt.slice(0, 700)}\n\n` +
        `${params.taskUrl}\n\n` +
        "Siteyi yayınlamak için sohbeti açıp **‘Sitemi yayınla / Web sitesini yayınla ve canlı bağlantıyı oluştur’** mesajını gönder.",
    );
    return true;
  } catch (error) {
    console.error("Owner task URL bildirimi DM ile gönderilemedi:", error);
    return false;
  }
}

/**
 * !agent bir onay/bilgi beklediğinde owner'a güvenli DM yollar.
 */
export async function notifyOwnerAgentWaiting(
  client: Client,
  params: {
    requester: User;
    prompt: string;
    detail: string;
    type?: string;
  },
): Promise<boolean> {
  try {
    const owner = await resolveOwner(client);
    if (!owner) return false;

    await owner.send(
      "⚠️ **Manus agent onay/bilgi bekliyor.**\n" +
        `İsteyen: ${params.requester.tag} (${params.requester.id})\n` +
        `İstek: ${params.prompt.slice(0, 700)}\n` +
        `Bekleyen işlem: ${params.detail}\n` +
        (params.type ? `Tür: ${params.type}\n` : "") +
        "Sohbet bağlantısı bu akışın başında yalnızca owner’a DM edildi. DM’deki sohbeti açıp gerekli onayı ver veya “Sitemi yayınla / Web sitesini yayınla ve canlı bağlantıyı oluştur” mesajını gönder.",
    );
    return true;
  } catch (error) {
    console.error("Owner waiting bildirimi DM ile gönderilemedi:", error);
    return false;
  }
}

/** !agent bir web sitesi/uygulama çıktısı ürettiğinde owner'a DM yollar. */
export async function notifyOwnerAgentSiteReady(
  client: Client,
  params: {
    requester: User;
    prompt: string;
    outputLinks: string[];
    fileNames: string[];
  },
): Promise<boolean> {
  try {
    const owner = await resolveOwner(client);
    if (!owner) return false;

    const links = params.outputLinks.length
      ? `\nYayın/önizleme bağlantıları:\n${params.outputLinks.map((link) => `• ${link}`).join("\n")}`
      : "";
    const files = params.fileNames.length
      ? `\nÜretilen dosyalar: ${params.fileNames.slice(0, 10).join(", ")}`
      : "";

    await owner.send(
      "🌐 **Manus site/uygulama çıktısı hazır.**\n" +
        `İsteyen: ${params.requester.tag} (${params.requester.id})\n` +
        `İstek: ${params.prompt.slice(0, 700)}\n\n` +
        "Manus sohbet bağlantısı başlangıçta yalnızca owner’a DM edildi. " +
        "İlgili sohbetten **‘Sitemi yayınla / Web sitesini yayınla ve canlı bağlantıyı oluştur’** şeklinde onay ver. " +
        "Yayın bağlantısı oluştuğunda Discord’daki sonuç mesajında görünecek." +
        links +
        files,
    );
    return true;
  } catch (error) {
    console.error("Owner site-hazır bildirimi DM ile gönderilemedi:", error);
    return false;
  }
}

export async function notifyOwnerAgentFailure(
  client: Client,
  params: { requester: User; prompt: string; error: string },
): Promise<boolean> {
  try {
    const owner = await resolveOwner(client);
    if (!owner) return false;
    await owner.send(
      "❌ **Manus agent işlemi başarısız oldu.**\n" +
        `İsteyen: ${params.requester.tag} (${params.requester.id})\n` +
        `İstek: ${params.prompt.slice(0, 700)}\n` +
        `Hata: ${params.error.slice(0, 1000)}`,
    );
    return true;
  } catch (error) {
    console.error("Owner agent hata bildirimi DM ile gönderilemedi:", error);
    return false;
  }
}

","utils/openrouter.ts":"// src/utils/openrouter.ts
// OpenRouter üzerinden MiniMax M3 (ücretsiz) entegrasyonu.
// https://openrouter.ai/

import { getActiveModel } from "./modelSettings.js";

const OPENROUTER_URL = "https://openrouter.ai/api/v1/chat/completions";
// Varsayılan model utils/modelSettings.ts'te (MODEL_GROUPS.openrouter.defaultModel)
// tanımlı; !modeller ile owner değiştirirse callOnce'a o model geçirilir.

// Eskiden 8_000'di — animasyonlu/çok dosyalı bir website gibi büyük
// istekler bu limiti aşınca cevap yarıda kesiliyordu (bkz. commit notu
// aşağıda). Kullanıcı OpenRouter'da aynı anahtarla tek istekte 200k
// token'ın sorunsuz döndüğünü doğruladığı için tavanı büyük tuttuk.
const MAX_TOKENS_PER_CALL = 100_000;
const REQUEST_TIMEOUT_MS = 120_000;

// Cevap yine de token limiti yüzünden yarıda kesilirse (finish_reason:
// "length" — MAX_TOKENS_PER_CALL yükseltildikten sonra pratikte neredeyse
// hiç olmaması gerekir ama sağlayıcı tarafında olası bir düşüş/limit
// değişikliğine karşı yine de tutuyoruz), modele "kaldığın yerden devam
// et" diyerek otomatik olarak tekrar sorup parçaları birleştiriyoruz. Bu
// olmadan, örneğin "hareketli/animasyonlu bir website" gibi büyük bir
// HTML+CSS+JS isteği limiti aşınca dosya yarıda kesiliyor ve script tam
// kapanmadığı için sitede butonlar çalışmıyor / scroll'da JS hatası alınıp
// sayfa bozuluyordu — gerçekte yaşanmış bir hataydı.
const MAX_CONTINUATIONS = 4;

class RateLimitError extends Error {
  status = 429;
  constructor(message = "Rate limit / kota (429)") {
    super(message);
  }
}

class KeyDeniedError extends Error {
  status = 401;
  constructor(message = "Key reddedildi (401/403)") {
    super(message);
  }
}

type JsonRecord = Record<string, unknown>;
function isRecord(value: unknown): value is JsonRecord {
  return typeof value === "object" && value !== null;
}

// .env'de sırayla denenecek OpenRouter anahtarları: OP_KOD_1..OP_KOD_6.
// Boş/tanımsız olanlar otomatik atlanır.
const OPENROUTER_KEY_ENV_NAMES = ["OP_KOD_1", "OP_KOD_2", "OP_KOD_3", "OP_KOD_4", "OP_KOD_5", "OP_KOD_6"] as const;

let keyRotationIndex = 0;

function getConfiguredKeys(): { key: string; label: string }[] {
  // BUG NOTU: boşluk/CR kontrolü `.trim()` ile yapılıyordu ama filtreden
  // geçen değer trim EDİLMEMİŞ orijinal `process.env[name]` idi. .env
  // dosyasında satır sonunda görünmeyen bir boşluk ya da (özellikle
  // Windows'ta CRLF ile kaydedilmiş .env dosyalarında oluşan) bir "\r"
  // karakteri varsa, key'in kendisi doğru olsa bile Authorization
  // header'ına o fazladan karakterle gidiyor ve OpenRouter bunu geçersiz
  // sayıp "401 user not found" ile reddediyordu. Artık gerçekten
  // kullanılan değer de trim ediliyor.
  return OPENROUTER_KEY_ENV_NAMES.map((name) => ({ key: process.env[name]?.trim(), label: name })).filter(
    (entry): entry is { key: string; label: string } => Boolean(entry.key),
  );
}

type ChatMessage = { role: "system" | "user" | "assistant"; content: string };
type CallResult = { content: string; finishReason: string | null };

async function callOnce(apiKey: string, messages: ChatMessage[], model: string): Promise<CallResult> {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);

  try {
    const res = await fetch(OPENROUTER_URL, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${apiKey}`,
      },
      signal: controller.signal,
      body: JSON.stringify({
        model,
        max_tokens: MAX_TOKENS_PER_CALL,
        messages,
      }),
    });

    clearTimeout(timeoutId);

    if (res.status === 429) throw new RateLimitError();
    if (res.status === 401 || res.status === 403) {
      const body = await res.text().catch(() => "");
      throw new KeyDeniedError(`Key reddedildi (${res.status}): ${body.slice(0, 200)}`);
    }
    if (!res.ok) {
      const body = await res.text().catch(() => "");
      throw new Error(`OpenRouter API hatası (${res.status}): ${body.slice(0, 300)}`);
    }

    const data: unknown = await res.json();

    // BUG NOTU: OpenRouter, özellikle ücretsiz modellerde (moderasyon,
    // sağlayıcı tarafı geçici hata, model o an kullanılamıyor vb.
    // durumlarda) bazen HTTP 200 döner ama gövdede "choices" yerine
    // üst seviye bir "error" objesi gönderir. Eskiden bu hiç kontrol
    // edilmiyordu; "choices[0]" bulunamayınca kod sessizce "boş yanıt"
    // hatası fırlatıyor ve gerçek sebep (rate limit, moderasyon,
    // sağlayıcı çökmesi vb.) tamamen gizleniyordu. Artık varsa önce bu
    // hatayı ayıklayıp asıl mesajla fırlatıyoruz.
    if (isRecord(data) && isRecord(data.error)) {
      const rawCode = data.error.code;
      const code = typeof rawCode === "number" || typeof rawCode === "string" ? rawCode : "?";
      // rawCode "429" (string) ya da 429 (number) olarak gelebilir — ikisini
      // de yakalamak için sayısal karşılaştırma yapıyoruz (eskiden `=== 429`
      // gibi katı karşılaştırmalar string "429"u kaçırıp genel/yanlış
      // sınıflandırılmış bir hataya düşüyordu, bu da key rotasyonunun
      // 429'da bir sonraki anahtara geçmesini engelliyordu).
      const numericCode = typeof code === "number" ? code : Number(code);
      const msg = typeof data.error.message === "string" ? data.error.message : JSON.stringify(data.error).slice(0, 300);
      if (numericCode === 429) throw new RateLimitError(`OpenRouter (${code}): ${msg}`);
      if (numericCode === 401 || numericCode === 403) throw new KeyDeniedError(`OpenRouter (${code}): ${msg}`);
      throw new Error(`OpenRouter hata döndürdü (${code}): ${msg}`);
    }

    const choice = isRecord(data) && Array.isArray(data.choices) && isRecord(data.choices[0])
      ? data.choices[0]
      : undefined;
    const message = choice && isRecord(choice.message) ? choice.message : undefined;

    // Bazı sağlayıcılar content'i düz string yerine parça dizisi olarak
    // dönebiliyor (ör. [{type:"text", text:"..."}, ...]). Eskiden sadece
    // typeof === "string" kabul edildiği için bu durumda da yanlışlıkla
    // "boş yanıt" hatası veriliyordu.
    let text = "";
    if (message && typeof message.content === "string") {
      text = message.content;
    } else if (message && Array.isArray(message.content)) {
      text = message.content
        .map((part) => (isRecord(part) && typeof part.text === "string" ? part.text : ""))
        .join("");
    }

    const finishReason: string | null = choice && typeof choice.finish_reason === "string"
      ? choice.finish_reason
      : null;

    if (!text.trim()) {
      // finish_reason burada teşhis için değerli — "content_filter" ise
      // moderasyon, "error" ise sağlayıcı tarafı bir hata anlamına gelir.
      throw new Error(
        `OpenRouter boş bir yanıt döndürdü${finishReason ? ` (finish_reason: ${finishReason})` : ""}.`,
      );
    }

    return { content: text, finishReason };
  } catch (err) {
    if (err instanceof Error && err.name === "AbortError") {
      throw new Error(`Timeout (${REQUEST_TIMEOUT_MS / 1000}sn) — model çok uzun sürdü.`);
    }
    throw err;
  } finally {
    clearTimeout(timeoutId);
  }
}

// Cevap "length" (token limiti) yüzünden kesildiyse, konuşmaya modelin
// yarım kalan cevabını ekleyip "kaldığın yerden devam et" diyerek tekrar
// soruyor ve parçaları birleştiriyor. Aynı Gemini fallback'indeki
// (utils/gemini.ts) mantığın OpenRouter karşılığı.
async function callWithContinuation(
  apiKey: string,
  systemPrompt: string,
  userPrompt: string,
  model: string,
): Promise<string> {
  const messages: ChatMessage[] = [
    { role: "system", content: systemPrompt },
    { role: "user", content: userPrompt },
  ];

  let fullText = "";

  for (let i = 0; i <= MAX_CONTINUATIONS; i++) {
    const { content, finishReason } = await callOnce(apiKey, messages, model);
    fullText += content;

    if (finishReason !== "length") {
      // Model normal şekilde bitirdi ("stop") ya da farklı bir sebeple durdu.
      return fullText;
    }

    if (i === MAX_CONTINUATIONS) {
      console.warn("⚠️ OpenRouter: maksimum devam sayısına ulaşıldı, cevap yine de yarıda kalmış olabilir.");
      break;
    }

    messages.push({ role: "assistant", content });
    messages.push({
      role: "user",
      content:
        "Cevabın token limiti yüzünden yarıda kesildi. Kaldığın YERDEN devam et. " +
        "Baştan tekrar başlama, önceki kısmı tekrar yazma, hiçbir açıklama ekleme " +
        "— sadece kesildiğin noktadan itibaren kodun/dosyanın geri kalanını yaz. " +
        "Hâlâ aynı dosyanın içindeysen dosya başlığını (===FILE: ...===) veya kod " +
        "bloğu (```) işaretini tekrarlama, doğrudan koddan devam et.",
    });
  }

  return fullText;
}

/**
 * OpenRouter'da MiniMax M3 (free) modeline istek atar. Tanımlı anahtarlar
 * arasında round-robin yapar; bir anahtar 429/401/403 alırsa sıradaki
 * anahtarla dener. Cevap token limiti yüzünden yarıda kesilirse otomatik
 * olarak devam ettirir (bkz. callWithContinuation). Hiçbir anahtar/istek
 * başarılı olmazsa hata fırlatır — çağıran taraf (bkz. utils/codeModel.ts)
 * bunu yakalayıp Gemini'ye düşer.
 */
export async function generateWithOpenRouter(systemPrompt: string, userPrompt: string, modelOverride?: string): Promise<string> {
  const keys = getConfiguredKeys();
  if (keys.length === 0) {
    throw new Error(
      "OP_KOD_1..OP_KOD_6 arasında hiçbiri tanımlı değil — OpenRouter atlanıyor.",
    );
  }

  const startIndex = keyRotationIndex % keys.length;
  keyRotationIndex = (keyRotationIndex + 1) % Number.MAX_SAFE_INTEGER;
  const model = modelOverride ?? getActiveModel("openrouter");

  let lastErr: unknown;
  for (let offset = 0; offset < keys.length; offset++) {
    const { key, label } = keys[(startIndex + offset) % keys.length];
    try {
      return await callWithContinuation(key, systemPrompt, userPrompt, model);
    } catch (err) {
      lastErr = err;
      if (err instanceof RateLimitError || err instanceof KeyDeniedError) {
        console.warn(`⚠️ OpenRouter isteği başarısız (${label}), sıradaki anahtara geçiliyor:`, err.message);
        continue;
      }
      console.warn(`⚠️ OpenRouter isteği başarısız (${label}):`, err);
      continue;
    }
  }

  throw lastErr instanceof Error ? lastErr : new Error("OpenRouter isteği başarısız.");
}
","utils/parse.ts":"import type { Guild } from "discord.js";

/** @mention veya düz ID'den kullanıcı ID'sini çıkarır */
export function parseMention(str: string): string | null {
  const match = str.match(/^<@!?(\d+)>$/) ?? str.match(/^(\d{17,20})$/);
  return match ? match[1] : null;
}

/** #kanal mention'ından veya düz ID'den kanal ID'sini çıkarır */
export function parseChannelMention(str: string): string | null {
  const match = str.match(/^<#(\d+)>$/) ?? str.match(/^(\d{17,20})$/);
  return match ? match[1] : null;
}

// Komut mesajının ham içeriğinden, baştaki `tokenCount` kadar boşlukla
// ayrılmış "kelimeyi" (prefix dahil, komut adı + varsa önceki argümanlar)
// atlayıp geri kalanını AYNEN (satır sonları, kod bloğu ``` işaretleri,
// çoklu boşluklar dahil) döndürür.
// `args.join(" ")` KULLANMA çünkü o, mesajı tek boşlukla parçalayıp
// birleştirdiği için kullanıcının markdown/kod bloğu biçimlendirmesini
// (özellikle satır sonlarını) bozar — çok satırlı custom event/komut kodu,
// hoşgeldin mesajı gibi şeyler tek satıra sıkışır.
export function extractRawRest(content: string, tokenCount: number, prefix: string): string | null {
  const withoutPrefix = content.slice(prefix.length);
  const re = new RegExp(`^\\s*(?:\\S+\\s+){${tokenCount}}`);
  const match = withoutPrefix.match(re);
  if (!match) return null;
  const rest = withoutPrefix.slice(match[0].length).trimEnd();
  return rest.length > 0 ? rest : null;
}

/** Dakika → okunabilir Türkçe süre metni */
export function formatDuration(minutes: number): string {
  if (minutes >= 1440) return `${Math.floor(minutes / 1440)} gün`;
  if (minutes >= 60) return `${Math.floor(minutes / 60)} saat`;
  return `${minutes} dakika`;
}
","utils/permissions.ts":"import { db } from "../db/index.js";
import { userPermissionsTable } from "../db/schema.js";
import { eq, and } from "drizzle-orm";
import type { Message } from "discord.js";
import { OWNER_ID } from "../config.js";

// ---------------------------------------------------------------------------
// PERFORMANS: Eskiden her hasPermission() çağrısı SIRAYLA (await -> await)
// 2 ayrı DB sorgusu atıyordu (önce kullanıcıya özel izin, sonra rol izinleri).
// Her prefix mod komutu (!ban, !kick, !timeout, !warn, ...) bu fonksiyonu
// çağırdığı için, o komutlar DB'ye gidiş-dönüş süresi kadar (Neon'da bazen
// yüzlerce ms) gecikmeyle cevap veriyordu — "! komutları geç cevap veriyor"
// şikayetinin doğrudan sebebi buydu.
//
// Çözüm: guild+permission başına TÜM izin satırlarını TEK sorguda çekip
// (kullanıcı VE rol hedefli satırlar birlikte), kısa süreli bellek-içi
// cache'e alıyoruz. Aynı sunucuda aynı izin tekrar kontrol edildiğinde
// (ör. art arda birkaç !ban kullanımı) DB'ye hiç gidilmiyor.
// ---------------------------------------------------------------------------
interface PermRow {
  targetId: string;
  targetType: string;
}
const CACHE_TTL_MS = 30_000;
const cache = new Map<string, { rows: PermRow[]; ts: number }>();
const inFlight = new Map<string, Promise<PermRow[]>>();

async function loadPermRows(guildId: string, permission: string): Promise<PermRow[]> {
  const key = `${guildId}:${permission}`;
  const cached = cache.get(key);
  if (cached && Date.now() - cached.ts < CACHE_TTL_MS) return cached.rows;

  const existingLoad = inFlight.get(key);
  if (existingLoad) return existingLoad;

  const load = db
    .select({ targetId: userPermissionsTable.targetId, targetType: userPermissionsTable.targetType })
    .from(userPermissionsTable)
    .where(and(eq(userPermissionsTable.guildId, guildId), eq(userPermissionsTable.permission, permission)))
    .then((rows) => {
      cache.set(key, { rows, ts: Date.now() });
      return rows;
    })
    .finally(() => {
      if (inFlight.get(key) === load) inFlight.delete(key);
    });
  inFlight.set(key, load);
  return load;
}

/** !izin-ver / !izin-al gibi komutlar bir sunucunun izinlerini değiştirdiğinde çağrılır. */
export function invalidatePermissionCache(guildId: string, permission?: string): void {
  if (permission) {
    cache.delete(`${guildId}:${permission}`);
    return;
  }
  for (const key of cache.keys()) {
    if (key.startsWith(`${guildId}:`)) cache.delete(key);
  }
}

export async function hasPermission(
  message: Message,
  permission: string
): Promise<boolean> {
  // Bot sahibi (OWNER_ID) her zaman, hiçbir izin/rol/Discord yetkisine
  // bakılmaksızın TÜM komutları kullanabilir — global geçersiz kılma.
  if (message.author.id === OWNER_ID) return true;
  if (message.member?.permissions.has("Administrator")) return true;

  const guildId = message.guildId!;
  const userId = message.author.id;

  const rows = await loadPermRows(guildId, permission);
  if (rows.some((r) => r.targetType === "user" && r.targetId === userId)) return true;

  const memberRoles = message.member?.roles.cache;
  if (!memberRoles || memberRoles.size === 0) return false;
  return rows.some((r) => r.targetType === "role" && memberRoles.has(r.targetId));
}","utils/pixrouter.ts":"// src/utils/pixrouter.ts
// PixRouter (New API uyumlu) üzerinden OpenAI-compatible chat completions.
// Resmi site: https://pixrouter.com
// Dokümantasyon: https://docs.newapi.pro/en/docs/api
//
// ---------------------------------------------------------------------------
// ZAMANAŞIMI DAVRANIŞI (ÖNEMLİ — bkz. geçmiş "!kod-* hep zamanaşımına
// uğruyor" hatası):
//
// Eskiden her (anahtar × token-bütçesi) denemesi kendi başına 120 sn'lik bir
// AbortController kullanıyordu ve zamanaşımında bir sonraki anahtara
// geçiliyordu. PixRouter tarafı yavaş/yanıtsızsa bu, 3 anahtar × 120 sn = 6
// dakikaya kadar tek bir generateWithPixRouter() çağrısını kilitleyebiliyordu.
// !kod-yaz gibi komutlar ise (özellikle "auto" dil modunda) bu fonksiyonu
// ART ARDA 2-3 KEZ çağırıyor (dil tespiti + kod üretimi + gerekirse dil
// düzeltme denemesi) — yani en kötü senaryoda 15-18 dakikaya kadar çıkıyordu.
// !sor ise tek bir çağrı yaptığı için aynı sorunu çok daha az hissediyordu.
//
// Çözüm: artık TÜM generateWithPixRouter() çağrısı (kaç anahtar/bütçe
// denenirse denensin) tek bir toplam süre bütçesiyle (PIXROUTER_TOTAL_TIMEOUT_MS)
// sınırlanıyor; her HTTP denemesi de ayrıca daha kısa bir üst sınıra
// (PIXROUTER_TIMEOUT_MS) tabi. Zamanaşımı/ağ hatalarında (diğer anahtarları
// denemek muhtemelen aynı sonucu verir) hemen sıradaki anahtara geçmek yerine
// kalan süre bütçesi kontrol edilip yetmiyorsa hızlıca vazgeçiliyor, böylece
// çağıran taraf (ör. codeModel.ts) OpenRouter/Gemini fallback'ine makul bir
// sürede düşebiliyor.
// ---------------------------------------------------------------------------

import { getActiveModel } from "./modelSettings.js";

const PIXROUTER_BASE_URL = "https://pixrouter.com/v1";
// PixRouter yönlendirilen modele göre daha düşük bir sınır uygulayabilir.
// İstek reddedilirse callOnce daha düşük kademeleri otomatik dener.
const DEFAULT_MAX_TOKENS = 131_072;

// Tek bir HTTP denemesinin en fazla ne kadar sürebileceği.
const DEFAULT_REQUEST_TIMEOUT_MS = 30_000;
// generateWithPixRouter()'ın TÜMÜ (kaç anahtar/bütçe denenirse denensin) için
// toplam üst sınır. Bu, anahtar rotasyonunun eski davranıştaki gibi süreyi
// katlamasını engeller.
const DEFAULT_TOTAL_TIMEOUT_MS = 60_000;

const PIXROUTER_KEY_ENV_NAMES = [
  "PIXROUTER_API_KEY_1",
  "PIXROUTER_API_KEY_2",
  "PIXROUTER_API_KEY_3",
] as const;

export type PixRouterContentPart =
  | { type: "text"; text: string }
  | { type: "image_url"; image_url: { url: string } };
type ChatMessage = {
  role: "system" | "user" | "assistant";
  content: string | PixRouterContentPart[];
};
type JsonRecord = Record<string, unknown>;

/** PixRouter'a özgü HTTP/ağ hataları — groq.ts'teki HttpError ile aynı yaklaşım. */
export class PixRouterError extends Error {
  constructor(
    message: string,
    readonly kind: "timeout" | "http" | "api" | "empty" | "config" = "http",
    readonly status?: number,
  ) {
    super(message);
    this.name = "PixRouterError";
  }
}

function isRecord(value: unknown): value is JsonRecord {
  return typeof value === "object" && value !== null;
}

function envInt(name: string, fallback: number): number {
  const raw = Number.parseInt(process.env[name] ?? "", 10);
  return Number.isFinite(raw) && raw > 0 ? raw : fallback;
}

function getRequestTimeoutMs(): number {
  return envInt("PIXROUTER_TIMEOUT_MS", DEFAULT_REQUEST_TIMEOUT_MS);
}

function getTotalTimeoutMs(): number {
  return envInt("PIXROUTER_TOTAL_TIMEOUT_MS", DEFAULT_TOTAL_TIMEOUT_MS);
}

function getConfiguredKeys(): { key: string; label: string }[] {
  // Tek anahtar için PIXROUTER_API_KEY de desteklenir; _1.._3 varsa rotasyona katılır.
  // Aynı değere sahip env'ler tek sefer sayılır (duplicate deneme olmasın).
  const names = ["PIXROUTER_API_KEY", ...PIXROUTER_KEY_ENV_NAMES];
  const seen = new Set<string>();
  const out: { key: string; label: string }[] = [];
  for (const name of names) {
    const key = process.env[name]?.trim();
    if (!key || seen.has(key)) continue;
    seen.add(key);
    out.push({ key, label: name });
  }
  return out;
}

function extractError(data: unknown): string | null {
  if (!isRecord(data) || !isRecord(data.error)) return null;
  const message =
    typeof data.error.message === "string"
      ? data.error.message
      : JSON.stringify(data.error);
  return message.slice(0, 400);
}

function getMaxTokensCap(): number {
  return envInt("PIXROUTER_MAX_TOKENS", DEFAULT_MAX_TOKENS);
}

function getTokenBudgets(requested: number): number[] {
  const cap = getMaxTokensCap();
  const initial = Math.min(Math.max(Math.floor(requested), 1), cap);
  const budgets = [initial, 131_072, 65_536, 32_768, 16_384, 8_192, 4_096]
    .filter((budget) => budget <= initial)
    .filter((budget, index, all) => all.indexOf(budget) === index);
  return budgets.length > 0 ? budgets : [1];
}

function shouldRetryWithSmallerBudget(status: number, detail: string): boolean {
  if (status < 400 || status >= 500) return false;
  return /token|context|length|max_tokens|max token|too large|parameter/i.test(
    detail,
  );
}

/**
 * Bir anahtarın zamanaşımı/ağ hatası vermesi diğer anahtarların da aynı
 * sonucu vermesi muhtemel olduğu anlamına gelir (aynı upstream servis, aynı
 * ağ yolu) — bu yüzden bu tür hatalarda anahtar rotasyonuna devam etmenin
 * pratik faydası azdır. 401/403/429 gibi ANAHTARA ÖZGÜ hatalarda ise
 * sıradaki anahtarı denemek hâlâ mantıklı.
 */
function isKeySpecificError(error: unknown): boolean {
  if (!(error instanceof PixRouterError)) return true;
  if (error.kind === "timeout") return false;
  if (error.kind === "http" && typeof error.status === "number") {
    return [401, 403, 429].includes(error.status);
  }
  return true;
}

export interface PixRouterResult {
  content: string;
  /** Modelin gerçek reasoning/thinking çıktısı — sağlayıcı destekliyorsa
   * (ör. reasoning_content / reasoning alanı) doldurulur, aksi halde
   * undefined. Bu ASLA uydurulmaz; sadece API böyle bir alan döndürdüyse
   * set edilir. */
  reasoning?: string;
}

function extractReasoning(message: JsonRecord): string | undefined {
  const candidates = [
    message.reasoning_content,
    message.reasoning,
    message.thinking,
  ];
  for (const candidate of candidates) {
    if (typeof candidate === "string" && candidate.trim()) {
      return candidate.trim();
    }
  }
  return undefined;
}

async function callOnce(
  apiKey: string,
  model: string,
  messages: ChatMessage[],
  maxTokens: number,
  temperature: number | undefined,
  deadlineAt: number,
  requestReasoning: boolean,
  /** Tek HTTP denemesi üst sınırı; verilmezse PIXROUTER_TIMEOUT_MS / 30sn */
  perRequestTimeoutMs?: number,
): Promise<PixRouterResult> {
  const budgets = getTokenBudgets(maxTokens);
  const requestTimeoutMs = perRequestTimeoutMs ?? getRequestTimeoutMs();
  let lastBudgetError: Error | null = null;

  for (const budget of budgets) {
    const remaining = deadlineAt - Date.now();
    if (remaining <= 0) {
      throw (
        lastBudgetError ??
        new PixRouterError(
          "PixRouter için ayrılan toplam süre bütçesi doldu.",
          "timeout",
        )
      );
    }

    const controller = new AbortController();
    // remaining > 0 garantili; en az 1 sn bırak ki anında abort olmasın
    const effectiveTimeout = Math.max(
      1_000,
      Math.min(requestTimeoutMs, remaining),
    );
    const timeoutId = setTimeout(() => controller.abort(), effectiveTimeout);
    try {
      const response = await fetch(`${PIXROUTER_BASE_URL}/chat/completions`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${apiKey}`,
        },
        signal: controller.signal,
        body: JSON.stringify({
          model,
          messages,
          max_tokens: budget,
          ...(temperature === undefined ? {} : { temperature }),
          // New API / OpenAI-uyumlu reasoning modelleri için: model reasoning
          // desteklemiyorsa bu alan sağlayıcı tarafından sessizce yoksayılır.
          ...(requestReasoning ? { reasoning: { enabled: true } } : {}),
        }),
      });

      const raw = await response.text();
      let data: unknown = null;
      try {
        data = raw ? JSON.parse(raw) : null;
      } catch {
        // Aşağıdaki HTTP hata mesajı ham gövdeyi gösterecek.
      }

      if (!response.ok) {
        const detail = extractError(data) ?? raw.slice(0, 400);
        if (
          shouldRetryWithSmallerBudget(response.status, detail) &&
          budget !== budgets[budgets.length - 1]
        ) {
          lastBudgetError = new PixRouterError(
            `PixRouter API hatası (${response.status}): ${detail}`,
            "http",
            response.status,
          );
          continue;
        }
        throw new PixRouterError(
          `PixRouter API hatası (${response.status}): ${detail}`,
          "http",
          response.status,
        );
      }
      const apiError = extractError(data);
      if (apiError)
        throw new PixRouterError(`PixRouter hata döndürdü: ${apiError}`, "api");

      const choices =
        isRecord(data) && Array.isArray(data.choices) ? data.choices : [];
      const first = isRecord(choices[0]) ? choices[0] : null;
      const message = first && isRecord(first.message) ? first.message : null;
      let content =
        message && typeof message.content === "string" ? message.content : "";
      if (message && Array.isArray(message.content)) {
        content = message.content
          .map((part) =>
            isRecord(part) && typeof part.text === "string" ? part.text : "",
          )
          .join("");
      }
      if (!content.trim())
        throw new PixRouterError("PixRouter boş yanıt döndürdü.", "empty");
      return {
        content: content.trim(),
        reasoning: message ? extractReasoning(message) : undefined,
      };
    } catch (error) {
      const isAbortError =
        error instanceof Error &&
        (error.name === "AbortError" ||
          error.message.toLowerCase().includes("abort") ||
          error.message.toLowerCase().includes("timeout") ||
          (error as { code?: string }).code === "ERR_HTTP_REQUEST_TIMEOUT");
      if (isAbortError) {
        throw new PixRouterError(
          `PixRouter isteği zamanaşımına uğradı (${(effectiveTimeout / 1000).toFixed(0)} sn).`,
          "timeout",
        );
      }
      if (error instanceof PixRouterError) throw error;
      throw new PixRouterError(
        error instanceof Error ? error.message : String(error),
        "http",
      );
    } finally {
      clearTimeout(timeoutId);
    }
  }

  throw (
    lastBudgetError ??
    new PixRouterError(
      "PixRouter uygun token bütçesiyle yanıt veremedi.",
      "http",
    )
  );
}

let keyRotationIndex = 0;

export interface PixRouterGenerateOptions {
  model?: string;
  maxTokens?: number;
  temperature?: number;
  /** Bu tek çağrı için toplam süre bütçesini (ms) override eder — ör. kısa
   * sınıflandırma istekleri (tek kelime cevap) tam bütçeyi hak etmez. */
  totalTimeoutMs?: number;
  /** Tek bir HTTP denemesinin üst süresi (ms). Varsayılan PIXROUTER_TIMEOUT_MS
   * (30sn). MentionAI gibi uzun cevaplar için totalTimeoutMs ile birlikte
   * yükseltilmeli; aksi halde 120sn total olsa bile istek 30sn'de kesilir. */
  requestTimeoutMs?: number;
  /** OpenAI uyumlu vision isteği için user mesajının çok parçalı içeriği. */
  userContent?: PixRouterContentPart[];
  /** true ise, sağlayıcı destekliyorsa reasoning/thinking çıktısını da iste
   * (New API / OpenAI-uyumlu sağlayıcılarda genelde `reasoning: {enabled:true}`
   * veya `reasoning_effort` gibi bir alanla açılır). Desteklemeyen modellerde
   * bu alan yoksayılır ve reasoning boş döner — asla uydurulmaz. */
  requestReasoning?: boolean;
}

export async function generateWithPixRouter(
  systemPrompt: string,
  userPrompt: string,
  options: PixRouterGenerateOptions = {},
): Promise<PixRouterResult> {
  const keys = getConfiguredKeys();
  if (keys.length === 0) {
    throw new PixRouterError(
      "PIXROUTER_API_KEY (veya PIXROUTER_API_KEY_1.._3) tanımlanmalı.",
      "config",
    );
  }

  const model = options.model ?? getActiveModel("groq");
  const startIndex = keyRotationIndex++ % keys.length;
  const messages: ChatMessage[] = [
    { role: "system", content: systemPrompt },
    { role: "user", content: options.userContent ?? userPrompt },
  ];
  const deadlineAt =
    Date.now() + (options.totalTimeoutMs ?? getTotalTimeoutMs());
  let lastError: unknown;

  for (let offset = 0; offset < keys.length; offset++) {
    if (Date.now() >= deadlineAt) break;
    const { key, label } = keys[(startIndex + offset) % keys.length];
    try {
      return await callOnce(
        key,
        model,
        messages,
        options.maxTokens ?? getMaxTokensCap(),
        options.temperature,
        deadlineAt,
        options.requestReasoning ?? false,
        options.requestTimeoutMs,
      );
    } catch (error) {
      lastError = error;
      const detail = error instanceof Error ? error.message : String(error);
      // Zamanaşımı/ağ hatası: diğer anahtarları denemek muhtemelen aynı
      // sonucu verir (aynı upstream), süre bütçesini boşuna tüketmemek için
      // hemen vazgeç. Anahtara özgü hatalarda (401/403/429) rotasyona devam.
      const keepTrying = isKeySpecificError(error);
      console.warn(
        `PixRouter anahtarıyla istek başarısız (${label}): ${detail}${keepTrying ? "; sıradaki deneniyor." : "; vazgeçiliyor (zamanaşımı/ağ hatası)."}`,
      );
      if (!keepTrying) break;
    }
  }

  // Tüm anahtarlar başarısız oldu (ya da süre bütçesi doldu). Genel/anlamsız
  // bir mesaj yerine SON denenen anahtarın gerçek hata detayını taşıyoruz ki
  // hem loglarda hem de kullanıcıya dönen mesajda asıl sebep (401/429/model
  // bulunamadı/zamanaşımı vb.) görünür olsun.
  if (lastError instanceof PixRouterError) {
    throw new PixRouterError(
      `PixRouter isteği başarısız oldu (${keys.length} anahtar denendi): ${lastError.message}`,
      lastError.kind,
      lastError.status,
    );
  }
  if (lastError instanceof Error) {
    throw new PixRouterError(
      `PixRouter isteği başarısız oldu (${keys.length} anahtar denendi): ${lastError.message}`,
      "http",
    );
  }
  throw new PixRouterError(
    `PixRouter isteği başarısız oldu (${keys.length} anahtar denendi), detay alınamadı.`,
    "http",
  );
}

export async function generateWithPixRouterForCode(
  systemPrompt: string,
  userPrompt: string,
  model: string,
): Promise<string> {
  const result = await generateWithPixRouter(systemPrompt, userPrompt, {
    model,
    maxTokens: getMaxTokensCap(),
  });
  return result.content;
}
","utils/purgeUserMessages.ts":"import {
  ChannelType,
  Collection,
  Guild,
  Message,
  PermissionFlagsBits,
  TextChannel,
} from "discord.js";
import { getErrorMessage } from "./errors.js";

const BULK_DELETE_LIMIT_MS = 14 * 24 * 60 * 60 * 1000; // Discord'un toplu silme sınırı: 14 gün
const INDIVIDUAL_DELETE_DELAY_MS = 350; // Rate limit'e takılmamak için eski mesajlar arası bekleme

/**
 * Bir sunucudaki, botun erişebildiği tüm metin kanallarını tarar ve
 * belirtilen kullanıcıya ait mesajları siler.
 *
 * 14 günden yeni mesajlar toplu (bulkDelete) silinir, daha eski mesajlar
 * Discord API kısıtı nedeniyle tek tek silinir (bu yüzden çok eski/çok
 * mesajlı kullanıcılarda işlem biraz sürebilir).
 *
 * @returns silinen toplam mesaj sayısı
 */
export async function purgeUserMessages(guild: Guild, userId: string): Promise<number> {
  const me = guild.members.me;
  if (!me) return 0;

  const channels = guild.channels.cache.filter((ch): ch is TextChannel => {
    if (ch.type !== ChannelType.GuildText && ch.type !== ChannelType.GuildAnnouncement) {
      return false;
    }
    const perms = ch.permissionsFor(me);
    return (
      perms?.has([
        PermissionFlagsBits.ViewChannel,
        PermissionFlagsBits.ReadMessageHistory,
        PermissionFlagsBits.ManageMessages,
      ]) ?? false
    );
  }) as Collection<string, TextChannel>;

  let totalDeleted = 0;

  for (const channel of channels.values()) {
    try {
      totalDeleted += await purgeChannel(channel, userId);
    } catch (err) {
      // Ham obje yerine kısa mesaj: çok kanallı sunucularda her kanal için
      // ayrı bir hata olabileceğinden ham dump konsolu hızla şişiriyordu.
      console.error(`[purgeUserMessages] #${channel.name} kanalında hata: ${getErrorMessage(err)}`);
    }
  }

  return totalDeleted;
}

async function purgeChannel(channel: TextChannel, userId: string): Promise<number> {
  let deleted = 0;
  let beforeId: string | undefined;

  // Kanalın tüm geçmişini baştan sona (yeni -> eski) tarar
  while (true) {
    const batch = await channel.messages
      .fetch({ limit: 100, before: beforeId })
      .catch(() => new Collection<string, Message>());

    if (batch.size === 0) break;
    beforeId = batch.last()!.id;

    const targetMessages = batch.filter((m) => m.author.id === userId && m.deletable);

    if (targetMessages.size > 0) {
      const now = Date.now();
      const recent = targetMessages.filter((m) => now - m.createdTimestamp < BULK_DELETE_LIMIT_MS);
      const old = targetMessages.filter((m) => now - m.createdTimestamp >= BULK_DELETE_LIMIT_MS);

      if (recent.size === 1) {
        await recent.first()!.delete().catch(() => null);
        deleted += 1;
      } else if (recent.size > 1) {
        const res = await channel.bulkDelete(recent, true).catch(() => null);
        deleted += res?.size ?? 0;
      }

      for (const msg of old.values()) {
        await msg.delete().catch(() => null);
        deleted += 1;
        await sleep(INDIVIDUAL_DELETE_DELAY_MS);
      }
    }

    if (batch.size < 100) break; // kanalın başına gelindi
  }

  return deleted;
}

function sleep(ms: number) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}
","utils/quizStore.ts":"import { db } from "../db/index.js";
import { quizScoresTable } from "../db/schema.js";
import { and, desc, eq, sql } from "drizzle-orm";

function scoreKey(guildId: string, userId: string): string {
  return `${guildId}:${userId}`;
}

/** Bir kullanıcının bilgi yarışması galibiyet sayısını 1 artırır (yoksa satırı oluşturur). */
export async function addQuizWin(guildId: string, userId: string): Promise<void> {
  const key = scoreKey(guildId, userId);
  await db
    .insert(quizScoresTable)
    .values({ key, guildId, userId, wins: 1 })
    .onConflictDoUpdate({
      target: quizScoresTable.key,
      set: { wins: sql`${quizScoresTable.wins} + 1`, updatedAt: new Date() },
    });
}

export interface QuizLeaderboardEntry {
  userId: string;
  wins: number;
}

/** Bir sunucudaki en yüksek skorlu ilk `limit` kullanıcıyı döner (çoktan aza). */
export async function getQuizLeaderboard(guildId: string, limit = 10): Promise<QuizLeaderboardEntry[]> {
  const rows = await db
    .select({ userId: quizScoresTable.userId, wins: quizScoresTable.wins })
    .from(quizScoresTable)
    .where(eq(quizScoresTable.guildId, guildId))
    .orderBy(desc(quizScoresTable.wins))
    .limit(limit);
  return rows;
}

/** Tek bir kullanıcının skorunu döner (hiç kazanmadıysa 0). */
export async function getQuizScore(guildId: string, userId: string): Promise<number> {
  const rows = await db
    .select({ wins: quizScoresTable.wins })
    .from(quizScoresTable)
    .where(and(eq(quizScoresTable.guildId, guildId), eq(quizScoresTable.userId, userId)));
  return rows[0]?.wins ?? 0;
}
","utils/rateLimit.ts":"import type { Message, Interaction } from "discord.js";
import { OWNER_ID } from "../config.js";
import { warningEmbed } from "./embeds.js";

/**
 * Bellek-içi rate limit katmanı.
 *
 * - Genel komut limiti: her prefix/slash komutu (spam / flood koruması)
 * - AI limiti: maliyetli komutlar için daha sıkı (premium dahil)
 *
 * Owner muaf. Restart'ta sıfırlanır (bilinçli tercih).
 */

// ---------- Genel komut limiti ----------
// Kullanıcı saniyede komut spam'lemesin.
const CMD_GLOBAL_COOLDOWN_MS = 1_250; // herhangi iki komut arası
const CMD_SAME_COOLDOWN_MS = 2_500; // aynı komutu peş peşe
// Kısa pencerede toplam komut üst sınırı (burst koruması)
const CMD_BURST_WINDOW_MS = 10_000;
const CMD_BURST_MAX = 8; // 10 sn içinde max 8 komut

// ---------- AI limiti (daha sıkı) ----------
const AI_GLOBAL_COOLDOWN_MS = 3_500;
const AI_PER_COMMAND_COOLDOWN_MS = 8_000;

const cmdGlobalLast = new Map<string, number>(); // userId
const cmdSameLast = new Map<string, number>(); // userId:cmd
const cmdBurstHits = new Map<string, number[]>(); // userId -> timestamps

const aiGlobalLast = new Map<string, number>();
const aiCmdLast = new Map<string, number>();

const CLEANUP_INTERVAL_MS = 5 * 60_000;
const ENTRY_MAX_AGE_MS = 15 * 60_000;

const cleanupTimer = setInterval(() => {
  const cutoff = Date.now() - ENTRY_MAX_AGE_MS;
  for (const map of [cmdGlobalLast, cmdSameLast, aiGlobalLast, aiCmdLast]) {
    for (const [key, ts] of map) {
      if (ts < cutoff) map.delete(key);
    }
  }
  for (const [key, hits] of cmdBurstHits) {
    const kept = hits.filter((t) => t >= cutoff);
    if (kept.length === 0) cmdBurstHits.delete(key);
    else cmdBurstHits.set(key, kept);
  }
}, CLEANUP_INTERVAL_MS);
cleanupTimer.unref?.();

function remainingMs(last: number | undefined, windowMs: number): number {
  if (last === undefined) return 0;
  return Math.max(0, windowMs - (Date.now() - last));
}

async function replyWait(
  target: Message | Interaction,
  secs: number,
  reason: string,
): Promise<void> {
  const payload = {
    embeds: [
      warningEmbed(
        "Yavaşla",
        `<a:1000060633:1548019629862031451> ${reason} **${secs} saniye** bekle.`,
      ),
    ],
  };

  try {
    // Slash / component interaction
    if ("commandName" in target || "customId" in target || "deferred" in target) {
      const interaction = target as Interaction & {
        deferred: boolean;
        replied: boolean;
        reply: (opts: Record<string, unknown>) => Promise<unknown>;
        followUp: (opts: Record<string, unknown>) => Promise<unknown>;
      };
      if (interaction.deferred || interaction.replied) {
        await interaction.followUp({ ...payload, ephemeral: true }).catch(() => null);
      } else {
        await interaction.reply({ ...payload, ephemeral: true }).catch(() => null);
      }
      return;
    }
    // Prefix message
    await (target as Message).reply(payload).catch(() => null);
  } catch {
    // yut — rate limit mesajı kritik değil
  }
}

/**
 * Tüm prefix / slash komutları için genel rate limit.
 * true = devam, false = reddedildi.
 */
export async function checkCommandRateLimit(
  target: Message | Interaction,
  userId: string,
  commandName: string,
): Promise<boolean> {
  if (userId === OWNER_ID) return true;

  const now = Date.now();
  const sameKey = `${userId}:${commandName}`;

  // Burst: 10 sn içinde çok fazla komut
  const hits = (cmdBurstHits.get(userId) ?? []).filter(
    (t) => now - t <= CMD_BURST_WINDOW_MS,
  );
  if (hits.length >= CMD_BURST_MAX) {
    const oldest = hits[0] ?? now;
    const wait = Math.ceil(
      (CMD_BURST_WINDOW_MS - (now - oldest)) / 1000,
    );
    await replyWait(
      target,
      Math.max(1, wait),
      `Çok hızlı komut kullanıyorsun. Devam etmeden önce`,
    );
    return false;
  }

  const globalRem = remainingMs(cmdGlobalLast.get(userId), CMD_GLOBAL_COOLDOWN_MS);
  const sameRem = remainingMs(cmdSameLast.get(sameKey), CMD_SAME_COOLDOWN_MS);
  const wait = Math.max(globalRem, sameRem);

  if (wait > 0) {
    await replyWait(
      target,
      Math.ceil(wait / 1000),
      "Komutları spam'lememek için",
    );
    return false;
  }

  cmdGlobalLast.set(userId, now);
  cmdSameLast.set(sameKey, now);
  hits.push(now);
  cmdBurstHits.set(userId, hits);
  return true;
}

/**
 * AI / maliyetli komutlar için ek (daha sıkı) rate limit.
 * requirePremiumOrTrial içinden çağrılır; genel limitin üstüne biner.
 */
export async function checkAiRateLimit(
  message: Message,
  commandName: string,
): Promise<boolean> {
  const userId = message.author.id;
  if (userId === OWNER_ID) return true;

  const now = Date.now();
  const globalRem = remainingMs(aiGlobalLast.get(userId), AI_GLOBAL_COOLDOWN_MS);
  const cmdKey = `${userId}:${commandName}`;
  const cmdRem = remainingMs(aiCmdLast.get(cmdKey), AI_PER_COMMAND_COOLDOWN_MS);
  const wait = Math.max(globalRem, cmdRem);

  if (wait > 0) {
    await replyWait(
      message,
      Math.ceil(wait / 1000),
      "Bu AI komutunu tekrar kullanmadan önce",
    );
    return false;
  }

  aiGlobalLast.set(userId, now);
  aiCmdLast.set(cmdKey, now);
  return true;
}
","utils/tdk.ts":"// src/utils/tdk.ts
// ---------------------------------------------------------------------------
// Kelime Zinciri için TDK (Türk Dil Kurumu) sözlük doğrulaması.
//
// BİLİNÇLİ TASARIM: hiçbir kelime listesi pakete gömülmüyor, hiçbir şey
// veritabanına yazılmıyor. Her kelime, TDK'nin herkese açık sözlük API'sine
// (sozluk.gov.tr) sorulup gerçekten var olan bir kelime mi diye kontrol
// edilir. Tekrar sorguları azaltmak için sadece BELLEK İÇİNDE, sabit
// boyutlu (yer kaplamayan, süreç kapanınca sıfırlanan) bir LRU cache
// tutulur — kalıcı depolama yok, DB'ye hiçbir etkisi yok.
// ---------------------------------------------------------------------------

const TDK_ENDPOINT = "https://sozluk.gov.tr/gts";
const REQUEST_TIMEOUT_MS = 4_000;

// Bellekte tutulacak maksimum kelime sayısı (yaklaşık birkaç yüz KB RAM,
// disk/DB'ye hiç dokunmaz). Limit aşılınca en eski girişler atılır.
const CACHE_MAX_ENTRIES = 5_000;

const cache = new Map<string, boolean>();

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function trLower(value: string): string {
  return value.replace(/[Iİ]/g, (character) => (character === "I" ? "ı" : "i")).toLowerCase();
}

function cacheGet(word: string): boolean | undefined {
  const hit = cache.get(word);
  if (hit !== undefined) {
    // LRU: erişileni sona taşı
    cache.delete(word);
    cache.set(word, hit);
  }
  return hit;
}

function cacheSet(word: string, valid: boolean): void {
  if (cache.size >= CACHE_MAX_ENTRIES) {
    const oldestKey = cache.keys().next().value;
    if (oldestKey !== undefined) cache.delete(oldestKey);
  }
  cache.set(word, valid);
}

/**
 * TDK sözlüğünde kelimenin gerçekten var olup olmadığını kontrol eder.
 * API'ye ulaşılamazsa (zaman aşımı, ağ hatası, TDK'nin kendisi çöktüyse)
 * `null` döner — bu durumda çağıran taraf oyunu TIKAMAMAK için kelimeyi
 * (harf/tekrar kurallarına uyduğu sürece) kabul etmeli; sözlük kontrolü
 * bir "iyileştirme"dir, tek hata noktası olmamalı.
 */
export async function isRealTurkishWord(rawWord: string): Promise<boolean | null> {
  const word = rawWord.trim().toLocaleLowerCase("tr-TR");
  if (!word) return false;

  const cached = cacheGet(word);
  if (cached !== undefined) return cached;

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);

  try {
    const res = await fetch(`${TDK_ENDPOINT}?ara=${encodeURIComponent(word)}`, {
      signal: controller.signal,
      headers: {
        // TDK, User-Agent göndermeyen istekleri genelde reddediyor/kesiyor.
        // Bu header olmadan res.ok her zaman false dönebilir ve fonksiyon
        // sürekli null'a (yani "kelimeyi kabul et") düşer — asıl bug buydu.
        "User-Agent":
          "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
        Accept: "application/json",
      },
    });

    if (!res.ok) {
      // TDK tarafı 4xx/5xx dönerse önbelleğe yazmadan null (bilinmiyor) dön.
      console.warn(`[tdk] Beklenmeyen HTTP durumu (${res.status}) — "${word}" kontrol edilemedi, oyunu tıkamamak için kabul ediliyor.`);
      return null;
    }

    const data = (await res.json()) as unknown;
    // TDK araması yaklaşık eşleşmeler döndürebilir: `ımza` sorgusu bazen
    // `imza` maddesini de getirir. Sadece sonuç dizisinin dolu olmasına bakmak
    // bu nedenle yazım hatasını yanlışlıkla kabul eder. Madde başlığı, aranan
    // kelimeyle Türkçe karakter duyarlı olarak birebir eşleşmeli.
    const valid = Array.isArray(data) && data.some(
      (entry) => isRecord(entry) && typeof entry.madde === "string" && trLower(entry.madde) === word,
    );

    cacheSet(word, valid);
    return valid;
  } catch (err) {
    // Zaman aşımı / ağ hatası — bilinmiyor, oyunu tıkamamak için null.
    console.warn(`[tdk] İstek başarısız — "${word}" kontrol edilemedi:`, err instanceof Error ? err.message : err);
    return null;
  } finally {
    clearTimeout(timeoutId);
  }
}
","utils/wordchain.ts":"import { desc, eq, sql } from "drizzle-orm";
import { db } from "../db/index.js";
import { wordChainChannelsTable, wordChainScoresTable, wordChainUsedWordsTable } from "../db/schema.js";
import { isRealTurkishWord } from "./tdk.js";

// ---------------------------------------------------------------------------
// Kelime Zinciri — bir kullanıcının yazdığı kelimenin SON harfi, bir sonraki
// kullanıcının yazacağı kelimenin İLK harfi olmak zorunda ("elma" -> "at" ->
// "top" -> ...).
//
// Bu artık geçici bir "etkinlik" (!kelime baslat / !kelime durdur) DEĞİL —
// bir yönetici bir kanalı kalıcı olarak "Kelime Zinciri kanalı" yapar
// (!kelime kanal #kanal) ve sistem sunucu kapanana/kanal kaldırılana kadar
// o kanalda sürekli çalışır. Tüm oyun durumu (mevcut zincir, son kelime,
// gereken harf, kullanılan kelimeler, mevcut seri VE tüm zamanların rekoru)
// veritabanına yazılır — bot yeniden başlatılsa (deploy, çökme, restart)
// bile zincir kaldığı yerden devam eder, hiçbir şey sıfırlanmaz.
//
// Bellekte tutulan `sessions` haritası sadece bir PERFORMANS ÖNBELLEĞİdir:
// her mesajda veritabanına gitmemek için. Kaynak gerçeklik (source of
// truth) her zaman veritabanıdır; süreç açılışında `loadWordChainChannels()`
// ile önbellek veritabanından doldurulur.
//
// NOT: Zincir kuralları (harf uyumu, tekrar etmeme, sadece harflerden
// oluşma) senkron/ucuz kontrollerle en başta elenir. Ardından, gerçek bir
// kelime olma ihtimali olan denemeler için TDK'nin (sozluk.gov.tr) genel
// sözlük API'sine sorulur — bkz. isRealTurkishWord() (./tdk.ts). TDK'ye
// ulaşılamazsa (zaman aşımı/ağ hatası) oyunu tıkamamak için kelime kabul
// edilir; bu tek istisna dışında kelimenin TDK'de gerçekten var olması
// zorunludur.
// ---------------------------------------------------------------------------

interface WordChainSession {
  guildId: string;
  channelId: string;
  lastWord: string | null;
  requiredLetter: string | null; // null = zincir sıfır, herhangi bir harfle başlanabilir
  usedWords: Set<string>;
  wordCooldownTimers: Map<string, ReturnType<typeof setTimeout>>;
  streak: number;
  lastPlayerId: string | null;
  bestStreak: number;
  bestHolderId: string | null;
  setBy: string;
}

// channelId -> oturum (aktif/kalıcı kanal başına tek oturum)
const sessions = new Map<string, WordChainSession>();
// guildId -> channelId (bir sunucunun kelime zinciri kanalını hızlıca bulmak için)
const guildChannelIndex = new Map<string, string>();
const WORD_REUSE_COOLDOWN_MS = 2 * 60 * 60 * 1_000;
const submissionLocks = new Map<string, Promise<void>>();
const persistenceQueues = new Map<string, Promise<void>>();

function clearWordCooldowns(session: WordChainSession): void {
  for (const timer of session.wordCooldownTimers.values()) clearTimeout(timer);
  session.wordCooldownTimers.clear();
}

// Bot sahibine özel muafiyet anahtarı: açıkken bot sahibi Kelime Zinciri
// kanalına normal mesaj (duyuru vb.) atabilir, mesajı silinmez ve kelime
// denemesi olarak sayılmaz. Kapalıyken bot sahibi de herkes gibi oyuna
// dahildir. Süreç bazlı (bellekte), kalıcı değil — bot yeniden başlarsa
// varsayılan olarak kapalı gelir.
let ownerBypassEnabled = false;

export function setOwnerBypass(enabled: boolean): void {
  ownerBypassEnabled = enabled;
}

export function isOwnerBypassEnabled(): boolean {
  return ownerBypassEnabled;
}

export type WordChainResult =
  | { ok: true; streak: number; isNewRecord: boolean }
  | { ok: false; reason: "consecutive" | "used" | "wrong-letter" | "invalid-format" | "not-a-word" | "too-short" };

// 1, 2 ve 3 harfli kelimeler oyunda sayılmaz — geçerli bir deneme için
// en az 4 harf gerekir.
const MIN_WORD_LENGTH = 4;

const TR_LOWER_MAP: Record<string, string> = { I: "ı", İ: "i" };

/** Türkçe'ye duyarlı küçük harfe çevirme (İ -> i, I -> ı — JS'in varsayılan .toLowerCase()'i bunu YANLIŞ yapar). */
function trLower(s: string): string {
  return s.replace(/[Iİ]/g, (ch) => TR_LOWER_MAP[ch] ?? ch.toLowerCase()).toLowerCase();
}

// TDK'de kullanılan düzeltme işaretli Türkçe harfler de geçerlidir:
// hâl, kâğıt, îman, sûret gibi kelimeler ön kontrolde silinmemelidir.
const TR_WORD_RE = /^[a-zçğıöşüâîû]+$/;

/** "ğ" ile biten kelimelerde bir sonraki kelimenin başlaması gereken harf, ğ'den ÖNCEKİ sesli/ünsüzdür (yaygın oyun kuralı) — ör. "kolağ" yazılmaz ama "sağ" gibi kelimelerde bir sonraki "a" ile başlar. */
function requiredLetterAfter(word: string): string {
  if (word.endsWith("ğ") && word.length >= 2) {
    return word[word.length - 2];
  }
  return word[word.length - 1];
}

function rowToSession(
  row: {
    guildId: string;
    channelId: string;
    lastWord: string | null;
    requiredLetter: string | null;
    streak: number;
    lastPlayerId: string | null;
    bestStreak: number;
    bestHolderId: string | null;
    setBy: string;
  },
  usedWords: Set<string>,
): WordChainSession {
  return {
    guildId: row.guildId,
    channelId: row.channelId,
    lastWord: row.lastWord,
    requiredLetter: row.requiredLetter,
    usedWords,
    wordCooldownTimers: new Map(),
    streak: row.streak,
    lastPlayerId: row.lastPlayerId,
    bestStreak: row.bestStreak,
    bestHolderId: row.bestHolderId,
    setBy: row.setBy,
  };
}

/** Süreç açılışında (Discord'a bağlanmadan önce) çağrılır — tüm kalıcı Kelime Zinciri kanallarını veritabanından belleğe yükler. */
export async function loadWordChainChannels(): Promise<void> {
  try {
    const rows = await db.select().from(wordChainChannelsTable);
    const usedWordRows = await db.select().from(wordChainUsedWordsTable);

    const usedWordsByChannel = new Map<string, Set<string>>();
    const usedWordTimesByChannel = new Map<string, Map<string, number>>();
    for (const row of usedWordRows) {
      let set = usedWordsByChannel.get(row.channelId);
      if (!set) {
        set = new Set();
        usedWordsByChannel.set(row.channelId, set);
      }
      // Eski kayıtlar DB'de tutulmaya devam eder; yalnızca son 2 saatte
      // kullanılan kelimeler aktif cooldown olarak belleğe alınır.
      if (Date.now() - row.createdAt.getTime() < WORD_REUSE_COOLDOWN_MS) {
        set.add(row.word);
        let times = usedWordTimesByChannel.get(row.channelId);
        if (!times) {
          times = new Map();
          usedWordTimesByChannel.set(row.channelId, times);
        }
        times.set(row.word, row.createdAt.getTime());
      }
    }

    sessions.clear();
    guildChannelIndex.clear();
    for (const row of rows) {
      const session = rowToSession(row, usedWordsByChannel.get(row.channelId) ?? new Set());
      sessions.set(session.channelId, session);
      guildChannelIndex.set(session.guildId, session.channelId);
      for (const [word, createdAt] of usedWordTimesByChannel.get(session.channelId) ?? []) {
        const remainingMs = Math.max(1, WORD_REUSE_COOLDOWN_MS - (Date.now() - createdAt));
        const timer = setTimeout(() => {
          session.usedWords.delete(word);
          session.wordCooldownTimers.delete(word);
        }, remainingMs);
        timer.unref?.();
        session.wordCooldownTimers.set(word, timer);
      }
    }
    if (rows.length > 0) {
      console.log(`🔤 Kelime Zinciri: ${rows.length} kalıcı kanal yüklendi.`);
    }
  } catch (err) {
    console.error("[wordchain] Kalıcı kanallar yüklenirken hata:", err);
  }
}

function enqueuePersistence(channelId: string, task: () => Promise<void>): Promise<void> {
  const previous = persistenceQueues.get(channelId) ?? Promise.resolve();
  const current = previous
    .catch(() => undefined)
    .then(task)
    .finally(() => {
      if (persistenceQueues.get(channelId) === current) persistenceQueues.delete(channelId);
    });
  persistenceQueues.set(channelId, current);
  return current;
}

/** Oyun durumu ve kullanılan kelimeyi aynı kanal kuyruğunda, kabul sırasıyla yazar. */
async function persistAcceptedWord(session: WordChainSession, word: string): Promise<void> {
  await enqueuePersistence(session.channelId, async () => {
    const value = {
      channelId: session.channelId,
      lastWord: session.lastWord,
      requiredLetter: session.requiredLetter,
      streak: session.streak,
      lastPlayerId: session.lastPlayerId,
      bestStreak: session.bestStreak,
      bestHolderId: session.bestHolderId,
      updatedAt: new Date(),
    };
    try {
      await db
        .update(wordChainChannelsTable)
        .set(value)
        .where(eq(wordChainChannelsTable.guildId, session.guildId));
      await db
        .insert(wordChainUsedWordsTable)
        .values({ channelId: session.channelId, word })
        .onConflictDoUpdate({
          target: [wordChainUsedWordsTable.channelId, wordChainUsedWordsTable.word],
          set: { createdAt: new Date() },
        });
      await db
        .insert(wordChainScoresTable)
        .values({ guildId: session.guildId, userId: session.lastPlayerId!, words: 1 })
        .onConflictDoUpdate({
          target: [wordChainScoresTable.guildId, wordChainScoresTable.userId],
          set: { words: sql`${wordChainScoresTable.words} + 1`, updatedAt: new Date() },
        });
    } catch (err) {
      console.error("[wordchain] Oyun durumu/kelime kaydedilirken hata:", err);
    }
  });
}

export function isGameActive(channelId: string): boolean {
  return sessions.has(channelId);
}

/** Bu sunucuda kalıcı olarak ayarlanmış Kelime Zinciri kanalının ID'si (yoksa null). */
export function getConfiguredChannelId(guildId: string): string | null {
  return guildChannelIndex.get(guildId) ?? null;
}

/** Bir sonraki kelimenin başlaması gereken harf (kanal ayarlı değilse veya zincir sıfırsa null). */
export function getRequiredLetter(channelId: string): string | null {
  return sessions.get(channelId)?.requiredLetter ?? null;
}

export function getSession(channelId: string): WordChainSession | undefined {
  return sessions.get(channelId);
}

export type SetChannelResult =
  | { ok: true; replacedChannelId: string | null }
  | { ok: false; reason: "already-this-channel" };

/**
 * Bir kanalı bu sunucunun KALICI Kelime Zinciri kanalı yapar. Sunucuda daha
 * önce başka bir kanal ayarlıysa o kanaldaki eski durum silinir ve yeni
 * kanalda sıfırdan (rekor hariç, rekor sunucuya ait olduğu için korunur)
 * başlanır.
 */
export async function setWordChainChannel(guildId: string, channelId: string, setBy: string): Promise<SetChannelResult> {
  const existingChannelId = guildChannelIndex.get(guildId) ?? null;
  if (existingChannelId === channelId) {
    return { ok: false, reason: "already-this-channel" };
  }

  // Sunucunun mevcut rekoru varsa (kanal değişse bile) koru.
  const existing = existingChannelId ? sessions.get(existingChannelId) : undefined;

  const session: WordChainSession = {
    guildId,
    channelId,
    lastWord: null,
    requiredLetter: null,
    usedWords: new Set(),
    wordCooldownTimers: new Map(),
    streak: 0,
    lastPlayerId: null,
    bestStreak: existing?.bestStreak ?? 0,
    bestHolderId: existing?.bestHolderId ?? null,
    setBy,
  };

  await db
    .insert(wordChainChannelsTable)
    .values({
      guildId,
      channelId,
      lastWord: null,
      requiredLetter: null,
      usedWords: "[]",
      streak: 0,
      lastPlayerId: null,
      bestStreak: session.bestStreak,
      bestHolderId: session.bestHolderId,
      setBy,
    })
    .onConflictDoUpdate({
      target: wordChainChannelsTable.guildId,
      set: {
        channelId,
        lastWord: null,
        requiredLetter: null,
        usedWords: "[]",
        streak: 0,
        lastPlayerId: null,
        setBy,
        updatedAt: new Date(),
      },
    });

  // Yeni (veya sıfırdan başlayan) kanal için taze başlangıç — bu kanalda
  // önceden kalmış kelime kayıtları varsa (eski oturumdan) temizle.
  await db.delete(wordChainUsedWordsTable).where(eq(wordChainUsedWordsTable.channelId, channelId));
  if (existingChannelId && existingChannelId !== channelId) {
    await db.delete(wordChainUsedWordsTable).where(eq(wordChainUsedWordsTable.channelId, existingChannelId));
  }

  if (existingChannelId) {
    const oldSession = sessions.get(existingChannelId);
    if (oldSession) clearWordCooldowns(oldSession);
    sessions.delete(existingChannelId);
  }
  sessions.set(channelId, session);
  guildChannelIndex.set(guildId, channelId);

  return { ok: true, replacedChannelId: existingChannelId && existingChannelId !== channelId ? existingChannelId : null };
}

/** Kalıcı Kelime Zinciri kanalını sunucudan tamamen kaldırır (rekor dahil). Kaldırılan kanalın ID'sini döner (yoksa null). */
export async function removeWordChainChannel(guildId: string): Promise<string | null> {
  const channelId = guildChannelIndex.get(guildId);
  if (!channelId) return null;

  try {
    await db.delete(wordChainChannelsTable).where(eq(wordChainChannelsTable.guildId, guildId));
    await db.delete(wordChainUsedWordsTable).where(eq(wordChainUsedWordsTable.channelId, channelId));
  } catch (err) {
    // DB silinemediyse bellekte silmek, yeniden başlatmada kanalın geri
    // gelmesine ve kullanıcıların mevcut durumunu beklenmedik biçimde
    // kaybetmesine yol açar. Bu nedenle başarısızlığı üst kata bildiriyoruz.
    console.error("[wordchain] Kanal kaldırılırken hata:", err);
    return null;
  }

  const session = sessions.get(channelId);
  if (session) clearWordCooldowns(session);
  sessions.delete(channelId);
  guildChannelIndex.delete(guildId);
  return channelId;
}

/**
 * Gelen mesajın geçerli bir "kelime denemesi" olup olmadığını hızlıca
 * eler (boşluk içeriyorsa, çok uzunsa vb.) — messageCreate.ts'in her mesajda
 * gereksiz yere ağır işlem yapmaması için ucuz bir ön filtre.
 */
export function looksLikeWordAttempt(content: string): boolean {
  const trimmed = content.trim();
  if (!trimmed || trimmed.includes(" ") || trimmed.length > 32) return false;
  return TR_WORD_RE.test(trLower(trimmed));
}

/**
 * Bir kelime denemesini işler. Bu kanal kalıcı Kelime Zinciri kanalı değilse
 * null döner (çağıran taraf bu durumda mesajı görmezden gelmeli).
 *
 * TDK sözlük kontrolü EN SON yapılır — önce ucuz/senkron kurallar (format,
 * tekrar, art arda oynama, harf uyumu) elenir, gerçek bir kelime olma
 * ihtimali olan denemeler için ağ isteği atılır. Böylece geçersiz formatlı
 * mesajlarda (boşluklu, çok uzun vb.) gereksiz TDK isteği yapılmaz.
 */
async function submitWordUnsafe(channelId: string, playerId: string, rawWord: string): Promise<WordChainResult | null> {
  const session = sessions.get(channelId);
  if (!session) return null;

  const word = trLower(rawWord.trim());
  if (!TR_WORD_RE.test(word)) {
    return { ok: false, reason: "invalid-format" };
  }
  if (word.length < MIN_WORD_LENGTH) {
    return { ok: false, reason: "too-short" };
  }

  // Aynı kişi art arda iki kez oynayamaz — en az iki farklı kişi katılmalı
  // (tek kişi kendi kendine zincir kurup "seri"yi anlamsızlaştırmasın diye).
  if (session.lastPlayerId === playerId) {
    return { ok: false, reason: "consecutive" };
  }

  if (session.usedWords.has(word)) return { ok: false, reason: "used" };

  if (session.requiredLetter && word[0] !== session.requiredLetter) {
    return { ok: false, reason: "wrong-letter" };
  }

  // TDK'ye göre gerçek bir kelime mi? API'ye ulaşılamazsa (null) oyunu
  // tıkamamak için kelimeyi kabul ediyoruz — sözlük kontrolü bir katkı,
  // tek hata noktası olmamalı.
  const isReal = await isRealTurkishWord(word);
  if (isReal === false) {
    return { ok: false, reason: "not-a-word" };
  }

  // Bu kontrol sırasında aynı kanalda başka bir kelime kabul edilmiş
  // olabilir (await sırasında oturum değişmiş olabilir) — session hâlâ
  // güncel mi diye tekrar bakıyoruz.
  const current = sessions.get(channelId);
  if (!current || current !== session) return null;
  if (current.lastPlayerId === playerId) {
    return { ok: false, reason: "consecutive" };
  }
  if (current.usedWords.has(word)) return { ok: false, reason: "used" };
  if (current.requiredLetter && word[0] !== current.requiredLetter) {
    return { ok: false, reason: "wrong-letter" };
  }

  session.usedWords.add(word);
  const previousCooldown = session.wordCooldownTimers.get(word);
  if (previousCooldown) clearTimeout(previousCooldown);
  const cooldownTimer = setTimeout(() => {
    session.usedWords.delete(word);
    session.wordCooldownTimers.delete(word);
  }, WORD_REUSE_COOLDOWN_MS);
  cooldownTimer.unref?.();
  session.wordCooldownTimers.set(word, cooldownTimer);
  session.lastWord = word;
  session.requiredLetter = requiredLetterAfter(word);
  session.streak += 1;
  session.lastPlayerId = playerId;

  let isNewRecord = false;
  if (session.streak > session.bestStreak) {
    session.bestStreak = session.streak;
    session.bestHolderId = playerId;
    isNewRecord = true;
  }

  await persistAcceptedWord(session, word);

  return { ok: true, streak: session.streak, isNewRecord };
}

/** Aynı kanala aynı anda gelen mesajları sıraya alır; TDK beklemesi sırasında
 * iki oyuncunun aynı zincir durumunu görüp ikisinin de kabul edilmesini önler. */
export async function submitWord(channelId: string, playerId: string, rawWord: string): Promise<WordChainResult | null> {
  const previous = submissionLocks.get(channelId) ?? Promise.resolve();
  let release!: () => void;
  const current = new Promise<void>((resolve) => {
    release = resolve;
  });
  submissionLocks.set(channelId, current);
  await previous;
  try {
    return await submitWordUnsafe(channelId, playerId, rawWord);
  } finally {
    release();
    if (submissionLocks.get(channelId) === current) submissionLocks.delete(channelId);
  }
}

export interface WordChainStatus {
  channelId: string;
  lastWord: string | null;
  requiredLetter: string | null;
  streak: number;
  bestStreak: number;
  bestHolderId: string | null;
  usedWordsCount: number;
}

export interface WordChainTopEntry {
  guildId: string;
  bestStreak: number;
  bestHolderId: string | null;
}

export interface WordChainScore {
  userId: string;
  words: number;
}

/** Sunucudaki kabul edilmiş kelime sayısına göre gerçek oyuncu sıralaması. */
export async function getGuildWordScores(guildId: string, limit = 10): Promise<WordChainScore[]> {
  const rows = await db
    .select({ userId: wordChainScoresTable.userId, words: wordChainScoresTable.words })
    .from(wordChainScoresTable)
    .where(eq(wordChainScoresTable.guildId, guildId))
    .orderBy(desc(wordChainScoresTable.words))
    .limit(limit);
  return rows;
}

/**
 * Tüm sunuculardaki Kelime Zinciri rekorlarının en yükseğe göre sıralanmış
 * ilk `limit` tanesi (varsayılan 10) — `!kelime top`. Bellekteki oturum
 * haritası zaten kaynak gerçekliğin (DB) önbelleği olduğundan doğrudan
 * `sessions` üzerinden okunur, ekstra bir DB sorgusuna gerek yoktur.
 */
export function getTopStreaks(limit = 10): WordChainTopEntry[] {
  return [...sessions.values()]
    .filter((session) => session.bestStreak > 0)
    .sort((a, b) => b.bestStreak - a.bestStreak)
    .slice(0, limit)
    .map((session) => ({
      guildId: session.guildId,
      bestStreak: session.bestStreak,
      bestHolderId: session.bestHolderId,
    }));
}

export function getStatus(guildId: string): WordChainStatus | null {
  const channelId = guildChannelIndex.get(guildId);
  if (!channelId) return null;
  const session = sessions.get(channelId);
  if (!session) return null;
  return {
    channelId: session.channelId,
    lastWord: session.lastWord,
    requiredLetter: session.requiredLetter,
    streak: session.streak,
    bestStreak: session.bestStreak,
    bestHolderId: session.bestHolderId,
    usedWordsCount: session.usedWords.size,
  };
}
","welcome/panel.ts":"import {
