export const WELCOME_PLACEHOLDER_HELP =
  "`{n}` üye sayısı • `{kullanici}` etiket • `{isim}` kullanıcı adı • `{sunucu}` sunucu adı";

function truncate(text: string, max = 300): string {
  return text.length > max ? `${text.slice(0, max)}…` : text;
}

export async function buildWelcomePanelView(guildId: string) {
  const cfg = await getGuildWelcomeConfig(guildId);

  const embed = new EmbedBuilder()
    .setColor(cfg.enabled ? COLORS.success : COLORS.info)
    .setTitle("👋 Hoşgeldin & Görüşürüz Sistemi")
    .setDescription(
      [
        `**Durum**\n${cfg.enabled ? "✅ Aktif" : "⛔ Kapalı"}`,
        `**Kanal**\n${cfg.channelId ? `<#${cfg.channelId}>` : "*ayarlanmamış*"}`,
      ].join("\n\n"),
    )
    .addFields(
      {
        name: "📝 Giriş Mesajı",
        value: cfg.message ? `\`\`\`\n${truncate(cfg.message)}\n\`\`\`` : "*ayarlanmamış*",
      },
      {
        name: "🖼️ Giriş Görseli",
        value: cfg.welcomeImage ? truncate(cfg.welcomeImage, 100) : "*ayarlanmamış*",
        inline: true,
      },
      {
        name: "📝 Çıkış Mesajı",
        value: cfg.leaveMessage ? `\`\`\`\n${truncate(cfg.leaveMessage)}\n\`\`\`` : "*ayarlanmamış (gönderilmiyor)*",
      },
      {
        name: "🖼️ Çıkış Görseli",
        value: cfg.leaveImage ? truncate(cfg.leaveImage, 100) : "*ayarlanmamış*",
        inline: true,
      },
    )
    .setFooter({ text: `${WELCOME_PLACEHOLDER_HELP} • Sadece Sunucuyu Yönet yetkisine sahip kişiler kullanabilir` })
    .setTimestamp();

  const channelRow = new ActionRowBuilder<ChannelSelectMenuBuilder>().addComponents(
    new ChannelSelectMenuBuilder()
      .setCustomId("welcome_panel_channel")
      .setPlaceholder("Giriş/çıkış kanalını seç ya da değiştir…")
      .addChannelTypes(ChannelType.GuildText),
  );

  const msgRow = new ActionRowBuilder<ButtonBuilder>().addComponents(
    new ButtonBuilder().setCustomId("welcome_panel_msg_welcome").setLabel("Giriş Mesajı").setEmoji("📝").setStyle(ButtonStyle.Primary),
    new ButtonBuilder().setCustomId("welcome_panel_msg_leave").setLabel("Çıkış Mesajı").setEmoji("📝").setStyle(ButtonStyle.Primary),
  );

  const imgRow = new ActionRowBuilder<ButtonBuilder>().addComponents(
    new ButtonBuilder().setCustomId("welcome_panel_img_welcome").setLabel("Giriş Görseli").setEmoji("🖼️").setStyle(ButtonStyle.Secondary),
    new ButtonBuilder().setCustomId("welcome_panel_img_leave").setLabel("Çıkış Görseli").setEmoji("🖼️").setStyle(ButtonStyle.Secondary),
  );

  const resetRow = new ActionRowBuilder<ButtonBuilder>().addComponents(
    new ButtonBuilder().setCustomId("welcome_panel_reset_welcome").setLabel("Girişi Sıfırla").setEmoji("🔄").setStyle(ButtonStyle.Secondary),
    new ButtonBuilder().setCustomId("welcome_panel_reset_leave").setLabel("Çıkışı Sıfırla").setEmoji("🔄").setStyle(ButtonStyle.Secondary),
  );

  const controlRow = new ActionRowBuilder<ButtonBuilder>().addComponents(
    cfg.enabled
      ? new ButtonBuilder().setCustomId("welcome_panel_toggle").setLabel("Sistemi Kapat").setEmoji("⛔").setStyle(ButtonStyle.Danger)
      : new ButtonBuilder().setCustomId("welcome_panel_toggle").setLabel("Sistemi Aç").setEmoji("✅").setStyle(ButtonStyle.Success),
    new ButtonBuilder().setCustomId("welcome_panel_refresh").setLabel("Yenile").setEmoji("🔁").setStyle(ButtonStyle.Secondary),
  );

  return {
    embeds: [embed],
    components: [channelRow, msgRow, imgRow, resetRow, controlRow],
  };
}
","welcome/render.ts":"import type { GuildMember } from "discord.js";

// Desteklenen placeholder'lar:
//   {n}         -> sunucunun güncel üye sayısı
//   {kullanici} -> üyeyi etiketler (@Kullanıcı)
//   {isim}      -> üyenin kullanıcı adı (etiketlemeden)
//   {sunucu}    -> sunucu adı
// Mesaj metni olduğu gibi (markdown/kod bloğu dahil) Discord'a gönderilir,
// burada sadece placeholder değişimi yapılır — biçimlendirmeye dokunulmaz.
// Hem katılma (hoşgeldin) hem ayrılma (görüşürüz) mesajları için ortak kullanılır.
export function renderWelcomeMessage(template: string, member: GuildMember): string {
  return template
    .split("{n}").join(String(member.guild.memberCount))
    .split("{kullanici}").join(`${member}`)
    .split("{isim}").join(member.user.username)
    .split("{sunucu}").join(member.guild.name);
}

// Discord mesaj içeriği limiti 2000 karakterdir. Bunu ayar anında kontrol
// etmezsek, `!hosgeldin ayarla`/`mesaj` başarıyla kaydedilir ama gerçek üye
// katıldığında/ayrıldığında gönderim discord.js tarafında sessizce hata verip
// hiçbir mesaj gitmezdi (bkz. events/welcome.ts try/catch). Placeholder'lar
// gerçek değerlerle genelde şablon metninden uzun olduğu için pay bırakıyoruz.
export const MAX_TEMPLATE_LENGTH = 1800;

export function isTemplateTooLong(template: string): boolean {
  return template.length > MAX_TEMPLATE_LENGTH;
}
","welcome/store.ts":"import { eq } from "drizzle-orm";
import { db, welcomeConfigTable } from "../db/index.js";

export interface GuildWelcomeConfig {
  enabled: boolean;
  channelId: string | null;
  message: string | null;
  // Üye sunucudan ayrıldığında aynı kanala atılacak mesaj. Opsiyoneldir;
  // null ise ayrılış mesajı gönderilmez (sadece hoşgeldin gönderilir).
  leaveMessage: string | null;
  // Giriş/çıkış mesajının altına eklenen resim URL'si (opsiyonel). Bkz.
  // welcome/panel.ts — "Giriş Görseli"/"Çıkış Görseli" butonları.
  welcomeImage: string | null;
  leaveImage: string | null;
}

export const DEFAULT_WELCOME_MESSAGE =
  "Hoşgeldin {kullanici}, seninle beraber **{n}** kişi olduk!";

const DEFAULTS: GuildWelcomeConfig = {
  enabled: false,
  channelId: null,
  message: null,
  leaveMessage: null,
  welcomeImage: null,
  leaveImage: null,
};

function rowToConfig(row: typeof welcomeConfigTable.$inferSelect): GuildWelcomeConfig {
  return {
    enabled: row.enabled,
    channelId: row.channelId,
    message: row.message,
    leaveMessage: row.leaveMessage,
    welcomeImage: row.welcomeImage,
    leaveImage: row.leaveImage,
  };
}

// automod/store.ts'deki ile aynı desen: her mesajda DB'ye gitmemek için kısa
// ömürlü bellek-içi cache. updateGuildConfig çağrıldığında cache hemen
// güncellenir; başka bir process'ten değişirse en geç CACHE_TTL_MS sonra
// fark edilir.
const cache = new Map<string, { cfg: GuildWelcomeConfig; ts: number }>();
const CACHE_TTL_MS = 30_000;
const configUpdateQueues = new Map<string, Promise<GuildWelcomeConfig>>();

export async function getGuildWelcomeConfig(guildId: string): Promise<GuildWelcomeConfig> {
  const cached = cache.get(guildId);
  if (cached && Date.now() - cached.ts < CACHE_TTL_MS) return cached.cfg;

  const rows = await db
    .select()
    .from(welcomeConfigTable)
    .where(eq(welcomeConfigTable.guildId, guildId));

  let cfg: GuildWelcomeConfig;
  if (rows[0]) {
    cfg = rowToConfig(rows[0]);
  } else {
    await db.insert(welcomeConfigTable).values({ guildId }).onConflictDoNothing();
    cfg = { ...DEFAULTS };
  }

  cache.set(guildId, { cfg, ts: Date.now() });
  return cfg;
}

export function updateGuildWelcomeConfig(
  guildId: string,
  patch: Partial<GuildWelcomeConfig>,
): Promise<GuildWelcomeConfig> {
  const previous = configUpdateQueues.get(guildId);
  const base = previous ? previous.catch(() => getGuildWelcomeConfig(guildId)) : getGuildWelcomeConfig(guildId);
  let update!: Promise<GuildWelcomeConfig>;
  update = base.then(async (current) => {
    const merged: GuildWelcomeConfig = { ...current, ...patch };
    const values = {
      guildId,
      enabled: merged.enabled,
      channelId: merged.channelId,
      message: merged.message,
      leaveMessage: merged.leaveMessage,
      welcomeImage: merged.welcomeImage,
      leaveImage: merged.leaveImage,
      updatedAt: new Date(),
    };

    await db
      .insert(welcomeConfigTable)
      .values(values)
      .onConflictDoUpdate({ target: welcomeConfigTable.guildId, set: values });

    cache.set(guildId, { cfg: merged, ts: Date.now() });
    return merged;
  });
  configUpdateQueues.set(guildId, update);
  void update.then(
    () => { if (configUpdateQueues.get(guildId) === update) configUpdateQueues.delete(guildId); },
    () => { if (configUpdateQueues.get(guildId) === update) configUpdateQueues.delete(guildId); },
  );
  return update;
}
","welcomeback/store.ts":"// src/welcomeback/store.ts
// "Tekrar hoşgeldin" sistemi: bir kullanıcı bir sunucuda belirlenen süre
// boyunca hiç mesaj/komut yazmazsa, tekrar yazdığında bot onu karşılar.
//
// AFK sistemi (bkz. src/afk/store.ts) DB'ye yazıyor; burada ise bilinçli
// olarak düz JSON dosyaları kullanıyoruz (DB tablosu eklemeye gerek yok):
//   - data/welcome-back-settings.json  -> sunucu bazlı açık/kapalı + süre
//   - data/welcome-back-activity.json  -> kullanıcı bazlı son aktiflik zamanı
//
// Ayarlar dosyası her değişiklikte (nadir) hemen diske yazılır.
// Aktiflik dosyası ise HER mesajda güncellenir; bu yüzden diske yazmayı
// debounce ediyoruz (dirty flag + periyodik flush) — aksi halde her mesajda
// senkron disk I/O yapmış oluruz.

import fs from "node:fs";
import path from "node:path";

// ---------------------------------------------------------------------------
// Sunucu ayarları
// ---------------------------------------------------------------------------

export interface WelcomeBackGuildSettings {
  enabled: boolean;
  /** Dakika cinsinden — bu süre boyunca sessiz kalan kullanıcı "döndüğünde" karşılanır. */
  durationMinutes: number;
}

export const DEFAULT_DURATION_MINUTES = 120;
const DEFAULT_SETTINGS: WelcomeBackGuildSettings = {
  enabled: false,
  durationMinutes: DEFAULT_DURATION_MINUTES,
};

const SETTINGS_FILE = path.resolve(process.cwd(), "data/welcome-back-settings.json");

type StoredSettings = Record<string, Partial<WelcomeBackGuildSettings>>;

let settingsCache: StoredSettings | null = null;

function loadSettingsFromDisk(): StoredSettings {
  if (settingsCache) return settingsCache;
  try {
    if (!fs.existsSync(SETTINGS_FILE)) {
      settingsCache = {};
      return settingsCache;
    }
    const raw = JSON.parse(fs.readFileSync(SETTINGS_FILE, "utf8")) as unknown;
    settingsCache = raw && typeof raw === "object" ? (raw as StoredSettings) : {};
  } catch (err) {
    console.error("⚠️ data/welcome-back-settings.json okunamadı, varsayılanlar kullanılacak:", err);
    settingsCache = {};
  }
  return settingsCache;
}

function persistSettings(settings: StoredSettings): void {
  try {
    fs.mkdirSync(path.dirname(SETTINGS_FILE), { recursive: true });
    fs.writeFileSync(SETTINGS_FILE, JSON.stringify(settings, null, 2), "utf8");
  } catch (err) {
    console.error("⚠️ data/welcome-back-settings.json yazılamadı:", err);
    throw err;
  }
}

/** Bir sunucunun tekrar hoşgeldin ayarlarını döner (hiç ayarlanmadıysa varsayılan: kapalı, 120dk). */
export function getWelcomeBackSettings(guildId: string): WelcomeBackGuildSettings {
  const stored = loadSettingsFromDisk()[guildId];
  return {
    enabled: stored?.enabled ?? DEFAULT_SETTINGS.enabled,
    durationMinutes: stored?.durationMinutes ?? DEFAULT_SETTINGS.durationMinutes,
  };
}

/** Sistemi açar/kapatır. */
export function setWelcomeBackEnabled(guildId: string, enabled: boolean): WelcomeBackGuildSettings {
  const settings = { ...loadSettingsFromDisk() };
  const current = getWelcomeBackSettings(guildId);
  const updated: WelcomeBackGuildSettings = { ...current, enabled };
  settings[guildId] = updated;
  persistSettings(settings);
  settingsCache = settings;
  return updated;
}

/** Süreyi (dakika) değiştirir. */
export function setWelcomeBackDuration(guildId: string, durationMinutes: number): WelcomeBackGuildSettings {
  const settings = { ...loadSettingsFromDisk() };
  const current = getWelcomeBackSettings(guildId);
  const updated: WelcomeBackGuildSettings = { ...current, durationMinutes };
  settings[guildId] = updated;
  persistSettings(settings);
  settingsCache = settings;
  return updated;
}

// ---------------------------------------------------------------------------
// Kullanıcı son aktiflik zamanı
// ---------------------------------------------------------------------------

const ACTIVITY_FILE = path.resolve(process.cwd(), "data/welcome-back-activity.json");
const ACTIVITY_FLUSH_INTERVAL_MS = 30_000;

// key: `${guildId}:${userId}` -> son aktiflik (epoch ms)
const activityMap = new Map<string, number>();
let activityLoaded = false;
let activityDirty = false;
let flushTimer: NodeJS.Timeout | null = null;

function activityKey(guildId: string, userId: string): string {
  return `${guildId}:${userId}`;
}

function loadActivityFromDisk(): void {
  try {
    if (!fs.existsSync(ACTIVITY_FILE)) return;
    const raw = JSON.parse(fs.readFileSync(ACTIVITY_FILE, "utf8")) as unknown;
    if (raw && typeof raw === "object") {
      for (const [key, value] of Object.entries(raw as Record<string, unknown>)) {
        if (typeof value === "number" && Number.isFinite(value)) activityMap.set(key, value);
      }
    }
  } catch (err) {
    console.error("⚠️ data/welcome-back-activity.json okunamadı, boş başlanacak:", err);
  }
}

function flushActivityToDisk(): void {
  if (!activityDirty) return;
  try {
    fs.mkdirSync(path.dirname(ACTIVITY_FILE), { recursive: true });
    const obj = Object.fromEntries(activityMap);
    fs.writeFileSync(ACTIVITY_FILE, JSON.stringify(obj, null, 2), "utf8");
    activityDirty = false;
  } catch (err) {
    console.error("⚠️ data/welcome-back-activity.json yazılamadı:", err);
  }
}

/** Uygulama başlangıcında bir kere çağrılır; diskteki aktiflik verisini belleğe yükler. */
export function ensureWelcomeBackActivityLoaded(): void {
  if (activityLoaded) return;
  loadActivityFromDisk();
  activityLoaded = true;
  if (!flushTimer) {
    flushTimer = setInterval(flushActivityToDisk, ACTIVITY_FLUSH_INTERVAL_MS);
    flushTimer.unref?.();
  }
}

/** Kullanıcının bu sunucudaki son aktiflik zamanını döner (hiç kaydı yoksa null). */
export function getLastActivity(guildId: string, userId: string): number | null {
  return activityMap.get(activityKey(guildId, userId)) ?? null;
}

/** Kullanıcının aktiflik zamanını "şimdi" olarak günceller (bellekte anında, diskte debounce'lu). */
export function touchActivity(guildId: string, userId: string, now: number = Date.now()): void {
  activityMap.set(activityKey(guildId, userId), now);
  activityDirty = true;
}

/** Process kapanırken (ör. graceful shutdown) bekleyen aktiflik verisini hemen diske yazar. */
export function flushWelcomeBackActivityNow(): void {
  flushActivityToDisk();
}
